window.__LIBQ=window.__LIBQ||{};window.__LIBQ["pham-nhan-tu-tien"]=window.__LIBQ["pham-nhan-tu-tien"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q09"]=window.__LIBQ["pham-nhan-tu-tien"]["q09"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q09"]["cotTruyen"]=[{"chuong":1354,"tieuDe":"Nhiệm Vụ","tomTat":"Hàn Lập hội họp với Lũng Đông, Diệp Dĩnh, Du Hồng và Lý đạo hữu trong một khu rừng quái thụ đỏ thẫm, hình thành đội thám sát gồm ba tu sĩ Nhân Tộc và hai tu sĩ Yêu Tộc. Sự chênh lệch cảnh giới khiến Lý đạo hữu nghi ngờ năng lực của Hàn Lập và Diệp Dĩnh, nhưng Lũng Đông đứng ra bảo đảm cho hai người. Du Hồng nhận ra Hàn Lập, tiết lộ hắn tu luyện Pháp Thể Song Tu và cho biết Đại Nhi đã ngưng kết Kim Đan. Cả đội được giao đến Hắc Thạch Sâm Lâm nằm vùng, thu thập tình báo về Mộc Linh Tộc, trong khi Thiên Mộc Mộng La Lung Tráo khiến mọi tu sĩ trên Hóa Thần tiến vào đều lập tức bại lộ. Hàn Lập nhận thấy thành phần cùng mức độ nguy hiểm của nhiệm vụ khác xa thông tin Triệu Vô Quy từng cung cấp, nhưng không thể rút lui vì có nguy cơ bị cấm rời Thiên Uyên Thành trong mười năm. Sau khi mọi người đồng ý xuất phát, Lũng Đông đề nghị dùng Linh Vân Thuyền để tiết kiệm pháp lực và che giấu hành tung trên đường."},{"chuong":1355,"tieuDe":"Sóng Ngầm","tomTat":"Lũng Đông điều khiển Linh Vân Chu đưa đoàn người rời khu rừng, sắp xếp tĩnh thất và lịch canh gác cho hành trình dự kiến kéo dài nửa năm. Khi những người khác đã nghỉ ngơi, hắn để lộ sự mong chờ bí ẩn đối với một ngày trong tương lai. Trong tĩnh thất riêng, Du Hồng nhận ra Diệp Dĩnh mang Thiên Phượng Huyết và dùng ba viên Hắc Viêm Đan thuyết phục Lý đạo hữu trợ giúp chiếm đoạt Chân Huyết sau khi nhiệm vụ kết thúc. Diệp Dĩnh vận công cùng một nhân hình hư ảnh có biểu hiện đồng bộ với nàng, nhưng chưa rõ nàng có biết âm mưu đang nhắm vào mình hay không. Hàn Lập xem xét Diệt Trần Đan rồi tiếp tục nghiên cứu ngọc giản chứa tấm bản đồ khuyết và điểm tròn phát kim quang. Ở một mật thất sâu dưới lòng đất, Kim Việt đại sư cùng đạo nhân trung niên mặt vàng bàn về hiểm nguy của nhiệm vụ tại khu vực Dị Tộc và nghi ngờ Yêu Tộc có kế hoạch riêng. Cuộc đối thoại hé lộ kế hoạch đã bị thay đổi vì Huyền Thiên Trảm Linh Kiếm mới xuất hiện trên Hỗn Độn Vạn Linh Bảng và được xếp trong ba Huyền Thiên Bảo mạnh nhất."},{"chuong":1356,"tieuDe":"Tử Ảnh - Thánh Hoàng","tomTat":"Kim Việt đại sư giải thích rằng sự xuất thế của Huyền Thiên Linh Bảo thường kéo theo những cuộc tranh đoạt đẫm máu, còn lời Dự Ngôn của Yêu Tộc đã xác định Huyền Thiên Trảm Linh Kiếm sẽ xuất hiện trong Nhân Tộc tại tây bắc Phong Nguyên Đại Lục. Để phân tán tai họa và bảo tồn lực lượng phục hưng, Trưởng Lão Hội bí mật điều các phi thăng tu sĩ cùng một số tu sĩ bản địa có tư chất cao rời Thiên Uyên Thành. Kim Việt phản đối việc cưỡng ép lục soát thần thức vì lo dị tộc nằm vùng sẽ làm lộ tin tức, khiến Nhân Tộc bị các thế lực khác vây công và mất liên minh với Yêu Tộc. Cuộc đối thoại thực chất còn nhằm kéo dài thời gian để Tứ Thần Hương phát tác, giúp Kim Việt vạch trần đạo sĩ đối diện là Tử Ảnh đang chiếm thân Lôi La Chân Nhân. Kim Việt đánh bật Tử Ảnh khỏi thân xác, còn Thiên Nguyên Thánh Hoàng hiện thân và dùng Ngọc Bát thu giữ nó. Lôi La được xác nhận đã chết sau nhiều năm bị chiếm thân, nên Kim Việt đau buồn hỏa táng di thể người bạn cũ. Vì Tử Ảnh đã mạo danh Lôi La trong Thiên Uyên Thành suốt nhiều năm và có thể truyền ra nhiều bí mật, Kim Việt kết luận rằng phần lớn hệ thống phòng ngự cùng cấm chế của thành phải được thay đổi."},{"chuong":1357,"tieuDe":"Sá Linh Tỳ Bà","tomTat":"Thiên Nguyên Thánh Hoàng giao Ngọc Bát đang giam Tử Ảnh cho Kim Việt đại sư khảo vấn, đồng thời tiết lộ ông đã bí mật tăng viện vì dự đoán Ảnh Tộc sẽ phục kích đoàn phi thăng tu sĩ. Kim Việt đại sư xác nhận tin về Huyền Linh Trảm Linh Kiếm chỉ là kế trì hoãn và giải thích rằng Huyền Thiên Linh Bảo rời giới diện trước khi thông linh sẽ mất cơ hội biến hóa. Trên đường tiến sâu vào Man Hoang, nhóm Hàn Lập bị hàng trăm quái điểu tập kích nhưng nhanh chóng tiêu diệt toàn bộ bằng phi kiếm, bạch hồng, Hắc Viêm Diễm, bán yêu hóa và Thạch Hóa. Sau trận chiến, cả đội thống nhất sẽ từ bỏ Linh Vân Chu nếu gặp cổ thú quá mạnh để ưu tiên bảo toàn tính mạng. Chu Hồng nhận ra Bích Ngọc Tỳ Bà của Diệp Dĩnh là bản phỏng chế Sá Linh Tỳ Bà, trong khi chính phẩm là Thông Thiên Linh Bảo có ba thần thông Thạch Hóa, Dong Kim và Băng Phong. Qua lời Lũng Đông và Diệp Dĩnh, Hàn Lập biết Thanh Nguyên Tử từng dùng kiếm trận chống ngang tu sĩ Hợp Thể kỳ rồi mất tích trong Man Hoang. Hắn nhận ra đây là người sáng tạo Thanh Nguyên Kiếm Quyết tại Hạ Giới nhưng giả vờ không biết kiếm trận để che giấu truyền thừa, sau đó lên vị trí cao nhất của Linh Vân Chu canh gác."},{"chuong":1358,"tieuDe":"Lôi Quy","tomTat":"Trong phiên canh gác kéo dài chín ngày, Hàn Lập vừa nghiên cứu công pháp vừa dùng thần niệm cảnh giới quanh Linh Vân Chu. Khi đang thay linh thạch cho thuyền, hắn phát hiện một bóng đen khổng lồ giữa mây xám, sấm chớp và những vòi lốc nối trời đất nên lập tức báo động đồng đội. Diệp Dĩnh nhận ra đó là Lôi Quy, một Man Hoang Cổ Thú mà chỉ tu sĩ Hợp Thể kỳ mới đủ sức chính diện giao phong, còn Chu Hồng cảnh báo bão sấm sắp bùng phát. Lũng Đông lập tức đổi hướng Linh Vân Chu, sau đó cả năm người cùng truyền linh lực để đưa thuyền chạy liền mấy vạn dặm và thoát khỏi quầng sáng lam đang lan tới. Khi nguy hiểm qua đi, Chu Hồng tiết lộ Lôi Quy trưởng thành có hai dị châu thu lôi và phát lôi, còn thi thể của nó là tài liệu quý để luyện chế bảo vật thuộc tính lôi. Biết cả đội không đủ tu vi săn bắt Cổ Thú, mọi người trở về tĩnh thất, riêng Hàn Lập vẫn nhìn về phía bão sấm hồi lâu với vẻ tiếc nuối."},{"chuong":1359,"tieuDe":"Song Hoàng Xuất Hiện","tomTat":"Sau khi đoàn Hàn Lập rời đi, Lôi Quy tiếp tục hấp thu gần phân nửa lôi điện trong khu vực bão sét. Hai cường giả Thiên Diệu và Huyền Vũ cưỡi Khôi lỗi Cốt Phượng truyền tống tới, thỏa thuận chia bộ xương cùng Lôi Châu rồi bắt đầu săn giết Lôi Quy. Huyền Vũ đồng thời hé lộ rằng nhiệm vụ quan trọng của họ là đánh văng các dị tộc dám tới gần Thiên Uyên Thành. Trong một tháng tiếp theo, đoàn Hàn Lập vượt qua quái phong do tiểu trùng đỏ tạo thành và tránh được một quái điểu hai đầu khổng lồ. Linh Vân Chu sau đó bất ngờ bị một đòn tập kích chưa rõ nguồn phá hủy, nhưng cả đoàn kịp phi độn thoát ra. Nhìn xuống khe núi, họ phát hiện một thằn lằn xanh sừng đỏ và một cự nhân nhiều mắt đang giằng co quanh cây cự thảo tím. Hàn Lập dùng thần niệm nhận ra những quả tím trên cây đều chứa hình hài tiểu long và tỏa ra linh khí cực kỳ tinh thuần."},{"chuong":1360,"tieuDe":"Chi Long Quả","tomTat":"Nhóm Hàn Lập nhận ra linh quả trước mắt là Chi Long Quả, nguyên liệu chủ yếu để luyện Đằng Long Đan cấp Luyện Hư, ba vạn năm mới chín và có thể trực tiếp mang lại hiệu quả tương đương sáu mươi năm khổ tu. Hàn Lập xác định Cự Nhân mắt bạc là thành viên trưởng thành của Thiên Mục Tộc, còn Cự Tích Dịch đang giằng co với hắn cũng có thực lực khoảng Luyện Hư kỳ. Khi một đàn cự trùng bay tới rồi biến mất, Hàn Lập dùng Minh Thanh Linh Mục nhìn ra Cự Tích Dịch đã phóng chiếc lưỡi dài trong suốt để xuyên thủng và nuốt chúng. Lũng Đông suy đoán con thú là biến dị Cổ Thú và chính chiếc lưỡi nguy hiểm ấy đã phá hủy Linh Vân Chu. Cả đội chia thành hai phe khi Lý đạo hữu và Diệp Dĩnh muốn đoạt linh quả, còn Lũng Đông cùng Chu Hồng lo nhiệm vụ bị trì hoãn và Cự Nhân có thể đang chờ viện thủ. Hàn Lập quyết định ủng hộ việc mạo hiểm nhưng giới hạn thời gian hành động trong ba ngày, đồng thời đề xuất dụ hai đối thủ rời đi hoặc kích động chúng giao chiến. Chu Hồng và Lũng Đông cuối cùng chấp thuận với điều kiện kế hoạch không quá nguy hiểm và phải có tính khả thi."},{"chuong":1361,"tieuDe":"Khiêu Khích","tomTat":"Nhóm Lũng Đông thống nhất dùng hai Ngân Giao Khôi Lỗi phối hợp với Không Minh Phù để giả tạo công kích từ Cự Đại Tích Dịch và Thiên Mục Cự Nhân, khiến chúng hiểu lầm rồi giao chiến. Hàn Lập chủ động nhận nhiệm vụ đoạt linh quả, nhưng bác bỏ đề nghị đơn phương chịu cấm chế vì từng gặp họa trong lần hạ cấm chế lẫn nhau với Băng Phượng. Hai bên đổi sang phương án để bốn đồng bạn giữ bốn khẩu kim kiếm bổn mạng của hắn làm vật thế chấp, đồng thời trao đổi dấu hiệu linh lực để cảm ứng vị trí lẫn nhau. Sau khi tách nhóm, Hàn Lập kiểm tra không bị giám sát, gọi Thanh Bạch vũ sí rồi dùng Thái Nhất Hóa Thanh Phù hóa thành hư không và bí mật quay lại khu vực linh quả. Từ nơi ẩn nấp, hắn xác định bốn đồng bạn đều đã vào vị trí và chờ kế hoạch phát động. Chùm ngân ti cùng cột sáng bạc lần lượt đánh lừa hai quái vật, khiến Cự Đại Tích Dịch đứng dậy và chuẩn bị giao chiến với Thiên Mục Cự Nhân."},{"chuong":1362,"tieuDe":"Đoạt Quả","tomTat":"Hai khôi lỗi mình người đầu rồng được dùng làm mồi nhử nhưng nhanh chóng bị Cự Đại Tích Dịch và Thiên Mục Cự Nhân phá hủy, khiến kế hoạch kích động hai quái vật giao chiến thất bại. Diệp Dĩnh cùng Lũng Đông chuyển sang kiềm chế Cự Đại Tích Dịch, còn Thiếu phụ và Lý đạo hữu quấy rối Thiên Mục Cự Nhân rồi dùng các phương tiện độn thuật né phản kích. Hai Cổ Thú lần lượt bộc lộ hồng hà, lông nhọn, cự vĩ, hắc tuyến và khả năng hấp thu hắc diễm, nhưng sự chú ý của chúng đối với cây quả vẫn bị kéo giảm. Hàn Lập nhân cơ hội hóa vào hư không, lặng lẽ hạ xuống gần Chi Long Quả và ném các ngân viên cầu về phía hai quái vật. Hắn hái trọn chùm Linh Quả vào tay áo, sau đó dùng Lôi Độn, tàn ảnh và thuấn di dưới đất để thoát khỏi đòn hợp kích tức thời. Cuối chương, các ngân viên cầu bùng nổ thành vùng điện quang rộng lớn, phóng vô số điện hồ và bao phủ cả hai Cổ Thú."},{"chuong":1363,"tieuDe":"Chia Quả","tomTat":"Hàn Lập dùng bốn viên Lôi Châu cầm chân Cự Đại Tích Dịch và Thiên Mục Cự Nhân, sau đó kết hợp Phong Lôi Sí với Huyết Ảnh Độn để mang linh quả chạy xa mấy vạn dặm. Khi đã tìm được một đỉnh núi an toàn, hắn uống đan dược hồi phục nguyên khí và xác nhận chiến lợi phẩm là sáu quả Chi Long Quả chính hiệu. Hàn Lập nhận ra mình chỉ còn thiếu Đằng Vân Giao cùng một số dược vật căn bản để có thể luyện Đằng Long Đan. Lũng Đông, Lý đạo hữu, Tiểu Hồng và Diệp Dĩnh lần lượt hội họp, trong đó Diệp Dĩnh đến muộn vì phát hiện một gốc Bích Linh Mộc vạn năm. Năm người mỗi người nhận một Chi Long Quả, còn Tiểu Hồng và Lý đạo hữu đồng thời tháo cấm chế, hoàn trả Thanh Trúc Phong Vân Kiếm cho Hàn Lập. Đề nghị đấu giá quả thứ sáu của Lũng Đông bị bác bỏ vì ưu thế tài lực của Lũng gia, nên cả nhóm thống nhất sẽ dùng linh đan, tài liệu hoặc vật phẩm tương xứng để trao đổi. Sau đó họ rời đi bằng phi xa, còn Hàn Lập giữ gốc Bích Linh Mộc và dự định tiếp tục nuôi dưỡng để sử dụng về sau."},{"chuong":1364,"tieuDe":"Thành Nhỏ","tomTat":"Bạch bào thiếu nữ dùng lượng lớn tài liệu quý hiếm đổi lấy linh quả cuối cùng, còn Hàn Lập chọn một đoạn bích linh mộc vạn năm từ phần tài liệu của nàng. Đoàn người chuyển sang phi xa do Lũng Đông cung cấp vì tốc độ của nó cao hơn Linh Vân Chu, trong khi Hàn Lập âm thầm nhận định bạch bào thiếu nữ là người khó dò xét nhất đoàn. Sau nửa tháng, họ tới Nam Cấn đại sa mạc và buộc phải đi xuyên qua nơi này vì Thái Thú sơn mạch cùng Giao Uyên đại hạp cốc đều quá nguy hiểm. Cả đoàn cất phi xa, thi triển thuật ẩn thân và bay thấp để tránh Mộc Tộc, Ảnh Tộc cùng các mối đe dọa khác. Bạch bào thiếu nữ kể Nam Cấn vốn là vùng núi lửa, về sau bị bão cát của Thiên Phượng vùi lấp trong cuộc đại chiến với Hỏa Ngạc. Mười ngày sau, Lý đạo hữu phát hiện một ốc đảo có thành nhỏ và dùng hóa thân chim ưng xác nhận bên trong có nhân tộc cùng tám tu sĩ Hóa Thần kỳ. Hàn Lập muốn tránh can dự, nhưng Lũng Đông cho rằng tình hình quá bất thường và quyết định phải hỏi rõ trước khi tiếp tục hành trình."},{"chuong":1365,"tieuDe":"Ma Ảnh Tái Hiện","tomTat":"Trên đường tới Nhất Tuyến Thiên, nhóm Hàn Lập phát hiện một ốc đảo có thành nhỏ và quyết định quan sát để đề phòng nguy hiểm. Một lão đạo sĩ Luyện Hư trung kỳ tự xưng Tử Vân thượng nhân bất ngờ xuất hiện, cảnh báo Nhất Tuyến Thiên vừa xảy ra biến cố rồi mời cả nhóm vào thành. Khi đi qua hàng thủ vệ, Hàn Lập dùng lửa bạc đánh vào một người, ép bóng xám của Ảnh tộc rời khỏi vật chủ và thiêu diệt nó. Tử Vân thượng nhân lập tức dùng bàn tay hồng quang trấn áp, nhưng Hàn Lập dựa vào thể chất mạnh mẽ cùng Tật Phong Cửu Biến để thoát thân. Nhận ra cư dân trong thành đều là con rối bị phụ thể, Hàn Lập cảnh báo đồng đội và dẫn đầu cuộc tháo chạy. Tử Vân thượng nhân phóng vô số hồng ti, quấn lấy một thành viên trong nhóm và kéo người đó khỏi độn quang, nhưng danh tính người bị bắt chưa được tiết lộ."},{"chuong":1366,"tieuDe":"Thận Thú","tomTat":"Bị hồng ti của đạo nhân khóa chặt, Lý đạo hữu hóa thành hình thái nửa yêu Huyền Ưng nhưng vẫn không thể thoát vì những sợi tơ liên tục khôi phục. Khi nhận ra đối phương có Xích ảnh, hắn tự bạo yêu đan khổ tu nhiều năm thay vì để nhục thân bị chiếm đoạt, song một đạo hồng ảnh đã cuốn lấy cả hắn lẫn vụ nổ. Đạo nhân sau đó phái tám thuộc hạ chia đường truy sát, đồng thời giải trừ thành trì, hồ nước và phàm nhân giả, để lộ quái thú song đầu đầu rắn thân ếch là nguồn tạo ra cảnh tượng ấy. Lão cưỡi quái thú hóa thành hắc khí và trực tiếp đuổi theo hướng Hàn Lập bỏ chạy. Ở một hướng khác, thiếu phụ phát hiện viên châu trên ngọc bài đã vỡ, rồi bị đôi nam nữ do Ảnh Tộc nhập thân đuổi kịp và phải hóa thành hắc phượng nghênh chiến. Lũng Đông cũng bị truy sát nhưng đã kích phát Hoàng Sắc Đồng Giáp Phù, dùng huyết sắc trường kiếm tạo vô số bạch ti và chém nát đồng thời hai chân thân Ảnh Tộc."},{"chuong":1367,"tieuDe":"Ác Chiến Sa Mạc","tomTat":"Sau trận chiến trước đó, Lũng Đông thu hồi thanh huyết kiếm dưới dạng tinh huyết, uống một viên đan dược đỏ tươi rồi nhanh chóng rời khỏi sa mạc. Ở một nơi khác, bạch bào thiếu nữ đứng cạnh bốn thi thể không có thương tích, vuốt ve bình ngọc trắng và hóa thành kim quang bay đi. Hàn Lập không thể cắt đuôi lão đạo Ảnh tộc nên quyết định quay lại nghênh chiến, dùng Phá Diệt Pháp Mục, Thất Thần Thứ và Tịch Tà Thần Lôi để đánh phủ đầu. Quái thú hai đầu rắn thân ếch do hắc khí hộ thể huyễn hóa đã thay lão đạo gánh phần lớn lôi điện. Hàn Lập tiếp tục sử dụng Nguyên Từ thần sơn cùng năm chiếc khô lâu cốt giới, nhưng tiểu đao trong suốt, kiếm quang đỏ sậm và quái thú hộ thân của đối phương lần lượt hóa giải các đòn công kích. Quái thú cuối cùng phát ra sóng chấn động, triệu tập vô số quái thú lớn nhỏ và khép vòng vây quanh Hàn Lập giữa sa mạc."},{"chuong":1368,"tieuDe":"Trùng Uy","tomTat":"Hàn Lập dùng hàng trăm kim sắc phi kiếm chém giết đàn quái thú huyễn hóa, nhưng thi thể của chúng biến thành hắc vụ và dần làm chậm kiếm quang. Nhờ Minh Thanh Linh Mục, hắn kịp dùng hai bàn tay đỡ hai chiếc lưỡi tập kích vào đầu và tim, rồi phát huy sức mạnh của Nguyên Từ thần sơn cùng Ngũ Tử Đồng Tâm Ma đã dung hợp vào hai cánh tay để phá hủy chúng. Khi quái thú hoàn toàn ẩn hình, Hàn Lập thả hơn một nghìn Phệ Kim trùng thành thục thể phủ kín không gian, ép nó hiện thân rồi cắn nuốt cả thân thể đã hóa thành hắc khí. Nhận ra đàn linh trùng đáng sợ, Tử Vân thượng nhân lập tức bỏ lại thân xác và quái thú, để nguyên thần hóa thành xích sắc kinh hồng tháo chạy. Sau trận chiến, Hàn Lập phát hiện thần thức của mình đã âm thầm hao tổn bảy tám phần và suýt tổn thương nguyên thần. Thử nghiệm với một con Phệ Kim trùng giúp hắn xác nhận mỗi thành thục thể đều liên tục tiêu hao thần niệm, trong khi mức hao tổn chỉ được phát hiện nếu hắn chủ động kiểm tra."},{"chuong":1369,"tieuDe":"Hội Hợp","tomTat":"Hàn Lập kiểm tra đàn Phệ Kim Trùng thành thục và xác định chúng tự hút thần niệm quấn quanh thân khi hoạt động, khiến việc sử dụng cả đàn trong chiến đấu kéo dài có thể đẩy người điều khiển vào nguy hiểm. Chưa tìm được cách khắc phục, hắn giữ đàn linh trùng làm đòn sát thủ rồi bí mật vượt sa mạc trở lại Nhất Tuyến Thiên. Trên đường, Hàn Lập xem xét dược bình bị Thiên Uyên thành đặt cấm chế và dùng quang bào phóng lôi quang vàng bạc tiêu diệt một đàn quái điểu đầu vàng. Tại di tích thượng cổ, Du Hồng và Lũng Đông đón Diệp Dĩnh trở về, đồng thời nhận định Lý đạo hữu bị Ảnh Tộc bắt có lẽ dữ nhiều lành ít. Ba người quyết định chờ Hàn Lập thêm tối đa hai ngày, sau đó dùng định vị bàn hồi đáp tín hiệu và dẫn hắn tới điểm tập kết. Bốn người chỉ nghỉ thêm nửa ngày rồi rời di tích để tránh Ảnh Tộc tiếp tục dây dưa. Khi tiến vào vùng bão cát trước Nhất Tuyến Thiên, cả nhóm mở hộ thể linh quang chống cuồng phong và được Du Hồng cảnh báo phải đề phòng cạm bẫy phía trước."},{"chuong":1370,"tieuDe":"Linh Thụ Mộng La","tomTat":"Hàn Lập dùng linh mục quan sát dị tượng Nhất Tuyến Thiên, nơi hắc sắc mê vụ và lốc cát vàng bị một khe bạch quang khổng lồ phân cách. Lũng Đông dẫn đội nuốt Định Phong Châu để chống gió bão và phong nhận, nhưng sau khi bị hút vào khe hở, Hàn Lập mất dấu toàn bộ đồng đội và phải tiếp tục một mình. Vài ngày sau, hai tu sĩ cẩm bào đeo băng tím có dung mạo khá giống Lũng Đông cũng xuất hiện rồi tiến vào Nhất Tuyến Thiên. Mấy tháng sau, Hàn Lập tới gần Hắc Diệp Sâm Lâm, chờ đồng đội nửa tháng nhưng không thể liên lạc với ai nên quyết định độc lập hoàn thành nhiệm vụ lấy tình báo và dò xét Mộc Tộc. Để tránh linh giác của Mộc Tộc cùng sự giám sát của Mộng La Linh Thụ, hắn hành động vào ban đêm, thi triển thuật ẩn nấp, thu liễm khí tức và phối hợp Tật Phong Cửu Biến với La Yên Bộ để di chuyển dưới tán rừng. Khi còn cách điểm hẹn khoảng ba ngày đường, Hàn Lập nghe tiếng bước chân nặng nề, ẩn vào tán cây và nhìn thấy hai cự viên xanh biếc mang đồng xiên đi ngang phía dưới."},{"chuong":1371,"tieuDe":"Hắc Diệp Sâm Lâm","tomTat":"Hàn Lập tiến sâu vào Hắc Diệp Sâm Lâm và phát hiện những trường mao thú ba mắt mang binh khí, khiến hắn nghi ngờ chúng là dị tộc có linh trí hoặc chiến thú mới của Mộc Tộc. Một ngày sau, tám trường mao thú lông đỏ dùng con mắt thứ ba nhìn thấu chỗ ẩn nấp của hắn, nhưng đều bị Kim sắc tiểu kiếm phân hóa thành tám kim ti giết chết trước khi thi thể bị thiêu sạch. Hàn Lập không biết rằng các đại thụ có mắt xanh trong rừng đã theo dõi cả hắn lẫn Lũng Đông và Tiểu Hồng. Sau một trận chiến khác, Lũng Đông và Tiểu Hồng để lộ thỏa thuận rằng nàng sẽ lấy một vật phục vụ đại sự trong tộc, còn hắn nhắm tới người mang Thiên Phượng Huyết. Tại một khu cấm chế bí ẩn, nhân ảnh mắt bích lục báo cáo tin tức cho bóng người cao lớn, khiến cả nhóm lập tức dùng Ngân sắc tiểu thụ truyền tống rời đi. Dù cảm thấy bất an vì hiếm khi gặp người Mộc Tộc, Hàn Lập vẫn không rút lui bởi nhiệm vụ liên quan trực tiếp đến Diệt Trần Đan. Hai ngày sau, hắn dùng pháp bàn tìm được cổ thụ nửa cháy tại ngọn núi mục tiêu, đưa ngân châu xuống lòng đất bằng Ngân sắc Hỏa Điểu, bố trí trận kỳ quanh núi rồi ẩn mình tiến vào."},{"chuong":1372,"tieuDe":"Mộc Tộc","tomTat":"Hàn Lập tới cây cổ thụ dùng làm điểm cất giấu tình báo, chém cây và tìm thấy một ngọc giản, nhưng Diệp Dĩnh bất ngờ hiện thân giành lấy trước. Lũng Đông và Tiểu Hồng tới sau, khiến bốn người tái hợp trong thế giằng co vì Diệp Dĩnh không chịu giao ngọc giản cho Tiểu Hồng kiểm tra. Trước khi bất kỳ ai đọc được nội dung, quang ti gần như vô hình của một cự trùng trong suốt đánh vỡ ngọc giản thành vô số mảnh. Mộc Thụy cùng các Mộc linh đai cam lập tức lộ diện, xác nhận họ đã lần theo nhóm Hàn Lập để tìm ra điểm cất giấu tình báo. Thuộc hạ của Mộc Thụy phát tán lục quang, phá tan ảo thuật cấm chế và biến cây cối quanh khu đồi thành hàng nghìn mộc vượn thú có vũ trang. Mộc Thụy tiết lộ giống thú này là thành quả Mộc Tộc nghiên cứu gần nghìn năm và tuyên bố sẽ giữ toàn bộ nhóm thâm nhập lại. Đúng lúc vòng vây khép kín, một giọng nói xa lạ vang lên từ hư không ra lệnh động thủ, khiến Diệp Dĩnh phóng nhiều huyết ti tấn công tất cả Mộc linh đai cam nhưng loại trừ Mộc Thụy."},{"chuong":1373,"tieuDe":"Sáu Tay Sơ Hiện","tomTat":"Huyết ti của Bạch bào thiếu nữ trói chặt nhiều mộc linh, còn một kim sắc phù trận bất ngờ vây giữ Mộc Thụy, tạo cơ hội cho nhóm Hàn Lập chia đường đào thoát. Thiếu phụ hóa thành hỏa phượng, Lũng Đông kích phát hư ảnh Ngũ Trảo Kim Long nhập thể, còn Hàn Lập dùng Huyết Ảnh Độn lao khỏi vòng vây. Bạch bào thiếu nữ dùng hồng sắc trường đao dẫn động thiên địa nguyên khí, thiêu hơn trăm mộc viên thú thành tro rồi thi triển độn thuật quỷ dị rời chiến trường. Mộc Thụy phá phần lớn phù văn và phát lệnh cho lực lượng Mộc Tộc chia nhau truy kích những người đang chạy trốn. Sau hai lần sử dụng Huyết Ảnh Độn, Hàn Lập bị tổn thương nguyên khí nhưng vẫn phối hợp Phong Lôi Sí để duy trì tốc độ. Khi ba Mộc Tộc phục kích, hắn dựa vào thân thể cường hãn giết một kẻ và lấy tinh thể trong cơ thể đối phương. Hai tay Hàn Lập sau đó bị lục quang giữ chặt, buộc hắn niệm chú làm kim quang bùng lên và lần đầu hiện thêm bốn cánh tay vàng mơ hồ dưới sườn."},{"chuong":1374,"tieuDe":"Lui Địch","tomTat":"Hàn Lập vận dụng Phạm Thánh Chân Ma Công cùng Thanh Trúc Phong Vân Kiếm phá tan những Mộc Linh đang kiềm giữ mình, đồng thời nhận ra đệ nhị quyết hiện chỉ thích hợp cho tập kích bất ngờ. Trên đường rời Hắc Diệp Sâm Lâm, hắn bị hai Mộc Linh tử giai cùng bốn mộc viên chặn lại nên dùng Nguyên Từ Thần Quang đánh lạc hướng và âm thầm triển khai Đại Canh Kiếm Trận. Kiếm ti trong trận giết sạch cả sáu đối thủ, khiến Hàn Lập xác nhận uy lực của kiếm trận vượt xa dự đoán. Trong khi đó, Tiểu Hồng bị ba Mộc Linh tử giai chặn đường, Lũng Đông bị kim mao mộc viên truy sát, còn hai đạo bạch hồng và ngân quang tiếp tục truy đuổi nhau ra khỏi rừng. Sau khi thoát khỏi rừng, Hàn Lập dùng Thái Nhất Hóa Thanh phù ẩn thân và đổi hướng, nhờ đó tránh được hai Mộc Linh cấp Luyện Hư đang lần theo dấu vết. Vì ngọc giản tình báo đã bị phá hủy, hắn suy đoán thiếu nữ áo bào trắng có thể là người nằm vùng đang giữ tình báo thật và quyết định tìm nàng. Hàn Lập gọi báo lân thú ra, dùng đan dược khiến nó hợp tác rồi cho nó nuốt nhũ quang lấy từ pháp bàn để bắt đầu truy tìm."},{"chuong":1375,"tieuDe":"Mộc Phượng","tomTat":"Hàn Lập dùng tinh khí của Diệp Dĩnh để báo lân thú truy tìm nàng bằng thiên phú thần thức cảm ứng, đồng thời tiếp tục giữ Phệ Linh Thiên Hỏa ẩn dưới đất làm phục binh. Sau ba ngày ba đêm liên tục đổi hướng, hắn đoán Diệp Dĩnh đang bị truy đuổi nhưng vẫn tiến lên vì nàng có liên quan đến Diệt Trần Đan. Sáng ngày thứ tư, báo lân thú xác nhận mục tiêu đã dừng, khiến Hàn Lập thay lá Thái Nhất Hóa Thanh Phù gần cạn uy năng bằng một lá mới rồi ẩn thân tiếp cận hòn đảo phía trước. Tại trung tâm đảo, hắn thấy Diệp Dĩnh đang bị thương và đứng cạnh một nữ tử da xanh tỏa ra hỏa linh lực mạnh mẽ. Diệp Dĩnh bất ngờ nhìn thấu trạng thái ẩn thân của Hàn Lập, buộc hắn phải hiện thân. Nàng giới thiệu nữ tử kia là Diệp Sở, người của Diệp gia được phái nằm vùng trong Mộc Tộc. Diệp Sở xác nhận mình là Nhân Tộc mang Mộc Phượng linh huyết, đã đạt Luyện Hư hậu kỳ đại thành và nhờ huyết mạch này mà vượt qua cuộc điều tra của Mộc Tộc. Nàng cũng tiết lộ toàn bộ người nằm vùng khác đã bị phát hiện và giết chết, khiến mình trở thành người sống sót duy nhất trong mạng lưới."},{"chuong":1376,"tieuDe":"Hoàn Thành Nhiệm Vụ","tomTat":"Diệp Sở cho biết nàng đã hoàn thành việc thu thập bí mật trong nhiều năm tiềm phục tại Mộc Tộc, nhưng thân phận bại lộ khiến nàng không thể tiếp tục ở lại. Hàn Lập đưa Bách Thánh hoàn và Hồi Linh thủy cho Bạch Bào Thiếu Nữ chữa nội thương, đồng thời biết công pháp của nàng có thể khắc chế một phần khả năng ẩn nấp của Thái Nhất Hóa Thanh Phù. Diệp Sở giao ngọc giản tình báo, còn Bạch Bào Thiếu Nữ kích hoạt Truyền Tống trận loại nhỏ để chuyển nó về Thiên Uyên Thành, khiến pháp bàn dùng để truyền tống bị hủy hoàn toàn. Hàn Lập và thiếu nữ sau đó nhận hồi đáp qua vạn lý phù; riêng Hàn Lập được trao phương pháp giải cấm chế trên bình Diệt Trần Đan, xác nhận nhiệm vụ đã hoàn thành và hắn giành lại tự do. Diệp Sở dùng khôi lỗi mộc điểu chở cả ba rời khỏi lãnh địa Mộc Tộc, trong khi Lũng Đông và Tiểu Hồng không được nhắc tới, còn một đạo ngân hồng bí ẩn xuất hiện sau đó và đuổi theo hướng họ rời đi. Sau một tháng liên tục chạy trốn, nhóm tới gần Nhất Tuyến Thiên thì cuồng phong, mây đen và sấm sét nổi lên, một tồn tại khổng lồ có hai cặp mắt vàng xuất hiện và dùng uy áp khiến Hàn Lập không thể cử động."},{"chuong":1377,"tieuDe":"Chân Linh Chi Phách","tomTat":"Hàn Lập thoát khỏi sự chấn nhiếp của đầu rồng vàng nhờ vận chuyển Đại Diễn Quyết, còn Diệp Sở nhận ra linh lực của nó chỉ tương đương yêu tu Hợp Thể trung kỳ. Thiếu nữ áo bào trắng xác định đây là chân long chi phách được tạo ra bằng cách cưỡng ép kích phát chân long huyết, đồng thời vạch rõ ý đồ của Lũng Đông nhằm đoạt thiên phượng chân huyết. Nàng cho rằng Lũng gia còn phái một tu sĩ Luyện Hư bí mật đi theo hỗ trợ và quyết định tự kích phát thiên phượng chi phách để nghênh chiến. Với Hàn Lập hộ pháp và Diệp Sở truyền mộc linh khí, nàng dựng pháp trận, gọi ra năm bảo vật rồi phục dụng linh đan ngũ sắc. Hư ảnh huyết mạch trên đầu nàng hóa thành Thải Phượng khổng lồ dài trăm trượng, đối đầu kim long dài hơn hai trăm trượng. Kim long điều động điện giao và phun kim sắc quang trụ, trong khi Thải Phượng dẫn động cuồng phong cùng biển bạch diễm, khiến không trung bị bao phủ bởi lôi điện, gió dữ và hỏa diễm. Chứng kiến hai chân linh chi phách cắn xé lẫn nhau, Hàn Lập càng tin rằng chân long và thiên phượng chân chính có thể là những tồn tại nghịch thiên không sợ chân tiên."},{"chuong":1378,"tieuDe":"Huyết Tinh Ma Ha Kiếm","tomTat":"Diệp Dĩnh điều khiển thải phượng chuyển phong lực thành cực hàn chi lực, phối hợp băng liên với hỏa diễm để đẩy lui lôi điện của kim long. Người điều khiển kim long khiến cự long hóa thành huyết sắc, triệu ra Huyết Tinh Ma Ha Kiếm rồi nhập vào kiếm, chém tách Huyết Phượng hư ảnh và hút hơn phân nửa Thiên phượng huyết của nàng. Diệp Sở xác định linh huyết mới chỉ bị ma kiếm giam giữ và thuyết phục Hàn Lập cùng tham gia đoạt kiếm, còn Diệp Dĩnh hứa Diệp gia sẽ báo đáp hắn. Khi ba người tiếp cận ma kiếm, Lũng Vũ và Lũng Lân hiện thân ngăn cản, đồng thời tuyên bố thiếu chủ Lũng gia sắp thu đủ long phượng chân huyết. Diệp Dĩnh nghi ngờ Âm Dương Lưỡng Cực Quyết đã được Lũng gia cố ý bán cho mình để tạo sơ hở cho ma kiếm tách Thiên phượng huyết, nhưng hai tu sĩ đối phương không trả lời. Diệp Sở phát động lục quang mộc linh, Lũng Vũ và Lũng Lân dùng cổ thư cùng hắc họa gọi huyết quang và hắc phong chống đỡ, còn Diệp Dĩnh tế Kim Đao cùng viên hoàn thúy lục tham chiến."},{"chuong":1379,"tieuDe":"Xích Quỷ","tomTat":"Diệp Dĩnh dùng kim sắc đoản đao, viên hoàn xanh biếc cùng ba nhạc khí tấn công tuyến phòng thủ quanh huyết sắc cự kiếm, nhưng bị bảy Xích Quỷ liên tiếp ngăn cản. Ở một hướng khác, Diệp Sở bị đám ma quỷ đầu lâu của hai tu sĩ Lũng gia vây trong tử sắc ma chướng rộng trăm trượng và chưa thể thoát thân. Tiểu Hồng ngăn Hàn Lập can thiệp, yêu cầu phe Diệp gia giao Thiên Phượng chi linh và tiết lộ Yêu Tộc từng cài người nằm vùng tại Mộc Tộc. Diệp Sở phủ nhận đang giữ linh vật, nhưng không thể khiến Tiểu Hồng nhượng bộ. Hàn Lập bác bỏ đề nghị cùng đứng ngoài vì cho rằng Lũng Đông hoàn tất dung hợp chân linh huyết sẽ đặt mình vào tình thế nguy hiểm. Hắn lập tức áp sát Tiểu Hồng bằng La Yên Bộ và Tật Phong Cửu Biến, rồi liên tiếp triển khai Nguyên Từ Thần Quang, ngũ sắc cực hàn chi diễm, Phong Lôi Sí và hàng trăm đạo kiếm quang. Trước chuỗi công kích dồn dập, Tiểu Hồng phải dùng hắc diễm, ô quang và bạch ti võng phòng thủ, cuối chương rơi vào tình thế hiểm nghèo."},{"chuong":1380,"tieuDe":"Lực Áp Hắc Phượng","tomTat":"Hàn Lập dùng kiếm quang, Ngũ Sắc Quang Diễm và Nguyên Từ Thần Quang áp đảo ti võng, hắc diễm cùng cổ kính của Tiểu Hồng. Tiểu Hồng hiện nguyên hình Hắc Phượng và mở khe nứt hư không bỏ chạy, nhưng bị Phá Diệt Pháp Mục ép hiện thân rồi trúng Thất Thần Thứ. Hàn Lập dùng thanh ti trói nàng, đánh nàng bất tỉnh, lấy trữ vật thủ trạc và dùng Nguyên Từ Thần Sơn trấn áp, song không giết để tránh kết tử thù với các thế lực Yêu Tộc. Hai tu sĩ Lũng gia kinh ngạc trước chiến lực vượt cấp của hắn, trong đó một người phóng huyết quang tập kích nhưng bị Diệp Sở chuyển hướng. Hàn Lập nhân cơ hội dùng lôi độn áp sát Huyết Tinh Ma Ha Kiếm và lấy sức mạnh thân thể đánh vỡ nhũ sắc quang thủ của một tu sĩ Luyện Hư. Hắn tiếp tục dùng hai lôi châu cùng kim sắc kiếm khí phá vỡ quầng sáng bảo hộ ma kiếm. Tuy nhiên, hơn mười bóng đen bất ngờ xuất hiện sau một tiếng quái rống và đánh tan toàn bộ kiếm khí còn lại."},{"chuong":1381,"tieuDe":"Đề Hồn Biến Thân","tomTat":"Vô Tướng Quỷ Vương hiện thân sau khi ngân sắc lôi điện tan hết, hấp thu âm khí chữa lành thương thế rồi dùng quỷ trảo và hắc mang tấn công Hàn Lập. Hàn Lập thả Đề Hồn thú ra ứng chiến, để linh thú dùng thần quang nhiếp hồn hóa giải quỷ thuật và hấp thu âm khí. Khi Vô Tướng Quỷ Vương gọi ra đôi bạch cốt cự chùy đánh tan thần quang, Đề Hồn thú biến thân lần thứ hai, mọc ba sừng, yêu mục đỏ và ba xương gai. Huyết sắc điện hồ từ yêu mục phá hủy cốt chùy cùng chiến giáp, xuyên thủng quỷ vương rồi kéo nó vào miệng Đề Hồn thú. Nhân lúc mọi người còn kinh hãi, Hàn Lập dùng bảy mươi hai phi kiếm chém vỡ quầng sáng bảo hộ Huyết Tinh Ma Ha Kiếm, nhưng cự kiếm vàng và lôi châu đều không thể phá hủy bản thân linh bảo. Hai tu sĩ Lũng gia tiết lộ huyết kiếm là thượng bảo trên Hỗn Độn Vạn Linh Chi Bảng. Hàn Lập lập tức chuyển sang bố trí Đại Canh Kiếm Trận quanh huyết kiếm, dự định ép nguyên thần Lũng Đông ra ngoài hoặc trực tiếp hủy diệt linh bảo."},{"chuong":1382,"tieuDe":"Kiếm Trận Vs Huyết Kiếm","tomTat":"Hàn Lập hoàn tất Đại Canh kiếm trận, dùng tơ vàng vây cắt Huyết Tinh Ma Ha Kiếm và lấy Ích Tà thần lôi tiêu diệt phần lớn ma ảnh do Lũng gia song tu phóng ra. Đề Hồn thú dùng thanh hà nuốt ba ác quỷ, giải vây cho bạch bào thiếu nữ để nàng sang phối hợp với Diệp Sở giữ chân đối phương. Lũng Đông lần lượt uy hiếp và mua chuộc Hàn Lập nhưng không thể khiến hắn ngừng vận chuyển kiếm trận. Khi thân kiếm đầy vết nứt, Huyết Tinh Ma Ha Kiếm bất ngờ tự bạo, phá tan kiếm trận và buộc mọi người ở gần phải thuấn di lánh xa. Hàn Lập thoát khỏi vùng nổ, song hơn mười khẩu Thanh Trúc Phong Vân Kiếm bị tổn thương linh tính. Nhờ Minh Thanh linh mục, hắn phát hiện một huyết long đang ngậm huyết phượng bị thương và lợi dụng vùng sáng để đào thoát. Hàn Lập lập tức dùng hàn diễm năm màu vây khốn huyết long rồi gọi Hư Thiên Đỉnh ra."},{"chuong":1383,"tieuDe":"Thiên Phượng Chi Linh","tomTat":"Nguyên thần Lũng Đông hóa chân linh thành huyết sắc kiếm quang để chống trả, nhưng Hàn Lập dùng thanh ti của Hư Thiên Đỉnh thu hàn diễm năm màu cùng các phần chân linh huyết. Lũng Đông thoát khỏi vòng vây và liên tục thuấn di; dù bị Phá Diệt Pháp đánh trúng, hắn vẫn chạy khỏi tầm truy kích. Hai tu sĩ Lũng gia cùng bọn ác quỷ và ma vật rút lui theo hướng Lũng Đông, trong khi Diệp Dĩnh và Diệp Sở đến gặp Hàn Lập. Hàn Lập giao phần huyết phượng cho Diệp Dĩnh, giúp nàng dung hợp và thu hồi khoảng bảy tám phần chân phượng huyết. Khi Diệp Dĩnh yêu cầu cả chân long huyết, Hàn Lập giữ vật này làm điều kiện trao đổi vì nó còn lẫn một phần chân phượng huyết. Sau khi từ chối linh thạch và Chi Long Quả, hắn yêu cầu một chiếc Thiên phượng chi linh để luyện chế bảo vật, và Diệp Dĩnh chấp thuận. Theo lệnh thiếu chủ, Diệp Sở lấy ra một hộp ngọc đỏ tỏa nhiệt mạnh, khiến Hàn Lập nhận ra nó được chế từ Viêm ngọc."},{"chuong":1384,"tieuDe":"Ám Thủ","tomTat":"Hàn Lập kiểm tra thiên phượng chi linh do Diệp gia đưa ra, xác nhận là vật thật rồi giao phần chân long huyết chính cho Diệp Dĩnh và Diệp Sở. Hắn từ chối lời mời làm khách khanh Diệp gia, giao Tiểu Hồng cho Diệp Sở và kiên quyết tách đoàn dù khu vực vẫn nằm trong phạm vi Mộc tộc. Sau khi hắn rời đi, Diệp Dĩnh tiết lộ ý định bắt giữ hắn, nhưng Diệp Sở cho biết nàng đã bí mật ngăn cản vì không chắc có thể giết hoặc bắt sống đối phương. Diệp Sở đánh giá Hàn Lập còn giấu sát chiêu, đồng thời ưu tiên đưa chân long huyết về nên cùng Diệp Dĩnh cưỡi mộc điểu rời khỏi khu vực. Khi đã bay xa, Hàn Lập lấy Hư Thiên Đỉnh ra, dùng chú thuật khiến hai Phệ Kim Trùng trưởng thành nhả phần chân long huyết và chân phượng huyết mà hắn bí mật giữ lại. Chưa biết cách sử dụng hai loại chân linh huyết quý hiếm, hắn phong kín chúng trong mộc hạp rồi cảnh giác quan sát phía sau."},{"chuong":1385,"tieuDe":"Mộc Linh","tomTat":"Hàn Lập nhận ra kẻ truy đuổi mình là Ngân giai mộc linh từng xuất hiện trong rừng rậm lá đen và biết rằng Hóa Thanh Phù khó giúp hắn thoát khỏi sự khóa chặt của thần niệm đối phương. Nhận thấy mộc linh đã trọng thương, hắn đáp xuống một đỉnh núi, dùng bảy mươi hai phi kiếm bố trí Đại Canh kiếm trận, đồng thời dựng quang hà và quang hoàn cực hàn chi diễm năm màu để phòng ngự. Ngân giai mộc linh tới nơi, dùng quyền lực vô hình chấn động các tầng phòng hộ rồi triệu ra mộc giáp xanh biếc để áp sát tấn công. Hàn Lập phát động kiếm trận, khiến vô số tơ vàng liên tục khép lại quanh đối thủ. Mộc linh nhiều lần dùng thanh mang, ngân mang và thân pháp tìm cách phá vây, nhưng đều bị Hàn Lập dùng Lôi độn cùng song quyền ép trở lại. Khi thế trận kéo dài, mộc linh kích phát toàn bộ gai trên chiến giáp thành vô số mũi tên bạc bắn khắp kiếm trận. Cuối chương, hắn tăng vọt hình thể, khiến thân thể trở nên xanh biếc và gọi ra hư ảnh cổ thụ đang điên cuồng lan rộng, để lại cuộc giao chiến chưa phân thắng bại."},{"chuong":1386,"tieuDe":"Người, Cây Hợp Nhất","tomTat":"Hư ảnh cổ thụ của Mộc Thụy cản lục kiếm ti và liên tục quét phá, khiến Đại Canh Kiếm Trận không thể tiếp tục khép lại. Mộc Thụy hòa vào bổn mạng linh thụ, hiện nguyên hình mộc linh chi thể dưới dạng cự nhân lục sắc cao mười trượng. Hàn Lập dùng ngũ sắc quang hoàn kiềm chế đối phương rồi huy động Lôi Châu, Lôi Bào, Phệ Linh Thiên Hỏa và toàn bộ phi kiếm hợp kích, nhưng thân thể Mộc Thụy vẫn không có một vết xước. Cự nhân bóp vỡ vòng trói buộc, dùng lục sắc linh quang giam Phệ Linh Thiên Hỏa và đánh bật Thanh Trúc Phong Vân Kiếm, khiến những phi kiếm vốn đã suy tổn linh tính càng thêm suy yếu. Nhận ra mình đã đánh giá thấp Ngân Giai Mộc Linh, Hàn Lập quyết định thử thêm một thủ đoạn cuối cùng và chuẩn bị dùng Huyết Ảnh Độn nếu thất bại. Hắn kích phát Phong Lôi Sí, tạo bốn thanh ảnh phối hợp đột kích, song Mộc Thụy chỉ vỗ một chưởng đã ép các phân ảnh hiện hình rồi tiêu diệt toàn bộ."},{"chuong":1387,"tieuDe":"Thoát Thân","tomTat":"Hàn Lập dùng nhiều hư ảnh và để Đề Hồn thú biến thành hình dáng của mình nhằm phân tán Mộc Thụy, sau đó áp sát và gieo Phệ Kim Trùng lên lưng đối phương. Khi bị cự thủ xanh bắt giữ, hắn thi triển Hóa Linh Phù Thế Kiếp, khiến thân thể tan thành linh quang rồi thoát ra ngoài. Đàn Phệ Kim Trùng thành thục phóng lớn, cắn mất gần nửa thân thể người cây của Mộc Thụy và buộc hắn phải rút lui. Hàn Lập cũng chủ động rời chiến trường, nhưng việc điều khiển đàn trùng truy kích từ khoảng cách quá xa khiến thần niệm của hắn gần như cạn kiệt. Mộc Thụy hấp thu lực lượng cây cối để phục hồi hình thể, song vì bổn mạng linh thụ tổn hao nghiêm trọng nên quyết định từ bỏ truy sát và trở về Hắc Diệp sâm lâm. Sau khi hồi phục sơ bộ, Hàn Lập tiếp tục hướng tới Nhất Tuyến Thiên, rồi dừng tại một cao nguyên hoang vu để dùng đan dược và bế quan hơn một tháng, cuối cùng khôi phục hoàn toàn tinh khí thần."},{"chuong":1388,"tieuDe":"Luyện Lại Phong Lôi Sí","tomTat":"Hàn Lập kiểm kê trữ vật trạc lấy từ Tiểu Hồng, phát hiện nhiều tài liệu yêu thú quý hiếm, cực phẩm linh thạch, linh dược và đan dược. Trong số chiến lợi phẩm, hắn tìm thấy một viên cực phẩm linh thạch phong thuộc tính, một viên Chi Long Quả và ba viên Hắc Viêm đan có thể hỗ trợ trùng kích bình cảnh Luyện Hư. Dù đã có Nguyên Từ Thần Quang giúp hợp nhất linh lực Ngũ Hành, hắn xác định trước mắt vẫn phải tiến lên Hóa Thần hậu kỳ và tìm dịch cóc qua nhiệm vụ liên quan đến Mộc Tộc. Sau khi kiểm tra Phong Lôi Sí bị thủng, Hàn Lập quyết định không chỉ sửa chữa mà còn dung hợp Thiên Phượng Chi Linh vào bảo vật. Hắn dùng ngân sắc hỏa diễm luyện Phong Lôi Sí cùng cực phẩm linh thạch phong thuộc tính và nhiều tài liệu phụ trợ trong mười ngày mười đêm. Thành phẩm chính thức tiến giai thành Linh Bảo, mang ngũ sắc hào quang, có trạng thái như ẩn như hiện và sở hữu uy năng vượt xa dự đoán của Hàn Lập."},{"chuong":1389,"tieuDe":"Tụ Tập","tomTat":"Hàn Lập dành một năm dùng nhất khẩu luyện chế lại mấy thanh Thanh Trúc Phong Vân Kiếm bị tổn hại, khôi phục linh tính cho chúng rồi rời nơi ẩn thân. Hắn mất hơn nửa năm vượt qua vùng núi hồ hoang dã, giết hơn mười dị thú tập kích trước khi tìm thấy cặp núi băng-tím đánh dấu địa điểm hội hợp. Liễu lão giả và Âu Dương đạo hữu ra đón, dùng lệnh bài mở ảo trận để dẫn hắn vào khu băng ốc bí mật trong lòng băng sơn. Tại đây, Hàn Lập gặp Oánh tiên tử, Triệu Đát, một đại hán áo bào tro cùng những thành viên khác của nhóm tu sĩ phi thăng. Hắn lấy lý do bị thương nhẹ và hao tổn pháp lực để từ chối trò chuyện, sau đó vào một băng ốc riêng điều tức trong lúc chờ ngày xuất phát. Sau khi hắn rời đi, mọi người bàn luận về thực lực vượt xa cảnh giới biểu hiện của hắn. Oánh tiên tử và Liễu lão giả tiết lộ Hàn Lập được mời vì thần thông của hắn có thể khắc chế Ảnh tộc, qua đó trở thành phương án đối phó Ảnh trùng thú đang đe dọa đại sự của cả nhóm."},{"chuong":1390,"tieuDe":"Mưu Đồ Chân Thiềm","tomTat":"Sau hơn mười ngày nghỉ ngơi, Hàn Lập được tiếng huýt của Chúc tiền bối triệu tập tới băng điện cùng gần hai mươi tu sĩ từ Hóa Thần kỳ trở lên. Chúc tiền bối tuyên bố những người tham chiến sẽ nhận Chân Thiềm Linh Huyết theo công lao, còn vợ chồng ông lấy Chu Thiên Tâm Hoa được quần thú bảo vệ. Oánh tiên tử cho biết sào huyệt có khoảng mười Bích Nhãn Chân Thiềm, gồm hai con trưởng thành mạnh ngang Luyện Hư trung kỳ, đồng thời còn được hơn trăm Hắc Huyết Nghĩ và hơn trăm Ảnh Trùng Thú hỗ trợ. Trước sự chất vấn của Du đạo hữu, Chúc tiền bối công bố kế hoạch dùng Đàn Hạc Hương dẫn đàn kiến tới nơi mai phục và giao tám tu sĩ dùng Huyền Thanh Thiên Lôi Kỳ lập Thiên Đô Hoàn Lôi Trận vây đàn Ảnh Trùng. Hàn Lập cùng Tiếu tiên tử được phân công hỗ trợ tiêu diệt Ảnh Trùng Thú nhờ công pháp có tính khắc chế, trong khi lực lượng còn lại tập trung đối phó Chân Thiềm. Sau ba ngày ba đêm bay về phía tây, đoàn người tới một hồ lớn phủ sương mù dày đặc và đồng loạt dừng bên ngoài vì lo ngại cổ thú phục kích."},{"chuong":1391,"tieuDe":"Đàn Hạc Hương Và Hắc Tuyết Nghĩ","tomTat":"Chúc tiền bối dùng bình ngọc trắng phóng cuồng phong mở đường qua màn sương dày trên hồ, dẫn đoàn săn tiến về nơi ẩn náu của Chân Thiềm Thú. Dọc đường, cả nhóm chống đỡ hơn mười ba đợt tập kích của vô số quái cầm màu trắng có thủy tiễn chứa toan dịch ăn mòn pháp bảo, cho tới khi đàn chim tự rút lui. Sau nửa ngày, đoàn người tới cự sơn giữa hồ và biết rằng hang Chân Thiềm Thú nằm trong hệ thống động ngầm dưới chân núi. Chúc tiền bối cảnh báo về khả năng phá linh quang hộ thể cùng độc tính của Hắc Huyết Nghĩ, sau đó đốt Đàn Hạc Hương để dẫn dụ chúng. Tiêu tiên tử dùng Bách Chướng Nghịch Quang Phiên che giấu mình và Hàn Lập; bảo vật ngăn được Minh Thanh Linh Mục nhưng vẫn bị thần niệm của hắn phát hiện. Khi đàn Hắc Huyết Nghĩ khổng lồ bay vào vòng vây, Chúc tiền bối cùng bạn lữ phát lệnh để hơn mười pháp bảo và nhiều pháp thuật phạm vi lớn đồng loạt đánh xuống. Sau vụ oanh kích, khu vực đàn kiến từng tụ tập trở nên trống rỗng, không còn lưu lại dấu vết hay tro tàn."},{"chuong":1392,"tieuDe":"Huyền Qua Thú","tomTat":"Sau khi tiêu diệt Hắc Huyết Nghĩ, Chúc tiền bối thu đàn hương, phân phát Huyền Thanh Thiên Lôi Kỳ và để Triệu lão cùng Tuần đạo hữu cảnh giới bên ngoài trước khi dẫn những người còn lại vào cự sơn. Đội ngũ đi sâu qua thông đạo ẩm ướt đầy độc trùng, trong đó Hàn Lập và Tiêu tiên tử lần lượt dùng hồng ti cùng bạch sắc quang tráo để bảo vệ bản thân. Chúc tiền bối và Hàn Lập phát hiện bất thường phía trước, còn lão ông họ Du dùng Phong Độn Thuật thăm dò rồi xác nhận có hai Huyền Qua Thú gần Hóa Thần kỳ chặn đường. Do loài thú này có thể bỏ chạy bằng thủy độn, lôi độn và phát tiếng báo động truyền xa, đội ngũ cần giết chúng thật nhanh và kín đáo. Phương án dùng Thổ Độn Thuật vòng qua cũng bị bác bỏ vì Linh Từ Thạch Mạch trong núi có thể hút sạch linh lực của người độn vào đá. Hàn Lập chủ động nhận giết một con để đổi lấy thêm một phần Chân Thiềm linh huyết, đồng thời cam kết bồi thường nếu thất bại, nên được Chúc tiền bối chấp thuận. Cuối chương, Hàn Lập, mỹ diễm nữ tử và lão ông họ Du dùng các thủ đoạn ẩn nấp khác nhau, tiếp cận hai Huyền Qua Thú trắng béo đang bám trên vách đá ăn rêu."},{"chuong":1393,"tieuDe":"Kinh Biến","tomTat":"Hàn Lập dùng Hư Hóa Thuật áp sát hai Huyền Qua Thú và nhờ Minh Thanh Linh Mục xác định vị trí các đồng đội đang ẩn nấp. Khi ra tay, hắn dùng Nguyên Từ Thần Quang hóa giải thần thông của trùng thú, lấy hắc sắc tiểu sơn trấn áp rồi tung Phệ Linh Thiên Hỏa thiêu mục tiêu thành tro chỉ trong một nhịp thở; nữ tử xinh đẹp cũng dùng phi kiếm đỏ chém đôi con còn lại. Lão ông họ Du phát phù gọi cả đội tới, sau đó Chúc tiền bối dẫn mọi người đến sông ngầm và phân công nhóm mang Huyền Thanh Thiên Lôi Kỳ phối hợp với Hàn Lập, Tiêu tiên tử kiềm chế Ảnh trùng thú. Trong lúc đội săn tiến sâu vào sào huyệt Chân Thiềm Thú, Triệu lão và Tuần đạo hữu làm nhiệm vụ cảnh giới bên ngoài cự sơn. Hai sinh vật có cánh thịt bất ngờ tập kích, khiến Triệu lão bị bóp nát cả thân thể lẫn Nguyên Anh, còn Nguyên Anh của Tuần đạo hữu bị hắc hà bắt giữ. Hai hung thủ xem Nguyên Anh tu sĩ Nhân tộc là vật đại bổ và tuyên bố muốn săn tu sĩ Luyện Hư hoặc Hợp Thể để tăng cơ hội tiến giai thành Dạ Xoa Vương."},{"chuong":1394,"tieuDe":"Trảm Sơn Chi Uy","tomTat":"Một đôi dị tộc thuộc đội đi trước từ bỏ ý định đối đầu tu sĩ Hợp Thể, chỉ xử lý các mục tiêu Nhân tộc đã lộ diện rồi rời đi trước khi đại quân kéo tới. Sau đó, vô số dị tộc mang cánh, cự vật hình tổ ong, cổ thú và hắc toa liên tục vượt qua khu vực, cho thấy một chiến dịch quân sự quy mô lớn đang tiến sâu vào địa vực Nhân tộc. Mộng Tường dẫn lực lượng tinh nhuệ lục soát cự sơn nhưng Linh Từ Thạch Mạch cản trở dò xét, vì vậy hắn dùng hồng sắc quang phiến chém xuyên sườn núi và sai hai thuộc hạ khổng lồ đánh sập phần đã bị cắt. Hồng tuyến xuyên vào hang động, phân thây đại hán áo bào tro đang cầm trận kỳ, khiến pháp trận mất hiệu lực và đám bóng đen chạy thoát. Hàn Lập định dùng Nguyên Từ Thần Quang ngăn chúng nhưng phải chuyển sang tự vệ khi hang động vỡ vụn và nước sông ngầm cuộn trào. Hơn mười tu sĩ do Chúc tiền bối và Tiếu tiên tử dẫn đầu thoát khỏi nửa ngọn núi còn lại, song lập tức bị khoảng trăm dị tộc có nhiều cường giả cấp Luyện Hư bao vây. Nhận thấy phía Nhân tộc chỉ có hai tu sĩ Luyện Hư, Mộng Tường giao việc xử lý cho thuộc hạ, ra lệnh ưu tiên bắt sống để tra hỏi rồi rời khỏi chiến trường."},{"chuong":1395,"tieuDe":"Dạ Xoa Vương","tomTat":"Đoàn tầm bảo Nhân tộc bị hơn trăm Dạ Xoa bao vây dù hai tộc không ở trong thời kỳ giao chiến, và nữ Dạ Xoa chỉ huy lập tức ra lệnh giết sạch. Đợt công kích đầu tiên phá tan phần lớn phòng ngự, khiến hơn mười tu sĩ chỉ còn vài người sống sót. Thanh niên họ Chúc cùng đạo lữ dùng song phiên lam hồng chống đỡ rồi cho bảo vật nổ tung, tạo cơn lốc khổng lồ để mở đường, nhưng hai Dạ Xoa khổng lồ dùng cự lực chặn đứng cuộc phá vây. Trong khi đó, Hàn Lập không theo đoàn người lên mặt đất mà vận dụng Nguyên Từ Thần Quang xuyên qua ảnh hưởng của Linh Từ Thạch Mạch để độn ngầm. Trên đường, hắn giết Bích Mục Chân Thiềm bị thương, thu thi thể rồi từ bỏ việc tìm Thiên Tâm Hoa. Sau khi chạy xa hàng nghìn dặm và trồi lên trong một sơn cốc, Hàn Lập phát hiện hai Dạ Xoa có tu vi vượt xa mình đang đứng ngay gần đó mà thần niệm không thể cảm ứng. Thiếu nữ họ Tiêu cũng cưỡi Ngũ sắc tiểu thuyền xuất hiện tại sơn cốc, vừa mừng vì gặp Hàn Lập đã lập tức biến sắc khi nhìn thấy hai cường giả Dạ Xoa."},{"chuong":1396,"tieuDe":"Xương Nô","tomTat":"Hàn Lập và Tiêu tiên tử vừa thoát khỏi lòng đất đã bị Mộng Tường cùng Chuyển Luân Vương chặn lại. Nhận thấy thần thông độn thuật của Hàn Lập và pháp bảo biến hóa của Tiêu tiên tử không tầm thường, Chuyển Luân Vương đề nghị mỗi Dạ Xoa Vương phái một Xương Nô truy sát một người để phân định thắng bại. Hai tu sĩ được chạy trước một ngàn dặm nhưng phải giữ khoảng cách với nhau không quá một trăm dặm, nếu vi phạm sẽ bị hai Dạ Xoa Vương trực tiếp ra tay. Hàn Lập thuấn di lên ngũ sắc cự giao của Tiêu tiên tử và cùng nàng nhanh chóng rời đi. Sau khi dùng Nhật Quang Bội ngăn thần niệm nghe lén, Tiêu tiên tử giải thích Xương Nô là sinh vật bán quỷ bán yêu được nuôi bằng máu huyết và có thể mang một phần đáng kể thần thông của chủ nhân. Hàn Lập nhận ra rằng ngay cả khi thắng Xương Nô, hai Dạ Xoa Vương vẫn chưa từng hứa tha mạng cho họ. Hai người trao đổi công pháp, thần thông và bảo vật để chuẩn bị liên thủ, rồi nghe thấy hai tiếng tru thê lương báo hiệu Xương Nô đã bắt đầu truy sát."},{"chuong":1397,"tieuDe":"Bố Trí Mai Phục","tomTat":"Nữ tử họ Tiêu dùng ngũ sắc hà quang mang Hàn Lập phi độn, còn hắn hỗ trợ tăng tốc để kéo hai Xương Nô ra chiến trường cách xa hai Dạ Xoa Vương. Hàn Lập thử dùng Ích Tà Thần Lôi công kích huyết vân nhưng không có tác dụng, trong khi Minh Thanh Linh Mục giúp hắn phát hiện hai quái vật đã bí mật thoát ra. Nữ tử họ Tiêu triệu tinh hồn ngũ thủ cầu giao nghênh chiến, song nó bị huyết ti của một Xương Nô đánh tan trong một kích. Hai quái vật chia nhau mục tiêu, một con tấn công nàng còn con kia lặng lẽ áp sát đánh úp Hàn Lập. Nguyên Từ Thần Sơn bảo vệ nữ tử họ Tiêu, còn Hàn Lập dựa vào kim ngân trường bào, bốn cánh tay kim sắc và độn pháp để thoát khỏi lợi trảo. Khi đối phương đã tiến vào vị trí, Hàn Lập ra hiệu hành động và nữ tử họ Tiêu dùng pháp bàn kích hoạt ba mươi sáu cây tiểu phiên. Chương kết thúc khi các phiên kỳ cùng vô số đạo kim trong suốt bắt đầu khép vòng vây quanh hai Xương Nô."},{"chuong":1398,"tieuDe":"Quang Trận","tomTat":"Hàn Lập dùng Đại Canh Kiếm Trận vây hai Xương Nô, liên tiếp kích phát cực hàn và điện quang của Thanh Trúc Phong Vân Kiếm nhưng vẫn không thể ngăn chúng tái hợp. Hai quái vật vận dụng xúc tu và huyết ti xoay tròn để đẩy lùi kim ti, khiến kiếm trận dần mất khả năng giam giữ chúng. Trong lúc Hàn Lập cầm chân địch và chuẩn bị mười viên lôi châu, nữ tử họ Tiêu điều khiển pháp bàn cùng ba mươi sáu trận kỳ, điều động thiên địa nguyên khí để dựng một quang trận gần như che kín bầu trời. Khi hai Xương Nô phá vây lao tới, quang trận bắn xuống hai cột sáng trắng sữa và truyền tống chúng tới một nơi chưa rõ. Nữ tử họ Tiêu sau đó đột ngột bay thẳng lên quang trận, Hàn Lập lập tức theo sát. Hai Dạ Xoa Vương hiện thân ngoài trăm trượng và đồng thời tung quyền kình cùng quang phiến huyết sắc đánh chặn hai người."},{"chuong":1399,"tieuDe":"Trư Yêu Cùng Ấu Thú","tomTat":"Nữ tử họ Tiêu tiến vào quang trận trước, còn Hàn Lập thu kiếm, dùng kim ngân sắc lôi cản hai Dạ Xoa Vương rồi vận dụng đôi cánh mới luyện chế để tiến vào trung tâm trận pháp. Quang trận phát động truyền tống cự ly cực xa và vỡ vụn, khiến Bất Diệt cùng Chuyển Luân Vương không thể xác định hai tu sĩ Nhân tộc đã bình an rời đi hay rơi vào khe không gian; hai Xương Nô cũng bị truyền tới nơi chưa rõ. Hai Dạ Xoa Vương sau đó gác việc truy bắt để bàn chuyện liên quân, trong lúc đại quân Dạ Xoa tộc đang tiến về Thiên Uyên Thành. Hàn Lập tỉnh lại một mình giữa bãi loạn thạch phủ sương xám, nơi thần niệm của hắn tạm thời không thể rời khỏi thân thể, rồi tìm thấy một dòng suối có nước uống được. Tại đây, hắn đánh trúng một Vương bát trư yêu nhưng yêu vật giả vờ vụng về, bất ngờ thoát khỏi quy xác và hóa thành lợn rừng chạy mất; Hàn Lập giữ lại chiếc mai có sức phòng ngự khác thường. Khi một đàn thú giống hươu lẫn ngựa tới uống nước, một ấu thú mắt lam nhạt chủ động thân cận hắn và được ban một viên Khai Linh Đan. Các con trưởng thành lập tức bảo vệ ấu thú, còn Hàn Lập tiếp tục điều dưỡng và không làm hại đàn thú."},{"chuong":1400,"tieuDe":"Cạnh Biển","tomTat":"Sau khi đàn thú rời đi và sương mù tan hết, Hàn Lập xác nhận pháp lực cùng thần khí đã khôi phục hoàn toàn, nhưng thần niệm bị hoàn cảnh áp chế nên phải dùng Minh Thanh Linh Mục khảo sát. Hắn phát hiện một vùng biển xích hồng ở phía bắc và từ sự thay đổi của mặt trời suy đoán mình đã bị truyền tống tới nơi cực kỳ xa khu vực Nhân tộc. Trên bãi cát có hơn nghìn cự quy cùng nhiều quy xác, trong đó Hàn Lập tìm được ba quy xác mang ngân văn có sức phòng ngự khác thường rồi thu lấy. Ngoài khơi, một yêu vật hình mực dùng hào quang đen nuốt hơn trăm quái điểu trước khi phát hiện Hàn Lập và hoảng sợ bỏ chạy xuống biển. Hàn Lập nhìn xuyên hắc vụ và định dùng Phong Lôi Sí truy bắt, nhưng một yêu thú mang khí tức cấp Hóa Thần xuất hiện rồi hội hợp với yêu vật. Không muốn tùy tiện giao chiến ở vùng đất chưa rõ tình hình, hắn từ bỏ truy đuổi, quay về phía nam và dừng lại bên một dãy núi xanh liên miên."},{"chuong":1401,"tieuDe":"Hắc Sắc Vụ Hải","tomTat":"Hàn Lập tiến sâu vào dãy núi hiểm trở, phát hiện nơi đây có linh khí nồng đậm, rất nhiều linh thảo, linh mộc và các đàn yêu thú. Trên đường đi, hắn chứng kiến hai đàn hung thú giao chiến có tổ chức, trong đó cách tiến lui của đàn cự vượn khiến hắn nảy sinh một ý tưởng chưa được tiết lộ. Sau hai tháng, hắn gặp biển sương đen có khả năng khiến cây cối khô héo và hóa bụi chỉ trong khoảnh khắc, rồi phát hiện ba văn tự dị tộc cổ mang sát khí trên một vách núi gần đó. Qua nhiều lần khảo sát và tìm đường vòng, hắn xác định vùng đất mình đang ở là một cự đảo hoặc bán đảo khổng lồ, với một phần đáng kể bị màn sương đen bao phủ. Hàn Lập tiếp tục dò xét hơn mười vạn dặm mặt biển xung quanh nhưng chỉ tìm thấy đảo hoang và hải thú yếu, nên quyết định ở lại tu luyện. Hắn chọn ngọn cự sơn có linh khí tốt nhất để mở động phủ, bố trí cấm chế và trồng linh dược. Trong mật thất, hắn lấy chín thi thể Châm Thiềm thú ra khỏi trữ vật trạc, bắt đầu xử lý một thi thể Ấu Thiềm và thu được chất lỏng sền sệt màu trắng bạc."},{"chuong":1402,"tieuDe":"Khổ Tu","tomTat":"Hàn Lập dùng Phệ Linh Thiên Hỏa luyện hết tàn huyết trong thi thể Ấu Thiềm, thu toàn bộ Châm Thiềm huyết vào bình vì loại linh huyết này không thể được thúc sinh. Hắn tạm hoãn luyện Châm Thiềm dịch, giao động phủ cho Nguyên Anh thứ hai và Cự Vượn Khôi Lỗi quản lý rồi đóng kín mật thất, chuẩn bị tu tới cực đỉnh Hóa Thần trung kỳ. Trong thời gian bế quan, Hàn Lập dùng đan dược, Long Lân Quả và Thoái Cốt quyết để đồng thời tăng tiến pháp lực lẫn thân thể, đồng thời dùng Bách Mạch Luyện Bảo Quyết dung nhập bảy mươi hai thanh phi kiếm vào xương cốt. Sau một giáp, bốn yêu thú cấp sáu, cấp bảy dẫn hàng nghìn mãnh thú và độc trùng tấn công động phủ, nhưng Phòng Ngự Cô trận giết phần lớn thú đàn rồi dùng ánh sáng ngũ sắc phá tan cơn lốc hợp kích của chúng. Từ đó, yêu vật hoàn toàn tránh xa khu vực một trăm dặm quanh động phủ. Hơn ba mươi năm sau, Hàn Lập rời mật thất và hiển hóa pháp tướng ba đầu sáu tay chân thật hơn trước, nhưng quầng sáng bất ngờ nứt ra khiến pháp tướng tan vỡ. Hắn tỉnh lại sau lần vận công thất bại với một nụ cười gượng gạo."},{"chuong":1403,"tieuDe":"Thiên Bằng Tộc Và Cung Phụng","tomTat":"Sau ba lần phá chướng ngại thất bại, Hàn Lập cân nhắc dùng Hắc Viêm Đan nhưng quyết định giữ đủ ba viên cho lần tiến cấp Luyện Hư sau này. Hắn kiểm tra Huyền Thiên Quả Thực, nhận thấy quầng sáng bên trong đã lớn bằng ngón tay cái, rồi tiếp tục bồi dưỡng nó bằng lục dịch thần bí. Nguyên Anh thứ hai báo tin nhóm yêu vật từng quấy nhiễu động phủ đã trở lại cùng trợ thủ, khiến Hàn Lập vận dụng pháp trận liên kết với Vạn Lung Châu để phát hiện chúng. Hắn nhanh chóng bắt sống Tam thủ cự mãng, quái thú đầu trâu thân sư tử và một ngư yêu cấp sáu mới Hóa Hình. Sau khi sưu hồn rồi tiêu diệt ngư yêu, Hàn Lập biết tới Thiên Bằng tộc, Bảo Quang tôn giả và chế độ cung phụng, đồng thời nắm được ngôn ngữ dị tộc để tra hỏi hai yêu vật còn lại. Chúng khai rằng cần Hoa Mộc Linh trên linh sơn của Hàn Lập để hoàn thành kỳ cung phụng nghìn năm và đã hứa trả mười đôi Kim Tủy Tinh Trùng để thuê ngư yêu trợ chiến. Hàn Lập còn biết tam đại trưởng lão Thiên Bằng tộc từng thanh trừng những yêu vật có tu vi cao tại Hắc Ẩn sơn, chỉ giữ lại nhóm có thiên phú tìm vật cung phụng."},{"chuong":1404,"tieuDe":"Kim Tủy Tinh Trùng Và Kim Mẫu San Hô Sa","tomTat":"Hàn Lập thương lượng với các yêu thú Hắc Ẩn sơn, đề nghị dùng Mộc Linh Hoa đổi Kim Tủy Tinh Trùng hoặc Kim Mẫu San Hô Sa rồi cho chúng thời gian chuẩn bị. Sau khi hắn rời đi, thú đầu trâu dùng nội đan dựng màn cách âm và cùng Tam thủ cự mãng bàn về kỳ cung phụng, nô ngân của Thiên Bằng tộc và hy vọng được một tiền bối Hạo Thú tộc nửa quỷ nửa yêu giải cứu. Hàn Lập thực ra vẫn ẩn gần đó và dùng một con Phệ Kim Trùng thu nhỏ mang thần niệm để nghe trọn cuộc đối thoại. Từ những thông tin thu được, hắn nhận ra Kim Tủy Tinh Trùng và Kim Mẫu San Hô Sa có thể hỗ trợ con đường luyện thể, giúp hắn hướng tới Kim Cương Pháp Thân và ngưng luyện Phạm Thánh Chân Ma Pháp Tướng thành thực thể. Hàn Lập sau đó khởi động Phong Lôi sí đã thành linh bảo, mất hơn hai ngày để tới vùng biển san hô nơi đặt động phủ Bảo Quang tôn giả. Vừa đến nơi, hắn lập tức thúc Nguyên Từ thần Sơn lớn đến nghìn trượng và phóng Nguyên Từ Thần quang bao phủ toàn bộ vùng biển san hô."},{"chuong":1405,"tieuDe":"Thạch Đôn","tomTat":"Hàn Lập dùng Nguyên Từ thần sơn công phá vùng san hô trên biển, tạo ra sóng lớn và xoáy nước, đồng thời giết hai hải yêu cấp sáu canh giữ động phủ. Bảo Quang tôn giả xuất hiện dưới hình dạng đại hán giáp lam rồi hiện nguyên hình giao long xanh cấp tám, nhưng vẫn bị thần sơn nghiền nát thân thể và bị Phệ Linh Thiên Hỏa thiêu diệt nguyên thần; bốn hải thú đi cùng cũng không thể sống sót. Sau khi thu đầu giao long, Hàn Lập đổi ý lặn xuống đáy biển, phá cấm chế và cửa san hô để tiến vào động phủ. Trong một gian phòng xa hoa, hắn phát hiện thạch đôn xám trắng có sức nặng trên mười mấy vạn cân, truyền cảm giác lạnh nóng kỳ lạ và chìm sâu vào nền Huyền Thiết tinh. Dù phối hợp sức mạnh thân thể với Bách Mạch luyện bảo quyết, hắn vẫn không thể nhấc vật này lên. Kiếm khí cũng không làm thạch đôn tổn hại, khiến Hàn Lập lấy trường kiếm kim sắc chém mạnh xuống để tiếp tục thử nghiệm."},{"chuong":1406,"tieuDe":"Biến Dị","tomTat":"Hàn Lập dùng Thanh Trúc Phong Vân kiếm, Phệ Linh Thiên Hỏa và nhiều loại lực lượng thử luyện hóa thạch đôn kỳ dị, nhưng chỉ hỏa diễm bạc có thể khiến vật liệu tan chảy với tốc độ cực chậm. Vì thạch đôn quá nặng để cất giữ hoặc vận chuyển nguyên vẹn, hắn huy động hàng nghìn Phệ Kim Trùng cắn vật liệu và chia nó thành ba khối gần bằng nhau. Hàn Lập giấu hai khối trong động phủ của Bảo Quang tôn giả, sau đó vận Phạm Thánh Chân Ma Công và Phong Lôi sí đưa khối còn lại về động phủ tại Hắc Ẩn sơn mạch. Tại đây, hắn phát hiện đàn Phệ Kim Trùng trưởng thành đã ngủ say sau khi nuốt vật liệu và có khả năng phát sinh biến dị, nên quyết định chờ kết quả tiến hóa rồi mới xử lý khối đá. Đúng kỳ hạn bảy ngày, hai yêu thú đầu trâu, Kim Mao cự viên và Dã trư khổng lồ tới gặp hắn. Hàn Lập đưa thủ cấp Bảo Quang tôn giả ra để hủy giao dịch cũ, yêu cầu chúng giao vật mình cần và cho thấy hơn một trăm đóa Mộc Linh Hoa đã chuẩn bị làm vật trao đổi."},{"chuong":1407,"tieuDe":"Kim Tủy Luyện Thể","tomTat":"Hàn Lập dùng hai hộp Hoa Mộc Linh nghìn năm đổi lấy mười lăm đôi Kim Tủy Tinh Trùng và ba hồ lô Kim Mẫu San Hô Sa cực phẩm từ bốn yêu thú Hắc Ẩn sơn. Sau khi tự kiểm tra phẩm chất, hắn hoàn tất giao dịch và mở lời rằng mình còn nhiều vật khác để trao đổi lâu dài. Rời động phủ, bốn yêu thú bàn cách dùng Hoa Mộc Linh làm cung phụng cho Thiên Bằng tộc, mong tránh bị trừng phạt và vượt qua một trăm năm còn lại trước khi nô ngân được xóa. Chúng cũng phải tìm bốn viên linh thạch thượng đẳng mang bốn thuộc tính khác nhau cho một vị đại nhân, nhưng quyết định chưa vội hỏi Hàn Lập để tránh khiến hắn nghi ngờ. Trở lại mật thất, Hàn Lập cân nhắc các cách sử dụng Kim Tủy Tinh Trùng rồi dành mười đôi cho kế hoạch ngưng luyện Phạm Thánh Chân Ma Pháp Tướng thành thực thể. Năm đôi còn lại được hắn dùng để cường hóa thân thể và chuẩn bị xung kích Hóa Thần trung kỳ trong khoảng năm sáu năm. Hắn kích thích một đôi tinh trùng tiết kim tủy, dẫn chất lỏng bao phủ cánh tay và bắt đầu vận hành linh lực luyện thể."},{"chuong":1408,"tieuDe":"Thiên Bằng Nhân","tomTat":"Sau năm năm bế quan, Hàn Lập đã luyện toàn bộ kim tủy cùng ba bình Kim Mẫu San Hô Sa vào huyết nhục, khiến thân thể mạnh lên nhưng vẫn chưa vượt qua bình cảnh Luyện Hư trung kỳ. Nguyên anh thứ hai báo tin sứ giả Thiên Bằng sắp tới, đồng thời những ký ức lấy từ Ngư yêu mặt người giúp hắn xác định Hắc Minh đảo thực chất là bán đảo nối với Phong Nguyên đại lục và nằm trong vùng thống trị của Phi Linh tộc. Hàn Lập kiểm tra hơn một nghìn Phệ Kim Trùng vừa tỉnh lại sau biến dị, nhận thấy chúng cực nặng, linh hoạt và có sức mạnh lớn nhưng chưa khám phá hết năng lực mới. Hắn che giấu hành tung, dùng Thanh minh linh nhãn tìm cửa động phủ rồi phái một con Phệ Kim Trùng vào trước và hóa thành gió nhẹ lẻn theo. Ba đại điểu bạc dùng lôi điện tăng tốc giáng xuống đảo, sau đó hóa thành hai nam một nữ có cánh bạc với tu vi tương đương Hóa Thần sơ kỳ đến trung kỳ. Bốn yêu thú cung kính nghênh đón nhưng phải thừa nhận một số cống vật đã tuyệt diệt và xin bù bằng năm mươi bông Hoa Mộc Linh. Đề nghị này khiến ba sứ giả vui mừng, song nam tử lớn tuổi lập tức nghi ngờ số hoa chưa đủ năm tháng và đe dọa hậu quả nếu cống vật không đạt yêu cầu."},{"chuong":1409,"tieuDe":"Xích Dung Tộc","tomTat":"Bốn yêu vật dâng hai hộp Hoa Mộc Linh trên ngàn năm cho ba người Thiên Bằng tộc, nhờ đó bù đủ phần Kim tủy tinh trùng, Kim mẫu san hô sa và Thanh quang mộc còn thiếu rồi nhận tiên đan áp chế nô ngân. Hàn Lập bí mật quan sát cuộc giao nhận bằng kim sắc tiểu trùng, sau đó ẩn thân bám theo đoàn Thiên Bằng hơn hai tháng để tìm đường trở về Thiên Nguyên đại lục và thu thập tình báo. Khi họ tiến vào khu vực đồi núi ven bờ, Thiên Minh dẫn một đội Xích Dung tộc cùng chim lớn hai đầu xuất hiện, đòi Hoa Mộc Linh và ép ba người đối phương quy thuận. Thiên Minh còn tuyên bố Côn Bằng thánh chủ cuối cùng đã chết và Thiên Bằng tộc sắp bị gạch tên khỏi Phi Linh tộc, nhưng Phong Khiếu cùng đồng bạn không tin. Đội Xích Dung dùng các ống ngắn màu lam triển khai Khốn Ma Võng, khiến ba người Thiên Bằng không thể độn thoát. Hai phe lần lượt hóa thành hỏa điểu và đại điểu ngân sắc, dùng hỏa diễm cùng lôi điện giao chiến. Do dừng lại quan sát quá gần, Hàn Lập cũng bị nhốt bên trong Khốn Ma Võng."},{"chuong":1410,"tieuDe":"Lộ Diện","tomTat":"Hàn Lập bị Khốn Ma Võng giữ lại khi đang ẩn thân và phải quan sát lực lượng Xích Dung tộc phục kích ba người Thiên Bằng mang Hoa Mộc Linh trở về. Qua cuộc đối đầu, hắn biết Thiên Bằng tộc vừa mất một nhân vật lớn và đang suy yếu, khiến kế hoạch trà trộn của hắn đứng trước nguy cơ thất bại. Phong Khiếu cùng hai đồng bạn hóa thành ngân điểu chống lại biển lửa và Hỏa long châu, sau đó dùng Lôi độn thuật biến mất khỏi chiến trường. Thiên Minh thả Thông linh chi phong truy tìm họ, nhưng đàn linh trùng lại tụ quanh Hàn Lập và buộc hắn phải hiện thân. Hàn Lập biến đổi Phong Lôi Sí thành đôi cánh trắng để giả dạng người Thiên Bằng, song vẫn bị Thiên Minh ra lệnh vây giết. Hắn dùng quang hà màu xám hóa giải các đòn công kích, độn đến bên Hỏa long châu rồi dùng bàn tay phủ kim lân siết nát bảo vật thành bụi đỏ. Thiên Minh kinh sợ và phẫn nộ, lập tức hóa thành hỏa điểu cùng cự cầm hai đầu tiếp tục lao vào tấn công Hàn Lập."},{"chuong":1411,"tieuDe":"Đẩy Lùi Xích Dung","tomTat":"Hàn Lập bỏ qua Thiên Minh để áp sát song đầu cự cầm, dùng Nguyên Từ Thần Quang, hai bàn tay đã luyện Bách Mạch Luyện Bảo Quyết và sức mạnh thân thể phá các đòn hàn quang, âm ba cùng cự trảo của nó. Khi Thiên Minh dẫn các tộc nhân Xích Dung hợp tử diễm và hỏa cầu thành biển lửa giáp công, Hàn Lập triệu Nguyên Từ Thần Sơn và Pháp Tướng ba đầu sáu tay để vừa phòng thủ vừa tiếp tục chế trụ cự cầm. Sáu cánh tay kim quang giữ chặt hai cánh, bẻ gãy cả hai cổ, sau đó ngân diễm thiêu xác cự cầm thành tro. Thiên Minh lập tức ra lệnh rút lui, cùng đồng tộc dung hợp thành Hỏa Điểu màu tím khổng lồ, phá lưới điện của ba viện binh Thiên Bằng rồi thoát khỏi chiến trường. Phong Khiếu và hai đồng bạn cảm tạ Hàn Lập, dựa vào Thiên Bằng khí tức nồng đậm để nhận hắn là hậu duệ đồng tộc từng lưu lạc ngoài hải ngoại. Hàn Lập thuận thế dựng thân phận mới và nhận ra cánh Côn Bằng đã giúp mình che giấu lai lịch thật. Qua lời Phong Khiếu, hắn còn biết việc Xích Dung tộc công khai xâm nhập và cướp đoạt có thể báo hiệu Thiên Bằng tộc đang gặp một biến cố nghiêm trọng."},{"chuong":1412,"tieuDe":"Thiên Bằng Thánh Địa","tomTat":"Phong Khiếu lo Xích Dung tộc tiếp tục chặn giết nên nhờ Hàn Lập bảo vệ ba người trên đường trở về, còn Hàn Lập nhận lời vì muốn nhân cơ hội trà trộn vào Thiên Bằng tộc. Hắn dùng Phệ Linh Thiên Hỏa thiêu hủy lam sắc ma võng rồi cùng ba người rời nơi giam giữ. Trong một tháng di chuyển, Hàn Lập giả làm tộc nhân khổ tu tại hải ngoại, kín đáo hỏi thăm tình hình Phi Linh tộc và Thiên Bằng tộc trong khi né tránh những câu hỏi về lai lịch. Đoàn người tiến vào dãy núi thuộc lãnh địa Thiên Bằng mà không gặp thêm cuộc tập kích nào, nhưng thái độ khác biệt đối với những tộc nhân mang màu cánh khác nhau khiến Hàn Lập nhận ra trong tộc tồn tại những quy củ hoặc kiêng kỵ chưa rõ. Một đội tuần tra truyền lệnh của các trưởng lão, buộc Phong Khiếu và hai người đồng hành phải lập tức tới Vạn Bằng các. Trước khi rời đi, Phong Khiếu trao cho Hàn Lập một mộc bài thông hành và yêu cầu đội tuần tra bố trí người dẫn đường. Hóa Vũ dùng linh vũ trắng sữa mở cấm chế huyễn thuật, đưa Hàn Lập vượt qua lối vào được che giấu và tiến vào tòa thành khổng lồ trong Thiên Bằng Thánh địa."},{"chuong":1413,"tieuDe":"Phong Linh Tháp","tomTat":"Hóa Vũ dẫn Hàn Lập vượt qua cấm chế quanh Khai Thiên trụ và tiến vào Thánh thành Thiên Bằng tộc, đồng thời giới thiệu hệ thống phòng thủ từng nhiều lần cứu tộc khỏi nguy cơ diệt vong. Hàn Lập dùng linh mục quan sát màn sáng, nhận ra phần lớn linh lực đáng sợ bắt nguồn từ vô số quang ti xanh bạc trên cao. Tại Quý Tân quán, Bạch Thúy tiếp đón hắn, giải thích quy mô Thiên Bằng tộc cùng điều kiện chỉ những người có khả năng biến hình mới được vào thành. Hàn Lập giả xưng từng tu luyện ở hải ngoại rồi nhận một ống trúc chứa bản đồ chi tiết, qua đó xác định đại điện giao dịch và Truyện Linh điện là những nơi đáng chú ý. Không muốn can dự vào tranh chấp giữa các chi của Phi Linh tộc, hắn quyết định nhanh chóng thu thập tài liệu rồi rời đi. Trên đường tới đại điện giao dịch, Hàn Lập phát hiện Phong Linh tháp, một cự tháp bát lăng có hắc khí bị hào quang bảy màu phong tỏa. Sự vắng lặng tuyệt đối trong phạm vi hơn trăm trượng quanh tháp khiến hắn nhận định đây không phải nơi an lành."},{"chuong":1414,"tieuDe":"Thiên Bằng Thánh Tử Cùng Côn Bằng Chân Huyết","tomTat":"Khi bay vòng qua Phong Linh tháp, Hàn Lập nhận ra hắc vụ rò rỉ từ cấm địa có mùi giống Hắc minh vụ từng gặp tại bán đảo Vụ Hải. Côn Bằng Thánh linh trong tháp bất ngờ dị động, khiến hàng trăm Thiên Bằng nhân mất ý thức, còn Phong Lôi Sí của Hàn Lập nóng rực và tạm thời mất công hiệu. Hư ảnh Côn Bằng màu xanh hiện lên sau lưng hắn, cộng hưởng với cự điểu màu đen bao phủ tòa tháp và khiến không gian quanh hắn bị nén chặt. Các tu sĩ trấn tháp vận hành cấm chế, cho tinh thạch trên đỉnh tháp tự bạo và dùng thất sắc thải quang đánh tan điểu ảnh. Sau khi được giải thoát, Hàn Lập bị hai lão giả Hóa Thần hậu kỳ nhận định là người có đủ Thiên Bằng khí tức để kế thừa Côn Bằng Chân Huyết và trở thành Thánh tử. Hắn phủ nhận tư cách này rồi định dùng Phong Lôi Sí rời đi, nhưng Kim Duyệt xuất hiện, nhận ra hắn là dị tộc nhân và tuyên bố hắn phải để lại đôi cánh nếu muốn rời khỏi Thiên Bằng tộc. Nàng tiếp quản việc xử lý Hàn Lập và ra lệnh cho các tu sĩ quay lại Phong Linh tháp gia cố phong ấn Côn Bằng Thánh linh."},{"chuong":1415,"tieuDe":"Đại Trưởng Lão","tomTat":"Kim Duyệt đưa Hàn Lập tới một phòng nghị sự trong Thánh thành Thiên Bằng tộc và dùng thánh khí nhìn thấu thân phận Nhân tộc của hắn. Nàng giải thích rằng Phong Linh tháp đang phong ấn nửa thánh hồn Côn Bằng chân thánh, đồng thời nói rõ ý nghĩa của Thánh tử, chân huyết và khảo nghiệm trở thành Thánh chủ. Theo yêu cầu của nàng, Hàn Lập giao Phong Lôi Sí để kiểm tra rồi gọi pháp bảo trở lại bằng thần thông không gian. Kim Duyệt phát hiện đôi cánh dung hợp cả linh vũ Côn Bằng lẫn lông Phượng yêu, trong đó linh vũ còn chứa máu huyết chân thánh và có thể đã khiến Hàn Lập mang máu Côn Bằng. Nàng bất ngờ đề nghị hắn gia nhập Yêu man tộc và trở thành Thánh tử Thiên Bằng, nhưng vẫn cần thương lượng với các trưởng lão khác. Khi Hàn Lập nói ra cái chết của Thánh chủ và nguy cơ Thiên Bằng tộc bị xóa tên, Kim Duyệt dùng uy áp áp chế hắn rồi yêu cầu giữ kín bí mật. Cuối cùng, nàng tiết lộ trong tộc vẫn còn hai Thánh tử nhưng tu vi quá thấp, khiến Hàn Lập hiểu rằng mình được mời tới để hỗ trợ họ vượt qua khảo nghiệm."},{"chuong":1416,"tieuDe":"Đại Điện Giao Dịch","tomTat":"Kim Duyệt đề nghị Hàn Lập giả làm Thánh tử Thiên Bằng tộc để trợ giúp hai Thánh tử hiện tại vượt qua thí luyện, đổi lại chân huyết Côn Bằng và các hậu tạ khác. Sau khi biết mức độ nguy hiểm cùng tình trạng yếu kém của hai Thánh tử, Hàn Lập xin ba ngày cân nhắc. Trong cuộc bàn bạc bí mật sau đó, Tư trưởng lão đề nghị giết Hàn Lập để cướp Phong Lôi Sí, nhưng Kim Duyệt bác bỏ vì bảo vật khó đổi chủ trong thời gian ngắn. Ba trưởng lão cuối cùng thống nhất lợi dụng Hàn Lập vượt qua kiếp nạn rồi tìm cách giam lỏng hắn, đồng thời Kim Duyệt tiết lộ đã gieo dấu hiệu lên Vũ sí để giám sát hắn. Hàn Lập tự phát hiện dấu hiệu và nhận ra dù nhận lời hay từ chối đều nguy hiểm, vì vậy quyết định tìm hiểu nội tình Thiên Bằng tộc để đưa ra điều kiện tự bảo vệ, nếu không sẽ mạo hiểm bỏ chạy. Hắn dành một ngày một đêm đọc sách trong thành, trở về quán Quý Tân suy tính rồi tới đại điện giao dịch vào sáng ngày thứ ba. Tại khu giao dịch nằm sâu trong vách núi, Hàn Lập nhìn thấy nhiều tầng điện cùng vô số người Thiên Bằng qua lại."},{"chuong":1417,"tieuDe":"Thanh La Quả","tomTat":"Hàn Lập theo ba người Thiên Bằng tiến vào một quảng trường buôn bán và quan sát cách cột đá trung tâm truyền tin giao dịch bằng hai loại văn tự xanh, đỏ. Sau khi tự chạm vào các dòng chữ để kiểm chứng, hắn phát hiện tin rao bán Thanh La quả, một linh quả quý hiếm đã thất truyền trong Nhân tộc gần nghìn năm. Hắn nhớ lại Thanh La quả có liên quan đến Thiên La đan, loại đan dược có thể phối hợp với nhiều linh dược và hỗ trợ tu sĩ Luyện Hư nhưng hiệu quả cực kỳ thất thường, thậm chí có thể khiến người dùng mất mạng. Linh quả này phải mất năm sáu nghìn năm mới chín, mỗi cây Chu Linh chỉ kết một quả rồi mất linh khí, trong khi quả lại khó bảo tồn lâu. Dù thông tin giao dịch cho thấy việc lấy quả có trở ngại, Hàn Lập vẫn quyết không bỏ qua cơ hội và lập tức bay lên tầng thứ chín của đại điện giao dịch. Hắn tìm thấy Vạn Lôi Phường, đi xuyên qua quầng sáng che cửa rồi âm thầm dùng thần niệm dò xét nam tử khô gầy cùng hai người Thiên Bằng bên trong. Kết quả dò xét khiến sắc mặt Hàn Lập đột ngột thay đổi."},{"chuong":1418,"tieuDe":"Ba Lựa Chọn","tomTat":"Hàn Lập bước vào một cửa tiệm trong đại điện giao dịch và chứng kiến đôi phu phụ tu sĩ Luyện Hư thất bại trong việc đổi Tử Tiên Mộc vì không có Hấp Linh Thạch. Khi hắn hỏi mua Thanh La Quả, Điếm chủ họ Ngư dùng cự lực vô hình thử sức nhưng bị kim mang của Hàn Lập phá vỡ. Điếm chủ đưa ra ba lựa chọn: giao U Minh Liên hoặc Hắc Ám Huyết Tinh, trả năm sáu trăm viên Cực Phẩm Linh Thạch, hoặc dùng thần thông lôi điện hỗ trợ thu phục một con linh thú. Hàn Lập chứng minh năng lực bằng cách ngưng tụ hơn mười lôi cầu màu bạc rồi nhận lời thực hiện lựa chọn thứ ba, hai bên hẹn gặp lại sau bốn ngày. Trước khi rời đại điện, hắn tiếp tục tìm kiếm và thu được nhiều tài liệu quý hiếm của Thiên Bằng Tộc. Trong số đó có một linh dược phối hợp được với Kim Tủy Tinh Trùng, khiến hắn chỉ còn thiếu hai loại linh dược để chuẩn bị đủ tài liệu ngưng hóa Pháp Tướng Chân Thân."},{"chuong":1419,"tieuDe":"Côn Bằng Xá Lợi Và Thiên Bằng Chi Thệ","tomTat":"Hàn Lập chấp nhận gia nhập Thiên Bằng tộc và giả làm thánh tử dự thí luyện, nhưng yêu cầu một viên Côn Bằng xá lợi cùng quyền lưu danh trên phó quyển Thiên Bằng Chi Thệ. Tư trưởng lão và mỹ phụ phản đối vì hai thứ đều là trọng bảo hữu hạn, song Kim Duyệt đặt sự tồn vong của tộc lên trên tổn thất và chấp thuận cả hai điều kiện. Đổi lại, Hàn Lập phải ký huyết thệ tận lực hành sự; nếu hắn khiến thí luyện thất bại, Kim Duyệt có thể hao tổn thọ nguyên phá bỏ sự bảo hộ rồi giết hắn. Sau khi Hàn Lập rời đi, Kim Duyệt giải thích rằng lời thệ chỉ hạn chế người Thiên Bằng tộc nên vẫn có thể nhờ ngoại tộc xử lý hắn nếu cần. Ba huynh muội Phong Khiếu, Bạch Lôi và Bạch Ngưng tới thăm Hàn Lập trước ngày cử hành nghi thức. Sáng hôm sau, tám người trẻ dẫn hắn tới quảng trường khai linh, nơi Kim Duyệt cùng các trưởng lão chuẩn bị dung hợp Côn Bằng chân huyết, luyện hóa xá lợi và truyền thuật biến thân. Kim Duyệt cảnh báo nguy cơ bị Côn Bằng chi lực phản phệ và tâm ma xâm nhập, nhưng Hàn Lập vẫn chấp nhận. Một thị nữ dâng chậu bạc, Kim Duyệt phá lớp bạch quang che phủ và làm lộ chiếc bình xanh cổ xưa dùng cho bước tiếp theo của nghi thức."},{"chuong":1420,"tieuDe":"Chân Huyết Nhập Thể","tomTat":"Kim Duyệt cùng Tư trưởng lão và mỹ phụ dùng huyết liên, lá chuối xanh cùng linh lực tinh thuần để đưa Côn Bằng chân huyết vào cơ thể Hàn Lập. Dù bị hương sen làm mê man, Hàn Lập vẫn giữ được một tia tỉnh táo và được xác nhận đủ khả năng tiếp nhận chân huyết. Kim Duyệt bí mật xác lập hắn làm thánh tử thứ ba của Thiên Bằng tộc, đồng thời yêu cầu toàn bộ cao tầng giữ kín thân phận và dùng việc phái hắn ra hải ngoại làm vỏ bọc. Nàng thông báo kỳ thí luyện đã bị Xích Dung tộc, Độ Nha tộc cùng nhiều phân chi thúc đẩy lên sớm, khiến thời gian chuẩn bị chỉ còn hai tháng, rồi ra lệnh truy sát những kẻ ngoại tộc đang xâm nhập địa bàn. Kim Duyệt còn chọn xá lợi của Hồng Vân để dùng cho Hàn Lập dù biết bên trong vẫn còn thần niệm hỗn tạp và có thể gây hậu hoạn. Hai ngày sau, Hàn Lập đã hóa thành Bằng điểu khổng lồ, thi triển phong nhận, lôi cầu, phong độn và biến hóa thân thể tới hơn trăm trượng. Kim Duyệt cho rằng Côn Bằng chi vũ từng được hắn luyện hóa đã sớm cải biến thể chất, nhưng Tư trưởng lão vẫn chưa hoàn toàn tin tưởng lời giải thích này."},{"chuong":1421,"tieuDe":"Kinh Chập Thập Nhị Biến","tomTat":"Sau khi dung hợp chân huyết Côn Bằng và xá lợi, Hàn Lập khôi phục hình người, biểu hiện Chân thánh pháp tương và được Thiên Bằng tộc chấp nhận cho tham gia thí luyện. Kim Duyệt cho phép hắn tự do hoạt động trong Thánh thành trong hai tháng, đồng thời yêu cầu hắn lưu danh vào phó quyển Thiên Bằng chi thệ trước khi lên đường. Trở về Quý Tân quán, Hàn Lập dùng Đại Diễn Quyết trấn áp tinh thần lực hung ác của Hồng Vân và phát hiện trong đó có Kinh Chập Thập Nhị Biến. Qua sự chuyển đổi của đồ án pháp tương giữa Côn Bằng, Ngũ Sắc Khổng Tước và Kim Viên, hắn xác nhận mình đã nắm ba loại khẩu quyết nhưng còn thiếu chân huyết thích hợp để thi triển trọn vẹn. Hàn Lập cũng biết Hồng Vân từng sáng lập công pháp này rồi bị chân huyết phản phệ đến mức tự bạo, vì vậy quyết định giữ kín khẩu quyết với Thiên Bằng tộc. Hai lần kích thích trong quá trình dung hợp đã phá vỡ chướng ngại tu luyện, giúp hắn tiến lên Hóa Thần hậu kỳ và phải dùng đan dược củng cố cảnh giới. Một ngày sau, Hàn Lập tới Vạn Lôi phường dự hẹn, nhưng tại cửa hàng đã có nhiều vị khách khác và một đại hán hắc giáp lập tức chất vấn điếm chủ về sự cạnh tranh này."},{"chuong":1422,"tieuDe":"Tu Di Động Thiên","tomTat":"Tại cửa hàng, điếm chủ họ Ngư đề nghị Hàn Lập, một thanh niên sắc mặt âm nhu và một đại hán hắc giáp hợp sức dùng thần thông lôi điện để hàng phục linh thú. Ông đưa Băng Tâm Tinh, Tử Quang Thiết và Thanh La Quả đã bị hạ cấm chế ra cho ba người kiểm tra trước, trong đó Hàn Lập kín đáo dùng linh mục dò xét Thanh La Quả nhưng không nói ra điều mình phát hiện. Sau khi thỏa thuận được xác lập, điếm chủ dẫn cả nhóm tới một kiến trúc bí mật do hai đệ tử Kết Đan canh giữ trong khu vực hẻo lánh của thánh thành. Tại đây, ông công khai một Tu Di Động Thiên Đồ có tỳ vết, đồng thời tiết lộ nó là một trong ba phế phẩm từng được Ngũ Quang Tộc luyện chế từ linh cốt Ngũ Sắc Khổng Tước rồi thất lạc. Điếm chủ cho biết linh thú đang ở trong động thiên và kích hoạt quyển trục, khiến quang mang ngũ sắc dung nhập vào bức cổ họa sơn thủy trên tường. Hàn Lập không chống lại lực truyền tống nhưng âm thầm tăng cường linh quang hộ thể, rồi cùng những người còn lại bị cuốn vào động thiên."},{"chuong":1423,"tieuDe":"Lôi Thú","tomTat":"Hàn Lập cùng điếm chủ họ Ngư, thanh niên sắc mặt âm nhu và đại hán hắc giáp được truyền tống vào không gian bên trong Tu Di Động Thiên Đồ, rồi tiến tới tòa các lâu giam giữ linh thú. Tiếng sấm từ tầng hai tác động mạnh tới thần thức, buộc Hàn Lập phải vận chuyển Đại Diễn Quyết để khôi phục tỉnh táo trước khi cả nhóm vượt qua màn sáng. Bên trong cấm địa, tám mươi mốt cột đồng tạo thành lưới điện màu đen đang giam một sinh vật ẩn trong hắc vụ. Điếm chủ họ Ngư đặt Hào mang thú đã bị chế trụ lên cột đồng, khiến Lôi thú nổi giận, xua tan hắc vụ và hiện nguyên hình nửa người nửa chim. Lôi thú đồng thời phát động quyền ảnh bạch quang, tên điện màu lam và giao long điện màu vàng, nhưng cả ba đợt công kích đều bị Phược Lôi Tiêu Quang đại trận chặn lại. Sau khi chứng minh năng lực khắc chế của đại trận, điếm chủ đưa Hào mang thú xuyên qua lưới điện tới vị trí chỉ cách Lôi thú một xích."},{"chuong":1424,"tieuDe":"Ngũ Sắc Thiên Lôi","tomTat":"Lôi thú nuốt Hào mang thú đã mất sức phản kháng, sau đó thu nhỏ thân thể và ẩn mình trong hắc khí. Từ lời điếm chủ từng nói Lôi thú là sinh vật độc nhất vô nhị trong Linh giới, Hàn Lập suy ra nó có thể không thuộc giới này, khiến những người còn lại liên tưởng đến Chân Tiên giới. Bị thanh niên sắc mặt âm nhu truy vấn và viện dẫn người anh là trưởng lão Thiên Bằng tộc, điếm chủ tiết lộ Lôi thú là lôi điện chi linh do hắn dùng bí thuật truyền từ Chân Tiên giới để thôi sinh. Hàn Lập nhận thấy cái giá hàng phục quá lớn nên nghi ngờ con thú còn thần thông hoặc công dụng bí mật mà điếm chủ chưa nói rõ. Điếm chủ yêu cầu ba người liên tục truyền lôi điện chi lực vào Lôi thú, đồng thời điều khiển Tu Di Động Thiên đồ biến khu vực lầu các thành một bình đài lộ thiên. Hắn kích phát toàn bộ thiên địa nguyên khí trong họa đồ để mô phỏng yêu lôi, chấp nhận khiến bảo vật bị hủy một nửa và hứa thưởng thêm lượng lớn tinh thạch nếu thành công. Cuối cùng, một đạo ngũ sắc điện hồ xuất hiện; dù chỉ mang khoảng một phần nghìn uy lực của ngũ sắc thiên lôi cấp Đại Thừa, nó vẫn khiến Hàn Lập không chắc những người tại chỗ có thể đỡ nổi một kích."},{"chuong":1425,"tieuDe":"Hàng Thú","tomTat":"Các đồng trụ trong cấm chế huyễn hóa long thủ, phóng hắc sắc điện hồ đuổi kịp lôi thú đang thi triển lôi độn rồi biến thành xiềng xích trói chặt nó. Điếm chủ họ Ngư cắm năm hắc tinh chủy thủ vào tứ chi và trái tim con thú, khiến tứ sắc điện hồ hộ thể suy yếu và biến mất. Hắn kích phát tinh hạch của mình bằng máu, đưa nó vào đầu lôi thú rồi yêu cầu Hàn Lập, đại hán và thanh niên âm nhu cùng truyền ba loại lôi điện vào nghi thức. Năm chủy thủ hấp thu và chuyển hóa lượng lôi lực này, khiến cả ba người trợ giúp tiêu hao quá nửa linh lực. Nam tử khô gầy tiếp tục dùng mộc bài xanh biếc kéo hơn nửa tinh hồn lôi thú ra khỏi thân thể, nhưng con thú bất ngờ tỉnh lại, khôi phục tứ sắc điện hồ và thu tinh hồn trở về. Khi ba người trợ giúp đều không thể tăng thêm lôi lực, điếm chủ quyết định mạo hiểm thi triển ngũ thải thiên lôi và bay lên chuẩn bị thi pháp."},{"chuong":1426,"tieuDe":"Dẫn Lôi Châu","tomTat":"Điếm chủ họ Ngư liên tục hao tổn tinh huyết, dùng huyết phù và huyết võng ép ngũ sắc thiên lôi co thành lôi cầu. Nhờ Hàn Lập cùng hai người trợ giúp áp chế, hắn dùng mộc bài kéo tinh hồn Lôi thú khỏi thể xác rồi phong ấn. Sau khi tuyên bố thành công, Điếm chủ họ Ngư trở mặt, ngụy trang Dẫn Lôi Châu thành ba hộp thù lao để dẫn thiên lôi ám toán mọi người; thanh niên âm nhu và đại hán hắc giáp bị đánh ngã, còn Hàn Lập dùng kim sắc lôi bào tránh nạn. Thân thể Lôi thú vẫn biểu lộ linh trí và bất ngờ tập kích Hàn Lập, nhưng hắn thi triển Lôi độn né tránh rồi phá đồng trụ cùng cấm chế giam giữ. Hàn Lập không rút lui mà yêu cầu Điếm chủ họ Ngư giao vật đã thỏa thuận, đồng thời chỉ ra đối phương đã suy yếu nghiêm trọng vì mất nhiều tinh huyết. Trước thế giáp công của Điếm chủ họ Ngư và Lôi thú, hắn gọi Đề Hồn thú, thả phi kiếm và hiện hóa nhiều pháp tướng cùng bảo vật để chuẩn bị giao chiến."},{"chuong":1427,"tieuDe":"Kiêng Kỵ","tomTat":"Hàn Lập phô bày Ngũ Sắc Thiên Phượng pháp tướng và sức mạnh của Đề Hồn thú, đồng thời chỉ ra tu vi điếm chủ họ Ngư đã suy giảm để buộc đối phương chấp nhận thương lượng. Điếm chủ thừa nhận Thanh La quả chỉ là hình ảnh do bí thuật Ngũ Quang tộc huyễn hóa, còn Hàn Lập dùng máu huyết phá biến ảo và lấy được hột quả thật cùng mấy khối cực phẩm linh thạch. Hàn Lập bác bỏ ngầm ý diệt khẩu, yêu cầu mang thanh niên sắc mặt âm nhu và đại hán hắc giáp đang hôn mê rời đi, đồng thời nhận ra điếm chủ có ý dùng Lôi thú luyện thành thân ngoại hóa thân. Khi Tu Di động thiên bắt đầu tan rã vì mất thiên địa nguyên khí, điếm chủ mở quang môn đưa mọi người ra ngoài, còn Tu Di Động Thiên Đồ sau đó rơi xuống và hóa thành tro bụi. Sau khi Hàn Lập rời đi, điếm chủ ra lệnh cho hai môn nhân thu dọn đồ đạc, chuẩn bị dùng Truyền Tống Trận ngầm để trốn sang Ngũ Quang tộc bằng một thân phận khác. Ông uống hai viên đan màu xanh biếc, thay đổi hoàn toàn dung mạo và thân hình rồi đi xuống mật đạo. Hàn Lập đưa hai người hôn mê tới một nơi vắng vẻ, kiểm tra họ và phóng hơn mười cây ngân châm vào thân thể, nhưng mục đích của thủ đoạn này chưa được làm rõ."},{"chuong":1428,"tieuDe":"Thiên Bằng Thánh Tử","tomTat":"Sau khi tỉnh lại từ vụ ám toán bằng Dẫn Lôi Châu, thanh niên sắc mặt âm nhu và đại hán hắc giáp kết luận Điếm chủ họ Ngư đã trở mặt rồi bỏ trốn, còn Hàn Lập che giấu diễn biến thật và từ chối cùng họ truy tìm lão. Hàn Lập trở về Quý tân quán, dùng đan dược củng cố cảnh giới Hóa Thần hậu kỳ, tham ngộ Thiên Bằng biến và nhận thấy Man biến thuật giúp thân pháp tiến bộ. Hai tháng sau, Bạch Bích phụng lệnh Đại trưởng lão tới đón hắn, đồng thời tiết lộ mình là Thánh tử Thiên Bằng tộc, là cháu của Bạch Lôi và Bạch Ngưng, và đã kích phát Côn Man Chân Thánh huyết mạch. Bạch Bích đưa Hàn Lập tới đại điện trong một tòa thành cổ bằng bạch thạch, nơi Kim Duyệt cùng các trưởng lão và một hắc bào nam tử đang chờ. Nữ Thánh tử Lôi Lan đến muộn vì vừa lĩnh ngộ pháp quyết và được Kim Duyệt miễn trách. Kim Duyệt giải thích Uyên thí luyện quyết định sự tồn vong của Thiên Bằng tộc, trong khi Bạch Bích và Lôi Lan có nguy cơ bị Thánh tử các tộc thù địch sát hại. Vì vậy, bà đề nghị Hàn Lập tạm gia nhập Thiên Bằng tộc với thân phận Thánh tử thứ ba để hỗ trợ hai người vượt qua thí luyện."},{"chuong":1429,"tieuDe":"Phi Linh Chư Tộc","tomTat":"Kim Duyệt ra lệnh che giấu nguồn gốc thật của Hàn Lập, chỉ cho phép công bố hắn là người được Thiên Bằng tộc bồi dưỡng tại hải ngoại. Nàng cùng Thạch trưởng lão, Tư trưởng lão và mỹ phụ dùng linh vũ mở phong ấn Thiên Bằng chi thệ, sau đó dùng gương đồng thu hồi hư ảnh đại điểu phát ra từ quyển trục. Hàn Lập dùng một giọt tinh huyết vàng nhạt viết tên thật lên thệ ước, qua đó chịu sức ràng buộc bí ẩn và khiến các trưởng lão chú ý tới mức độ cường đại của thân thể hắn. Tư trưởng lão tiếp tục giảng giải về Địa Uyên thí luyện, cuộc thí luyện do chi thứ bảy mươi hai của Phi Linh tộc tổ chức định kỳ ba trăm năm một lần. Vài ngày sau, Hàn Lập cùng đoàn người cưỡi cự điểu trắng rời Thánh thành, và ba tháng sau nhiều thành viên Phi Linh tộc đã tụ tập trên sân đá xanh ở đỉnh một cự phong. Tại đây, Tuân huynh hóa thành hạc tiên giao đấu với một thanh niên Giác Thứu tộc trong hình thái quái điểu một sừng, bốn cánh. Sau màn đối công bằng đao sáng, cuồng phong, cột sáng trắng và tia đỏ, thanh niên Giác Thứu tộc hóa thành hoàng chuông, dùng tiếng chuông chấn động thần thức đánh Tuân huynh bất tỉnh và giành chiến thắng."},{"chuong":1430,"tieuDe":"Ngọc Hoàng Đỉnh","tomTat":"Gần võ đài, nam tử hóa hạc thừa nhận thất bại trước Thiên chung giáng Ma thần thông của thanh niên Bị Thức tộc, còn người thắng tiếp tục khiêu chiến cho đến khi nghe tin thánh tử các tộc lớn đã tới. Đoàn Thiên Bằng tộc do Kim Duyệt và Thạch trưởng lão dẫn dắt cùng Hàn Lập và ba thánh tử hội quân với Xích Dung tộc, Ngũ Quang tộc để tiến về Ngọc Hoàng Đỉnh. Trên đường, Kim Duyệt từ chối đề nghị sáp nhập, khiến Chúc trưởng lão đe dọa sẽ vận động trưởng lão hội cưỡng ép xóa bỏ Thiên Bằng tộc nếu các thánh tử thất bại trong thí luyện. Thu phu nhân tiếp đó chất vấn liệu Xích Dung tộc muốn thâu tóm Thiên Bằng tộc để đàn áp Cửu Việt tộc hay không, nhưng Chúc trưởng lão phủ nhận. Mười thành viên trưởng lão hội xuất hiện nghênh đón và xác nhận thịnh hội có thể bắt đầu dù Quỷ Diện tộc cùng Độc Cưu tộc chưa tới; Hàn Lập nhận ra hơn nửa số họ có tu vi Hợp Thể. Đoàn người đến cự phong, bước lên cây cầu bảy sắc và được dịch chuyển tức thời tới quần thể kiến trúc trên Ngọc Hoàng Đỉnh. Tại đầu cầu, các trưởng lão được mời vào điện hội kiến, còn Hàn Lập cùng những thánh tử khác được một thiếu nữ áo trắng dẫn đi thu xếp chỗ ở."},{"chuong":1431,"tieuDe":"Chúc Âm Tử","tomTat":"Ba nhóm Thánh tử Xích Dung, Ngũ Quang và Thiên Bằng cùng tới khu lầu các trên Ngọc Hoàng Đỉnh, qua đó cho thấy Thiên Bằng tộc đang lép vế rõ rệt về lực lượng. Hàn Lập đặc biệt cảnh giác với Chúc Âm Tử, một Thánh tử Xích Dung tộc có sát khí nặng và từng bảy lần một mình tiến vào Địa Uyên. Tiểu Trúc dẫn mọi người nhận nơi ở và thông báo chỉ giác kỹ tràng phía Đông cho phép tự do tỷ thí, còn tranh đấu ở nơi khác có thể bị phế bỏ tu vi. Sau khi nghỉ ngơi, Hàn Lập phát hiện Bạch Bích vẫn nhập định nhưng Lôi Lan đã rời đi, nên quyết định ra ngoài tìm nàng. Xích Thiên giả vờ tình cờ gặp Hàn Lập rồi tiết lộ Lôi Lan đã cùng Hồng Sa tới giác kỹ tràng, khiến hắn lập tức lên đường. Khi Hàn Lập đi xa, Chúc Âm Tử xuất hiện và xác nhận đây là kế hoạch do mình bố trí. Dựa vào lời miêu tả của Thiên Minh, hắn nhận định Hàn Lập chính là người từng đánh lui Thiên Minh, giết Xích hống cầm và phá hủy Hỏa long châu. Vì các trưởng lão Xích Dung tộc quyết ngăn Thiên Bằng tộc sinh ra Thánh chủ mới, Chúc Âm Tử cùng Xích Thiên bay về phía Đông để tiếp tục thăm dò thần thông của Hàn Lập."},{"chuong":1432,"tieuDe":"Giác Kỹ Tràng","tomTat":"Trên đường đi, Hàn Lập quan sát lực lượng Phi Linh tộc tập trung và nhận ra Nhân tộc cùng Yêu tộc thuộc nhóm tương đối nhỏ yếu tại Linh giới. Hắn gặp Tiểu Trúc ở một tiểu đình và biết Lôi Lan đã cùng Hồng Sa tới giác kỹ tràng, từ đó lo cuộc đấu sẽ ảnh hưởng đến địa uyên thí luyện và hiệp nghị với Kim Duyệt. Hàn Lập che giấu hành tung để tiếp cận nơi giao đấu, đồng thời phát hiện một ánh mắt âm hàn theo dõi mình nhưng không xác định được kẻ đó. Sau khi đánh bại một nam tử cánh lam, Hồng Sa lấy lôi tinh thạch làm điều kiện khiêu chiến Lôi Lan. Hàn Lập vẫn khoanh tay quan sát, khiến Hồng Sa bối rối vì kế hoạch ban đầu không diễn ra như dự tính. Lôi Lan nhận lời giao đấu, dùng lôi tơ màu bạc tấn công, còn Hồng Sa tạo hỏa vân và hàng loạt hỏa cầu phản kích. Cuối chương, Lôi Lan hợp nhất điện quang thành một cánh cung sét khổng lồ để nghênh đón hỏa cầu."},{"chuong":1433,"tieuDe":"Thử Dò Xét","tomTat":"Lôi Lan biến thành bạch điểu giao chiến với Hồng Sa trong hình thái hỏa điểu, đồng thời nhờ tử điện từ hồ lô vàng mà dần chiếm thượng phong. Sau khi nhận truyền âm, Hồng Sa biến linh vũ thành hỏa điểu thứ hai, đảo ngược cục diện và đẩy Lôi Lan vào nguy cơ trọng thương. Hàn Lập dùng điện độn tiến vào chiến trường, trong khi Chúc Âm Tử cũng xuất hiện, khiến cuộc đấu giữa hai nữ tử bị chấm dứt. Lôi Lan lúc này nhận ra mình chỉ là mồi nhử trong kế hoạch ép Hàn Lập bộc lộ thần thông. Chúc Âm Tử công khai khiêu chiến rồi tung năm trảo mang hóa thành cự lao có linh áp và sức ăn mòn khi Hàn Lập từ chối. Hàn Lập dùng ngọn núi đen chặn đòn, khôi phục những vết xước trên pháp bảo và quyết định nhận lời luận bàn. Chương kết thúc khi hắn hiện hai cánh và triệu ra bốn phong trụ màu xanh quanh mình để chuẩn bị nghênh chiến."},{"chuong":1434,"tieuDe":"Uyên Thủ Vệ","tomTat":"Hàn Lập dùng phong nhận và điện giao giao đấu với Chúc Âm Tử, nhưng hai bên vẫn chưa phân thắng bại rõ rệt. Chàng lợi dụng vụ va chạm giữa điện giao và viên châu đỏ đậm để áp sát Lôi Lan, dùng Hỏa linh ti phá vật cản rồi chủ động rời giác kỹ tràng vì không muốn ảnh hưởng tới nhiệm vụ quan trọng. Sau trận đấu, Chúc Âm Tử nhận ra Hàn Lập tinh thông thần thông phong, lôi và có ngọn núi đen đủ sức chống Xích viêm trảo, nên dự định tìm cách hóa giải. Trở về lầu các, Lôi Lan bị Kim Duyệt khiển trách vì mạo hiểm tranh đoạt Lôi tinh thạch từ Hồng Sa, còn Bạch Bích cũng bị trách vì biết chuyện mà không ngăn cản. Kim Duyệt cấm Hàn Lập, Lôi Lan và Bạch Bích ra ngoài cho tới khi thí luyện bắt đầu. Hai tháng sau, đoàn Phi Linh tộc cưỡi khoảng nghìn cự cầm và phi trùng rời Ngọc Hoàng đỉnh, tiến qua cao nguyên hoàng thổ tới cửa vào địa uyên. Tại tuyến phòng vệ có bức tường khổng lồ và những trụ bạch ngọc khắc phù văn, Uyên thủ vệ Kim Phong dẫn người ra nghênh đón. Ba trưởng lão quyền lực nhất hội liên tịch cũng xuất hiện và tỏ ra đặc biệt khách khí với Kim Phong."},{"chuong":1435,"tieuDe":"Tứ Sát Hóa Giáp Thuật","tomTat":"Hàn Lập nhận ra thanh giáp của Kim Trác và chiến giáp của hàng vạn Uyên thủ vệ đều do sát khí ngưng tụ, đồng thời đánh giá lực lượng trấn giữ Địa Uyên cực kỳ tinh nhuệ. Kim Trác báo cho các đại trưởng lão rằng hắc triều còn ít nhất một năm mới bộc phát, nhưng khí hắc ám đã nguy hiểm hơn bình thường và yêu vật cao giai sẽ xuất hiện nhiều hơn. Vì chưa có yêu vương và nếu bỏ lỡ phải chờ hơn trăm năm, ba đại trưởng lão quyết định vẫn tiến hành thí luyện. Uyên thủ vệ mở đường cho các đoàn vào khu nghỉ, nơi mọi người được bố trí khôi phục tinh thần và pháp lực trước ngày tiến vào Địa Uyên. Tại lầu các của đoàn Thiên Bằng tộc, Hàn Lập hỏi về phương pháp ngưng tụ sát khí thành áo giáp và giải phóng lượng sát khí từng bị Kim Cương quyết chèn ép trong cơ thể. Thạch trưởng lão xác nhận hắn thích hợp tu luyện rồi trao ống trúc chứa toàn bộ Tứ Sát Hóa Giáp Thuật. Hàn Lập tiếp nhận pháp quyết và bắt đầu ngưng tụ tầng sát giáp đầu tiên, khiến sát khí màu đen quanh thân xoay chuyển thành một tầng hắc phong."},{"chuong":1436,"tieuDe":"Nội Dung Thí Luyện","tomTat":"Sáng hôm sau, Hàn Lập báo với Thạch trưởng lão rằng hắn đã bước đầu luyện thành bí thuật mới và có thể tạm dùng đối địch. Kim Duyệt trao cho hắn trấn tộc chi bảo Lôi giao tiễn, món tiễn đao có thể sử dụng ngay bằng cách quán chú linh lực nhưng cũng dễ bị cường địch cướp đoạt. Hàn Lập cùng Bạch Bích và Lôi Lan tới nơi tập kết, tại đó hắn chú ý đến Ngao Thanh Chước của Thất Việt tộc và nhận ra địch ý từ Chúc Âm Tử. Thanh giáp nhân dùng mộc bài màu tím kích hoạt pháp trận bạc, khiến Phong Ma môn hiện ra và mở lối tới vùng đất đen phủ bụi trắng bên ngoài thành. Tam đại trưởng lão công bố nhiệm vụ mới là mang về Minh Diễm quả thành thục, loại linh quả hiếm chủ yếu xuất hiện ở các tầng sâu của Địa Uyên. Các thánh tử được tự quyết định cách hành động nhưng phải trở lại sau ba tháng, khi Phong Ma môn được mở lần nữa. Sau khi các trưởng lão quay vào thành, hơn trăm thánh tử Phi Linh tộc bị để lại bên ngoài cửa và chính thức bước vào kỳ thí luyện."},{"chuong":1437,"tieuDe":"Địa Uyên Nhất Tầng","tomTat":"Hơn trăm thánh tử Phi Linh tộc lần lượt chia thành các đội, rời cự tường và tiến vào Địa Uyên theo những tuyến khác nhau. Hàn Lập dẫn Bạch Bích cùng Lôi Lan xuất phát trước đội Xích Dung tộc, còn Ngao Thanh Chước bị một đại hán bốn đồng tử dẫn người bám theo. Để tránh chạm trán các đội khác, Hàn Lập chủ động đổi hướng rồi vượt qua phong tà, sương bụi và băng lao màu đen để tìm tới một cự uyên mênh mông. Ba người dùng nguyệt quang thạch soi đường, hạ xuống nhiều ngàn trượng và đặt chân tới tầng thứ nhất có mặt đất đen vàng, cây cối khổng lồ cùng nhiều loài chim thú kỳ dị. Lôi Lan giải thích rằng sinh vật nơi đây bị hắc ám khí tức ảnh hưởng nhưng phần lớn yêu vật chỉ thuộc cấp thấp. Sau khi dùng kiếm quang tiêu diệt đàn quái điểu tập kích, Hàn Lập xác định tầng này gần như không có Minh Diễm quả. Hắn quyết định bỏ qua việc tìm kiếm, chọn một cửa vào tầng hai hẻo lánh và buộc hai người đồng hành tuân theo quyền chỉ huy của mình."},{"chuong":1438,"tieuDe":"Âm Chu Phong","tomTat":"Sau bốn năm ngày phi hành trong tầng thứ nhất Địa uyên, Hàn Lập, Bạch Bích và Lôi Lan tiến vào một vùng thạch bích đen, hắc vụ và hàn phong, nơi thần niệm bị áp chế dữ dội. Hàn Lập dùng Nguyệt quang thạch dò đường rồi phát hiện hơn vạn Âm Chu phong đang bao vây cả nhóm. Trong khi hai đồng hành chuẩn bị thần thông ứng chiến, hắn tế Phệ linh thiên hỏa, để hỏa diễm tự động thiêu sạch đàn yêu vật và cắn nuốt hắc ám khí tức khiến chúng không thể phục hồi. Sức mạnh này khiến sự bất mãn của Bạch Bích và Lôi Lan đối với Hàn Lập giảm đi rõ rệt. Sau thêm một ngày một đêm, ba người gặp một sa mạc xám bạc tại vị trí mà cả ba pháp bàn đều ghi là con sông ngầm lớn, nhưng Hàn Lập quyết định không dừng lại điều tra. Khi bay sâu vào sa mạc, hắn phát hiện một ốc đảo có mùi máu tanh, còn Lôi Lan nhận thấy thiên địa nguyên khí tại đó đang hỗn loạn như vừa có người thi triển thần thông và đề nghị tới xem xét."},{"chuong":1439,"tieuDe":"Cự Linh Hoa","tomTat":"Hàn Lập, Lôi Lan và Bạch Bích đổi hướng theo mùi máu tanh, phát hiện một ốc đảo có huyết đàm cùng hơn mười xác uyên thú bị thạch trùy xuyên thủng. Sau khi dò xét, Hàn Lập dùng kiếm quang ép những Oán viên thú mai phục dưới đất phải lộ diện, còn Bạch Bích nhận ra toàn bộ ốc đảo là do Cự linh hoa huyễn hóa. Cự linh hoa hiện nguyên hình và phát động tập kích, nhưng Hàn Lập phá hủy nhụy hoa, điều khiển phi kiếm chém chết đàn yêu thú rồi trảm nát tâm hoa. Ba người chia nhau thu mật hoa làm tài liệu luyện đan, sau đó Lôi Lan bí mật dùng ngân lôi thiêu sạch hài cốt linh hoa. Khi họ đã rời đi, một Cự linh hoa màu đen lớn như núi xuất hiện, mang theo nữ tử mờ ảo ngồi trên ghế bạc và thuộc hạ lùn tịt. Nữ tử tức giận vì linh hoa cúng tế bị phá, ra lệnh truy tìm thủ phạm rồi vung roi da xanh biếc làm không gian dao động và phóng ra vô số hắc vụ."},{"chuong":1440,"tieuDe":"Yêu Viên","tomTat":"Nữ tử thần bí giao nhiệm vụ cho thuộc hạ rồi kích hoạt pháp trận trên cự hoa màu đen để trở về tầng ba Địa Uyên. Thuộc hạ của nàng lộ nguyên hình là Oán viên thú bốn tai đã khai mở linh trí, sau đó hòa tan và hấp thu hài cốt cự linh hoa khiến cơ thể phát sinh dị biến xanh lục. Một thánh tử Phi Linh tộc tưởng yêu thú đang trọng thương nên đánh lén, nhưng mắc bẫy hư ảnh và bị lục vụ ăn mòn thành dịch lỏng rồi hút sạch. Oán viên thú nhận ra kỳ thí luyện đã tới sớm, lần theo dấu vết và bắt đầu truy đuổi đoàn Hàn Lập. Ở phía trước, Hàn Lập đề nghị Lôi Lan cùng Bạch Bích nhận Vô cực bài để phòng khi thất lạc nhưng cả hai đều từ chối. Hắn chuyển sang dùng phi xa linh mộc có tốc độ và khả năng ẩn nặc cao, dù bảo vật này tiêu hao nhiều linh thạch và phòng ngự rất yếu. Phi xa tạm thời kéo giãn khoảng cách, song Oán viên thú tức giận tăng tốc tiếp tục bám theo, trong khi Chúc Âm Tử dẫn một đội thánh tử Xích Dung tộc tiến vào hạp cốc gần đường vào tầng thứ nhất."},{"chuong":1441,"tieuDe":"Thần Bí Sơn Mạch","tomTat":"Chúc Âm Tử dẫn đội Xích Dung tộc vượt qua hạp cốc tối tăm, dùng linh vũ hóa thành tên lửa tiêu diệt sạch đàn dơi rồi tiếp tục tiến xuống tầng hai. Ở một nơi khác, Ngao Thanh Chước bình thản dẫn đội truy đuổi Kim Nha Thú, bác đề nghị giết nó ngay và tuyên bố sẵn sàng tranh đoạt Minh Diễm Quả từ đội khác nếu cần. Nhiều đội thánh tử Phi Linh tộc đồng thời gặp trở ngại, trong đó ba người bị một yêu vật vốn thường xuất hiện ở tầng ba ép phải liều mạng ngay tại tầng một. Sau hai ngày hai đêm đi bằng linh xa, nhóm Hàn Lập phát hiện một dãy núi đen khổng lồ nằm tại nơi trên bản đồ vốn là bình nguyên. Qua kiểm tra dấu vết, Hàn Lập nhận định cả dãy núi mới xuất hiện trong khoảng gần trăm năm và có thể đã bị di chuyển tới bằng đại pháp lực, bảo vật hoặc pháp trận. Hai hướng vòng qua núi lần lượt bị Uyên Phong Đái và sào huyệt hơn mười vạn Hắc Uyên Phi Nghĩ chắn giữ, nhưng Hàn Lập vẫn kiên quyết không đi xuyên qua khe núi và chấp nhận chậm thêm một hai ngày. Nguyên nhân sâu xa là Minh Hồn Châu trong cơ thể hắn đột nhiên nóng lên, còn Đề Hồn Thú trong linh thú trạc trở nên bất an và liên tục gầm nhẹ khi tới gần dãy núi."},{"chuong":1442,"tieuDe":"Lục Ảnh","tomTat":"Sau khi Lôi Lan và Bạch Bích trở lại linh xa, nhóm Hàn Lập tiếp tục rời đi, trong khi một nữ tử bí ẩn ở tầng ba trách Bát Diện Thú thất bại và tuyên bố vẫn có thể tìm ra họ. Trên đường vượt tầng một, linh xa tiêu diệt đường lang khổng lồ cùng thạch yêu rồi đưa cả nhóm tới một sơn cốc phủ sương có thông đạo dẫn xuống tầng hai. Ba người vượt qua phi xà và Địa Uyên Chi Phong cực lạnh, trong đó Lôi Lan cùng Bạch Bích suýt bị nhốt lại và phải nhờ Hàn Lập trợ giúp. Vì đã hao phí nhiều thời gian, Hàn Lập quyết định bỏ việc tìm Minh Diễm Quả tại tầng hai, chọn thông đạo có nhiều cây để tiến thẳng xuống tầng ba và dùng pháp bàn xác định phương hướng. Một Nê khôi lỗi bí mật theo dõi họ từ trong bùn khiến Hàn Lập sinh ra cảm ứng, nhưng linh mục của hắn không tìm thấy dấu vết. Tại một ngọn núi nhỏ ở tầng một, huyết bào nhân quan sát cả nhóm qua gương đồng, nhận ra thần niệm Hàn Lập rất mạnh và quyết định bắt thần hồn hắn làm lễ vật cho Quỷ Bà để đổi lấy Huyết Ngư. Chương kết thúc khi huyết bào nhân truyền hồng quang vào một viên châu trong suốt, khiến nó xoay tròn và phát sáng."},{"chuong":1443,"tieuDe":"Địa Uyên Thâm Tằng (1)","tomTat":"Địa Huyết dùng một viên châu và bí thuật để liên lạc từ xa với lão phụ nhân đang phụ trách bồi dưỡng âm giáp huyền quỷ. Cuộc trao đổi hé lộ kế hoạch chung trong đó Mộc Thanh sưu tầm huyết thực tế tự, Lục Túc thu thập âm linh chi lực, Địa Huyết luyện chế khôi lỗi và lão phụ nhân chuẩn bị tám ngàn âm giáp huyền quỷ. Lão phụ nhân cho biết bà mới luyện thành ba trong tám âm giáp quỷ vương cần thiết vì mỗi quỷ vương đòi hỏi tinh hồn của một người cường đại và xác suất thành công rất thấp. Địa Huyết sau đó tiết lộ đã phát hiện một người Phi Linh Tộc ở Linh Tương Kỳ có thể cảm ứng phân thần hắn đặt trên nê khôi lỗi. Nhận thấy thần thức của người này đủ mạnh để làm nguyên liệu luyện quỷ vương, hắn đề nghị giao mục tiêu cho lão phụ nhân. Bà chấp nhận lễ vật nhưng yêu cầu Địa Huyết nói rõ thứ hắn muốn đổi lấy."},{"chuong":1444,"tieuDe":"Địa Uyên Thâm Tằng (2)","tomTat":"Địa Huyết nhận lời lấy tinh hồn Hàn Lập trong mười ngày để đổi lấy một phần vạn niên huyết ngư từ lão phụ nhân tóc trắng. Hai bên thống nhất tạm thời không quấy nhiễu các thánh tử Phi Linh Tộc tại ba tầng trên, miễn họ không cản trở đại sự hoặc tiến xuống dưới tầng bốn. Sau cuộc giao dịch, Địa Huyết phái ba huyết mộc khôi lỗi truy sát đoàn Hàn Lập và thu tinh hồn. Ở một vùng núi thần bí, người cao lớn khoác áo choàng đen đứng dưới tế đàn thờ nhãn cầu khổng lồ đang hút hôi khí. Tại tầng sáu, lão phụ nhân tóc trắng ra lệnh cho hai nữ tử hợp nhất minh hỏa từ tiểu bình và tiêu phiến để luyện bóng người bất động trong hồ sâu. Trong khi đó, Hàn Lập dẫn Lôi Lan và Bạch Bích vượt tầng hai, dùng linh mục tránh yêu vật để hai người đồng hành hồi phục pháp lực. Đến ngày thứ hai, bốn đạo thúy mang bất ngờ áp sát từ hai hướng, buộc cả đoàn dừng độn quang để ứng phó."},{"chuong":1445,"tieuDe":"Phích Lịch Diệt Địch","tomTat":"Tần Hiểu của Dạ Lục Tộc dùng thúy toa chạy trốn ba thánh tử Hoàng Phong Tộc rồi viện dẫn minh ước với Thiên Bằng Tộc để cầu cứu nhóm Hàn Lập. Khi ba viện binh Hoàng Phong Tộc cưỡi mộc điểu xuất hiện, những kẻ truy đuổi phong tỏa đường lui và quyết định giết cả nhóm. Hàn Lập chủ động dùng lôi độn áp sát, phối hợp tiếng hừ chấn thần, Nguyên Từ Thần Sơn và Nguyên Từ Thần Quang để giết cao giai Linh Tương. Hai kẻ còn lại hóa thành quái điểu bỏ chạy nhưng lần lượt bị thanh sắc tiễn đao chém đôi và ngũ sắc quang diễm thiêu thành tro. Ba viện binh kinh hãi trước chiến lực của Hàn Lập nên lập tức cưỡi mộc điểu tháo chạy. Hàn Lập không truy kích, chỉ thu ngân sắc viên bàn của kẻ đã chết rồi yêu cầu Lôi Lan, Bạch Bích và Tần Hiểu rời khỏi chiến trường."},{"chuong":1446,"tieuDe":"Băng Sát Chi Địa Và Lời Của Vạn Đằng","tomTat":"Trên đường đồng hành, Tần Hiểu tiết lộ hai thánh tử Dạ Lục Tộc đi cùng mình đã chết và nàng bị Hoàng Phong Tộc truy sát vì mang Hỗn Nguyên Hồ. Biết bảo vật có thể thao túng hỗn nguyên lực nhưng đã cạn hỗn nguyên tinh thạch, Hàn Lập vẫn không tỏ ý đoạt lấy, khiến Tần Hiểu yên tâm tiếp tục đi cùng và kết giao thân thiết với Lôi Lan. Sau hai ngày di chuyển, nhóm bốn người tới Băng Sát Chi Địa, nơi có nhiều băng sát yêu vật và lời đồn về yêu vương, rồi thận trọng tiến vào vùng băng đen. Tại lối xuống tầng ba, Chúc Âm Tử dùng Tinh Viêm Ti giết một hắc tê yêu trước khi chia lực lượng Xích Dung Tộc thành hai nhóm. Hắn dẫn Xích Thiên và Hồng Sa xuống tầng ba tìm Minh Diễm Quả, đồng thời giao Lạc Hồn Chung cho hán tử họ Vưu tổ chức phục kích nhóm Thiên Bằng Tộc bằng pháp trận ẩn nặc. Ở một khu rừng khác, khoảng hai mươi người Phi Linh Tộc có hình xăm bị ngàn vạn phi nga vàng kim vây kín gần cự trụ màu vàng và phải liên tục dùng bí thuật cùng bảo vật để phòng thủ."},{"chuong":1447,"tieuDe":"Tiểu Thú Và Băng Sát","tomTat":"Trong lúc các thánh tử Phi Linh Tộc bị đàn Kim Minh Nga vây khốn, Ngao Thanh và Phí Dạ vẫn đứng ngoài quan sát. Ngao Thanh từ chối lời cầu hôn của Phí Dạ vì cho rằng thực lực của hắn chưa đủ, đồng thời tiết lộ linh giác từ Thất Khiếu Thông Huyền Quyết khiến nàng đánh giá Hàn Lập là người sâu không lường được. Phí Dạ vì thế quyết định tìm Hàn Lập thử sức, rồi hóa thành cự điểu, hợp nhất với cự kiếm và dùng kim mang giết gần nửa đàn yêu trùng. Ngao Thanh tiếp tục triệu các hư ảnh đầu thú, dùng bảy luồng lục sắc quang hà hút và tiêu diệt gần hết số Kim Minh Nga còn lại. Tại Băng Sát Chi Địa, báo lân thú chủ động rời vòng trữ vật, phát hiện các yêu vật ẩn dưới băng rồi xé nát và hấp thu nguyên sát chi khí của chúng. Sau khi thôn phệ hơn một ngàn băng sát yêu vật, thân thể tiểu thú xuất hiện bạch sắc oánh quang và có dấu hiệu tăng tu vi, khiến Hàn Lập chú ý suy ngẫm."},{"chuong":1448,"tieuDe":"Băng Sát Yêu Vương","tomTat":"Hàn Lập nhận ra báo lân thú đã đạt cấp mười và băng sát chi khí tại đây có thể trở thành cơ duyên giúp nó phá bình cảnh Hóa Thần Kỳ. Khi nhóm tiến vào một hạp cốc sâu giữa Băng Sát Chi Địa, phản ứng cảnh giác của tiểu thú khiến Hàn Lập dùng linh mục phát hiện yêu vật ẩn dưới lớp băng. Bạch Bích xác nhận đối phương là băng sát yêu vương, một yêu vật lập tức ngưng tụ thành hắc sắc băng phượng và coi báo lân thú như sinh tử đại địch. Hàn Lập hóa thành điện hồ thanh bạch áp sát, dùng quyền ảnh hắc bạch phá cự trảo rồi đánh vỡ toàn bộ thân băng phượng. Báo lân thú lao vào thôn phệ gần một nửa hắc khí của yêu vương, trong khi Hàn Lập dùng hỏa diễm ngăn nó tái tạo thân thể. Sau khi tiểu thú nằm xuống hấp thu, Hàn Lập dùng bình ngọc màu trắng thu phần băng sát chi khí còn lại. Qua liên hệ tâm thần, hắn xác nhận báo lân thú đang hưng phấn chứ không gặp nguy hiểm và dùng thần niệm trấn an nó."},{"chuong":1449,"tieuDe":"Tiến Giai","tomTat":"Báo lân thú bất ngờ bắt đầu tiến giai dưới bạch quang từ trời, đồng thời tỏa ra mùi hương mãnh liệt có thể dẫn dụ yêu vật. Dù Bạch Bích cảnh báo nguy cơ băng sát yêu vật cấp cao kéo đến, Hàn Lập vẫn quyết định ở lại bảo vệ linh thú. Hắn dựng Thập Phương Diệt Viêm Trận và Đại Canh Kiếm Trận, giấu ngân sắc hỏa điểu dưới băng rồi lấy Tam Giác Linh Xa làm nơi chờ đợi. Lôi Lan, Bạch Bích và Tần Hiểu cân nhắc nhu cầu được Hàn Lập bảo hộ nên cũng tiếp tục ở lại. Một đàn băng tri chu đông đảo nhanh chóng tràn tới, khiến Tần Hiểu điều động mộc khôi lỗi hình thằn lằn nghênh chiến. Khi các khôi lỗi bị tơ nhện trói chặt và kéo ngã, nàng trực tiếp xuất trận, dùng lục diễm cùng lục sắc hỏa kiếm tiêu diệt hàng loạt yêu vật. Cuối chương, nhiều băng tri chu khổng lồ mọc cánh bay lên trời, khiến tình thế trở nên nguy hiểm hơn."},{"chuong":1450,"tieuDe":"Bích Mộc Yêu","tomTat":"Trong lúc Tần Hiểu giao chiến bên ngoài, Lôi Lan nhận đối phó đàn yêu lang còn Bạch Bích chặn đàn băng viên, rồi cả ba cùng tiêu diệt các yêu vật trung giai và trở về linh xa. Hơn trăm băng sát yêu vật bị mùi thơm của báo lân thú thu hút vào pháp trận, nơi Hàn Lập kích phát hồng sắc quang hà để hóa giải thần thông băng tuyết và làm chúng tan thành nước. Hắn dùng Hư Thiên Đỉnh phóng thanh ti xuyên qua hư không, giết sạch số yêu vật còn quanh quẩn ngoài trận. Trong nửa ngày tiếp theo, nhiều đàn yêu vật liên tục tập kích nhưng đều bị đại trận thiêu diệt, còn một yêu vật cấp cao bị Đại Canh Kiếm Trận giết chết. Khi mùi thơm của báo lân thú suy giảm và thú triều giải tán, Bích Mộc Yêu mang đôi cự chùy xuất hiện cùng một Chu Nho mặt xanh ẩn trên đầu. Chu Nho đòi nhóm Hàn Lập giao linh thú đang tiến giai, nhưng khi bị phớt lờ, hắn dùng quải trượng thúc Bích Mộc Yêu lao thẳng vào đại trận."},{"chuong":1451,"tieuDe":"Huyết Khôi Lỗi","tomTat":"Hàn Lập chờ Bích Mộc Yêu tiến vào Đại Canh Kiếm Trận, nhưng ba huyết khôi lỗi của Địa Huyết bất ngờ xuất hiện khiến Chu Nho dừng yêu vật ngay ngoài phạm vi trận. Ba khôi lỗi tập trung công kích Hàn Lập bằng huyết sắc quang trụ, xuyên qua Nguyên Từ Thần Quang và sát giáp trước khi bị lôi bào hóa giải. Khi chúng độn không áp sát bằng huyết nhận, Hàn Lập dùng thân thể phủ kim lân và song chưởng đen trắng đánh bật binh khí rồi thuấn di trở về linh xa để nhử địch. Đại Canh Kiếm Trận ép ba khôi lỗi hiện hình và cắt chúng thành vô số mảnh, nhưng chúng nhanh chóng tụ máu để tái tạo thân thể. Hàn Lập lập tức dùng Phệ Linh Thiên Hỏa thiêu cả ba huyết cầu thành tro, phá hoàn toàn năng lực tái sinh của chúng. Chứng kiến kết cục đó, Chu Nho điều khiển Bích Mộc Yêu âm thầm lui xa rồi chạy về phía tây. Hàn Lập định dùng Hư Thiên Bảo Đỉnh truy kích nhưng đổi ý khi biết báo lân thú đã hoàn thành tiến giai, sau đó truyền linh lực cho tiểu thú. Nhóm Lôi Lan trên linh xa cùng thở phào rồi bất ngờ đồng loạt biến sắc."},{"chuong":1452,"tieuDe":"Mộc Thanh Cùng Huyết Giao","tomTat":"Sau khi đẩy lui đám yêu vật, Hàn Lập tiếp tục bảo vệ Báo lân thú hoàn thành tiến giai lên Hóa Thần kỳ, rồi cho nó dùng đan dược và thu vào trữ vật trạc nghỉ ngơi. Lôi Lan và Bạch Bích kinh sợ khi nhận ra tiểu thú mang huyết mạch kỳ lân chân linh, sau đó cùng Hàn Lập lên Tam Giác Linh Xa tiến về tầng ba Địa Uyên. Ở nơi sâu trong Địa Uyên, Địa Huyết cảm ứng được ba huyết khôi lỗi cùng thần niệm của mình đã bị tiêu diệt nên dùng huyết châu liên lạc với Mộc Thanh. Hắn lấy linh mộc làm giá để mượn lực lượng Huyết Giao truy sát nhóm Phi Linh tộc, đồng thời yêu cầu mang tinh hồn của các mục tiêu về. Mộc Thanh chấp thuận, triệu Huyết Độc và giao hắc sắc trúc đồng chứa vị trí cùng ngoại hình của nhóm Hàn Lập, ra lệnh nó lên tầng hai giết người nhưng phải trở về báo cáo nếu phát hiện bất thường. Sau khi Huyết Độc rời đi, Mộc Thanh tiếp tục thúc giục thuộc hạ báo cáo việc tìm huyết thực vì thời gian tiến hành tế tự đã gần."},{"chuong":1453,"tieuDe":"Thiên Cương Huyết Lôi, Kim Ô Linh Hỏa","tomTat":"Tại tầng hai Bắc Uyên, bốn thánh tử Phi Linh tộc vừa đẩy lui một đàn hắc sắc độc hạt thì gặp người bí ẩn ẩn trong huyết vụ. Vì không tìm thấy những người mình truy lùng, kẻ này tùy ý thi triển Thiên Cương Huyết Lôi, xuyên không đuổi theo và thiêu cả bốn thành tro. Ở một nơi khác trong Địa Uyên, Hàn Lập, Lôi Lan, Bạch Bích và Tần Hiểu bị bảy người Hắc Linh tộc bao vây; thủ lĩnh đối phương thừa nhận đã nhận lợi ích từ các phân chi Xích Dung tộc để giết nhóm Thiên Bằng tộc. Sáu người Hắc Linh tộc dùng linh vũ tạo lồng Kim Ô Linh Hỏa có khả năng hấp thu pháp lực, buộc Lôi Lan, Bạch Bích và Tần Hiểu phải dốc sức phòng thủ. Hàn Lập dùng Ngũ Sắc Quang Diễm giữ vững thân mình rồi thả Phệ Linh Hỏa Điểu nuốt sạch toàn bộ hắc diễm. Sau khi phá vòng vây, hắn dùng độn thuật áp sát thủ lĩnh Hắc Linh tộc, lấy chiến giáp chặn ba lôi cầu, xé rách hắc sa và xuyên thủng ngực đối phương bằng cánh tay phủ kim sắc lân giáp."},{"chuong":1454,"tieuDe":"Hủ Diệp Lâm Cùng Minh Diễm Quả","tomTat":"Hàn Lập dùng Thanh Trúc Phong Vân kiếm cùng lôi độn tiêu diệt toàn bộ bảy thánh tử Hắc Linh tộc, không để tinh hồn hay kẻ bỏ chạy nào thoát được. Hắn thu giữ một chiếc linh vũ có kim mang, hắc sắc phù văn và khả năng sinh hắc diễm rồi quay lại hội hợp với Lôi Lan, Bạch Bích và Tần Hiểu, khiến thái độ của ba người đối với hắn càng thêm kính sợ. Đoàn người sau đó tới Hủ Diệp lâm, nơi hắc ám uế khí ngưng kết và có khả năng sinh Minh Diễm quả, nên quyết định dừng lại nửa ngày để tìm kiếm trước khi đi Vạn Đằng đạo. Tần Hiểu thả khôi lỗi thằn lằn, Lôi Lan dùng phi nghĩ màu bạc còn Bạch Bích điều khiển kim sắc tiểu xà dò xét cả khu rừng lẫn lòng đất. Trong lúc chờ đợi, Hàn Lập thoáng cảm ứng một luồng khí tức cực kỳ cường đại trên trời nhưng nó lập tức biến mất. Lôi Lan sau đó báo đã tìm thấy một Minh Diễm thụ có sáu quả, hơn phân nửa mang dáng vẻ thành thục, khiến cả nhóm lập tức theo nàng tới thủy đàm sâu trong rừng để xác minh."},{"chuong":1455,"tieuDe":"Huyết Hà Minh Châm","tomTat":"Hàn Lập xua bớt vụ khí và phát hiện một thủy đàm có nhiều cây kết Minh Diễm quả, với số quả chín đủ để cả nhóm phân chia. Trước lúc mọi người xuống hái quả, hắn phát hiện một kẻ cao lớn ẩn trong huyết vụ và dùng ngũ sắc đại thủ ép đối phương hiện thân. Hàn Lập ở lại nghênh chiến, còn Lôi Lan, Bạch Bích và Tần Hiểu xuống thủy đàm rồi bị yêu vật giống bạch tuộc dùng xúc tu cùng thủy tiễn tập kích. Kẻ trong huyết vụ bất ngờ phóng Huyết Hà minh châm sát trán Hàn Lập, nhưng mũi châm bị thân thể cứng như pháp bảo của hắn bật ngược và bị ngũ sắc quang diễm khống chế. Hàn Lập dùng Kinh Thần Thứ làm đối phương chậm phản ứng, phối hợp Phong Lôi Sí áp sát và lấy Thanh Trúc Phong Vân kiếm chém tới, song thanh sắc lân giáp chỉ bị xuyên vào vài tấc. Sau khi tránh huyết sắc quang trụ phản công, Hàn Lập thấy huyết vụ tản đi và nhận ra đối thủ là một Huyết giao toàn thân đỏ rực."},{"chuong":1456,"tieuDe":"Thiên Cương Huyết Lôi","tomTat":"Hàn Lập đối đầu một huyết giao Luyện Hư hậu kỳ và biết rằng chủ nhân bí ẩn của nó đã dặn phải đề phòng mình. Đối phương vận chuyển tinh huyết, triệu hồi huyết vân rồi dùng Thiên Cương Huyết Lôi liên tiếp phá năm tầng phòng ngự gồm Nguyên Từ Thần Quang, cự võng thanh ti, Thanh Trúc Phong Vân kiếm, lôi bào và sát giáp. Hàn Lập hiện pháp tướng ba đầu sáu tay, dùng quyền ảnh cùng thân thể cường hoành đánh tan những đạo huyết điện cuối, khiến huyết giao kinh hãi vì hắn chịu được đòn đánh có mười hai thành uy lực. Hàn Lập lập tức phản kích nhưng chỉ chém trúng thân ảnh trong huyết vụ, còn đối phương giữ lời rút lui và dùng độn thuật cực nhanh đào thoát để trở về báo cáo chủ nhân. Sau trận đấu, hai bàn tay Hàn Lập hóa đen và tỏa mùi cay, khiến hắn nhận ra mình không hoàn toàn vô sự và đánh giá phần thắng trong một trận tử chiến chỉ khoảng bảy thành. Lo ngại chủ nhân của huyết giao là mối đe dọa vượt quá khả năng hiện tại, Hàn Lập quyết định lập tức trở lại mặt đất để dựa vào các trưởng lão Phi Linh tộc. Trước khi rời đi, hắn dùng kiếm khí chém chết cự đại chương ngư đang cầm chân nhóm Lôi Lan và cho họ ba mươi giây thu hái Minh Diễm quả."},{"chuong":1457,"tieuDe":"Bỏ Chạy","tomTat":"Theo lệnh Hàn Lập, Lôi Lan, Bạch Bích và Tần Hiểu thu hoạch những quả Minh Diễm đã chín rồi lập tức rút khỏi khu vực, trong đó Tần Hiểu dâng phần của mình cho hắn. Hai ngày sau, Huyết Độc trở về đại điện tầng ba báo cáo thất bại và thừa nhận Hàn Lập có thân thể, độn thuật cùng nhiều thần thông vượt xa tu vi biểu hiện. Mộc Thanh xem Hàn Lập là cực phẩm huyết thực thích hợp cho nghi thức huyết tế, sau đó mang Huyết Độc truyền tống lên tầng hai để tự mình truy bắt. Nhóm Hàn Lập liên tục phi độn qua các tầng và nhanh chóng trở lại tầng một, nhưng hắn vẫn không cho phép ba người đồng hành nghỉ lại. Nhận ra một yêu vương Địa Uyên đang nhắm chủ yếu vào mình, Hàn Lập yêu cầu Lôi Lan, Bạch Bích và Tần Hiểu chia đường chạy về mặt đất. Một mình bỏ chạy, hắn dùng cực phẩm linh thạch bổ sung linh lực, phun tinh huyết tăng tốc và phát huy Phong Lôi Sí đến cực hạn khi hắc sắc hà quang áp sát. Dù hóa thành thanh bạch tế ti xuyên lướt hư không, Hàn Lập vẫn nghe rõ tiếng hừ của kẻ truy đuổi như vang ngay bên tai."},{"chuong":1458,"tieuDe":"Mưu Đồ","tomTat":"Mộc Thanh cùng Huyết Độc đón lõng Hàn Lập, biến hắc sắc quang hà thành trận pháp để cuốn hắn vào và cưỡng ép truyền tống về sào huyệt tại tầng hai Địa Uyên. Hàn Lập dùng Ích Tà Thần Lôi phá hắc hà cùng âm phong nhưng vẫn không thoát khỏi lực lượng vô hình trong trận, sau đó phải vận chuyển Đại Diễn Quyết để ổn định thần thức. Nhận thấy bầu trời sào huyệt bị cấm chế mạnh phong tỏa và đối phương chưa định giết mình, hắn tạm thời thuận theo Mộc Thanh vào đại điện. Tại đây, Hàn Lập uống Âm Sát Trà được luyện từ tám mươi mốt loại kỳ độc và xác nhận trà không gây hại mà còn giúp thần trí tỉnh táo. Mộc Thanh tự giới thiệu, chưa tiết lộ việc cần thương lượng nhưng sai Bích Nhi đưa hắn đến quý tân lâu nghỉ vài ngày. Sau khi Hàn Lập rời đi, nàng nói với Huyết Độc rằng mình đã từ bỏ ý định biến hắn thành huyết thực vì Ích Tà Thần Lôi có thể tăng thêm phần chắc chắn cho một đại sự chưa được công bố."},{"chuong":1459,"tieuDe":"Thần Lôi Chi Mê","tomTat":"Mộc Thanh ra lệnh cho Huyết Độc giám sát Hàn Lập, không để hắn rời khỏi Hắc Vụ Lâm trước khi nàng giải quyết mâu thuẫn liên quan đến Huyết lão quái. Nàng dùng kim sắc viên kính liên lạc với Lục Túc và biết lượng âm khí thu thập được đã đủ để Quỷ Bà ngưng luyện tám ngàn huyền quỷ, góp vào lực lượng mở đường tiến vào Minh Hà Chi Địa. Mộc Thanh tiết lộ Ích Tà Thần Lôi của Hàn Lập có thể khắc chế Minh Ma Chi Khí trong kết giới Minh Hà, nhưng hắn chưa biết pháp môn khu sử chính thức nên chưa phát huy trọn uy lực. Nàng muốn tự mình chỉ điểm và giữ quyền khống chế Hàn Lập, còn Lục Túc yêu cầu bốn người gặp trực tiếp tại Mộc Tiên Điện sau nửa tháng rồi mới quyết định. Trong lầu các, Huyết Độc hóa thành trung niên nho sinh, dùng mộc tủy tửu khoản đãi Hàn Lập và cho biết họ đang ở Hắc Vụ Lâm thuộc tầng ba Địa Uyên. Hắn tìm cách thuyết phục Hàn Lập ở lại Mộc Tiên Cốc bằng lời hứa về tài nguyên tu luyện, sau đó bất ngờ chuẩn bị nêu một điều khó hiểu. Nhận ra đối phương sắp dò hỏi, Hàn Lập lập tức vận hành Đại Diễn Quyết để xóa men say và đề cao cảnh giác."},{"chuong":1460,"tieuDe":"Gặp Lại Nguyên Dao","tomTat":"Huyết Độc dò hỏi vì sao thân thể Hàn Lập có thể làm Huyết Hà Minh Châm bật ngược và truy vấn nguồn gốc pháp tướng ba đầu sáu tay, nhưng Hàn Lập dùng linh dược cùng pháp môn ngoại tộc làm lời giải thích né tránh. Nhận ra Huyết Độc ở ngay lầu bên cạnh để giám thị, Hàn Lập cho thị nữ lui xuống rồi dựng cấm chế ngăn thần niệm dò xét. Từ việc Mộc Thanh đột ngột từ bỏ sát ý, hắn suy đoán Ích Tà Thần Lôi chính là nguyên nhân khiến mình được giữ mạng và quyết định tạm hoãn đào thoát để chờ đối phương nói rõ mục đích. Nửa tháng sau, Huyết Độc dẫn hắn tới Mộc Tiên Điện, nơi có nhiều cường giả bí ẩn đang tụ họp. Hàn Lập bất ngờ nhận ra Nguyên Dao và Nghiên Lệ đứng sau một mỹ phụ tóc bạc, qua đó biết hoàn hồn thuật năm xưa nhiều khả năng đã thành công. Nguyên Dao cũng nhận ra hắn nhưng nhanh chóng che giấu vẻ kinh ngạc, trong khi Nghiên Lệ chỉ cảm thấy quen mắt. Cuối cùng, mỹ phụ tóc bạc lạnh lùng nghi ngờ liệu một tu sĩ mới ở Linh Tương Kỳ như Hàn Lập có thật sự hữu dụng hay không."},{"chuong":1461,"tieuDe":"Tứ Đại Yêu Vương","tomTat":"Mộc Thanh, Lam đạo hữu, Lục Túc và Địa Huyết tranh luận về giá trị của Hàn Lập, cuối cùng thống nhất rằng Ích Tà Thần Lôi của hắn là công cụ quan trọng để phá Minh Hà cấm chế. Theo yêu cầu của Lục Túc, Hàn Lập phóng kim sắc lôi điện đánh tan âm phong thử nghiệm, nhưng chỉ khai một phần ba số thần lôi mà mình thực sự có thể khu sử. Lục Túc quyết định dành sáu năm để hắn học khu lôi chi đạo, gồm hai năm theo Mộc Thanh, hai năm theo Lam đạo hữu và hai năm tự lĩnh ngộ. Sau đó, bốn yêu vương lần lượt gieo hôi ti, hắc khí, lục quang và huyết vụ tiêu ký vào cơ thể Hàn Lập nhằm ngăn hắn đào thoát. Hàn Lập còn bị buộc phải ở lại Mộc Tiên Cốc trong hai năm đầu và không có quyền phản đối trước bốn cường giả Hợp Thể Kỳ. Cuối cuộc gặp, hắn âm thầm suy xét bí mật vận dụng Ích Tà Thần Lôi rồi kín đáo trao đổi ánh mắt với Nguyên Dao, trong khi nàng vẫn giữ vẻ thản nhiên."},{"chuong":1462,"tieuDe":"Tà Long Tộc","tomTat":"Hàn Lập âm thầm nghe các yêu vương thương nghị về Huyền quỷ khôi lỗi, việc luyện binh quy mô lớn và Minh Hà Chi Địa, đồng thời quan sát những điểm kỳ dị trong lai lịch của từng người. Sau hội nghị, Huyết lão quái nhắc lại việc hai huyết khôi lỗi bị Hàn Lập tiêu diệt và buộc hắn nhận lời làm một việc để bồi thường. Huyết Độc tiết lộ Ích Tà Thần Lôi chính là Mộc Thần Lôi thuộc ngũ hành chân lôi, từng khiến Tà Long Tộc phải truy tìm và phá hủy gần hết Thiên Lôi Trúc. Hàn Lập cũng biết thêm về cuộc đại chiến thời Linh giới sơ khai, khi các chủng tộc liên thủ tiêu diệt những cổ đại tộc từng áp bức họ. Mộc Thanh ra hạn hai năm để Hàn Lập nắm giữ khu lôi chi đạo, hẹn hắn đến Mộc Tinh Động và quyết định tự mình chỉ điểm. Khi trở về nơi ở, Hàn Lập phát hiện chữ “Nguyên” do Nguyên Dao bí mật lưu trong lòng bàn tay, qua đó hoàn toàn xác nhận thân phận nàng. Cuối cùng, hắn gọi một đoàn kim sắc lôi cầu ra và lặng lẽ suy xét về Ích Tà Thần Lôi."},{"chuong":1463,"tieuDe":"Mộc Tinh Động","tomTat":"Hàn Lập nhận ra Ích Tà Thần Lôi trong Thanh Trúc Phong Vân Kiếm có thể chính là Chí Mộc Thần Lôi thuộc ngũ hành chân lôi, nhưng cũng lo ngại chuyến đi Minh Hà Chi Địa do Mộc Thanh sắp đặt. Cuộc gặp lại Nguyên Dao khiến hắn nhớ chuyện nàng từng hủy Kim Đan cứu Nghiên Lệ, rồi chìm vào hồi ức về Nam Cung Uyển và những năm tháng tại Thiên Nam. Ba ngày sau, Mộc Thanh dẫn hắn xuyên qua cấm chế bí mật để vào Mộc Tinh Động, cho sử dụng một mật thất và hứa cứ bảy ngày sẽ chỉ điểm khu lôi chi đạo. Đổi lại, nàng phong tỏa cửa động và buộc hắn không được rời nơi này trong hai năm. Sau một thời gian tu luyện, tiểu thiên kiếp lần thứ hai của Hàn Lập giáng xuống bằng thanh sắc thiên lôi. Mộc Thanh xem đây là cơ hội để hắn tôi luyện khả năng khu lôi nên rời khỏi pháp trận, để hắn tự ứng phó. Hàn Lập triệu thanh sắc tiểu đỉnh, dựng phòng hộ rồi kết Ích Tà Thần Lôi thành kim sắc điện võng, hấp thu hơn trăm đạo điện hồ và dễ dàng vượt qua đợt thiên lôi đầu tiên."},{"chuong":1464,"tieuDe":"Thu Lôi","tomTat":"Hàn Lập dùng kim sắc điện võng do Ích Tà Thần Lôi tạo thành cùng Nguyên Từ Thần Quang để vượt qua đợt thiên lôi thứ hai. Khi đợt thiên lôi thứ ba mạnh hơn giáng xuống, hắn phối hợp ngũ sắc quang diễm, Nguyên Từ Thần Quang và Hư Thiên Đỉnh để thu toàn bộ thanh sắc lôi cầu. Sau tiểu thiên kiếp, hắn xác nhận số thiên kiếp chi lôi này có thể luyện thành lôi châu đủ sức uy hiếp tu sĩ Hợp Thể Kỳ khi được sử dụng đồng loạt. Hàn Lập cũng nhận ra mình chưa thể âm thầm thoát khỏi Mộc Tinh Động hoặc loại bỏ bốn đạo ấn ký, nên dự tính phối hợp Nguyên Từ Thần Quang với Ích Tà Thần Lôi để tạm che cảm ứng của chúng. Sau nhiều ngày, hắn dùng khoảng một nửa số thiên lôi để luyện thành hơn ba mươi thanh sắc lôi châu. Việc luyện chế tạm dừng khi Mộc Thanh gửi truyền âm phù gọi hắn tới thính đường, nơi Huyết lão quái đang chờ và được xác nhận là cố ý đến tìm hắn."},{"chuong":1465,"tieuDe":"Huyết Diễm Sơn","tomTat":"Huyết bào nhân thương lượng với Mộc Thanh và được phép mượn Hàn Lập trong một tháng rưỡi để hỗ trợ luyện chế khôi lỗi bằng Ích Tà Thần Lôi. Sau khi truyền tống tới Huyết Diễm Sơn, Hàn Lập được giới thiệu tứ đại Tử Huyết khôi lỗi rồi theo hai huyết bào nhân đi qua mạng lưới thông đạo đầy khôi lỗi tuần tra. Từ số lượng và thực lực của chúng, hắn nhận ra khôi lỗi chi đạo của chủ nhân nơi đây sâu không lường được, nhưng cho rằng ưu thế ấy còn đến từ cảnh giới và tài nguyên Linh Giới. Tới hồ dung nham bao quanh Huyết Diễm Cung, Hàn Lập dùng Minh Thanh Linh Mục phát hiện mạng lưới cấm chế tơ trong suốt liên kết với hồ và các khối tinh thạch đỏ. Một chiếc chuông vàng khiến thần thức hắn rung động, song Đại Diễn Quyết giúp hắn nhanh chóng ổn định. Tiếng chuông gọi Độn Quy Thú lên khỏi dung nham, con thú nhận thức ăn rồi chở ba người vượt hồ tới cung điện. Tại đây, hai đội sinh linh có khí tức sinh mệnh nhưng hoàn toàn im lặng ra nghênh đón và chấp hành lệnh mở Âm Hỏa Điện, khiến Hàn Lập âm thầm nghi ngờ."},{"chuong":1466,"tieuDe":"Linh Thị","tomTat":"Tại Âm Hỏa Điện, Huyết lão quái giải thích Linh Thị là bán khôi lỗi được tạo bằng cách dung hợp linh thể chưa có nguyên thần và tinh hồn với thân khôi lỗi. Lão trao cho Hàn Lập bí thuật Địch linh nhập vật, mười hai vũ nữ, mười bốn nhạc sĩ Linh Thị cùng ống trúc ghi phương pháp luyện chế và tế luyện. Hàn Lập nghi ngờ sự ưu đãi bất thường này có liên quan đến Ích Tà Thần Lôi nên kiểm tra kỹ các tượng gỗ rồi niêm phong chúng vì chưa thể xác nhận an toàn. Sang hôm sau, hắn được dẫn tới Huyết Luyện Đường và tận mắt thấy Tử Huyết khôi lỗi khổng lồ chứa một tia phân thần của Huyết lão quái. Chỉ một ánh mắt của khôi lỗi đã tạo sức ép khiến Hàn Lập phải dựa vào Đại Diễn Quyết mới chịu đựng được. Huyết lão quái sau đó công bố nhiệm vụ thật sự là để Hàn Lập quán chú Ích Tà Thần Lôi vào Minh Ấn Phù Trận trên khôi giáp, rồi phong ấn cả phù trận lẫn thần lôi để hoàn thiện khôi lỗi."},{"chuong":1467,"tieuDe":"Hai Loại Phù Lục","tomTat":"Hàn Lập ở lại Huyết Diễm Cung phối hợp với Huyết lão quái khắc phù trận lên chiến giáp khôi lỗi và liên tục quán chú Ích Tà Thần Lôi vào mắt trận. Trong quá trình kéo dài hơn một tháng, một huyết bào nhân trực tiếp giảng giải phù trận Kim Minh, giúp hắn hiểu sâu hơn về trận pháp, khôi lỗi và phương pháp luyện chế Linh Thị. Khi khôi lỗi hoàn thành, Mộc Thanh đưa Hàn Lập trở về Mộc Tinh động, còn hắn mang theo những kiến thức và tài liệu luyện khôi lỗi mới nhận được. Tại tĩnh thất, Hàn Lập nghiên cứu kim khuyết ngọc thư và lĩnh ngộ được cách luyện Cửu Cung Thiên Kiền Phù cùng Giáp Nguyên Phù, trong khi Thiên Qua Phù vẫn còn quá huyền diệu để nắm bắt trọn vẹn. Không muốn giao tính mạng cho các yêu vương Hợp Thể Kỳ, hắn quyết định nhanh chóng luyện hai loại phù làm thủ đoạn bảo vệ bản thân. Hàn Lập chọn Giáp Nguyên Phù trước, lấy da Phong Hỏa Thú làm vật liệu rồi phóng Phệ Linh Thiên Hỏa hóa thành ngân sắc hỏa điểu để luyện hóa. Tấm da không bị thiêu cháy, trái lại những hoa văn trên bề mặt bắt đầu chuyển động như sống lại, báo hiệu một biến hóa khác thường."},{"chuong":1468,"tieuDe":"Tế Lôi Chi Thuật","tomTat":"Sau khi hoàn tất một đợt luyện chế phù lê, Hàn Lập đi dạo trong Mộc Tinh Động và phát hiện Thúy Ngâm Viên bị tầng tầng cấm chế bao phủ, nhưng chủ động từ bỏ ý định dò xét. Hơn nửa năm sau, hắn đã nắm được tám chín phần Tế Lôi Chi Thuật nên Mộc Thanh triệu tập các yêu vương tới Mộc Linh Điện kiểm chứng. Lam đạo hữu cảnh báo rằng việc dùng Kim Lôi Trúc làm bổn mạng pháp bảo có thể khiến Hàn Lập bị Ích Tà Thần Lôi phản phệ, còn Mộc Thanh khẳng định hiện chưa có dấu hiệu bất ổn. Theo yêu cầu của Lục Túc và huyết bào nhân, Hàn Lập hội tụ vô số kim sắc điện hồ cùng phù văn, tạo ra mây đen và một mặt trời sấm sét trên trời. Khi Lục Túc yêu cầu dừng lại, Hàn Lập thừa nhận mình chưa đủ thuần thục để thu hồi thuật. Kim sắc quang trụ sau đó đánh xuống, phá tan cấm chế cùng tinh cương và tạo ra một hố sâu không thấy đáy. Sau khi kiểm tra kết quả, Lam đạo hữu xác nhận Hàn Lập đã nắm giữ Tế Lôi Chi Thuật và cho rằng ngay cả các yêu vương cũng không dám trực tiếp đón đỡ công kích ấy."},{"chuong":1469,"tieuDe":"Minh Hà Chi Địa","tomTat":"Lục Túc giải thích rằng pháp lực thâm hậu là nguyên nhân quan trọng giúp Hàn Lập tạm thời cưỡng chế phản phệ khi khu sử Ích Tà Thần Lôi, song không thể bảo đảm hắn vẫn an toàn sau khi tiến giai. Mộc Thanh và mỹ phụ tóc bạc tranh chấp quyền chỉ điểm Hàn Lập, buộc Lục Túc phải đứng ra điều hòa và cảnh cáo họ không được làm hỏng kế hoạch tiến vào Minh Hà Chi Địa. Sau một cuộc truyền âm liên quan đến bảo vật thần diệu chưa rõ tên, mỹ phụ tóc bạc khiến Mộc Thanh chấp thuận thỏa thuận mới rồi rời đi. Mộc Thanh sau đó hứa truyền Khu Lôi Chi Thuật, chỉ điểm tu luyện và trả lời ba vấn đề, đổi lấy việc Hàn Lập dùng Ích Tà Thần Lôi giúp nàng tại Minh Hà Chi Địa; Hàn Lập đồng ý với điều kiện nhiệm vụ không đe dọa tính mạng. Nàng tiết lộ Minh Hà Chi Địa là không gian ở tầng thấp nhất dưới lòng đất, được năm yêu vương phát hiện hơn trăm năm trước và từng khiến một yêu vương tử vong trong chuyến thăm dò đầu tiên. Cấm địa này chứa nhiều ác quỷ, hung hồn, quỷ vương và hồn yêu hùng mạnh, bên ngoài còn bị lớp âm thủy dày khoảng vạn trượng bao bọc; người bình thường lọt vào sẽ mất hồn phách, hóa thành âm thi và vĩnh viễn mắc kẹt."},{"chuong":1470,"tieuDe":"Hắc Mộc Cùng Kim Viên","tomTat":"Hàn Lập dùng câu hỏi cuối cùng để làm rõ nhiệm vụ tại Minh Hà Chi Địa và biết Ích Tà Thần Lôi của mình sẽ được dùng để khắc chế ma vật đang canh giữ một vật Mộc Thanh muốn lấy. Mộc Thanh đưa Chân Linh Chi Huyết Ngũ Sắc Khổng Tước ra làm thù lao, bởi chân huyết này có thể giúp Hàn Lập tu thêm một biến hóa của Kinh Chập Thập Nhị Biến. Nàng giao trước một nửa, còn Hàn Lập kiểm tra khí tức trong chiếc bình đỏ tươi rồi thu lấy. Sau khi Hàn Lập rời đi, Mộc Thanh dùng hắc sắc quang trận trở về Mộc Tinh Động và tiến vào hoa viên bí mật đặt một cự mộc đen. Cuộc gặp với Kim Linh xác nhận cự mộc chính là bản thể và nhược điểm trí mạng của Mộc Thanh, hiện vẫn có một nửa khô héo. Kim Linh nhắc lại lần từng mắc kế điệu hổ ly sơn, khiến Mộc Thanh phải hy sinh một nửa nguyên khí bản thể và tự bạo để đánh trọng thương kẻ xâm nhập. Mộc Thanh cho biết đã phần nào đoán được thủ phạm nhưng chưa muốn đánh động, dự định sau khi trở về từ Minh Hà Chi Địa sẽ ra tay báo thù."},{"chuong":1471,"tieuDe":"Tâm Cơ Khó Dò","tomTat":"Mộc Thanh quyết định mang bản thể linh mộc vào Minh Hà Chi Địa bằng vật trữ đã luyện chế riêng, đồng thời giao Kim Linh nhiệm vụ trông chừng và bảo vệ Hàn Lập. Nàng tiết lộ Hàn Lập không chỉ có khả năng phá cấm chế mà còn giữ vai trò quan trọng đối với việc bản thể của nàng phục hồi nguyên khí. Tại Huyết Diễm Cung, chủ nhân Tử Huyết Khôi Lỗi cho biết nguyên thần chính của mình đã hòa vào thân thể khôi lỗi và âm thầm chuẩn bị lợi dụng Ích Tà Thần Lôi để tranh vật giúp khôi lỗi tiến giai. Mỹ phụ tóc bạc cùng Lục Túc cũng riêng rẽ chuẩn bị lực lượng và những thủ đoạn bí mật tại Uyên Canh. Trong khi đó, Hàn Lập bế quan hai năm, dùng Kinh Chập Quyết dung nhập chân linh chi huyết ngũ sắc khổng tước, luyện thành biến thân và khiến tu vi tăng tiến. Dù vậy, hắn vẫn không thể hóa giải ấn ký của bốn yêu vương và cũng chưa kích hoạt được Huyền Thiên Quả Thật dù đã bồi dưỡng vật này nhiều năm. Khi Hàn Lập xác định chuyến đi Minh Hà Chi Địa là không thể tránh khỏi, một mộc hạp cháy đen bí ẩn bất ngờ xuyên qua cấm chế mật thất và rơi vào tay hắn."},{"chuong":1472,"tieuDe":"Nhị Nữ Tới Chơi","tomTat":"Hàn Lập kiểm tra chiếc mộc hạp bí mật được đưa vào tĩnh thất, nhận lời hẹn từ viên châu đen bên trong rồi tới một sơn cốc vô danh. Tại đó, hắn gặp lại Nguyên Dao và Nghiên Lệ, hai người quen cũ từ Loạn Tinh Hải. Nhị nữ kể rằng họ đã mượn âm minh chi khí luyện thành Âm Dương Luân Hồi Quyết, trở thành tồn tại nửa người nửa quỷ và mất tư cách bước vào luân hồi. Sau khi tiến vào Hóa Thần kỳ, họ bị một luồng âm phong cuốn thẳng tới Linh giới rồi được Quỷ Phiền thu làm môn hạ. Nghiên Lệ tiết lộ Quỷ Bà muốn thôn phệ tinh hồn cùng âm khí tinh thuần của hai người để tăng tu vi, buộc họ phải bí mật cầu cứu trong lúc bà ta đang luyện chế Đại Âm Giáp Quỷ Vương. Đổi lại sự trợ giúp, Nghiên Lệ đề nghị cung cấp phương pháp có thể tạm thời khu trừ ấn ký trên người Hàn Lập khi tiến vào Minh Hà Chi Địa. Hàn Lập đồng ý giúp hai người thoát thân với điều kiện phương pháp ấy được chứng minh là thật."},{"chuong":1473,"tieuDe":"Huyết Thực","tomTat":"Nghiên Lệ và Nguyên Dao đề nghị Hàn Lập giả vờ có tình ý sâu đậm với Nguyên Dao, qua đó khiến Quỷ Bà e ngại mà không dám sát hại hai nàng. Dù lo ngại hiệp nghị bí mật giữa Quỷ Bà và Mộc Thanh có thể làm kế hoạch phát sinh biến số, Hàn Lập vẫn đồng ý phối hợp và cùng hai nàng xác định Minh Hà là cơ hội đào thoát. Sau khi nhị nữ trở về Duyến Thâm Thành, Hàn Lập hóa thành khổng tước trở lại động phủ bế quan; hai tháng sau, một đoàn âm phong bí ẩn xuyên qua cấm chế vào gặp hắn rồi rời đi. Gần hai năm trôi qua, lực lượng của tứ đại yêu vương hội tụ tại một sa mạc thuộc Hắc Ám Khí, gồm hàng vạn yêu vật, quỷ binh, khôi lỗi và nhiều thuộc hạ cấp cao. Hàn Lập bị cưỡng ép đi cùng và nhận ra các yêu vương đang dốc phần lớn lực lượng cho chuyến tiến vào Minh Hà Chi Địa dù chưa nắm chắc tình hình bên trong. Theo lệnh Lục Túc, Mộc Thanh cho thuộc hạ phóng lượng lớn tinh huyết từ những dây lưng đỏ, ngưng tụ thành huyết cầu khổng lồ. Nàng tiếp tục thúc động một bình đen nhỏ, đưa vài giọt chất lỏng đỏ vào huyết cầu và mở đầu nghi thức huyết tế."},{"chuong":1474,"tieuDe":"Kinh Không Ma","tomTat":"Huyết cầu sau khi hấp thu vật chất màu đỏ tỏa hương nồng, kích động đàn yêu cho đến khi Lục Túc dùng linh áp lạnh lẽo trấn áp tất cả. Huyết cầu tiếp tục gây biến động không gian và dụ Kinh Không Ma xé rách hư không hiện thân; tiếng gáy của ma vật áp chế những sinh linh đã nhiễm khí tức hắc ám, nhưng Hàn Lập vẫn bình yên nhờ Kim Lôi Trúc và thời gian lưu lại Địa Uyên chưa lâu. Kinh Không Ma nuốt huyết cầu rồi quay vào hắc động, đúng theo kế hoạch lợi dụng năng lực không gian của tứ đại yêu vương. Lục Túc và Mộc Thanh dẫn đầu tiến vào thông đạo, còn Hàn Lập bị Kim Linh giám sát nên buộc phải đi theo. Sau khi bay khoảng trăm trượng, nhóm tiên phong dừng trước một vùng ngân hà chắn đường. Mộc Thanh xác nhận đã dùng đủ Phê Huyết Thực, còn Lục Túc cho biết linh dược vạn năm sẽ khiến Kinh Không Ma ngủ mê trong vài tháng, duy trì thông đạo đủ lâu cho đại quân đi và về. Lục Túc kết thúc trao đổi và ra lệnh đả thông phần không gian còn lại nối với Minh Hà Chi Địa."},{"chuong":1475,"tieuDe":"Minh Hà Cấp Chế Cùng Bát Môn Dẫn Lôi Trận","tomTat":"Lục Túc mọc thêm hai cánh tay và phối hợp với Mộc Thanh dùng nhiều pháp bảo, thần thông đánh tan ngân hà chắn đường, mở thông đạo không gian tới Minh Hà. Hàn Lập theo Mộc Thanh vượt qua luồng hàn phong có thể xuyên qua linh quang hộ thể, nhưng nhờ ngũ sắc hàn diễm nên không chịu tổn hại đáng kể. Tại Minh Hà, Lục Túc thăm dò mặt nước và phát hiện đàn quái ngư dưới Minh Thủy có thể phóng ngân mang công kích liên tục. Hai huyết bào nhân, mỹ phụ tóc bạc, tám hắc ảnh, Nguyên Dao, Nghiên Lệ cùng đại quân yêu vật và khôi lỗi lần lượt tiến vào, chuẩn bị liên thủ phá cấm. Lục Túc giao cho Hàn Lập nhiệm vụ dùng Ích Tà Thần Lôi đánh tan ma khí trong Minh Thủy để các yêu vương có thể tách dòng nước. Lo thần lôi cắn trả, Hàn Lập bí mật dùng tám thanh tiểu kỳ ngưng từ lôi phù dựng tiểu pháp trận tám lôi môn nhằm dẫn lôi lực khỏi thân thể. Chương kết thúc khi đại pháp trận của Lục Túc và Mộc Thanh, đội hình mỹ phụ tóc bạc cùng tám hắc ảnh, và các khôi lỗi khổng lồ của phe Địa Huyết đều hoàn tất bước chuẩn bị ban đầu."},{"chuong":1476,"tieuDe":"Liên Thủ Phá Cấm Chế","tomTat":"Lục Túc chỉ huy Hàn Lập chuẩn bị Tế Lôi Thuật, trong khi bản thân cùng Mộc Thanh và hai huyết bào nhân trên khôi lỗi hợp lực dùng thần thông phá mặt nước Minh Hà, mở ra một khe sâu. Tuy nhiên những sợi tơ đen trong suốt xuất hiện bao phủ mọi luồng công kích, khiến thần thông các yêu vương nhanh chóng suy yếu. Lục Túc thúc giục Hàn Lập ra tay, Hàn Lập thi triển Tế Lôi Thuật dẫn Tịch Tà Thần Lôi kim sắc xuống Minh Hà, lôi quang lan rộng tiêu diệt sạch tơ đen. Mỹ phụ đầu bạc thu nạp âm khí của tám Âm giáp Quỷ Vương rồi thúc động chiếc chuông đen cổ kính, phóng hắc sắc quang ba nâng tường nước tạo thành thông đạo hoàn chỉnh. Sau một khắc đồng hồ, thông đạo xuyên Minh Hà hoàn toàn đả thông. Lục Túc xác định thông đạo chỉ duy trì được vài canh giờ nên lập tức đưa gần vạn yêu thú cùng yêu vật làm tiên phong, kẹp giữa khôi lỗi và huyền quỷ hai bên, tiến vào thông đạo thăm dò. Vừa vào, vô số tơ bạc đồng loạt bắn ra từ mọi phía nhưng chỉ nhắm vào đám đê giai yêu vật ở giữa, hoàn toàn bỏ qua khôi lỗi và huyền quỷ."},{"chuong":1477,"tieuDe":"Minh Linh Chi Tinh","tomTat":"Đàn Minh Hà quái ngư hóa thành tơ bạc, xuyên thủng nhiều yêu vật cấp thấp đang tiến qua thông đạo, trong khi khôi lỗi và các đơn vị có linh quang hộ thể chống đỡ tốt hơn. Vô số Âm Quỷ sau đó hiện ra từ hắc sắc quang mạc, dùng thủy tiễn và răng độc tấn công, còn cơ thể chúng gần như vô hiệu hóa pháp thuật thông thường. Lục Túc chỉ rõ Âm Quỷ không thể rời Minh Hà quá xa, khiến yêu đàn dốc sức chạy khỏi phạm vi của chúng. Các yêu vương cố ý dùng yêu đàn tạo động tĩnh để dẫn Minh Hà chi linh xuất hiện, rồi hợp lực giữ chặt xúc tu và chém đôi thân thể quái vật. Lục Túc lấy được Minh Linh chi tinh từ xác nó, xác nhận tinh thạch sẽ giúp đoàn người vượt qua những cửa ải kế tiếp. Đại quân sau đó tiến vào không gian dưới Minh Hà, tổ chức lại đội hình với quỷ binh đi trước, lực lượng Mộc Thanh ở giữa và khôi lỗi đoạn hậu. Khi toàn quân đi sâu vào bình nguyên xương trắng đầy xú khí, Hàn Lập vận dụng Minh Thanh Linh Mục quan sát và bất ngờ phát hiện một dấu hiệu bất thường phía trước."},{"chuong":1478,"tieuDe":"Tao Ngộ Kịch Chiến","tomTat":"Hôi khí trên cánh đồng bạch cốt khiến vô số bộ xương sống dậy, nhưng hai huyết bào nhân và mỹ phụ đầu bạc phối hợp quét sạch đợt tập kích. Đội ngũ Địa Uyên tiếp tục tiến sâu vào Minh Hà Chi Địa, lần lượt giao chiến với dơi máu, quỷ ảnh, cự nhân ba đầu và nhiều quỷ vật khác, khiến yêu vật, quỷ binh cùng khôi lỗi hao tổn nặng. Hàn Lập phát hiện Ích Tà Thần Lôi đặc biệt khắc chế quỷ vật mang ma khí, đồng thời dùng ngũ sắc hàn diễm và Nguyên Từ Thần Sơn tiêu diệt nhiều kẻ địch. Sau đó, hơn ba mươi lệ quỷ thống lĩnh dẫn đại quân bất ngờ phục kích, thả quỷ vụ bao phủ chiến trường và chia cắt toàn bộ đội ngũ. Hàn Lập chiến đấu bên Kim Linh một thời gian nhưng cuối cùng mất liên hệ với tất cả mọi người, còn Minh Thanh Linh Mục cũng không thể nhìn xuyên sương mù quá xa. Sau khi dùng Nguyên Từ Thần Sơn đè bẹp cự thi độc nhãn và quét sạch quỷ vật lân cận, hắn bay về hướng có tiếng giao chiến nhỏ nhất để tự tìm đường thoát, đồng thời chuẩn bị thả Đề Hồn nếu tình thế tiếp tục xấu đi."},{"chuong":1479,"tieuDe":"Cơ Hội Chạy Trốn","tomTat":"Hàn Lập dựa vào Linh Mục né các chiến trường lớn trong quỷ vụ, nhưng sương mù và những cuộc hỗn chiến liên tiếp khiến hắn hoàn toàn mất phương hướng. Sau khi luyện hóa một nhóm lệ phách vô hình, hắn phát hiện Nghiên Lệ và Nguyên Dao đang bị hàng trăm huyết hồng khô lâu vây khốn. Hàn Lập dùng bảy mươi hai khẩu phi kiếm chém nát quân khô lâu, rồi lấy ngũ sắc hàn diễm và kim sắc thiểm điện tiêu diệt đại quỷ vật do huyết dịch tụ thành. Qua trao đổi, hắn suy đoán các quỷ vật cấp Luyện Hư đang bị nhóm Lục Túc cầm chân nên đề nghị hai nữ tử nhân lúc hỗn loạn thoát khỏi sự khống chế của Mộc Thanh và quỷ bà. Hàn Lập dự tính tiến vào Minh Hà, tìm nơi có âm khí tinh thuần để xóa ký hiệu truy tung trên cơ thể. Nghiên Lệ và Nguyên Dao đồng ý đi cùng, đồng thời cho biết Âm Dương luân hồi quyết và bán quỷ chi khu giúp họ có cách tìm đường ra khỏi quỷ vụ."},{"chuong":1480,"tieuDe":"Bạch Ảnh","tomTat":"Hàn Lập hộ tống Nguyên Dao, Nghiên Lệ và số quỷ binh còn lại rời chiến trường, trong khi hai nữ tu phối hợp thi triển hợp độn để xác định đường thoát khỏi sương mù. Do bí thuật không cho phép đổi hướng giữa chừng, cả đoàn phải trực tiếp vượt qua những quỷ vật cản đường và được Hàn Lập đi trước mở lối. Trong lúc trò chuyện, Hàn Lập khẳng định có thể chống lại đối thủ chưa đạt Luyện Hư hậu kỳ, đồng thời chỉ ra rằng Nguyên Dao và Nghiên Lệ vẫn có hy vọng xua tan âm khí để khôi phục nhân thân. Khi đoàn người đến gần mép sương mù, một tiếng cười quỷ dị khiến hai nữ tu cùng đám huyền quỷ mất sức, trì trệ thần thức và cạn âm lực. Hàn Lập dùng tiếng hừ lạnh đánh thức họ rồi vận dụng linh mục phát hiện một bạch ảnh ẩn trong hư không. Kiếm quang không thể làm bạch ảnh bị thương, còn thế vây bằng hôi hà và ngũ sắc quang diễm cũng thất bại khi đối phương liên tục phân tách thành vô số thân ảnh tràn khắp bầu trời."},{"chuong":1481,"tieuDe":"Quỷ Nữ","tomTat":"Hàn Lập dùng hôi hà và ngũ sắc quang diễm công kích những bạch ảnh liên tục phân liệt nhưng không thể tiêu diệt toàn bộ. Sau khi nhận ra kẻ địch ẩn nấp phía sau, hắn mở Phá Diệt Pháp Mục và ép một nữ tử bạch bào hiện thân. Quỷ nữ dùng cốt trảo xuyên qua hư không đánh trúng cổ Hàn Lập, song kim lân hộ thể giúp hắn không bị thương, còn kiếm quang và hỏa diễm của hắn cũng chưa thể làm đối phương tổn hại. Hàn Lập chuẩn bị triệu Đề Hồn Thú và dùng lôi châu, trong khi quỷ nữ để lộ gương mặt hai nửa rồi kéo sương mù cùng vô số quỷ ảnh tới. Một tiếng rống bí ẩn từ sâu trong quỷ vụ khiến quỷ nữ lập tức thu hồi thần thông và rút lui. Hàn Lập không truy kích mà dẫn Nguyên Dao và Nghiên Lệ chạy khỏi sương mù vì nghi nhóm Lục Túc đang ở gần. Vừa thoát khỏi cấm chế, ba người bị võ tướng mặc tử giáp phát hiện và nhận ra mình đã lọt vào chiến trường nơi đội ngũ Mộc Thanh cùng mỹ phụ đầu bạc đang giằng co với ba võ tướng, hàng nghìn quỷ binh và đạo quân huyết giáp đông đảo."},{"chuong":1482,"tieuDe":"Phù Du Tộc","tomTat":"Tử giáp võ tướng nhận ra Nguyên Dao và Nghiên Lệ mang bán quỷ thân rồi dùng thần niệm dò xét Hàn Lập, nhưng Hàn Lập vận chuyển Đại Diễn Quyết chống lại và phát hiện toàn bộ võ tướng cùng huyết giáp binh sĩ đều là khôi lỗi. Trở lại bên Mộc Thanh, Hàn Lập báo rằng mình đã thất lạc Kim Linh trong lúc bị quỷ vật công kích. Tử giáp võ tướng tuyên bố Minh Hà là thánh địa chứa thánh vật của Phù Du Tộc và đe dọa truy sát những kẻ xâm nhập trên toàn Linh giới. Mỹ phụ đầu bạc nhận ra đối phương chỉ dùng phân hồn phụ vào khôi lỗi nên từ chối nhượng bộ, khiến đàm phán tan vỡ. Hai phe lập tức khai chiến khi quỷ quân và tám quỷ vương xông vào đại quân huyết giáp khôi lỗi, còn Mộc Thanh dùng hoa ảnh chặn kim quang từ đôi kim chùy. Cuối chương, khôi lỗi võ tướng ba mắt tiết lộ đã gọi viện quân và yêu cầu đồng bọn chỉ cần cầm chân đối phương cho tới khi lực lượng tiếp viện tới nơi."},{"chuong":1483,"tieuDe":"Trọng Tụ","tomTat":"Mộc Thanh, mỹ phụ đầu bạc và ba võ tướng khôi lỗi tạm thời án binh, để quân đoàn huyết giáp tiếp tục giao chiến với âm giáp quỷ binh trong lúc chờ viện thủ. Tám quỷ vương dẫn đầu quỷ binh chiếm ưu thế, phá hủy hàng nghìn khôi lỗi và toàn bộ hơn trăm chiến xa, nhưng phe quỷ cũng tổn thất gần một nửa. Một luồng linh áp đáng sợ bất ngờ bùng lên từ sâu trong Vụ hải, kéo theo cuồng phong quét sạch sương mù, phá tan cấm chế và nghiền nát những đơn vị không kịp tháo chạy. Theo hiệu lệnh của mỹ phụ đầu bạc, tám quỷ vương dung hợp thành cự quỷ để thoát khỏi phong bạo. Lục Túc và Địa Huyết sau đó trở lại trên tử huyết khôi lỗi cao nghìn trượng, đồng thời đưa ra bốn chiếc đầu để chứng minh những đối thủ mạnh hơn ba võ tướng còn lại đã bị giết. Lục Túc hạ lệnh diệt khẩu, khiến ba võ tướng chia nhau đào tẩu và lần lượt bị Mộc Thanh, mỹ phụ đầu bạc cùng một huyết bào nhân truy đuổi. Khi các cường giả rời khỏi hiện trường, Nghiên Lệ truyền âm đề nghị Hàn Lập nhân cơ hội đưa nàng và Nguyên Dao bỏ trốn."},{"chuong":1484,"tieuDe":"Trùng Ảnh","tomTat":"Hàn Lập phát hiện Kim Linh đang ẩn nấp và buộc hắn hiện thân, nhưng sau khi cân nhắc lực lượng yêu vật xung quanh, Hàn Lập quyết định tạm hoãn kế hoạch đưa Nguyên Dao và Nghiên Lệ trốn đi. Mộc Thanh trở về tiếp nhận Kim Linh, rồi mỹ phụ đầu bạc cũng xuất hiện trong trạng thái hao tổn pháp lực và cho biết tám quỷ vương bị thương đã được thu vào Âm Vân túi. Khi mọi người nhận ra Lục Túc cùng Địa Huyết vẫn chưa trở lại, một tiếng tiêm minh từ phương xa bất ngờ đánh thẳng vào thần thức, khiến Hàn Lập tạm mất quyền khống chế thân thể và hơn mười cao giai yêu vật rơi xuống đất. Hàn Lập dùng Tinh Thần Thứ tự kích thích để tỉnh lại, dựng nhiều lớp phòng hộ rồi vận dụng Nguyên Từ Thần Quang cứu Nguyên Dao và Nghiên Lệ. Ở cuối chân trời, một trùng ảnh màu đỏ hình ruồi hiện lên che kín nửa bầu trời, vừa phát tiếng cánh đáng sợ vừa phóng vô số quang trụ đỏ xuống phía dưới. Trong lưới quang trụ có tử huyết khôi lỗi đã thu nhỏ cùng một vật thể khác đang né tránh, và hình dạng của vật thể chưa rõ danh tính ấy khiến Hàn Lập chấn động."},{"chuong":1485,"tieuDe":"Phù Du Tộc Và Trùng Hải","tomTat":"Tử huyết khôi lỗi và quái trùng đen sáu chi vừa né các cột sáng đỏ vừa phản kích ảo ảnh Thiên phù, nhưng công kích của chúng không thể xuyên qua lực lượng bảo vệ mục tiêu. Mộc Thanh nhận ra trùng ảnh chỉ là ảo ảnh do khôi lỗi Phù Du tộc triệu hồi, còn mỹ phụ đầu bạc giúp đám cao giai yêu vật khôi phục thần trí trong lúc chờ uy năng của nó cạn kiệt. Khi trùng ảnh tan biến, quái trùng đen hóa lại thành Lục Túc và để lộ dung mạo thật cùng đôi mắt xanh biếc lạnh lẽo. Bị Mộc Thanh chất vấn, Lục Túc thừa nhận mình vốn xuất thân từ Phù Du tộc nhưng phủ nhận chuyện cố ý dẫn cả nhóm vào thánh địa, nói rằng hắn chỉ vô tình phát hiện mối liên hệ giữa Địa Uyên và Minh Hà. Địa Huyết cho rằng Lục Túc không nói dối và nhắc mọi người rằng họ không thể cam tâm quay về khi chưa lấy được Minh Hà thần nhũ. Mộc Thanh phân tích rằng Phù Du tộc khó điều động đại quân Trùng hải chỉ để đối phó nhóm họ vì mỗi lần xuất quân sẽ khiến toàn tộc tổn hao quá nửa nguyên khí. Lục Túc dự đoán đối phương cần ít nhất vài tháng mới tới, đủ để cả nhóm tìm thần nhũ và đường trở về, rồi bắt đầu hỏi số âm binh cùng khôi lỗi còn có thể sử dụng."},{"chuong":1486,"tieuDe":"Âm Thủy Quỳ Tinh Và Ngũ Long Trát","tomTat":"Sau trận chiến, Lục Túc kiểm kê tổn thất của khôi lỗi và quỷ binh, đồng thời vạch ra việc mỹ phụ đầu bạc còn bí mật chuẩn bị năm trăm hắc giáp quỷ binh tinh nhuệ. Hắn cảnh cáo các bên không được phân tâm khỏi mục tiêu Minh Hà Thần Nhũ rồi dẫn toàn đội tiếp tục tiến sâu vào Minh Hà chi địa. Vài ngày sau, huyết giáp khôi lỗi sống sót đến thạch động của Khương tiền bối, báo rằng các hóa thân khác đã bị hủy và viện quân Phù Du tộc chưa thể tới trong nửa năm. Khương tiền bối từ chối trực tiếp xuất chiến vì giao ước cũ không bao gồm việc diệt địch và ông còn phải trấn áp nguồn âm khí bất ổn. Huyết giáp khôi lỗi bèn giao Âm Thủy Quỳ Tinh quý hiếm để đổi lấy sự trợ giúp, khiến Khương tiền bối chấp thuận cho mượn Ngũ Long Trát. Lão giả tiết lộ chí bảo này được luyện từ thi cốt và tinh hồn của năm ác giao đại thần thông, từng đứng hàng đầu trong số Thông Thiên Linh Bảo trên Vạn Linh Bảng. Sau khi chứng kiến hư ảnh năm giao long và uy lực của trát đao, huyết giáp khôi lỗi thu bảo vật vào tay áo, tin rằng mình đủ sức tiêu diệt năm tồn tại thiên phù cấp."},{"chuong":1487,"tieuDe":"Khống Chế","tomTat":"Trong hang động, lão giả truyền cho Huyết giáp khôi lỗi một pháp quyết cho phép dùng thần niệm phát huy uy lực Ngũ Long Trát từ xa, dù phương thức này có thể ảnh hưởng tới bản thể. Vì lo sẽ bị Phù Du tộc trọng phạt nếu nhiệm vụ thất bại, khôi lỗi chấp nhận mạo hiểm, nhận thêm bình đan dược hồi phục quỷ vật rồi dẫn chúng rời đi. Ở một nơi khác, đoàn Lục Túc vượt qua khu rừng khô có những bộ hài cốt tự ghép lại, tiếp tục đi qua hồ nước đen và nhiều hiểm địa trong suốt một tháng. Hàn Lập trợ giúp Nguyên Dao và Nghiên Lệ sống sót, đồng thời nhận ra mình chưa thể rời đoàn vì cần người dẫn đường và luôn bị Kim Linh giám sát. Sau nhiều tổn thất, những người còn lại cuối cùng nhìn thấy sơn mạch màu xám, nơi được cho là cất giấu Minh Hà thần nhũ. Lục Túc cùng các yêu vương bàn bạc về Hàn Lập, sau đó gọi hắn tới nhận một nhiệm vụ chưa rõ và đưa ra viên châu đen mờ khiến hắn cảm thấy rất quen thuộc."},{"chuong":1488,"tieuDe":"Càn Khôn Phiên Cùng Minh Lôi Thú","tomTat":"Lục Túc tiết lộ nhãn châu trong người Hàn Lập là nhiếp hồn dị bảo được luyện từ mắt của một mãnh thú cường đại, có thể trấn áp thần hồn và tước quyền tự chủ của hắn. Sau khi cân nhắc giữa ma phần chi vật và thần nhũ, các yêu vương quyết định ưu tiên thần nhũ vì linh vật này có thể tạo thông linh chi thể, tăng mạnh khả năng điều khiển thiên địa nguyên khí và đem lại hy vọng phi thăng. Mỹ phụ đầu bạc thừa nhận đã sai Địa Huyết khống chế Nguyên Dao cùng Nghiên Lệ, vừa ngăn họ gây trở ngại vừa chuẩn bị lợi dụng âm khí tinh thuần của hai người để luyện hóa thần nhũ. Đoàn người vượt dãy núi xám và tới một thung lũng rộng lớn có quang mạc đen che kín khu vực trung tâm, nơi Minh Lôi thú trưởng thành đang ẩn náu. Lục Túc phân công tử huyết khôi lỗi phá thông thiên tường, đồng thời định ép Hàn Lập dùng Tích Tà thần lôi dẫn con thú rời khỏi ao đầm. Để kéo dài thời gian sống sót của Hàn Lập, mỹ phụ đầu bạc tạm giao Càn Khôn phiên cho hắn, còn Địa Huyết gia trì hơn mười phù triện lên người hắn. Cuối cùng, Mộc Thanh hóa phần thân dưới thành cây, cắm rễ sâu và khởi động Thiên Hoa Loạn Diệp trận, khiến hoa cỏ sinh trưởng dày đặc và che mờ thân ảnh của cả khu vực."},{"chuong":1489,"tieuDe":"Mồi","tomTat":"Lục Túc xác nhận Thiên Hoa Loạn Diệp của Mộc Thanh đủ sức che giấu cả nhóm trước Minh Lôi thú, rồi các yêu vương chuẩn bị huyết nhận để phá hắc sắc quang mạc và để Hàn Lập ở ngoài làm mồi. Thử liệt nhãn châu tưởng như đã khống chế Hàn Lập, nhưng Phá diệt pháp mục tự động hấp thu nhiếp thần hắc ti, giúp hắn giữ nguyên thần trí và âm thầm quyết định tương kế tựu kế. Huyết phù của Địa Huyết khiến linh lực hắn tăng gần một nửa, trong khi Càn Khôn phiên cùng những vật phẩm bí mật chuẩn bị trở thành hậu thủ cho kế hoạch thoát thân và cứu Nguyên Dao, Nghiên Lệ. Sau khi nhóm yêu vương đánh động cấm chế, Minh Lôi thú phá quang mạc xuất hiện và lập tức bị khí tức Ích Tà Thần Lôi trên người Hàn Lập hấp dẫn. Hàn Lập vừa dùng Càn Khôn phiên hộ thân vừa phi độn rời đi, rồi triển khai đôi cánh ngũ sắc để nhanh chóng bỏ xa con thú đang truy đuổi. Khi cả hai khuất khỏi chân trời, Lục Túc thúc giục đồng bọn toàn lực phá cấm bằng huyết nhận, trùng ảnh và Tử huyết khôi lỗi."},{"chuong":1490,"tieuDe":"Ngũ Long Trát","tomTat":"Tử huyết khôi lỗi cùng mỹ phụ đầu bạc tiếp tục công kích quang mạc đen, giúp các tồn tại cấp Hợp Thể mở được một khe hở dẫn vào thần trì. Lục Túc dùng tám cột trụ pháp khí màu lam cố định khe hở thành thông đạo rồi dẫn đầu tiến vào, sau đó một thân thể Địa Huyết, Mộc Thanh, mỹ phụ đầu bạc, Nguyên Dao và Nghiên Lệ lần lượt theo sau. Kim Linh cùng thân thể Địa Huyết còn lại và ba yêu vật cao giai được giao trấn giữ bên ngoài, đồng thời bí mật về đại thần thông nhất hồn phân hóa của Địa Huyết được hé lộ. Một huyết giáp khôi lỗi bị tồn tại cao giai Phù Du tộc phụ thân bất ngờ hiện thân, tuyên bố sẽ lợi dụng lúc lực lượng đối phương bị chia tách để tiêu diệt toàn bộ. Kẻ này gọi ra Ngũ Long Trát, chém chết ba yêu vật cao giai, phá nát hai đoản kiếm của Kim Linh rồi diệt cả thân thể lẫn nguyên thần của hắn. Địa Huyết hóa thành huyết vụ né tránh và lao về thông đạo, nhưng Ngũ Long Trát biến thành năm giao long khác màu rồi hóa thành năm cự nhận trong suốt chặn ngay trên đường rút."},{"chuong":1491,"tieuDe":"Kế Thoát Thân","tomTat":"Huyết bào nhân dốc nhiều bảo vật, chiến giáp và pháp khí cứu mạng để chống Ngũ Long Trát nhưng toàn bộ phòng ngự đều bị phá, khiến thân thể cùng nguyên thần bị hàn quang khống chế. Huyết giáp khôi lỗi thu hồi bảo vật và nhận ra mỗi lần sử dụng đều tiêu hao thần niệm nghiêm trọng, buộc hắn phải tính chuyện tốc chiến tốc thắng. Hắn chia nhóm cao giai quỷ vật, dẫn một nửa vào thông đạo màu lam và lệnh cho số còn lại dựng đại trận phong tỏa, đồng thời tiết lộ vẫn còn một Minh Lôi thú canh giữ thần nhũ bên trong. Bạch Quỷ được phái theo dõi Hàn Lập và con Minh Lôi thú đang bị dẫn đi để kịp thời báo tin bằng Vạn Lý Phù. Trong cuộc truy đuổi, Hàn Lập dùng Tích Tà Thần Lôi, Phong Lôi Sí và phong lôi độn thuật để kéo dài thời gian, nhưng vẫn bị trảo mang của yêu thú đánh tổn thương nguyên khí. Càn Khôn phiên giúp hắn hấp thu phần lớn thế công, nhờ đó hắn tiếp tục dẫn Minh Lôi thú tới sơn mạch màu xám và rời xa đoàn Lục Túc. Nhận thấy các biện pháp thông thường không thể cắt đuôi yêu thú, Hàn Lập quyết định phối hợp một số Phệ Kim Trùng với phù và đặt thần niệm lên Linh Thú Hoàn để chuẩn bị thực hiện kế thoát thân."},{"chuong":1492,"tieuDe":"Đại Chiến Minh Lôi Thú","tomTat":"Hàn Lập dùng Ích Tà Thần Lôi nhử Minh Lôi Thú rồi thả ba Phệ Kim Trùng thành thục thể, nhưng con thú dùng ngân hà cuốn và nuốt cả ba vào bụng. Minh Lôi Thú tiếp tục thi triển Ảnh độn thuật, liên tục áp sát, dựng điện võng chặn đường và dùng thú trảo áp chế Hàn Lập. Một Thanh Trúc Phong Vân Kiếm bị nó bắt lấy và bóp mạnh nhưng vẫn nguyên vẹn nhờ độ cứng tích lũy từ nhiều tài liệu quý. Hàn Lập gọi ra kim sắc nhân ảnh ba đầu sáu tay rồi thuấn di, song Minh Lôi Thú đánh vào hư không và ép hắn hiện hình trở lại. Hàn Lập lập tức thúc giục ba Phệ Kim Trùng công kích từ trong bụng đối phương, khiến Ảnh độn thuật bị gián đoạn và thần thông của con thú suy giảm. Hơn mười lôi châu màu xanh sau đó đồng loạt phát nổ, tạo thành lôi vân có uy lực tương đương một đòn toàn lực của tu sĩ Hợp Thể kỳ và bao phủ Minh Lôi Thú."},{"chuong":1493,"tieuDe":"Cửu Cung Thiên Càn Phù","tomTat":"Hàn Lập kích phát một trăm lẻ tám lá Cửu Cung Thiên Càn Phù, tạo thành quang trận có cung điện và ngân hà để vây Minh Lôi Thú. Minh Lôi Thú đánh tan lôi vân, bức ba con Phệ Kim Trùng thành thục thể khỏi cơ thể rồi bị cuốn vào không gian cấm chế, nhưng sức công phá của nó khiến Hàn Lập biết phù trận không thể duy trì lâu. Hàn Lập thu hồi linh trùng và Thanh Trúc Phong Vân Kiếm, từ bỏ ý định giết con thú rồi lập tức rút lui. Trên đường chạy, hắn phát hiện Bạch Quỷ ẩn trong hư không và gọi Đề Hồn Thú ra đối phó. Bạch Quỷ dùng áo trắng tạo quang tráo cản Nhiếp Hồn Thần Quang, song Đề Hồn biến thân và dùng huyết sắc điện hồ từ con mắt thứ ba xuyên thủng phòng hộ rồi nuốt nàng. Đề Hồn sau đó nhả ra một khối ngọc bài màu đen được Hàn Lập nhận ra là Vạn Lý Phù. Nghe tiếng Minh Lôi Thú phá trận vọng tới, Hàn Lập thu Đề Hồn và hóa thành thanh sắc đại bàng tiếp tục đào thoát."},{"chuong":1494,"tieuDe":"Giáp Nguyên Phù","tomTat":"Hàn Lập vừa duy trì Thiên Bằng biến thân vừa vận chuyển Đại Diễn Quyết và các bí thuật Đại Diễn Chân Kinh, tạm phong kín ấn ký truy tung của bốn đại yêu vương trong khoảng một ngày đêm. Hắn quyết định quay lại cứu Nguyên Dao, dự tính lợi dụng việc Minh Lôi Thú trở về Thần Trì để gây xung đột với các yêu vương. Khi Minh Lôi Thú bay qua, Hàn Lập dùng Thái Nhất Hóa Thanh Phù hóa thành hư vô nên không bị phát hiện, rồi bí mật bám theo nó. Tới cổng cấm địa, hắn thấy hơn nghìn quỷ vật đã bị cuồng lôi tiêu diệt vì Bạch Quỷ không còn sống để dùng Vạn Lý Phù cảnh báo. Hàn Lập bố trí bộ Cửu Cung Thiên Càn Phù cuối cùng, kích phát hai Nguyên Giáp Phù và để Phệ linh hỏa điểu mang hơn mười thanh sắc lôi châu mai phục ngoài thông đạo. Sau đó hắn tiếp tục hóa hư, xâm nhập vùng đất tối đen nhưng linh khí nồng đậm bên trong quầng sáng. Bay hơn mười dặm về phía trung tâm cấm chế, hắn tìm thấy một cung điện đá và nhận ra hai luồng âm khí nghi là quỷ vật cấp cao đang ẩn nấp cạnh cửa."},{"chuong":1495,"tieuDe":"Minh Hà Thần Nhũ","tomTat":"Để tránh quỷ vật canh cửa phá hỏng kế hoạch, Hàn Lập cùng Đề Hồn Thú bất ngờ ra tay, lần lượt chế trụ và luyện hóa song đầu khô lâu cùng bạch mao cương thi. Hàn Lập sau đó ra lệnh cho Đề Hồn giả dạng Minh Lôi Thú rồi dùng Thái Nhất Hóa Thanh Phù lẻn qua cung điện phía trên, tiến xuống điện đường ngầm sâu hơn ngàn trượng. Tại đây, hắn chứng kiến hai đầu Minh Lôi Thú dùng lôi điện áp chế huyết vụ của phe Địa Huyết lão quái và phát hiện một thủy trì xanh biếc nghi chứa Minh Hà thần nhũ. Hắn cũng tìm thấy Nguyên Dao và Nghiên Lệ đang bị cấm chế khống chế thân thể, đồng thời nhận định mình có khả năng phá bỏ cấm chế cho họ. Trong lúc cân nhắc cách cứu người, Hàn Lập dùng linh mục phát hiện một quỷ vật bí ẩn ẩn trong lục khí cùng viên châu có dấu hiệu linh tính, nhưng kịp ngừng quan sát và tránh được thần niệm dò xét. Cuối chương, chiến cuộc đột ngột biến đổi khi một tử huyết khôi lỗi khổng lồ hiện ra từ huyết vụ, trên vai có một huyết bào nhân chưa rõ danh tính đứng chắp tay."},{"chuong":1496,"tieuDe":"Cơ Hội","tomTat":"Tử huyết khôi lỗi do Địa Huyết điều khiển giao chiến với Minh Lôi Thú, sau đó Mộc Thanh và mỹ phụ đầu bạc hiện thân, đồng thời phát hiện trong đại điện có tới hai con mãnh thú. Ba yêu vương buộc phải hợp lực nghênh chiến trong khi Lục Túc được cho là đang chặt đứt mối liên hệ giữa linh mạch và Minh Hà thần nhũ. Ẩn thân bằng Thái Nhất Hóa Thanh Phù, Hàn Lập lặng lẽ áp sát Nguyên Dao và Nguyên Lệ, quyết định phải cứu hai người. Nhờ linh mục thần thông, hắn nhận ra nhị nữ đang bị huyết phù cấm chế của Địa Huyết khống chế, nhưng chưa thể dùng Ích Tà Thần Lôi phá giải vì sẽ lập tức bại lộ. Hàn Lập tiếp tục dè chừng đạo lục khí, đồng thời nghi Lục Túc đang ẩn dưới thủy trì và phương pháp thu lấy thần nhũ còn có điều đặc biệt. Sau khoảng một tuần trà giằng co, hai Minh Lôi Thú mất kiên nhẫn và bắt đầu liều mạng, khiến cơ hội phá vỡ thế cân bằng sắp xuất hiện."},{"chuong":1497,"tieuDe":"Hoàng Tước","tomTat":"Hai Minh Lôi Thú gọi hắc phong hộ thể, hóa thành yêu vật hình người có độc giác và vảy bạc rồi đẩy lui công kích của Mộc Thanh cùng mỹ phụ đầu bạc. Chúng hợp hai độc giác thành lôi chùy, xuyên thủng phòng hộ và gây cho Địa Huyết một vết thương lớn trước ngực, buộc hắn phải dùng huyết sắc phù triện chữa trị. Sau đó, hai thú hiến tinh huyết để thúc động tiểu phiên cùng pháp bàn, mở hai tầng pháp trận trên đỉnh điện và dưới lục trì, khiến đường lấy thần nhũ tạm thời bị phong tỏa. Mỹ phụ đầu bạc, Mộc Thanh và Địa Huyết quyết định liên thủ phá cấm chế, lần lượt triển khai tám âm giáp quỷ vương, thanh ti cùng kỳ hoa dị thảo và bảy khôi lỗi kim loại. Trong khi hai phe chuẩn bị quyết chiến, Hàn Lập vẫn ẩn ở một góc, âm thầm lấy ra hơn mười thanh sắc viên châu. Hắn đồng thời theo dõi lục khí cùng viên châu ở một hướng khác trong đại điện, đúng lúc lực lượng bí ẩn này bắt đầu hành động."},{"chuong":1498,"tieuDe":"Ra Tay","tomTat":"Viên châu trong suốt biến mất khỏi sự dò xét của Minh Thanh Linh Mục, khiến Hàn Lập phải mở rộng thần thức, nắm chặt lôi châu và chờ cơ hội duy nhất để cứu Nguyên Dao. Trong chiến đoàn, Mộc Thanh cùng mỹ phụ đầu bạc liên thủ chống hắc sắc quang trận do hai Minh Lôi Thú điều khiển, nhưng bão cát đen vẫn từng bước áp chế họ. Mộc Thanh dùng nhánh cây hóa thành thúy thụ, còn mỹ phụ đầu bạc hóa thành cự nhân mặc cổ chiến giáp và hợp tám âm giáp quỷ vương vào quái chùy. Địa Huyết phái bảy kim chúc khôi lỗi quấy nhiễu đối phương, song hai Minh Lôi Thú mở hắc động và dùng hắc hà thu mất toàn bộ số khôi lỗi. Khi Địa Huyết nổi giận chuẩn bị phản kích, Mộc Thanh phát hiện dao động bất thường và dùng thanh ti đánh vào một đoàn lục khí. Viên châu trong suốt bất ngờ hiện ra phía trên nàng, để lộ kim giáp khôi lỗi đang cầm Ngũ Long Trát. Đòn chém của ngân trát phá tan mạng lưới linh ti rồi bổ xuống khăn lụa màu xanh, để lại kết quả cuộc tập kích chưa rõ."},{"chuong":1499,"tieuDe":"Hỗn Chiến","tomTat":"Kim giáp khôi lỗi bất ngờ dùng Ngũ Long Trát phá tan các lớp phòng ngự và chém thân thể Mộc Thanh thành vô số mảnh. Lo Lục Túc sẽ chặt đứt liên hệ giữa thủy trì với linh mạch, hắn tiếp tục công kích huyết bào nhân và mỹ phụ đầu bạc thay vì ẩn nấp chờ đợi. Huyết bào nhân phối hợp với tử huyết khôi lỗi tạo huyết sắc phi kiếm để cầm chân Ngũ Long Trát, còn mỹ phụ đầu bạc thả hơn trăm âm giáp quỷ binh tham chiến. Kim giáp khôi lỗi điều quỷ vật mình người mặt ngựa chặn quỷ binh rồi khiến Ngũ Long Trát phân thành năm đạo kinh hồng, ép các đối thủ vào khổ chiến. Kim sắc quang trận chấn động dữ dội, báo hiệu Lục Túc sắp thoát ra và khiến mỹ phụ đầu bạc tiếp tục chống đỡ. Nhân lúc các bên hỗn chiến, Hàn Lập dùng Ích Tà Thần Lôi giải trừ huyết ti khống chế Nguyên Dao và Nghiên Lệ, sau đó cuốn hai người lao về cửa đại điện."},{"chuong":1500,"tieuDe":"Bất Ngờ Nối Tiếp Bất Ngờ","tomTat":"Mỹ phụ đầu bạc vừa chống hai đạo ngân hồng của Ngũ Long Trát và hắc sắc quang trận, vừa tìm cách ngăn Hàn Lập tiếp cận lối ra nhưng không thành. Mộc Thanh bất ngờ tái xuất sau khi từng bị cho là đã chết, ra tay chặn Hàn Lập rồi bị hơn mười viên lôi châu hóa thành thanh sắc lôi vân tạm thời vây khốn. Hàn Lập nhân cơ hội đưa Nguyên Dao và Nghiên Lệ đang hôn mê tới bên mình, nhưng một huyết khôi lỗi có chiến lực không kém tu sĩ Hợp Thể kỳ đột ngột xuất hiện để bắt giữ hắn. Huyết thủ phá nát lôi bào cùng hắc sắc chiến giáp, song bị kim sắc lân giáp do Phạm Thánh Chân Ma Công tạo thành ngăn lại. Khi huyết khôi lỗi nhìn thấu hư ảnh và tiếp tục truy kích, Hàn Lập dùng Nguyên Từ Thần Sơn đỡ trảo mang rồi phóng Lôi Giao Tiễn để tranh thủ độn đi cùng hai nữ tu. Hai kim sắc giáp sĩ do Giáp Nguyên Phù hóa thành tiếp tục giữ chân huyết khôi lỗi, giúp Hàn Lập xuất hiện tại lối ra vào và hóa thành thanh hồng bay khỏi đại điện. Trong lúc đó, tử huyết khôi lỗi biểu hiện dấu hiệu không còn bị khống chế, còn tiếng nổ từ phong ấn quanh lục trì báo hiệu Lục Túc sắp thoát ra."},{"chuong":1501,"tieuDe":"Vây Địch Thoát Thân","tomTat":"Hai kim sắc ảnh khôi lỗi do Giáp Nguyên Phù tạo ra liên tục phá hỏng thuấn di của huyết khôi lỗi, nhưng cuối cùng bị đối phương dùng huyết sắc quang cầu hóa thành huyết diễm nung chảy. Huyết khôi lỗi tiếp tục truy đuổi qua lam sắc thông đạo rồi bị Đề Hồn Thú giả dạng Minh Lôi Thú chặn tại cửa động. Phệ linh hỏa điểu phun hơn mười thanh sắc lôi châu ép truy binh lùi vào Cửu Cung Thiên Càn Phù, khiến nó tạm thời mắc kẹt giữa biển sương trắng và cảnh tượng lầu điện trùng điệp. Sau khi kế hoạch thành công, Đề Hồn Thú trở lại hình tiểu hầu, còn hỏa điểu thu hồi lôi châu và quay về với Hàn Lập. Hàn Lập thu linh thú vào Linh Thú Hoàn, mang Nguyên Dao cùng Nghiên Lệ toàn lực độn đi khỏi khu vực. Trong cung điện ngầm, Mộc Thanh gần phá tan lôi vân, nhóm mỹ phụ đầu bạc khổ sở chống Ngũ Long Trát, còn quỷ binh chiếm ưu thế trước quỷ vật cao cấp. Cuối cùng, kim sắc quang trận phong ấn lục trì tan biến và một bóng người cao lớn từ trong trì bay vọt ra."},{"chuong":1502,"tieuDe":"Chuyển Luân Tụ Âm Trận","tomTat":"Kim sắc quang trận chấn động dữ dội, khiến cung điện ngầm cùng mặt đất xung quanh sụp đổ thành một hố lớn trong lúc những người sống sót vừa tháo chạy vừa giao chiến. Hàn Lập dùng thanh hà đưa Nguyên Dao và Nghiên Lệ đang hôn mê rời xa chiến trường, đồng thời kiểm tra và xác nhận ấn ký trong cơ thể mình vẫn tạm thời bị phong bế. Lo nhóm yêu vương sẽ sớm kích hoạt ấn ký truy tìm, hắn chọn một vùng núi âm khí cách đó hơn trăm ngàn dặm, đào thạch động và bố trí hắc vụ che giấu cửa vào. Hàn Lập dùng ngân châm, phù triện, pháp quyết cùng một phần Kinh Thần Thứ để cứu tỉnh hai nữ tu, giúp họ xác nhận cấm chế và dị vật trong cơ thể đã được thanh trừ. Nguyên Dao đánh giá âm khí nơi đây đủ mang lại bảy tám thành nắm chắc, còn Nghiên Lệ đề nghị lập tức dùng Chuyển Luân Tụ Âm Trận để hỗ trợ khu trừ ấn ký. Nghiên Lệ dùng hôi sắc tiểu kỳ tìm ra gò đất có âm khí nồng đậm nhất, sau đó cùng Nguyên Dao bắt đầu bố trí đại trận trong khi Hàn Lập cảnh giới trên không."},{"chuong":1503,"tieuDe":"Thi Pháp Trừ Hoạn","tomTat":"Trong lúc Nguyên Dao và Nghiên Lệ hoàn tất pháp trận, một yêu vương bất ngờ kích phát ấn ký trong cơ thể Hàn Lập, khiến linh lực của hắn dao động bất ổn. Sau khi tạm áp chế tai họa, Hàn Lập quyết định lập tức dùng bí thuật âm khí nhập thể để khu trừ ấn ký dù Nghiên Lệ cảnh báo người sống có thể đau đớn đến hôn mê. Hai quỷ tu dùng cặp viên châu đen khởi động đại pháp trận, hút âm khí khắp không trung và lòng đất thành lốc xoáy rồi ngưng tụ một viên cầu đen. Dị tượng thu hút nhiều quỷ vật cấp thấp, nhưng Đề Hồn Thú và Báo Lân Thú được Hàn Lập triệu hồi đã nhanh chóng nuốt, giết hoặc xua đuổi chúng. Nguyên Dao và Nghiên Lệ dựng hai phiên kỳ, dẫn âm khí đã tinh luyện qua cơ thể mình rồi truyền sang Hàn Lập. Dù lượng âm khí vượt xa mức từng khiến hai quỷ tu hôn mê, Hàn Lập vẫn tỉnh táo và cảm nhận được một ấn ký bắt đầu hoạt động. Theo yêu cầu của hắn, hai người tiếp tục tăng mạnh âm khí quán thể, còn Hàn Lập chỉ hơi run và phát ra thanh quang khi nghi thức vẫn chưa kết thúc."},{"chuong":1504,"tieuDe":"Thối Tinh Chuyên","tomTat":"Nguyên Dao và Nghiên Lệ vận chuyển pháp trận, dẫn âm khí vào cơ thể Hàn Lập để giúp hắn ép ấn ký của Mộc Thanh ra ngoài rồi dùng kim sắc kiếm quang phá hủy. Dù đã mệt mỏi sau lần quán chú đầu tiên, Hàn Lập vẫn quyết định tiếp tục thanh trừ ba ấn ký còn lại để tránh phát sinh biến cố. Ở ngoài vạn dặm, Mộc Thanh cảm ứng được ấn ký đã mất, nghi Hàn Lập có cao nhân trợ giúp và tiếp tục truy tìm theo phương hướng mơ hồ. Trên hoang nguyên bạch cốt, Địa Huyết và Lam đạo hữu yêu cầu Lục Túc chia Minh Hà thần nhũ theo thỏa thuận, nhưng hắn tuyên bố lượng còn lại chỉ đủ cho một người. Lục Túc lấy Thối Tinh Chuyên do Phù Du Tộc chế tạo ra làm bằng chứng và cho phép hai người kia toàn lực công kích vật này để giành thần nhũ. Lam đạo hữu chấp thuận thử sức, còn Địa Huyết yêu cầu nếu mình thất bại thì Lục Túc phải giúp tiến vào ma phần lấy hai bảo vật, với điều kiện Hàn Lập còn sống để dùng Ích Tà Thần Lôi mở đường."},{"chuong":1505,"tieuDe":"Thực Lực Của Hàn Lập","tomTat":"Địa Huyết dùng việc Lục Túc độc chiếm Minh Hà thần nhũ để yêu cầu hắn cùng chia sẻ rủi ro trong chuyến đi tới ma phần, và Lục Túc chấp thuận với điều kiện chỉ hỗ trợ thu hai kiện ma khí. Lam đạo hữu cũng đồng ý lên đường nhưng yêu cầu kiểm tra Thối Tinh Chuyên, vì vậy bà dung hợp tám quỷ vương thành chiến giáp cùng quái chùy rồi tung hàng trăm đòn công kích mà vẫn không để lại vết xước trên bảo vật. Khi bàn cách truy tìm Hàn Lập, Địa Huyết thừa nhận ngay cả hóa thân huyết khôi lỗi của mình cũng không thể ngăn hắn cứu người rời đi. Lục Túc tiết lộ Hàn Lập là tu sĩ Nhân tộc đi theo con đường pháp thể song tu, có thân thể cực mạnh và chiến lực chân chính đủ sánh với Linh Suất hậu kỳ. Ba cường giả sau đó phối hợp thúc giục ấn ký truy tung, nhưng ấn ký của Lục Túc và Địa Huyết đều đã bị phá hủy, còn ấn ký của Lam đạo hữu bị một lớp phong ấn mạnh ngăn cách cảm ứng. Việc mất phương tiện định vị khiến kế hoạch truy bắt Hàn Lập của họ gặp trở ngại lớn."},{"chuong":1506,"tieuDe":"Tử Ngọ Thạch","tomTat":"Lam đạo hữu dùng âm khí của tám đầu quỷ vương để thúc đẩy ấn ký trong Hàn Lập nhưng xác nhận dấu vết cuối cùng này đã bị phá, thực chất do Nguyên Dao và Nghiên Lệ vận dụng bí thuật quỷ đạo. Địa Huyết tiết lộ linh thị trao cho Hàn Lập chứa Mộng Dẫn Huyết Khế Đại Pháp, song Hàn Lập chưa từng mở dùng nên tránh được bẫy khống chế tâm thần. Dù vậy, một mảnh Tử Ngọ Thạch giấu trong linh thị vẫn có thể cảm ứng với mảnh còn lại, cho phép ba yêu vương tiếp tục truy tìm phương vị của hắn. Lục Túc dẫn đồng bọn lên đường và thừa nhận Ngũ Long Trát từng đẩy mình đến nguy cơ vẫn lạc, trong khi người sử dụng linh bảo cũng đã cạn kiệt thần thức. Ở sâu trong Minh Hà chi địa, huyết giáp khôi lỗi kiệt quệ trở về thạch động, nhận lỗi về thất bại và xin Khương tiền bối dùng phá giới thuật tiếp dẫn bản thể tới đây. Khương tiền bối từ chối trực tiếp xuất thủ và cảnh báo âm khí sẽ ăn mòn tu vi người Phù Du Tộc, nhưng tỏ ra hứng thú khi biết bản thể khôi lỗi đang mang theo Thần Sào để tiếp tục cuộc truy sát."},{"chuong":1507,"tieuDe":"Phong Vân Tái Khởi","tomTat":"Huyết giáp khôi lỗi tiết lộ Tiểu Thần Sào chỉ là phỏng chế phẩm dùng một lần, rồi đạt thỏa thuận giao phần nguyên vật đã hỏng cho Khương tiền bối nghiên cứu để đổi lấy việc triệu hoán bản thể và tiếp tục mượn Ngũ Long Trát. Khương tiền bối dùng tia phân thần còn lưu lại làm môi giới thi pháp, khiến bạch sắc sơn mạch xuất hiện quang trụ, hắc khí, sấm sét, linh áp dữ dội và một tiếng hú đầy oán độc. Ở nơi khác, Nguyên Dao cùng Nghiên Lệ vận hành đại trận giúp Hàn Lập luyện hóa ấn ký cuối cùng, qua đó hủy diệt toàn bộ bốn ấn ký truy tung trong cơ thể hắn. Hàn Lập tặng hai người Lục Âm Đan để phục hồi âm lực, thu Đề Hồn Thú và Báo Lân Thú vào Linh Thú Hoàn rồi dẫn nhóm rời gò đất, dự định tìm cách phá vỡ không gian để trở về Linh giới. Mộc Thanh tới gò đất sau đó, từ dấu vết còn lại suy ra Hàn Lập đã trừ bỏ ấn ký nhưng vẫn quyết định tiếp tục truy tìm hắn vì vật trong ma phần. Nàng chọn một sơn cốc ít âm khí, thúc sinh cây cối thành đại trận phòng thủ rồi lấy ra một viên châu trắng sữa có hoa văn vàng để chuẩn bị thi pháp."},{"chuong":1508,"tieuDe":"Mộc Chi Lĩnh Vực","tomTat":"Mộc Thanh đưa bản thể linh mộc ra khỏi viên châu, dùng tinh huyết đánh thức phân thần còn lại của Kim Linh và để phân thần này kế thừa thân phận của chủ nguyên thần đã vẫn lạc. Vì ấn ký trên người Hàn Lập đã bị phá, nàng quyết định hao tổn bổn nguyên thi triển Mộc Chi Lĩnh Vực, đồng thời giao Thiên Mộc Kính và đôi Trường Thanh Mộc Linh Kiếm cho Kim Linh bảo vệ bản thể trong Thanh Mộc Chu Thiên Đại Trận. Mộc Thanh tiết lộ động cơ thực sự là hạt châu đồng nguyên trong ma phần, bảo vật có thể giúp nàng đột phá cảnh giới hiện tại và tiến lên tầng cao hơn. Tại nơi từng lưu dấu Hàn Lập, nàng dùng lĩnh vực liên kết cây cỏ với lòng đất, xác định hai môn hạ quỷ bà đã phá ấn ký nhưng vẫn lần ra hướng chạy của nhóm hắn. Trong khi đó, Hàn Lập dẫn Nguyên Dao và Nghiên Lệ vượt qua vùng cát vàng, liên tục đổi hướng mà không biết cuộc truy đuổi đã nối lại. Hắn đề nghị tìm không gian tiết điểm để trở về Linh giới, cho rằng mình có bảy tám phần nắm chắc vượt qua an toàn. Sau khi Nguyên Dao cảnh báo về phong bạo không gian và Nghiên Lệ đề nghị ở lại tu luyện, Hàn Lập bác bỏ phương án lưu lại vì Minh Hà chi địa là Thánh địa của Phù Du Tộc và viện binh của họ có thể xuất hiện."},{"chuong":1509,"tieuDe":"Quỷ Vụ Tái Hiện","tomTat":"Nghiên Lệ và Nguyên Dao đồng ý với kế hoạch ẩn náu, chờ khoảng trống giữa lúc nhóm quỷ bà rời Minh Hà chi địa và người Phù Du Tộc chưa tới để tìm không gian tiết điểm. Ba người tiến tới một thủy vực xanh đen phủ nhiều hắc vụ, nơi Hàn Lập cho rằng những tồn tại đáng sợ dưới đáy có thể ngăn đối phương tùy tiện tra xét. Khi họ bay vào một đám hắc vụ, linh khí hộ thể và độn quang lập tức tan rã, còn Nguyên Từ Thần Quang cùng Phạm Thánh Chân Ma Công của Hàn Lập đều mất hiệu lực. Hàn Lập chuyển sang thi triển Côn Bằng Biến trong Kinh Trập Thập Nhị Quyết, hóa thành đại bàng, khôi phục toàn bộ pháp lực và cứu hai nàng thoát ra. Hàn Lập và Nguyên Dao nhận ra vụ khí này có nét tương đồng với quỷ vụ từng cuốn họ từ Loạn Tinh Hải vào Âm Minh Chi Địa, dù tác dụng giữa hai loại không hoàn toàn giống nhau. Sau khi khảo sát khu vực bằng hình thái Côn Bằng, Hàn Lập xác nhận chỉ một số đám hắc vụ có khả năng thôn phệ linh lực, còn hơn phân nửa chỉ là vụ khí bình thường. Vì hắc vụ đặc biệt còn giam cầm thần niệm, cả nhóm cân nhắc dùng nó làm nơi trốn tránh các yêu vương, trong khi Nguyên Dao hỏi nguyên nhân Côn Bằng Biến không chịu sự áp chế của vụ khí."},{"chuong":1510,"tieuDe":"La Hầu Chi Mê","tomTat":"Hàn Lập giải thích rằng thuật biến thân Côn Bằng được học từ một phân chi Thiên Bằng Tộc thuộc Phi Linh Tộc, đồng thời suy đoán Côn Bằng chân huyết giúp hắn chống lại hắc vụ vì Côn Bằng là thiên địch của La Hầu. Từ sự tương đồng giữa quỷ vụ ở Âm Minh chi địa và vụ khí tại Minh Hà chi địa, hắn cùng Nghiên Lệ và Nguyên Dao đặt ra giả thuyết rằng Minh Hà chi địa là không gian độc lập trong cơ thể một La Hầu đã chết. Giả thuyết này giải thích được âm minh khí và nhiều quỷ vật cao cấp nhưng chưa làm rõ nguồn gốc linh khí cùng linh mạch. Lo viện quân Phù Du Tộc kéo tới, ba người quyết định dành tối đa hai ngày tìm lối thoát trong thủy vực hắc vụ. Hàn Lập khôi phục Phong Lôi Sí và ngưng tụ hai cây thanh linh từ khí tức Côn Bằng để giúp Nguyên Dao cùng Nghiên Lệ hoạt động trong hắc vụ. Nghiên Lệ thử nghiệm thành công, dù hơn phân nửa linh lực của nàng vẫn bị hạn chế. Hắc vụ bất ngờ hóa thành lốc xoáy có hấp lực dữ dội và hắc sắc thiểm điện, cuốn Hàn Lập cùng Nghiên Lệ biến mất. Ngay sau đó, lốc xoáy mở rộng và cuốn cả Nguyên Dao vào trong."},{"chuong":1511,"tieuDe":"Ngọc Trai","tomTat":"Hàn Lập và Nghiên Lệ bị hắc sắc thiểm điện truyền tống tới một ngọc thai giữa hắc vụ, trong khi Nguyên Dao bị bỏ lại bên ngoài và tạm thời thất lạc. Hàn Lập dùng Minh Thanh Linh Mục quan sát, phát hiện ngọc thai thuộc một quần thể gồm bảy kiến trúc bố trí trong lòng núi. Nghiên Lệ không thể giải cấm chế, còn Thanh Trúc Phong Vân Kiếm và hắc diễm từ quạt ba tiêu đều bị bạch sắc quang mạc đánh bật. Hàn Lập chuyển sang dùng Nguyên Từ Thần Quang phá quang mạc, hóa thành thanh sắc đại bàng dẫn Nghiên Lệ vượt qua hắc vụ và bức tường cấm chế thanh–vàng. Hai người tới một bình thai đối diện thông đạo phát sáng, nơi Hàn Lập thả hai kim sắc giáp trùng vào thăm dò. Linh trùng lập tức bị một người có tu vi sâu không lường được bắt giữ. Lão giả chưa lộ diện gọi tên Thất Môn Tỏa Âm Trận, xác nhận đây là phủ của mình và mời hai người tiến vào."},{"chuong":1512,"tieuDe":"Thanh Nguyên Tử","tomTat":"Hàn Lập và Nghiên Lệ tiến qua thông đạo đá, gặp một lão giả áo xám có tu vi sâu không lường được trong đại sảnh cổ kính. Lão giả họ Khương cho biết mình xuất thân Nhân tộc nhưng thân thể hiện tại vốn thuộc Trường Nguyên Tộc, đồng thời nhìn thấu bán quỷ chi thân của Nghiên Lệ và căn cơ phức tạp của Hàn Lập. Ông cưỡng ép gọi toàn bộ bảy mươi hai Thanh Trúc Phong Vân Kiếm ra ngoài rồi nhận ra chúng được luyện theo Thanh Nguyên Kiếm Quyết mà Thanh Nguyên Tử từng lưu lại Nhân giới. Từ lời giải thích của ông, Hàn Lập biết Thanh Nguyên Tử từng mất nhục thân và một nửa hồn phách, sau đó đoạt xá người Trường Nguyên Tộc rồi dung hợp ký ức, khiến lão giả trước mặt chỉ có thể xem là nửa Thanh Nguyên Tử. Lão giả cũng chỉ rõ việc pha trộn nhiều vật liệu đã khiến mộc linh tính của bộ phi kiếm trở nên hỗn tạp và trì hoãn cảnh giới kiếm tâm thông linh. Ông kể Thanh Nguyên Tử năm xưa chỉ dựa vào Thanh Trúc Phong Lôi Kiếm đã có thể vượt cấp đối địch. Cuối cùng, thái độ lão giả đột ngột lạnh đi khi truy hỏi Hàn Lập và Nghiên Lệ có cùng nhóm ngoại nhân tiến vào Minh Hà chi địa hay không."},{"chuong":1513,"tieuDe":"Thiên Âm Chi Thể","tomTat":"Hàn Lập dùng lời thật giả lẫn lộn để giải thích việc nhóm mình tiến vào Minh Hà chi địa, còn Khương lão giả tiết lộ ông ở lại đây theo một giao dịch với các thái thượng trưởng lão Phù Du Tộc. Ông cho biết một kiện ma khí tại nơi sâu nhất đã hóa thành hình người, thôn phệ số ma khí còn lại và hoàn thành vô thượng ma thân, đủ sức đe dọa những yêu vương Hợp Thể đang tìm tới. Khương lão giả cũng giải thích Thất Môn Tỏa Âm Trận được dùng để điều tiết âm khí và chính trận pháp này đã vô tình cuốn ba người Hàn Lập tới những nơi khác nhau. Sau khi mở thông đạo đưa Nguyên Dao về đại sảnh, ông kiểm tra và xác nhận nàng sở hữu Thiên Âm Chi Thể cực kỳ hiếm của Trường Nguyên Tộc. Thể chất ấy là điều kiện tu luyện một loại đại thần thông có thể giúp ông tăng khả năng vượt qua thiên kiếp, vì vậy ông đề nghị thu Nguyên Dao làm đệ tử. Khương lão giả công khai mình đã đạt Đại Thừa sơ kỳ từ một vạn năm trước, khiến Hàn Lập nhận ra đây là tu sĩ Đại Thừa đầu tiên hắn tận mắt gặp tại Linh giới. Nguyên Dao không nhận lời ngay mà xin bàn bạc với Hàn Lập và Nghiên Lệ, được ông cho ba ngày để đưa ra quyết định."},{"chuong":1514,"tieuDe":"Ý Kiến Trái Chiều","tomTat":"Khương lão giả sai Ảnh nô đưa Hàn Lập, Nguyên Dao và Nghiên Lệ tới khu phòng khách, đồng thời yêu cầu thuộc hạ tận lực đáp ứng nhu cầu của họ. Hàn Lập nhận ra Ảnh nô là một Quỷ Vương Luyện Hư hậu kỳ rồi cùng hai nữ tu nghỉ lại trong tiểu viện, chờ hết thời hạn ba ngày để đưa ra quyết định. Sau khi bố trí cấm chế chống nhìn trộm, hắn ngủ sâu và mộng thấy gia đình, cố nhân cùng ái thê Nam Cung Uyển tại Nhân giới. Khi ba người thương nghị, Nguyên Dao phản đối việc bái sư vì Âm Dương Luân Hồi Quyết đang khiến nàng và Nghiên Lệ dần chuyển thành quỷ vật, buộc họ phải sớm tìm cách khôi phục nhân thân. Nghiên Lệ lại khuyên sư muội nắm lấy cơ duyên được Khương lão giả che chở và truyền dạy, còn mình sẽ trở về Nhân tộc tìm bí thuật chữa trị. Nàng cũng lo rằng Nguyên Dao khó có thể rời đi nếu từ chối lời đề nghị bái sư. Sau khi nghe cả hai trình bày, Hàn Lập khẳng định việc bái sư và việc khôi phục nhân thân không nhất thiết loại trừ nhau, khiến hai nữ tu kinh ngạc."},{"chuong":1515,"tieuDe":"Tân Thanh Nguyên Kiếm Quyết","tomTat":"Hàn Lập khuyên Nguyên Dao và Nghiên Lệ trực tiếp nhờ lão giả họ Khương giải quyết bán quỷ chi thân, đồng thời dùng Nguyên Từ Thần Quang kiểm tra thần niệm theo dõi trước khi cảnh báo họ về nguy cơ ẩn sau việc thu đồ. Ảnh nô dẫn ba người tới đại sảnh, nơi lão giả họ Khương cho biết có thể dùng đan dược và pháp lực khu trừ âm lực để giúp hai nàng khôi phục nhân thân. Nguyên Dao lập tức bái ông làm sư phụ, còn lời cầu xin thu nhận Nghiên Lệ bị từ chối, dù nàng vẫn được hứa chữa trị. Sau đó, lão giả truyền âm cho Hàn Lập, tiết lộ từng cân nhắc thu hắn vì con đường pháp thể song tu nhưng đã chọn Nguyên Dao và cần chuẩn bị độ thiên kiếp. Ông hé lộ Thanh Nguyên Kiếm Quyết lưu tại Nhân giới chỉ là nửa đầu, còn phần sau có thể tu tới Hợp Thể sơ kỳ và khi đại thành đủ sức lập kiếm trận đối kháng Hợp Thể hậu kỳ. Cuối cùng, ông đề nghị đổi Tân Thanh Nguyên Kiếm Quyết lấy lượng Kim Lôi Trúc đủ luyện ba thanh phi kiếm, đồng thời hứa tinh luyện lại toàn bộ bảy mươi hai thanh Thanh Trúc Phong Vân Kiếm nếu Hàn Lập cung cấp nhiều hơn."},{"chuong":1516,"tieuDe":"Trúc Diệp","tomTat":"Khương lão giả muốn đổi kiếm quyết và phương pháp tinh luyện phi kiếm lấy Kim Lôi Trúc, nhưng Hàn Lập không còn linh trúc đã bồi dưỡng dư thừa nên dùng hai hộp lá trúc hoàn tất giao dịch. Sau khi trao ngọc giản, lão tiết lộ lá Kim Lôi Trúc có thể luyện Kim Cương Diệt Ma Thần Lôi hoặc nuôi linh trùng phát sinh biến dị lớn, khiến Hàn Lập đặc biệt lưu tâm. Lão cũng giải thích hiểm họa Vực Ngoại Thiên Ma đối với tu sĩ Đại Thừa và lý do mình cần thần lôi để chuẩn bị cho thiên kiếp kế tiếp. Khi Hàn Lập thừa nhận chưa tìm được đường rời Minh Hà chi địa, Khương lão giả hứa sẽ thi pháp đưa hắn ra ngoài sau hai ngày; tin này khiến Nguyên Dao thoáng tái mặt và bị Nghiên Lệ nhận ra. Tiếp đó, lão cho biết mình đã bí mật lấy được Minh Hà thần nhũ dù có hai Minh Lôi Thú canh giữ. Hàn Lập nhận ngọc giản ghi danh sách vật liệu và chấp thuận trong vòng một nghìn năm thu thập ít nhất hai phần ba số mục để đổi thần nhũ, còn việc được đưa rời khỏi Minh Hà chi địa được tính là khoản đặt cọc trước."},{"chuong":1517,"tieuDe":"Ly Khai","tomTat":"Sau hai ngày chuẩn bị, Khương lão giả trao cho Hàn Lập Nghịch Tinh Bàn phỏng chế phẩm, lam sắc ngọc giản và trả lại hai Phệ Kim Trùng từng bị thu giữ. Lão giải thích Phệ Kim Trùng thành thục thể chỉ thật sự đáng sợ khi đạt số lượng lớn, đồng thời kể về Phệ Kim Trùng Vương trong truyền thuyết có thể khiến cả Đại Thừa lẫn chân tiên kiêng dè. Khương lão giả sau đó vận hành pháp trận, ngưng tụ thanh sắc cự kiếm chém mở khe không gian và dùng ngũ sắc quang trụ đưa Hàn Lập rời Minh Hà chi địa trở về Linh giới. Nguyên Dao lo lắng cho Hàn Lập nhưng được sư phụ cùng Nghiên Lệ an ủi, rồi quyết tâm chuyên tâm tu luyện sau khi nghe cam kết về khả năng tiến vào Luyện Hư và Hợp Thể. Ở một hoang nguyên xa xôi, Lục Túc, Lam đạo hữu, Huyết bào nhân và Tử huyết khôi lỗi đang chống lại trùng hải đông đảo nhưng không thể ngăn quân số đối phương liên tục tăng thêm. Ngoài chiến đoàn, một quái trùng mặt người lạnh lùng quan sát, trong khi vật thể hình quạt ngân sắc phía trên nó không ngừng phóng thêm quái trùng vào cuộc vây công."},{"chuong":1518,"tieuDe":"Vụ Trung","tomTat":"Lục Túc nhận vật hình quạt của đối phương là Thánh Sào của Phù Du Tộc nên thuyết phục Huyết bào nhân và Lam đạo hữu từ bỏ việc lấy ma khí, phá vây trở về lối vào thông đạo. Ba cường giả lần lượt dùng hắc sắc quang hoàn, tử hồng quang trụ và quái phong băng hàn mở một khoảng trống giữa trùng hải, sau đó liên kết pháp lực lao khỏi vòng vây. Quái trùng mặt người nhập vào Thánh Sào phỏng chế, dẫn toàn bộ đàn trùng truy kích họ, trong khi Mộc Thanh vẫn do dự trước vùng hắc vụ trên hải vực. Ở một nơi khác, Hàn Lập bị khe hở không gian đưa khỏi Minh Hà chi địa và rơi vào Hắc Minh vụ hải thuộc Hắc Ẩn sơn mạch. Nguyên Từ Thần Quang tự động bảo vệ hắn, nhưng hắc vụ hạn chế thần niệm, hút sạch linh khí của cây cỏ và triệt tiêu độn quang. Sau khi nhận ra cấm chế ngăn phi hành và suy xét mối liên hệ giữa vụ hải với Minh Hà chi địa, Hàn Lập dựa vào thân thể mạnh mẽ, xác định phương hướng rồi đi bộ tìm đường thoát."},{"chuong":1519,"tieuDe":"Xuân Lê, Thanh Bàn","tomTat":"Hàn Lập thận trọng tìm đường rời Hắc Minh vụ hải, đồng thời kiểm kê những thu hoạch từ chuyến mạo hiểm tại Địa Uyên và Minh Hà chi địa. Hắn dự định trở về động phủ khổ tu tới Hóa Thần hậu kỳ đỉnh phong, sau đó dùng Hắc Viêm Đan trùng kích Luyện Hư và tìm đủ vật phẩm để đổi Minh Hà thần nhũ với Khương lão giả. Khi nghiên cứu Tân Thanh Nguyên Kiếm Quyết, hắn biết năm tầng sau có thể dẫn tới Luyện Hư hậu kỳ nhưng quyết định chỉ chọn những bí thuật phù hợp với con đường pháp thể song tu của mình. Hai kiếm trận Xuân Lê và Thanh Bàn có tiềm lực vượt cấp khiêu chiến, song yêu cầu tinh luyện lại Thanh Trúc Phong Vân Kiếm, khu trừ Canh Tinh và từ bỏ khả năng bố trí Đại Canh Kiếm Trận, khiến hắn chưa thể quyết định. Trên đường đi, Hàn Lập phát hiện một ngưu giác thanh niên tu vi Luyện Hư ẩn trong hắc vụ và dùng lôi cầu ép đối phương hiện thân. Bị nhìn ra lai lịch có thể liên quan tới Hạo Thú Tộc cùng công pháp quỷ đạo, ngưu giác thanh niên lập tức ra tay diệt khẩu. Âm phong của hắn bị hôi sắc hà quang hóa giải, nên hắn biến đôi sừng thành song loan đao lao vào cận chiến, còn Hàn Lập gọi ra kim sắc hư ảnh ba đầu sáu tay để nghênh địch."},{"chuong":1520,"tieuDe":"Hồi Phủ","tomTat":"Hàn Lập dùng Thanh Trúc Phong Vân Kiếm, ngũ sắc quang hà và pháp tướng Phạm Thánh Chân Ma Công áp đảo yêu vật Hạo Thú mới tiến giai Luyện Hư. Khi đối phương bỏ thân thể, dùng bạch cốt thuẫn che chở viên châu chứa nguyên thần đào tẩu, hắn hóa Ích Tà Thần Lôi thành sáu lôi thương phá tan mọi lớp phòng ngự rồi dùng điện võng diệt hẳn nguyên thần. Cái chết của Hạo Thú vô tình khiến kế hoạch thoát khỏi nô ngân Thiên Bằng Tộc của đám trung giai yêu thú Hắc Ẩn sơn mạch hoàn toàn thất bại. Sau hơn nửa tháng vượt Hắc Minh vụ hải, Hàn Lập trở về động phủ, kiểm tra dược viên và nghỉ ngơi hai ngày hai đêm. Hồi phục xong, hắn quyết định dùng Chân Thiềm Linh Dịch tiến tới Hóa Thần đại viên mãn, luyện hóa tinh thần lực trong Thiên Bằng xá lợi để lấy khẩu quyết dung hợp chân huyết chân long và thiên phượng, đồng thời nghiên cứu tân kiếm quyết. Trước khi vào mật thất, Hàn Lập thả đệ nhị Nguyên Anh, Đề Hồn và Báo Lân Thú, rồi giao tiểu bình thần bí cho đệ nhị Nguyên Anh tạm quản lý."},{"chuong":1521,"tieuDe":"Trọng Luyện Thần Sơn","tomTat":"Hàn Lập kiểm tra ba mảnh đá xám trắng lấy từ thạch đôn trong động phủ lam giao và cân nhắc tác động biến dị của chúng đối với Phệ Kim Trùng. Hắn vận dụng Phạm Thánh Chân Ma Công cùng sức mạnh thân thể để đưa một khối đá cực nặng vào Nguyên Từ Thần Sơn, rồi dùng Phệ Linh Hỏa Điểu và nhiều tài liệu phụ trợ bắt đầu quá trình dung hợp. Việc luyện hóa cả ba khối dự kiến kéo dài hơn trăm năm, trong thời gian đó thần sơn không thể thu vào cơ thể. Sau đó, Hàn Lập giao hột Thanh La Quả cho đệ nhị Nguyên Anh mang đi bồi dưỡng, chuẩn bị nguyên liệu luyện Thiên La Đan phối hợp với Hắc Viêm Đan để phá bình cảnh. Trải qua ba tháng nghiên cứu tân kiếm quyết, hắn lĩnh ngộ rằng Xuân Lê Kiếm Trận lấy ảo thuật làm chủ và tác động dựa trên công pháp cùng thần thức của người bị vây. Nhận thấy Đại Canh Kiếm Trận khó đối phó tu sĩ Hợp Thể, Hàn Lập quyết định từ bỏ trận này, không luyện thêm phi kiếm và chuyển sang tinh luyện lại bảy mươi hai Thanh Trúc Phong Vân Kiếm để theo đuổi Xuân Lê Kiếm Trận cùng Thanh La Kiếm Trận."},{"chuong":1522,"tieuDe":"Chủng Kiếm","tomTat":"Hàn Lập xem lại ngọc giản của lão giả họ Khương và cân nhắc ba phương pháp loại bỏ tạp chất khỏi Thanh Trúc Phong Vân Kiếm. Sau khi loại bỏ cách dùng Nguyên Anh chi hỏa và Cửu Việm Dong Kim Quyết vì thời gian, tài nguyên cùng nguy cơ tổn hại phi kiếm, hắn quyết định thử bí pháp di hoa tiếp mộc. Hàn Lập lấy đoạn Kim Lôi Trúc còn rễ, chọn một thanh phi kiếm làm thử nghiệm rồi giao cả hai cho đệ nhị Nguyên Anh xử lý. Sau đó hắn uống Chân Thiềm Linh Dịch, hiển hóa Phạm Thánh Chân Ma pháp tướng và bế quan tu luyện suốt một trăm năm. Trong thời gian này, đệ nhị Nguyên Anh bồi dưỡng Mộc Linh Hoa, còn Đề Hồn giả dạng Hàn Lập để duy trì việc trao đổi với các yêu thú trung giai. Khi thời hạn trăm năm kết thúc, một thiên tượng lớn xuất hiện trên động phủ, gồm sấm sét, linh vân, ngũ sắc quang hà và cơn lốc khổng lồ, khiến yêu vật quanh Hắc Ẩn sơn mạch bị chặn ngoài nghìn dặm. Cự mãng ba đầu và tiểu thú đầu trâu đều nghi Hàn Lập đang tiến hành một lần đột phá lớn, nhưng chương chưa xác nhận cảnh giới mới hoặc kết quả vượt quan."},{"chuong":1523,"tieuDe":"Tiến Giai Luyện Hư","tomTat":"Cự mãng ba đầu và kim viên đề nghị dùng một vật trọng yếu cho việc tiến giai để đổi lấy sự trợ giúp của Hàn Lập trong việc giải trừ nô ấn; tiểu thú đầu trâu cuối cùng cũng chấp thuận chờ kết quả. Tại cự sơn, pháp tướng ba đầu sáu tay của Hàn Lập hiện ra, dung nhập bốn hư ảnh chân linh rồi thu nạp toàn bộ ngũ sắc quang hà và linh vân hội tụ. Pháp tướng sau đó hóa thành ngũ sắc quang mạc bao phủ Hàn Lập, khiến thiên tượng và linh áp bên ngoài hoàn toàn tiêu tán. Tam yêu nhận ra quá trình phá bình cảnh mới bước vào thời khắc mấu chốt nên rời đi, về sau chỉ bí mật quay lại quan sát. Hàn Lập bất động trong quang mạc suốt hai tháng rưỡi, còn cự sơn được một cấm chế quy mô lớn bảo vệ khỏi dã thú xâm nhập. Cuối cùng hắn mở mắt, thét dài đầy vui mừng, giải tán quang mạc rồi gọi đôi cánh sau lưng và biến mất giữa tiếng sấm."},{"chuong":1524,"tieuDe":"Tế Luyện","tomTat":"Sau một trăm năm khổ tu, Hàn Lập đạt Hóa Thần đại viên mãn, luyện hóa tinh thần chi lực trong Thiên Bằng xá lợi và dung nhập Chân Long chi huyết cùng Thiên Phượng chi huyết, nhờ đó nắm giữ thêm hai biến hóa của Kinh Trập Quyết. Hắn dùng Hắc Viêm Đan phối hợp Thiên La Đan để trùng kích bình cảnh, thành công điều động thiên địa nguyên khí quán chú pháp thể và tiến vào Luyện Hư kỳ. Sau khi xuất quan, Hàn Lập thử ngưng tụ thiên địa nguyên khí thành bàn tay năm màu, xác nhận khả năng vận dụng nguyên khí đã vượt xa thời Hóa Thần. Hắn phát hiện Phệ Linh Hỏa Điểu đã dung luyện các mảnh thạch đôn cực nặng vào Nguyên Từ Thần Sơn nhưng bị hao tổn bổn nguyên, nên thu nó vào cơ thể bồi dưỡng. Vì phần vật liệu mới khiến thần sơn suýt kéo ngã mình khi phong ấn trên cánh tay, Hàn Lập dùng Bách Mạch Luyện Bảo Quyết và Phạm Thánh Chân Ma Công tế luyện lại pháp bảo gần nửa năm. Đệ nhị Nguyên Anh sau đó truyền lại những việc xảy ra trong thời gian bế quan, bao gồm chuyện bốn yêu thú từng giao dịch Mộc Linh Hoa tìm đến xin gặp. Tại đại sảnh, Đề Hồn đang giả dạng Hàn Lập để tiếp khách; khi chủ nhân thật xuất hiện, nó trở lại nguyên hình tiểu hầu và được thu vào tay áo. Hàn Lập ngồi vào ghế chủ tọa rồi yêu cầu tiểu thú đầu trâu, kim viên, cự mãng ba đầu và đại trư yêu trình bày lại mục đích tìm đến."},{"chuong":1525,"tieuDe":"Huyết Hạnh Và Nô Ngân","tomTat":"Tiểu thú đầu trâu cùng ba yêu vật đến chúc mừng Hàn Lập tiến giai, đồng thời dâng một quả Huyết Hạnh quý hiếm để cầu viện. Chúng tiết lộ bản thân bị Thiên Bằng Tộc đặt nô ngân, buộc phải ở lại đảo thu thập vật phẩm cống nộp dù nguồn linh vật trong Hắc Ẩn sơn mạch ngày càng cạn kiệt. Hàn Lập kiểm tra thân thể và tinh hồn của tiểu thú đầu trâu, dùng thanh ti kéo trùng ảnh đỏ đại diện cho cấm chế ra khỏi trán nó. Khi trùng ảnh chống lại, hắn triệu hư ảnh thanh sắc đại bàng mổ lấy rồi nuốt nó, khiến nô ngân hoàn toàn biến mất. Hàn Lập tiếp tục áp dụng phương pháp này cho ba yêu vật còn lại và giải phóng cả tứ yêu trong khoảng thời gian một bữa cơm. Sau khi biết người Thiên Bằng Tộc phải vài trăm năm nữa mới quay lại đảo, hắn buông bỏ sự kiêng kị vì tin rằng khi ấy mình đã rời đi rất xa."},{"chuong":1526,"tieuDe":"Đằng Long Đan","tomTat":"Sau khi tứ yêu rời đi, Hàn Lập kiểm tra Huyết Hạnh và xác định mình chỉ còn thiếu Viêm Kim Tinh để hoàn thiện nhóm tài liệu ngưng luyện Phạm Thánh Chân Ma pháp tướng. Hắn tới dược viên kiểm tra bảy mươi hai phi kiếm cấy trong thanh trúc, nhận thấy phương pháp chuyển hóa có hiệu quả nhưng chậm hơn dự tính nên tiếp tục duy trì phong ấn. Trong luyện đan thất, hắn bồi dưỡng Chi Long Quả rồi luyện lượng lớn Đằng Long Đan để tăng tiến tu vi Luyện Hư, dù tỷ lệ thất bại rất cao. Hàn Lập vừa luyện đan, củng cố tu vi và nghiên cứu Xuân Lê kiếm trận vừa để Đề Hồn cùng đệ nhị Nguyên Anh giả làm mình tiếp nhận tài liệu do tứ yêu mang tới. Sau bốn mươi năm bế quan, một luồng thần niệm lạnh lẽo xuyên qua nhiều tầng cấm chế khiến hắn cảnh giác. Pháp trận và kính đồng cho thấy hai quang điểm cực sáng đang dừng cách động phủ vài nghìn dặm. Vì hai tồn tại bí ẩn không tiến tới cũng không rời đi, Hàn Lập quyết định phun tinh huyết bao phủ kính đồng để tiếp tục tăng cường dò xét."},{"chuong":1527,"tieuDe":"Giác Xi Tộc Và Hải Vương Tộc","tomTat":"Hàn Lập kích phát thần thông của Vạn Lung Châu, bí mật quan sát một thanh niên ngân giác và một dị tộc mắt cá tại ngọn núi cạnh Hắc Minh vụ hải. Thanh niên ngân giác là Mẫn đạo hữu nhanh chóng phát hiện ánh nhìn từ xa và phá cấm chế, khiến Hàn Lập nhận ra cả hai có thể là cường giả Hợp Thể trung hoặc hậu kỳ. Mẫn đạo hữu thu một viên Vạn Lung Châu để nghiên cứu, còn Giản huynh tìm được viên khác rồi đóng băng và phá hủy nó. Qua cuộc trò chuyện, hai người tiết lộ họ đại diện cho Giác Xi Tộc và Hải Vương Tộc, được truyền tống vượt đại dương đến lãnh địa Phi Linh Tộc để truy tìm Huyền Thiên Trảm Linh Kiếm. Bảo vật này vừa hiện thế đã đứng thứ ba trong bảng Huyền Thiên chi bảo, khiến hai đại tộc sẵn sàng tiêu diệt bất kỳ bộ tộc nào dám chiếm giữ. Mẫn đạo hữu quyết định không truy bắt người theo dõi để tránh ảnh hưởng đại sự, rồi cùng Giản huynh bắt đầu thu lấy chân linh âm khí trong Hắc Minh vụ hải. Giản huynh triển khai biển sóng lam sắc quanh một hồ lô nhỏ, còn Mẫn đạo hữu gọi ra quái vật độc giác cao trăm trượng, mặc đồng giáp và cầm hai vật kỳ dị."},{"chuong":1528,"tieuDe":"Cửu U Minh Thi","tomTat":"Mẫn đạo hữu và dị tộc mắt cá dùng thanh sắc ngọc bình cùng lam sắc hồ lô hút hắc vụ trong Hắc Minh vụ hải, nhưng sau hai ngày hai đêm mới thu được khoảng một phần mười. Theo dõi họ qua Vạn Lung Châu, Hàn Lập cảm thấy bất an nên cất gần hết tài vật vào trữ vật thủ trạc và chuẩn bị bỏ động phủ nếu tình thế chuyển xấu. Hai dị tộc tiếp tục thi triển Nạp Nguyên Thuật, biến hai cột vụ khí thành hơn mười cột để đẩy nhanh quá trình thu lấy chân linh âm khí. Một tiếng rống từ sâu trong vụ hải bất ngờ phá vỡ toàn bộ cột khí, sau đó di hài Cửu Đầu Điểu chín đầu lao ra. Mẫn đạo hữu xác định cốt điểu đang ở giai đoạn tiến hóa thứ hai, có thực lực tương đương hai người, nhưng vẫn quyết định giao chiến vì công pháp của hắn cần chân linh âm khí. Cửu Đầu Điểu dùng tám đầu phát động hàng loạt công kích đa thuộc tính, còn dị tộc mắt cá dựng tường băng rồi phóng lam quang làm các đòn đánh biến mất và phản kích về phía cốt điểu."},{"chuong":1529,"tieuDe":"Ly Ý","tomTat":"Dị tộc mắt cá dùng lam hà và vô số lam sắc quang cầu tấn công Cửu Đầu Điểu, nhưng hung sát chi khí của minh thi nhanh chóng ăn mòn phần lớn thế công. Mẫn đạo hữu dùng thanh sắc điện hồ áp chế hôi khí, khiến Cửu Đầu Điểu phải thi triển Diệt Phách Thần Quang để phá tan điện quang và lam quang. Sau khi xác định đối thủ chỉ còn khoảng một phần ba hung sát chi khí, hai dị tộc nhân quyết định xuất toàn lực dù vẫn nghi ngờ nguồn chân linh âm khí tại đây có điều bất thường. Cửu Đầu Điểu hút vụ khí quanh vùng thành hắc sắc linh vũ rồi lao vào cận chiến, trong khi hai đối thủ đồng thời biến thành những hình thể khổng lồ và dùng thần thông, vũ khí nghênh chiến. Trận chiến giữa ba tồn tại Hợp Thể tạo ra chấn động lan xa cả ngàn dặm và dần tiến về phía động phủ của Hàn Lập. Quan sát tình hình qua cấm chế Vạn Lung Châu, Hàn Lập quyết định rời đi trước khi các bên phân thắng bại. Hắn sau đó xuất hiện trong dược viên, đứng trước dãy Kim Lôi Trúc vạn năm xanh tươi."},{"chuong":1530,"tieuDe":"Tân Phi Kiếm","tomTat":"Hàn Lập hoàn tất quá trình tinh luyện bảy mươi hai thanh Thanh Trúc Phong Vân Kiếm, khiến toàn bộ Kim Lôi Trúc khô héo và hóa thành tro. Lợi dụng lúc hai dị tộc cấp Hợp Thể đang giao chiến dữ dội với cự đại cốt điểu, hắn rời khỏi động phủ rồi liên tục thay đổi lộ trình để đề phòng bị truy sát. Sau khi xác nhận không có người đuổi theo, hắn quyết định men theo duyên hải phía Đông nhằm rời khỏi khu vực Phi Linh Tộc. Trong lúc kiểm nghiệm bộ kiếm mới, Hàn Lập phát hiện chúng đã chuyển hoàn toàn sang mộc thuộc tính, có thể hóa thành thể vô hình, tự phân giải và tái tổ hợp sau khi bị chém gãy. Hắn cũng nhận ra năng lực này không tạo ra kiếm thân bất diệt tuyệt đối, bởi mỗi lần khôi phục đều làm hao tổn phi kiếm và pháp lực của chủ nhân. Hàn Lập thu kiếm vào cơ thể để tiếp tục dùng chân nguyên bồi luyện, đồng thời tham ngộ Xuân Lê Kiếm Trận trong hành trình. Hơn nửa năm sau, vừa chém nát một con cự mãng tập kích từ biển, hắn đột nhiên biến sắc và nhìn lên không trung."},{"chuong":1531,"tieuDe":"Huyết Vân","tomTat":"Bầu trời quanh Hàn Lập đột ngột chuyển đỏ, vô số huyết vân mang mùi máu tươi lan kín phạm vi rộng lớn và khiến hắn nghi mình đã lọt vào một cấm chế thần bí. Dù dùng độn tốc gần đạt mức tu sĩ Hợp Thể Kỳ để bay hàng trăm vạn dặm, hắn vẫn không thể thoát khỏi khu vực này. Khi huyết sắc phù văn từ trong mây phát động công kích, Hàn Lập triển khai lôi bào, bảy mươi hai thanh phi kiếm và Nguyên Từ Thần Sơn để chống trả. Một cự đại huyết phù sau đó cảm ứng với hộp ngọc, đốt cháy các phù triện phong kín và cưỡng ép Huyền Thiên Quả Thật hiện ra. Nhiều hư ảnh yêu thú cùng dị tộc chịu thống khổ xuất hiện trong huyết vân, giúp Hàn Lập nhận ra đây là một nghi thức huyết tế. Các hư ảnh tụ thành huyết sắc quang trận khổng lồ, tiếp tục truy bám sau khi hắn bỏ chạy và đặt hắn đúng vào trung tâm trận. Chương kết thúc khi quang trận bắt đầu phát sinh dị biến mới."},{"chuong":1532,"tieuDe":"Huyền Thiên Chi Tranh","tomTat":"Huyết sắc quang trận phóng quang trụ xuyên qua Nguyên Từ Thần Sơn, trói cứng Hàn Lập và khiến kiếm quang cùng pháp tướng ban đầu không thể phá cấm. Khi huyết phù chuyển sang tranh đoạt Huyền Thiên Quả Thật, quả này tự bay lên, biến lớn và phóng kiếm khí phá tan phù văn. Hàn Lập nhân cơ hội thi triển Thánh Ma ngự trị, tiêu hao một nửa pháp lực để đẩy lui huyết quang và giành lại một phần tự do. Hắc động tiếp tục phóng huyết ti kết thành kén quanh Huyền Thiên Quả Thật, nhưng Hàn Lập dùng Kiếm Linh Hóa Hư chém đứt chúng rồi đoạt lại quả. Khi hắn bỏ chạy, trận pháp co rút và phóng huyết sắc thất luyện đuổi theo, bắt cả người lẫn quả. Phi kiếm hóa hư không thể phá dải huyết quang, còn Hàn Lập bị kéo vào hắc động giữa tiếng quỷ khóc sói tru và dao động không gian dữ dội."},{"chuong":1533,"tieuDe":"Linh Kiếm Hiện Thế","tomTat":"Hàn Lập nhận ra mình đã rơi vào hắc động nên dùng Phá Diệt Pháp Mục xuyên thủng huyết sắc thất luyện, sau đó dựa vào Phong Lôi Sí để chống lại lực hút. Vô số huyết ảnh tiếp tục vây công, khiến hắn phải phối hợp Ích Tà Thần Lôi với Hư Hóa Kiếm Quang, nhưng cấm chế vô hình ở rìa hắc động đã chặn kín đường thoát. Khi huyết ảnh hóa thành quang hà và quá trình truyền tống bắt đầu, những thần thông hắn thi triển đều không thể phá vỡ không gian xung quanh. Đúng lúc ấy, Huyền Thiên Quả Thật đâm xuyên bàn tay Hàn Lập, hút khoảng ba phần máu rồi chuyển thành màu đỏ tươi và hiện vô số phù văn. Quả sau đó hóa thành chuôi của một thanh kiếm có năm phù văn quái dị trên mũi, khiến huyết sắc quang trận cùng hắc động rung chuyển rồi biến mất. Giữa dị biến, Hàn Lập theo bản năng cầm kiếm chém ra. Ở một nơi xa xôi, hơn mười bóng người đứng trên huyết sắc tế đàn bên trên hồ máu đầy hài cốt, trong đó một người kinh hãi xác nhận đã cảm ứng được Huyền Thiên Chi Bảo."},{"chuong":1534,"tieuDe":"Đại Nan Đào Thoát","tomTat":"Trên tế đàn, Duyệt đạo hữu xác nhận mình và Giản huynh từng cảm ứng được Huyền Thiên Trảm Linh Kiếm, nhưng bảo vật đã đột nhiên biến mất giữa quá trình triệu hồi. Bất chấp sự phản đối của Diêu đạo hữu về hao tổn linh lực và chân nguyên, hai người chủ trì vẫn đề nghị tái khởi huyết tế, đồng thời cam kết sẽ rời đi nếu lần thứ hai tiếp tục thất bại. Hung đạo hữu chấp thuận điều kiện này và ra lệnh cho các cao tầng Phi Linh Tộc tiếp tục vận hành pháp trận. Ở một nơi khác, Hàn Lập tỉnh lại trong sơn cốc gần biển sau khi thanh kiếm do Huyền Thiên Quả Thực biến thành chém đứt truyền tống và xé rách hư không. Hắn phát hiện mình mất hơn nửa tinh huyết, cạn pháp lực, thần niệm chỉ còn khoảng một phần mười và gần như không thể cử động. Khi vừa khôi phục được chút sức ở ngón tay, Hàn Lập bị một con cự giải khổng lồ phát hiện và vung càng tấn công, nhưng hắn vẫn lạnh lùng đối diện."},{"chuong":1535,"tieuDe":"Xà Nhân","tomTat":"Khi cự giải sắp tiếp cận Hàn Lập, một cây ngân xoa từ ngoài sơn cốc bắn tới xuyên thủng giáp lưng của nó, mở đầu cho sự xuất hiện của đội săn gồm sáu nam và bảy nữ xà nhân. Nhóm dị tộc phối hợp ngân thương, ngân xoa, tơ tằm, găng tay cùng một viên đá biển có thể hóa thành hồng quang và liệt diễm để khống chế rồi giết chết cự giải. Sau đó, họ thành thạo phá vỏ, phân giải xác và thu lấy những phần có thể ăn được. Hàn Lập quan sát thấy xà nhân không có linh khí nhưng sở hữu sức mạnh và thân thủ gần với luyện thể sĩ nhân tộc. Một nữ xà nhân phát hiện hắn nằm bất động và báo cho đại hán cầm đầu, nhưng đôi bên không thể hiểu nhau dù Hàn Lập đã thử nhiều ngôn ngữ. Nhận ra Hàn Lập không thể cử động, đại hán sai bốn nữ xà nhân làm cáng bằng cây và da thú. Sau khi xác định nhóm dị tộc không có ác ý, Hàn Lập ngừng chuẩn bị thủ đoạn phòng thân và đồng ý để họ đưa mình lên cáng."},{"chuong":1536,"tieuDe":"Hỏa Dương Tộc","tomTat":"Sau khi chia cắt cự giải, đội săn xà nhân mang chiến lợi phẩm và khiêng Hàn Lập rời sơn cốc ven biển. Đoàn người dùng thuyền gỗ vượt biển tới một hải đảo rộng vài trăm dặm, nơi có cây cỏ xanh tươi và một ngọn núi giống núi lửa. Khi đoàn thuyền gặp mây đen, mưa lớn, cuồng phong và sóng dữ, quang tráo trên thuyền giúp họ cầm cự cho tới lúc một quang trụ từ đảo phá thủng tầng mây, khiến gió sóng suy yếu. Hàn Lập nhận thấy linh lực của quang trụ hỗn tạp và suy đoán nó được tạo ra bởi pháp trận hoặc pháp khí mượn sức linh thạch. Tại bến tàu, xà nữ Viêm Vũ dùng Phi Linh ngữ giao tiếp với hắn, giới thiệu mình phụ trách cúng tế cho một phân nhánh nhỏ của Hỏa Dương Tộc. Sau khi cân nhắc thực lực của đối phương, Hàn Lập đồng ý tới gặp đại tế ti để hỏi về hải vực. Viêm Vũ thả linh điểu truyền tin rồi dẫn bốn nữ xà nhân hộ tống hắn tới Hỏa Dương Thành ở trung tâm đảo."},{"chuong":1537,"tieuDe":"Đại Tế Ti","tomTat":"Viêm Vũ điều động một cỗ xe do thằn lằn kéo để đưa Hàn Lập đang suy yếu tới thổ thành của Hỏa Dương Tộc. Trên đường vào thành, Hàn Lập quan sát xã hội xà nhân, nhận thấy cư dân phần lớn mang binh khí, nữ nhiều hơn nam và màu sắc thân thể dường như phản ánh địa vị. Tại sân điện, hắn thấy nhiều tế ti áo trắng có linh khí ba động đang vận hành một viên trùy thanh đồng, nhưng người mạnh nhất trong số họ chỉ đạt Trúc Cơ kỳ. Đại tế ti Hỏa Nguyệt có tu vi Nguyên Anh xuất hiện, dùng ngôn ngữ Phi Linh Tộc tiếp đón và mời hắn vào điện. Nàng đề nghị tặng Khí huyết đan, đồng thời cho biết nơi đây là Hỏa Hô quần đảo và vùng lân cận không có tu sĩ nào mạnh hơn mình. Khi Hàn Lập dùng thanh hà đưa thạch giản ngôn ngữ lên trán để đọc, vật này bất ngờ bạo liệt và giải phóng sương mù bao vây hắn."},{"chuong":1538,"tieuDe":"Liệt Dương Thần Đan","tomTat":"Hàn Lập tiếp nhận thông tin từ hải đồ Hỏa Hô quần đảo và xác định với tốc độ của mình, hắn chỉ cần khoảng nửa năm để tới Lôi Minh đại lục. Đại tế tự Hỏa Dương tộc giải thích bộ tộc chủ yếu cư trú trên Hỏa Vân đảo, đồng thời đề nghị cung cấp linh mạch, linh dược và linh thạch để hắn dưỡng thương. Khi Hàn Lập từ chối nhận ân huệ vô cớ, bà cho người hầu lui ra rồi tiết lộ mình đã cưỡng ép hóa hình bằng đan dược và bí thuật bá đạo, phải trả giá bằng việc mất đường tiến cấp và giảm một nửa tuổi thọ. Bà kể rằng hai tộc láng giềng từng hỗ trợ Hỏa Dương Tộc đã bị tiêu diệt, nữ nhân bị ăn sống còn nam nhân mất tích, khiến bộ tộc của bà có thể trở thành mục tiêu kế tiếp. Để đổi lấy sự trợ giúp, bà đề nghị dâng Liệt Dương Thần Đan được luyện từ nội đan Song Đầu Viêm Giao và ôn dưỡng trong địa hỏa suốt mấy ngàn năm. Hàn Lập đồng ý giúp Hỏa Dương Tộc nếu viên đan thật sự chữa được thương thế, nhưng tuyên bố giao ước sẽ bị hủy nếu địch nhân mạnh quá khả năng ứng phó. Sau đó, Đại tế tự dùng pháp khí dạng khăn hóa thành bạch vân, đưa cả Hàn Lập cùng chiếc ghế tới chân một ngọn núi trên Hỏa Vân đảo để chuẩn bị tĩnh dưỡng."},{"chuong":1539,"tieuDe":"Châu Nhi Cùng Ô La Tộc","tomTat":"Đại tế tự Hỏa Dương Tộc đưa Hàn Lập tới một căn nhà gỗ có linh khí nồng đậm để tĩnh dưỡng, còn hắn cố ý tự di chuyển nhằm che giấu mức suy yếu thật sự. Khi chỉ còn một mình, Hàn Lập thừa nhận việc đứng dậy trong chốc lát đã làm cạn sạch thể lực tích tụ, sau đó uống hết nhiều bình đan dược chữa thương và vận công luyện hóa. Trở lại đại điện, đại tế tự bí mật thẩm tra Viêm Vũ cùng đội săn về toàn bộ quá trình phát hiện và đồng hành với Hàn Lập. Bạch Châu nhi bất ngờ trở về sau nhiều năm tu luyện, mang theo Phá Thiên Cung của sư phụ cùng một số bảo vật trấn đảo để giúp bộ tộc vượt qua đại nạn. Nàng phát hiện mẫu thân đã dùng Luyện Tiên Quả cưỡng ép đạt tới giai đoạn hóa hình, phải đánh đổi bằng sự tổn hao nghiêm trọng về tuổi thọ. Đại tế tự sau đó tiết lộ hai bộ tộc láng giềng đã bị tiêu diệt bí ẩn và phỏng đoán dư nghiệt Ô La Tộc, tử địch cổ xưa của Oa Thị Tộc, chính là thủ phạm. Tuy nhiên, bà chưa có chứng cứ trực tiếp và cũng không giải thích được vì sao kẻ địch nếu đã ẩn náu gần đó hàng ngàn năm lại chỉ mới bắt đầu ra tay."},{"chuong":1540,"tieuDe":"Huyền Kiếm Phụ Tí","tomTat":"Bạch Châu nhi và mẫu thân phân tích các cuộc tập kích của Ô La Tộc, từ đó nghi ngờ huyết mạch Ô La Vương Tộc từng được cho là tuyệt diệt đã tái xuất và tu luyện đại thành. Trước nguy cơ Hỏa Dương Tộc trở thành mục tiêu tiếp theo, Đại tế tự quyết định cầu viện các tộc khác, tăng gấp đôi phòng ngự trên đảo và cân nhắc dùng Liệt Dương Thần Đan đổi lấy sự trợ giúp của Hàn Lập. Bạch Châu nhi không muốn giao thần đan cho một ngoại nhân chưa rõ thực lực nên nhận nhiệm vụ thử thần niệm của hắn, với điều kiện không được quá phận. Sau một ngày điều tức, Hàn Lập chỉ khôi phục được chút pháp lực và nhận ra phải mất ba bốn năm mới bù lại tổn thất tinh huyết cùng thần niệm. Hắn triệu hồi Đề Hồn thú và Báo Lân Thú, bố trí chúng hỗ trợ phòng vệ rồi dùng trận kỳ củng cố nhà gỗ. Cuối cùng, Hàn Lập phát hiện Huyền Thiên Quả Thật đã hóa thành ấn ngân vàng trên cánh tay và quyết định bức bảo vật ra sau khi hồi phục vì uy lực của nó đi kèm tổn thương quá lớn."},{"chuong":1541,"tieuDe":"Dùng Hỏa Hóa Đan","tomTat":"Hàn Lập tiếp tục dùng đan dược dưỡng thương trong căn phòng được cấm chế bảo vệ, nhưng không đặt toàn bộ hy vọng hồi phục vào Liệt Dương thần đan. Hai ngày sau, Hỏa đạo hữu đưa Bạch Châu nhi tới và nhìn thấy hai người có hình dạng giống Hàn Lập, trong đó Đề Hồn đang hóa thành chủ nhân để tiếp khách. Bạch Châu nhi bí mật dùng mảnh lá xanh và pháp quyết dò xét, song thần niệm của nàng bị Đề Hồn hút vào như rơi xuống vòng xoáy rồi mới được thả ra. Hỏa đạo hữu trao Liệt Dương thần đan, kể lại nguồn gốc của viên thuốc và giải thích đan phương cùng những điều cần kiêng kị khi sử dụng. Sau khi hai mẹ con rời đi, Đề Hồn hiện lại nguyên hình Hắc Tiểu Hầu và thừa nhận đã cố ý cảnh cáo Bạch Châu nhi. Hàn Lập kiểm tra viên đan, nhận ra bên trong chứa lượng Cực Hỏa chi lực rất lớn nhưng xích diễm của nó không thể làm tổn thương thân thể hắn. Thay vì uống trực tiếp và dùng linh dược hàn thuộc để trung hòa, hắn hóa Phệ Linh Thiên Hỏa thành Hỏa Điểu bạc bao vây viên đan. Trên đường trở về, Hỏa đạo hữu xác nhận con gái chỉ bị kinh hãi chứ không chịu tổn thương thần niệm."},{"chuong":1542,"tieuDe":"Ô Giáp Thú","tomTat":"Sau khi Đại tế tự và Bạch Châu nhi rời căn nhà gỗ, Hàn Lập bế quan mười ngày để luyện hóa Liệt Dương Thần Đan, trong khi hơn mười vạn người Hỏa Dương Tộc co cụm vào thổ thành và mở toàn bộ cấm chế. Nhờ Phệ linh hỏa điểu hút hết hỏa linh lực trong đan, thương tổn máu huyết và thần niệm của hắn hồi phục hơn phân nửa, còn pháp lực đã có thể tự khôi phục hoàn toàn. Hàn Lập giữ lời đến đại điện trợ chiến dù thương thế mới hồi phục khoảng bảy tám phần, khiến Đại tế tự nhẹ nhõm. Nửa ngày sau, chấn động dữ dội vang lên quanh thổ thành, báo hiệu quân địch đã tới. Đại tế tự trấn an các tế tự rồi cùng tám tế tự áo bào trắng kích hoạt pháp trận và xích tinh cầu để quan sát bên ngoài. Hình ảnh truyền về cho thấy một đàn Ô Giáp thú khổng lồ phủ hắc lân giáp, mang nhiều căn bành và bóng người trên lưng, đang lặng lẽ áp sát tường thành. Khi nhận ra những kẻ cưỡi thú chính là người Ô La Tộc từng bị cho là đã tuyệt diệt, các tế tự Hỏa Dương Tộc đồng loạt im lặng và lộ vẻ khó coi."},{"chuong":1543,"tieuDe":"Địch Hiện","tomTat":"Qua hình ảnh do pháp trận Thủy Tinh cầu truyền về, Hàn Lập và người Oa Thị nhìn thấy đội quân nữ nhân Ô La Tộc mang nửa thân dưới hình rết đang tập kết ngoài thành. Đại tế tự Hỏa Dương tộc âm thầm dùng bí thuật chi phối tinh thần để ổn định quân tâm, sau đó chia các tế tự thành bốn đội đến bốn cửa thành đốc chiến. Khi nàng cảnh báo cường giả Ô La thường ẩn nấp ám sát người mạnh nhất, Hàn Lập lập tức phát hiện Ngân đồng Ô La nhân đang giấu mình cạnh cột gỗ và dùng bàn tay lớn trong suốt ép nàng hiện hình. Hắn tiếp tục dùng tiểu kiếm truy kích Kim đồng Ô La nhân trong góc tối, buộc đối phương hóa thành nhiều hắc ti né tránh rồi lộ diện. Đại tế tự nhận ra hai kẻ xâm nhập thuộc Ô La Vương Tộc nhờ đặc điểm kim ngân song đồng, đồng thời quy cái chết của Đại Tế Ti hai tộc khác cho họ. Do linh quang quỷ dị khiến thần niệm không thể nhìn thấu tu vi đối phương, Hàn Lập chưa vội ra tay. Bạch Châu nhi chủ động dùng Hoàng đại cung khai chiến, kéo Đại tế tự cùng bốn tế tự áo bào trắng hợp kích bằng tên vàng, hỏa giao và ngân mang. Hai nữ nhân Ô La đồng thời tạo ra hai luồng hắc quang vựng trước người để ứng phó."},{"chuong":1544,"tieuDe":"Linh Tuyền Tà Quang","tomTat":"Hai người Ô La vương tộc hợp nhất các quầng hắc quang, hút sạch tên bắn, đao mang và hỏa giao trong đợt vây công của Hỏa Dương Tộc. Họ phóng kim ngân tế ti truy sát Đại tế tự cùng Bạch Châu nhi; công kích từ Cốt tiễn của Châu nhi bị phản ngược, khiến nàng suýt chết và phải nhờ Hàn Lập liên tiếp cứu thoát. Hàn Lập lần lượt dùng Nguyên từ thần quang và Ngũ sắc hàn diễm để ngăn tà quang nhưng chỉ có thể cản trở nó trong thời gian ngắn. Khi kim ngân tế ti xuyên không đánh lén, hắn dùng Phệ linh thiên hỏa thiêu hủy một đạo rồi hóa thành hỏa điểu nuốt luôn đạo còn lại. Đại tế tự tiết lộ Linh Tuyền tà quang có thể phản ngược công kích, khắc chế nhiều thần thông và cấm chế, đồng thời mang độc tính lan khắp cơ thể, nhưng Hàn Lập tin rằng thiên hỏa đã tiêu hủy cả chất độc. Nhận ra hai đối thủ chưa luyện tà quang đến mức hoàn thiện, Hàn Lập chủ động áp sát, hiện kim sắc lân giáp cùng pháp tướng ba đầu sáu tay. Hai người Ô La vương tộc lập tức biến vùng hắc quang thành một thanh cự nhận khổng lồ và chém thẳng xuống hắn."},{"chuong":1545,"tieuDe":"Trảm Sát","tomTat":"Hàn Lập dùng pháp tướng màu vàng, phi kiếm và Nguyên Từ Thần Sơn lần lượt hóa giải đòn liên thủ của hai Ô La vương tộc. Khi ngân đồng Ô La nhân dùng tinh huyết tăng cường hư ảnh rết mặt người, hắn gia tăng sức nặng của thần sơn, nghiền tan hư ảnh và khiến đối thủ chịu phản phệ. Hơn mười thanh phi kiếm tiếp đó thi triển kiếm linh hóa hư, xuyên qua hai vầng sáng đen và phá hủy thân thể của cả hai kẻ địch. Hàn Lập phát hiện nguyên thần của họ hóa thành hai con rết nhỏ đang tìm cách đào thoát bằng Linh Tuyền Tà Quang, liền dùng Phệ Linh Thiên Hỏa khắc chế và thiêu chúng thành khói xanh. Sau khi hoàn tất việc trảm sát, hắn lấy hai chiếc khăn màu xám từ tàn thi đối thủ. Trước lời cảm tạ của phía Hỏa Dương Tộc, Hàn Lập nhận lời tiếp tục giúp họ xua đuổi số Ô La nhân còn lại bên ngoài."},{"chuong":1546,"tieuDe":"Hắc Sa","tomTat":"Hàn Lập triệu Báo Lân thú và ra lệnh tiêu diệt toàn bộ Ô La nhân còn lại, khiến đại tế tự cùng các tế tự Hỏa Dương tộc kinh hãi trước khí tức và độn tốc của linh thú. Sau khi hắn rời đại điện, cao tầng Hỏa Dương tộc nhận ra việc đại tế tự từng tặng Liệt Dương thần đan đã giúp cả tộc tránh khỏi họa diệt vong, rồi cùng Bạch Châu nhi ra ngoài truy quét tàn quân. Hàn Lập trở về nhà gỗ, coi như đã trả xong ân tình cứu giúp và dự định dành nửa năm chữa khỏi thương thế. Hắn nhận chủ Hắc Sa, phát hiện pháp khí này có thể ẩn hình, ngăn thần niệm dò xét, che giấu tu vi và dung nhập vào trường bào, đồng thời tiện dụng hơn Hóa thanh phù. Trong những tháng bế quan tiếp theo, hắn hiện Kim sắc pháp tướng tu luyện và để Đề Hồn thu linh dược cùng linh thạch do đại tế tự mang tới. Cuối cùng, Hàn Lập phát hiện Phệ Linh thiên hỏa đã hoàn tất luyện hóa Linh Tuyền tà quang, tạo thành kim ngân tế ti có thể xuyên thẳng qua cấm chế và vách tường."},{"chuong":1547,"tieuDe":"Không Vân Tinh","tomTat":"Hàn Lập thử kim ngân tế ti do ngân sắc hỏa điểu phun ra và xác nhận loại tế ti này có kịch độc đủ khiến một chiếc ghế gỗ hóa thành khói. Thanh Tiểu, sư phụ của Bạch Châu nhi và là nữ tu Hóa Thần trung kỳ, đến bái kiến người đã cứu Hỏa Dương Tộc khỏi đại địch. Hàn Lập nhìn thấu công pháp cùng các bảo vật phong thuộc tính của nàng, sau đó đôi bên trao đổi kinh nghiệm tu luyện và Thanh Tiểu được giải đáp nhiều nghi nan. Trong cuộc trò chuyện, Hàn Lập thừa nhận mình đến từ một đại lục khác và hỏi về con đường trở lại đại lục. Thanh Tiểu cho biết truyền tống trận nối Hỏa Hô quần đảo với Lôi Minh đại lục đã bị cự thú phá hủy từ mấy ngàn năm trước, khiến vùng biển gần như trở thành tuyệt địa. Trận vẫn có thể sửa chữa nếu đủ vật liệu, nhưng Không Vân Tinh dùng làm trung tâm pháp trận chỉ có tại một số khoáng mạch ở Lôi Minh đại lục. Khi Hàn Lập trở nên thất vọng vì trở ngại này, Thanh Tiểu bất ngờ hé lộ một tin khiến hắn ngẩn ngơ rồi vui mừng."},{"chuong":1548,"tieuDe":"Lam Hồ Đảo","tomTat":"Thanh Tiểu cho Hàn Lập biết một Hải Thú biến dị đã nuốt hơn phân nửa Truyền tống trận cùng Không Vân tinh, sau đó dựa vào năng lực thay đổi kích thước và thủy độn để nhiều lần thoát khỏi vây giết. Vì Không Vân tinh mang thuộc tính không gian nên vẫn có thể còn nguyên vẹn trong cơ thể con thú và được dùng để chữa lại trận pháp dẫn tới Lôi Minh Đại Lục. Hàn Lập nhận lời tham gia cuộc săn, lấy Ngân Sa lệnh làm tín vật và được hẹn tập hợp tại phía nam Lam Hồ đảo sau bốn tháng. Sau hơn hai tháng lưu lại Hỏa Vân đảo, hắn rời đi về phương nam, đồng thời suy tính đường trở lại Nhân tộc và khả năng Nam Cung Uyển đã phi thăng Linh giới. Hơn một tháng sau, hắn tiến vào vùng biển có gió tuyết lạnh buốt phía trên nhưng nước nóng như sôi phía dưới, rồi xuyên qua lớp hải vụ để tìm thấy Lam Hồ đảo. Ngay khi Hàn Lập chuẩn bị tiến vào Băng Đảo, một tiếng gầm trầm thấp từ sâu trong đảo khiến sắc mặt hắn đại biến và khí huyết trong người cuồng động."},{"chuong":1549,"tieuDe":"Quái Nga","tomTat":"Tiếng rống bí ẩn trên Băng Đảo kích động bốn loại chân linh chi huyết trong cơ thể Hàn Lập, buộc hắn dùng Phạm Thánh Chân Ma Công trấn áp rồi tiến sâu vào đảo điều tra. Trên đường, hắn chứng kiến một nhóm tu sĩ Nguyên Anh kỳ bị tiếng rống làm nổ cả thân thể lẫn nguyên thần. Thanh Tiểu và một thiếu phụ váy đen chạy tới trong lúc bị bóng xám khổng lồ truy sát, còn các đòn phản kích của họ đều bị sóng dao động vô hình đánh tan. Nhờ linh mục thần thông, Hàn Lập nhận ra kẻ truy đuổi là Quái Nga hai đầu có yêu lực khoảng Luyện Hư hậu kỳ. Hắn dùng bảy mươi hai khẩu phi kiếm hóa thành thanh ti băm nát quái vật để giải cứu hai nữ tu, nhưng tàn thi của nó nhanh chóng tụ lại và khôi phục nguyên trạng. Quái Nga sau đó vỗ cánh phát tán sóng dao động, ép các thanh ti hiện lại thành phi kiếm rồi khiến chúng hóa thành những đoàn thanh mang bạo liệt."},{"chuong":1550,"tieuDe":"Chiến Đấu Kịch Liệt","tomTat":"Hàn Lập vận dụng Kiếm linh hóa hư để phục hồi Thanh Trúc Phong Vân kiếm sau khi bị sóng dao động của Quái Nga nghiền nát, nhờ đó cứu Thanh Tiểu và thiếu phụ mặc váy đen thoát khỏi hiểm cảnh. Khi Quái Nga phục sinh rồi dùng tiếng rống khiến máu huyết của hai nữ tu sôi trào, hắn giúp họ ổn định thương thế và bảo họ rời khỏi Băng Đảo, còn bản thân ở lại quyết chiến. Hàn Lập lần lượt thi triển pháp tướng ba đầu sáu tay, Nguyên từ thần quang và Nguyên từ thần sơn, nhưng Quái Nga biến thành hình thái đầu cự mãng phủ vảy xanh, dùng cự lực chống đỡ rồi ném ngọn núi lên không. Quái vật tiếp tục dùng tinh thuẫn che mắt và ẩn tích, song bị ngũ sắc quang diễm ép hiện hình, bị thanh ti vây giữ và bị Linh tuyền tà quang xuyên thủng ngực. Dù vậy, nó vẫn phá vỡ vòng vây, giam Phệ linh hỏa điểu trong chất lỏng đen rồi xuyên không áp sát, nhưng Hàn Lập kịp dùng Phá Diệt Pháp Mục đánh bật nó khỏi trạng thái ẩn thân. Cuối cùng, Hàn Lập dung hợp kim sắc pháp tướng, hóa sáu tay cầm binh khí đối đầu trực diện; sau cú va chạm, hắn nhận ra Quái Nga nhỉnh hơn về sức lực nhưng thân thể kém cứng cỏi, đồng thời tinh thuẫn của nó dường như không thể ngăn binh khí thực thể."},{"chuong":1551,"tieuDe":"Kỳ Độc","tomTat":"Quái Nga chữa lành song chưởng, biến đôi cánh thành hàng trăm phi nhận rồi tiếp tục truy sát Hàn Lập. Hàn Lập chủ động kéo giãn khoảng cách và chờ Linh tuyền tà quang phát tác, khiến đối thủ choáng váng, tê liệt và tím tái dù đã dùng viên châu màu xanh áp chế độc tố. Hắn hóa thành Côn Bằng phá tan thế phi nhận, sau đó dùng Thanh minh linh mục và Ích Tà Thần Lôi tìm ra Quái Nga khi nó thi triển kim thiền thoát xác. Bị ép đến đường cùng, Quái Nga mọc thêm đầu sư tử và tạo hai trảo ảnh hấp thu thiên địa nguyên khí để phản công. Hàn Lập vận Kinh trập quyết hóa thành ngũ sắc khổng tước, dùng ngũ sắc linh quang triệt tiêu hoàn toàn đòn đánh. Kỳ độc cuối cùng lan lên cả hai đầu khiến Quái Nga mất thần quang và rơi xuống băng địa, còn Hàn Lập vẫn giữ khoảng cách rồi gọi Phệ linh thiên hỏa trở lại."},{"chuong":1552,"tieuDe":"Biển Sâu Cổ Đăng","tomTat":"Hàn Lập dùng thanh ti từ Hư Thiên tửu đỉnh vây giữ hai tinh hồn Quái nga rồi điều khiển Phệ linh thiên hỏa tiêu diệt hoàn toàn chúng, đồng thời từ bỏ việc sưu hồn vì lo gặp phản phệ. Cùng lúc đó, tại một cung điện ngọc trắng dưới đáy biển sâu, một đăng diễm trên cổ đăng màu xanh vụt tắt khiến Khô lâu đang bất động tỉnh lại. Khô lâu thả quái thú đầu trâu từ Hắc ấn Chân Long, truyền cho nó một đoàn lục diễm và phái nó rời mật thất bằng lôi độn, sau đó khôi phục đăng diễm trong trạng thái nhỏ yếu. Nó tiếp tục tạo ngân kính, duyệt qua hình ảnh nhiều cường giả và xác định được Hàn Lập trước khi phá hủy chiếc kính. Trên băng đảo, Hàn Lập thu toàn bộ thi thể Quái nga vào vòng trữ vật rồi tiến sâu vào đảo, nơi hắn phát hiện một khu kiến trúc hàn băng đã bị tàn phá. Một nữ tử áo bào trắng dẫn hơn mười nam nữ trẻ tuổi ra xin tha mạng và khai rằng họ là người hầu của Ngân Sa cư sĩ. Thanh Tiểu cùng thiếu phụ váy đen sau đó tìm đến, và Hàn Lập lấy thi thể Quái nga ra để chứng minh mình đã giết được quái vật."},{"chuong":1553,"tieuDe":"Hàn Tinh Tộc","tomTat":"Sau khi Quái nga bị giết, Thanh Tiểu và thiếu phụ váy đen cảm tạ Hàn Lập rồi kể lại việc quái vật từ sương mù ngoài đảo xông ra, sát hại nhiều tu sĩ và ép Ngân Sa cư sĩ phải hy sinh để cầm chân nó. Hàn Lập được giới thiệu về Hàn Tinh tộc, một tộc người không thể tu luyện nhưng có thiên phú hàn khí, giữ được dung mạo trẻ trung và đặc biệt giỏi chăm sóc động phủ, bồi dục linh dược. Nhóm người Hàn Tinh từng phục vụ Ngân Sa cư sĩ xin tìm nơi nương tựa mới; Hàn Lập và Thanh Tiểu đều từ chối nên thiếu phụ váy đen tiếp nhận họ. Khi bàn về cuộc săn hải thú, Hàn Lập biết Ngân Quang Sa từng là phương tiện truy tung chủ yếu nhưng đã chết cùng Ngân Sa cư sĩ. Không muốn huy động lực lượng đông đảo mà kém hiệu quả, hắn quyết định tự mình tìm mục tiêu để đoạt Không Vân tinh, đồng thời yêu cầu nhị nữ giúp chữa Truyền tống pháp trận nếu thành công. Sau khi hỏi rõ vị trí hải thú từng xuất hiện và cách liên lạc, Hàn Lập hóa thành thanh hồng rời đảo. Ở lại phía sau, thiếu phụ váy đen nghi ngờ thực lực thật của hắn và khuyên Thanh Tiểu kết thành đạo lữ song tu với hắn; Thanh Tiểu phủ nhận nhưng cuối cùng vẫn lặng lẽ nhìn theo hướng hắn biến mất."},{"chuong":1554,"tieuDe":"Nhị Thú","tomTat":"Sau nhiều năm dò tìm trong vùng biển mục tiêu, Hàn Lập vẫn chưa phát hiện cự kình Hải thú mà Thanh Tiểu từng nhắc tới. Trong thời gian đó, hắn để Nguyên Anh thứ hai bồi luyện Tinh lân tiểu thuẫn làm từ vảy Quái nga, đồng thời luyện đôi cánh của nó thành ba trăm sáu mươi khẩu phi đao và lo ngại tiếng rống của Quái nga đã để lộ nhược điểm tiềm ẩn trong Kinh Trập thập nhị quyết. Hắn còn dùng da Hải thú tìm được dưới đáy biển để luyện Cửu cung thiên kiền phù, Giáp Nguyên phù và Thái nhất hóa thanh phù, đồng thời có được linh cảm bước đầu về Thiên Qua phù. Cuối cùng, một tiếng kêu lạ dẫn Hàn Lập tới nơi cự kình Hải thú đang giằng co với một con Huyết diễm tôm giữa sóng gió dữ dội. Hàn Lập hiện thân giữa hai cự thú và quyết định thu cả hai, tung phi kiếm về phía cự kình, dùng Nguyên Từ Thần Sơn trấn áp cự tôm rồi vận chuyển Phạm Thánh Chân Ma Công gọi pháp tướng ba đầu sáu tay. Ba cột sáng vàng phá tan lam quang hộ thể và đánh thủng thân thể cự kình, khiến nó trọng thương và máu phun không ngừng."},{"chuong":1555,"tieuDe":"Chữa Trị Pháp Trận","tomTat":"Cự kình hải thú hấp thu linh quang trong nước để chữa thương, còn cự tôm dựa vào huyết sắc quang diễm và lớp vỏ cứng chống đỡ công kích. Hàn Lập dùng Nguyên Từ Thần Sơn nghiền vỡ nhiều bộ phận của cự tôm và trấn nó xuống đá ngầm. Khi cự kình hải thú phóng thủy thương rồi tìm cách thủy độn, hắn dùng Nguyên Từ Thần Quang hóa giải công kích và triển khai Xuân Lê kiếm trận để chặn đường rút. Hải thú dùng quang hồ, vật hình vuông màu hỏa hồng và thân thể khổng lồ phá vây nhưng đều thất bại, cuối cùng mắc kẹt trong huyễn cảnh và bị thanh mãng công kích. Nửa ngày sau, Hàn Lập rời vùng biển, còn đá ngầm đã chìm xuống đáy. Hai năm sau, truyền tống pháp trận tại Hỏa Hô quần đảo được chữa trị và đã đưa người trở về Lôi Minh đại lục, khiến nhiều tồn tại thượng tộc kéo tới. Hàn Lập hoàn thành truyền tống, tỉnh lại trong một đại sảnh có cấm chế rồi mở cửa đá và bất ngờ nghe thấy tiếng ồn ào bên ngoài."},{"chuong":1556,"tieuDe":"Khốn Cảnh","tomTat":"Hàn Lập tới Lục Quang Thành và phát hiện hàng vạn tu luyện giả thuộc nhiều dị tộc đang lo âu tụ tập trên quảng trường, trong đó có ba tồn tại Luyện Hư. Dù đã che giấu tu vi, hắn vẫn bị Nguyên huynh dùng Linh quang bàn phối hợp với cấm chế xác định vị trí. Khi chủ động tới gặp nhóm tu sĩ cao giai, Hàn Lập biết Giác Xi Tộc đang thâu tóm Thiên Vân mười ba tộc và các tuyến truyền tống nối với thành đã mất hiệu lực. Hắn giải thích mình tới từ Tử Hỏa hô quần đảo bằng một pháp trận vừa được sửa bằng Không Vân Tinh, nhưng đường truyền chỉ đưa được một người sau mỗi bảy ngày và có thể bị hủy nếu cưỡng ép vận hành sớm. Nguyên huynh cùng dị tộc nhân da màu lục nhạt theo hắn kiểm tra, xác nhận dấu vết dao động không gian còn lưu lại nhưng đầu kết nối bên kia đã đóng. Sau đó Hàn Lập biết phần lớn người trong thành là dân chạy nạn, quân tiên phong Giác Xi Tộc đã áp sát để chờ đại quân và đang ngăn cản kế hoạch bỏ thành. Nhận ra những tu luyện giả cao giai như mình khó được đối phương buông tha, Hàn Lập hiểu rằng bản thân vừa rơi vào một khốn cảnh nguy hiểm."},{"chuong":1557,"tieuDe":"Chiến Thuyền","tomTat":"Lục Quang Thành đột ngột rung chuyển khi vô số quang cầu từ trên cao liên tục oanh kích đại trận phòng hộ. Hàn Lập phá pháp trận tại quảng trường rồi dùng linh mục thần thông nhìn rõ một đại chiến thuyền Giác Xi Tộc khổng lồ đang lơ lửng trên thành. Nguyên huynh nhận định Giác Xi Tộc đã phát động chiến tranh nhằm diệt Thiên Vân mười ba tộc, sau đó tạo hư ảnh khổng lồ để trấn tĩnh dân chúng và ra lệnh tập trung tại cửa thành. Trong khi đoàn người chuẩn bị công khai tháo chạy, nhóm Hàn Lập bí mật tách ra, khiến hắn nhận ra những người chạy nạn còn bị dùng để thu hút sự chú ý của quân địch. Hàn Lập vì thế tăng thêm cảnh giác với ba dị tộc nhân đồng hành. Cả nhóm tới một lầu các tại trạm canh gác, nơi Nguyên huynh kích hoạt khôi lỗi thần tượng bốn mắt bốn tay và mở khoang bụng chứa Truyền Tống pháp trận loại nhỏ. Nguyên huynh bước vào pháp trận trước, chuẩn bị dẫn mọi người rời khỏi thành đang bị vây."},{"chuong":1558,"tieuDe":"Truy Binh","tomTat":"Gã dị tộc họ Nguyên kích hoạt Truyền Tống Trận giấu trong thần tượng khôi lỗi, đưa Hàn Lập cùng ba người đồng hành tới một động quật nối với mật đạo bí mật. Khi Lục Quang Thành rung chuyển vì công kích, gã đầu to dùng pháp bàn mở cấm chế tại bốn cửa thành cho cư dân tháo chạy, đồng thời khởi động pháp thuật tự bạo có thể biến toàn thành thành tro tàn. Phía Giác Xi Tộc lập tức tung hơn nghìn song đầu ưng, hơn trăm độc mộc chở giáp sĩ và nhiều giao long hai cánh từ Ngân đảo để truy sát những người đào thoát. Lực lượng truy binh áp đảo các tu luyện giả cấp thấp, khiến hàng trăm thi thể nhanh chóng phủ kín mặt đất dù phe tháo chạy có phản kích. Nhóm Hàn Lập đi hết mật đạo, phá vách đá và xuất hiện tại một sơn cốc nằm lệch khỏi bốn hướng cửa thành nên tạm thời tránh được truy binh. Gã dị tộc da xanh đề nghị mọi người chia nhau tìm đường sống, nhưng ngay trước lúc tách ra, gã đầu to bất ngờ xin ba người còn lại hỗ trợ một việc chưa được tiết lộ."},{"chuong":1559,"tieuDe":"Vật Trong Hộp","tomTat":"Gã đầu to họ Nguyên giao cho Hàn Lập và hai dị tộc nhân mỗi người một hộp ngọc phong cấm, yêu cầu mang chúng tới Vạn Cổ Tộc và phải hủy nếu có nguy cơ rơi vào tay Giác Xi Tộc. Hắn không tiết lộ vật bên trong nhưng cho biết mỗi hộp có thể đổi lấy khôi lỗi cấp thông linh hoặc bảo vật đồng cấp, thậm chí có nhiều khả năng đổi được Vạn Diệu đan. Hàn Lập thử dùng thần niệm dò xét song bị cấm chế đẩy lui, rồi chất vấn nguy cơ các trưởng lão nhận vật mà không trao thưởng. Họ Nguyên cho phép giao hộp cho thế lực khác thuộc Thiên Vân mười ba tộc, đồng thời giải thích rằng việc Giác Xi Tộc bất ngờ vây công Lục Quang Thành khiến hắn nghi tin tức về bí vật đã bị rò rỉ. Cả ba người nhận nhiệm vụ, trong đó Hàn Lập cất hộp vào túi trữ vật nhưng vẫn để ngỏ quyết định có đem nó đi đổi hay không. Họ Nguyên dùng pháp khí hình con quay độn thổ rời đi, còn dị tộc nhân Mặc Lục tộc thi triển bí thuật ẩn nặc rồi tiến vào rừng. Khi chỉ còn hai người, Hoằng Diệt bất ngờ yêu cầu Hàn Lập giao hộp ngọc cho mình, khiến tình thế có nguy cơ chuyển thành xung đột."},{"chuong":1560,"tieuDe":"Ảo Thuật","tomTat":"Hàn Lập từ chối dùng hộp ngọc trao đổi với Hoằng Diệt dù đối phương đưa Kim Huyết hoàn ra dụ dỗ. Sau khi âm thầm bố trí khôi lỗi và thủ đoạn đánh lạc hướng, hắn vạch trần việc Hoằng Diệt để lại dấu vết linh lực nhằm dẫn truy binh Giác Xi tộc tới. Hoằng Diệt lập tức phóng tín hiệu liên lạc và thi triển phân hồn thuật, nhưng tín hiệu bị Hàn Lập bắt gọn. Một phân hồn mắc bẫy viên châu xanh phát nổ, còn phân hồn kia xuyên qua thân giả của Hàn Lập rồi bị kim giáp khôi lỗi phục kích chém đôi, khiến bản thể Hoằng Diệt thổ huyết và tổn hại nguyên khí. Hoằng Diệt dùng tiểu thanh chung hỗ trợ bỏ chạy lên trời, song bị những đóa thanh liên khổng lồ của Hàn Lập phong tỏa. Hắn dùng ngân sắc đoản đao cùng kim sắc lệnh bài phá được đóa sen đầu tiên, nhưng một đóa cự liên khác lập tức hiện ra chắn đường."},{"chuong":1561,"tieuDe":"Đại Địch","tomTat":"Hàn Lập vận chuyển Xuân Lê Kiếm Trận, khiến Hỏa Nguyệt liên tiếp sa vào những huyễn cảnh thảo nguyên và rừng sâu gần như chân thực. Trong lúc đối phương mải phá các đại thụ công kích, Hàn Lập giấu Nguyên Từ Thần Sơn giữa cảnh giả rồi bất ngờ đè xuống, phá tan tấm ván gỗ phòng ngự và nghiền nát thân thể Hỏa Nguyệt. Nguyên thần Hỏa Nguyệt trốn trong một viên châu định độn xuống đất nhưng bị hôi quang giam giữ. Hàn Lập dò hỏi quan hệ giữa hắn với Giác Xi Tộc cùng tin tức về ngọc hạp, song Hỏa Nguyệt viện dẫn cấm chế do tồn tại cấp cao trong Thánh Tộc bố trí để từ chối khai báo. Không muốn mạo hiểm sưu hồn hoặc để đối phương mang dấu vết truy tung rời đi, Hàn Lập dùng kim sắc điện hồ phá viên châu và tiêu diệt nguyên thần. Cùng lúc đó, tại ngân sắc đại điện phía trên Lục Quang Thành, Đồ huynh phát hiện cấm chế trong thần niệm Hoằng Ngân biến mất và tinh thạch trong mộc bài đã vỡ. Ông cùng một trung niên nhân ngân bào nghi có cường giả Thánh Tộc cấp cao bí mật xuất hiện, vì vậy quyết định đích thân đi điều tra và can thiệp vào cuộc tranh đoạt vật chưa rõ."},{"chuong":1562,"tieuDe":"Thiên Huyền La Bàn","tomTat":"Lão giả họ Đồ và trung niên họ Nanh bàn về thực lực của mình, thừa nhận họ chỉ đạt mức tương đương Thánh Tộc Nhất Giai nhờ mười trưởng lão dùng bí thuật quán thể. Qua cuộc nói chuyện, thân phận Hoằng Diệt được hé lộ: hắn mang hai dòng huyết mạch, từng được cài vào Thiên Vân chư tộc và vốn sẽ được Viêm Hệ Giác Xi Tộc tẩy tủy sau khi hoàn thành nhiệm vụ. Cái chết của hắn khiến Giác Xi Tộc mất đầu mối xác định người đang giữ những vật phẩm bí mật, nên quân truy kích chuyển sang rà soát các tu luyện giả cấp cao quanh Lục Quang Thành. Trong lúc khoảng mười tám người đào thoát bị giết hoặc bắt, Hàn Lập thu ngọc hạp và Kim Huyết Hoàn từ Hoằng Diệt, thiêu hủy thi thể rồi thu lại Xuân Lê Kiếm Trận. Hắn dùng Hóa Thanh Phù bay qua ngay phía trên song đầu ưng và các giáp sĩ mà không bị phát hiện. Trên ngân sắc cự đảo, sáu người Giác Xi Tộc dùng Thiên Huyền La Bàn phát hiện bốn mục tiêu cường đại, sau đó chia bốn thuộc hạ thành hai nhóm mang Vũ Giao đi truy tìm. Cuối cùng, lão giả họ Đồ tiếp tục kích hoạt la bàn và khóa đúng phương hướng Hàn Lập đang đào thoát."},{"chuong":1563,"tieuDe":"Hóa Huyết","tomTat":"Đồ huynh phát hiện Thiên Huyền La Bàn có cảm ứng lúc mạnh lúc yếu ở một phương hướng, nên cùng trung niên nhân Giác Xi Tộc phái ngân sắc vũ giao đi trinh sát rồi chia nhau tìm kiếm. Cách Lục Quang Thành hơn ngàn dặm, một tu sĩ Luyện Hư sơ kỳ của Tâm Mị Tộc đang cưỡi bích hổ chạy trốn sau khi che giấu tu vi và trà trộn vào đám tộc nhân thấp giai. Trung niên nhân Giác Xi Tộc bất ngờ tập kích bằng kim sắc kiếm quang, phá hắc sắc tiểu thuẫn và giao chiến với các thủ đoạn phòng ngự của đối phương. Khi tu sĩ Tâm Mị Tộc tập trung chống đỡ kẻ địch phía trước, một nhân ảnh nửa trong suốt từ phía sau hóa thành lục quang xuyên qua tam sắc quang tráo rồi nhập vào cơ thể hắn. Hóa Huyết Ly Hồn đại pháp nhanh chóng tiêu diệt toàn bộ huyết nhục lẫn nguyên thần của nạn nhân, chỉ để lại một lớp da mà nhân ảnh dùng để hóa thành hình dạng giống hệt người vừa chết. Kẻ bí ẩn lục soát trữ vật thủ trạc nhưng không tìm được món cần thiết, đồng thời tiết lộ rằng vì chưa luyện thành Hấp Tinh Huyết Luyện Hóa nên chưa thể tiếp tục sử dụng đại pháp. Cuối cùng, hắn bỏ lớp da, trở lại hình thái nửa trong suốt và nhập vào trung niên nhân Giác Xi Tộc, khiến ánh mắt vốn đờ đẫn của người này trở nên sắc bén."},{"chuong":1564,"tieuDe":"Truy Đuổi","tomTat":"Lục Dư Nhân của Mặc Lục tộc mang theo ngọc hạp của Đại Đầu Nhân và bị một tử ảnh phục kích trên đường rời khu vực Lục Quang Thành. Tại nhiều hướng khác nhau, lực lượng Giác Xi tộc truy tung Đại Đầu Nhân và các dị tộc Luyện Hư đang rời thành. Hàn Lập đang ẩn thân thì Hóa Thanh Phù đột ngột mất hiệu lực, buộc hắn phải giao chiến với hai vũ giao Hóa Thần kỳ. Hắn dùng tiếng hừ công kích thần thức, kiếm quang, Ngũ sắc quang diễm và Kim sắc điện hồ để giết cả hai trong thời gian rất ngắn. Cái chết của vũ giao khiến lão giả Giác Xi tộc cảm ứng được vị trí, thu ngọc hạp cùng chiến lợi phẩm rồi đích thân truy đuổi Hàn Lập. Hàn Lập nhận ra đối phương là tu sĩ Hợp Thể sơ kỳ có độn tốc vượt xa mình, nhưng vẫn tin rằng bản thân có thể thoát thân nếu không thể đánh thắng."},{"chuong":1565,"tieuDe":"Lực Áp Hợp Thể","tomTat":"Hàn Lập hóa thành thanh ti bỏ chạy, dựa vào độn tốc để giữ khoảng cách với lão giả họ Đồ, một tu sĩ Hợp Thể sơ kỳ. Lão giả dùng tử sắc phù triện che giấu thân hình rồi chuyển xuống lòng đất bằng thuật ẩn nặc và thổ độn, nhưng Hàn Lập phát hiện được hành tung của hắn nhờ Minh Thanh Linh Mục. Khi đối phương áp sát, Hàn Lập chủ động lao vào khu rừng giữa hai ngọn núi, dùng tiểu kiếm dọn sạch một khoảng đất và giấu kiếm quang quanh chiến trường. Hắn tiếp tục dựng kim ngân sắc trường bào, hắc sắc sát giáp và tiểu thuẫn trong suốt để tạo ba tầng phòng hộ. Lão giả họ Đồ tập kích từ lòng đất nhưng bị Hàn Lập né tránh, sau đó tung quyền ảnh nóng rực. Hàn Lập thả Nguyên Từ Thần Sơn áp xuống, khiến quyền ảnh tan rã và buộc lão giả phải dùng đôi tay cùng toàn thân thần lực nâng đỡ ngọn núi."},{"chuong":1566,"tieuDe":"Hỏa Mộc Tương Khắc","tomTat":"Hàn Lập dùng Nguyên từ thần sơn phóng lớn để trấn áp lão giả họ Đồ, sau đó đóng băng chiến trường và triển khai Xuân Lê kiếm trận. Lão giả họ Đồ thi triển hỏa công, nung chảy mặt đất thành hồ dung nham để thoát thân và tìm cách kéo thần sơn xuống hồ, nhưng thất bại trước sức nặng của bảo vật. Hàn Lập chém nát bàn tay dung nham rồi đưa thần sơn trở lại quang mạc của kiếm trận. Xuân Lê kiếm trận liên tiếp phóng phong nhận, huyễn hóa cự mộc và tạo ra cảnh rừng cây, nhưng hỏa lực của lão giả thiêu hủy các công kích mộc thuộc tính. Khi nhận ra kiếm trận pha lẫn ảo thuật, lão giả dùng phù toản trợ phong và hư ảnh mặt người lân phiến đỏ để điều động thiên địa nguyên khí, khiến kiếm quang dần trì trệ. Cuối chương, hỏa trụ thiêu sạch cây cối huyễn hóa, làm cảnh sắc thật bắt đầu hiện lại."},{"chuong":1567,"tieuDe":"Hỗn Thiên Địa Cùng Hồ Lô","tomTat":"Hàn Lập nhận ra lão giả họ Đồ đang dựa vào chênh lệch cảnh giới để điều động thiên địa nguyên khí ép Xuân Lê Kiếm Trận. Hắn vận chuyển biến hóa do Thanh Nguyên Tử lưu lại, khiến kiếm trận hấp thu ngược toàn bộ nguyên khí và trở nên vững chắc hơn. Lão giả họ Đồ phát hiện tình hình, biến thành hình thái yêu ma rồi dùng kim sắc tiểu phiên và túi màu lam phối hợp thành tam sắc phong hỏa lực để phá trận. Hàn Lập nghi chiếc túi kia là Hỗn Thiên Đại, nhưng chưa thể xác định đó là chân phẩm hay phỏng chế phẩm. Trước nguy cơ kiếm trận bị hủy, hắn quyết định thi triển sát chiêu hồ lô xanh và chuẩn bị các thủ đoạn dự phòng. Hồ lô xanh thu nhận kiếm ảnh cùng ngũ sắc quang hà, phóng kiếm quang chém đôi tam sắc đại thủ rồi chuyển hướng công kích lão giả họ Đồ."},{"chuong":1568,"tieuDe":"Nguyên Khí Chi Kiếm","tomTat":"Lão giả họ Đồ dùng phi kiếm trong suốt chống lại ngũ sắc quang kiếm nhưng pháp bảo bị xuyên thủng và bản thân chịu phản phệ. Hắn thu hồi phong hỏa lực, dựng tam sắc chiến giáp, cầm cự kiếm cổ xưa rồi gọi kim sắc tiểu phiên và chiếc túi về hộ thân. Hàn Lập giải tán quang mạc bảo hộ, dồn toàn bộ linh lực kiếm trận vào Nguyên Khí Chi Kiếm và tung ra nhát chém quyết định. Kiếm quang chém gãy cự kiếm, phá đôi kim sắc tiểu phiên, xuyên thủng chiến giáp và cắt rời một cánh tay của lão giả. Dù lão giả nối lại được cánh tay, vết thương vẫn tái chảy máu khi hắn vận chuyển pháp lực. Hàn Lập tiếp tục thả Phệ Kim Trùng thành thục và triển khai nhiều thần thông, pháp bảo để áp sát, khiến lão giả phải kích nổ tử sắc phù triện rồi độn thổ chạy hơn mười dặm. Hàn Lập dùng thần thông linh mục nhận ra hướng đào tẩu nhưng thu hồi Phệ Kim Trùng vì việc khu sử chúng đã tiêu hao hơn nửa thần niệm."},{"chuong":1569,"tieuDe":"Rút Đi","tomTat":"Hàn Lập nhận ra ưu thế do Xuân Lê kiếm trận, Nguyên Khí Chi Kiếm và Phệ Kim Trùng tạo ra không thể kéo dài nên không truy kích lão giả họ Đồ, lập tức thu công pháp cùng bảo vật rồi đổi hướng rời chiến trường. Lão giả họ Đồ sau khi áp chế thương thế đã cùng Nanh đạo hữu quay lại, nhưng Hàn Lập đi quá xa và Thiên Huyền la bàn phải chờ ba ngày mới có thể sử dụng lần nữa. Hai cường giả Giác Xi tộc đánh giá cao mức độ nguy hiểm của Phệ Kim Trùng thành thục, đồng thời xác nhận họ đang giữ ba ngọc hạp lấy từ Đại Đầu Nhân và Lục phu nhân. Vì nghi Hàn Lập cũng có một ngọc hạp, họ quyết định truyền tin tới các thành thị lân cận, phong tỏa đường trọng yếu và huy động nhân thủ truy tìm hắn. Sau khi bay liền trăm vạn dặm, Hàn Lập ẩn trên một ngọn núi hoang, dùng linh thạch đỉnh giai mộc thuộc tính và tĩnh tọa để khôi phục bảy tám phần pháp lực. Hắn xem hải vực đồ, tránh các thành thị gần đó rồi chọn Kim Giáp thành, nơi tập trung lực lượng tinh nhuệ của Thiên Vân mười ba tộc, làm đích đến tiếp theo."},{"chuong":1570,"tieuDe":"Gặp Trên Đường","tomTat":"Hàn Lập tránh các thành thị và chọn đường hẻo lánh, nhưng liên tiếp gặp dân dị tộc chạy nạn cùng những đội tuần tra Giác Xi tộc ngày càng dày đặc. Trong một thành thị vừa bị chiếm, Ân Tôn giả nghe hai thuộc hạ báo cáo về việc phong tỏa khu vực, đồng thời biết Đồ sử giả đã gửi chân dung Hàn Lập và yêu cầu phối hợp truy tìm vật quan trọng trên người hắn. Do hai chiến thuyền bị trưởng lão hội điều sang phục vụ cuộc truy bắt, tiến độ chiếm lĩnh bị chậm lại, khiến Ân Tôn giả quyết định tự mình đánh chiếm hai thành thị cuối cùng. Nửa tháng sau, Hàn Lập dùng hắc sắc khinh sa thu liễm khí tức và bí mật tiếp cận một vòng vây lớn của quân Giác Xi tộc. Mục tiêu bị vây là một dị tộc nhân Hóa Thần kỳ đứng trên thuyền bay, bên cạnh có khôi lỗi thân ngựa đầu giao và khôi lỗi sư tử bảy đầu mang chiến lực Luyện Hư. Dị tộc nhân bất ngờ điều khiển hai khôi lỗi phản kích, một con dùng cánh hóa cự nhận chém quân địch, con còn lại tạo ra biển lửa bằng vô số hỏa cầu. Quân Giác Xi tộc đồng loạt đáp trả, khiến đại chiến chính thức bùng nổ."},{"chuong":1571,"tieuDe":"Tai Bay Vạ Gió","tomTat":"Giáp Thiên Mộc điều khiển kim cầu và hai khôi lỗi Luyện Hư kỳ phá vòng vây của Giác Xi tộc, giết gần trăm giáp sĩ cùng cự ưng. Quân Giác Xi tộc tản ra theo lệnh của kẻ cầm đầu Hóa Thần kỳ để hai chiến thuyền oanh kích chiến trường, nhưng lam sắc cự ô đã che chắn cho Giáp Thiên Mộc và các khôi lỗi. Sau thời gian dài chiến đấu, hai khôi lỗi lần lượt mất khả năng hoạt động và bị Giác Xi tộc bắt giữ. Giáp Thiên Mộc công khai tự xưng là người của Vạn Cổ tộc, chỉ điểm chỗ Hàn Lập ẩn thân và hứa tặng khôi lỗi thông linh để cầu cứu. Hàn Lập bị quân Giác Xi tộc phát hiện, dùng Kiếm Ti Nhâm hà giết toán quân dò xét rồi quét sạch thêm nhiều giáp sĩ và cự ưng quanh mình. Cuối chương, hắn gọi một con báo cùng một tiểu hầu ra và ra lệnh cho chúng giết toàn bộ đối phương."},{"chuong":1572,"tieuDe":"Đích Ảnh Tái Hiện","tomTat":"Theo lệnh Hàn Lập, báo lân thú phân hóa thành hơn mười ảo ảnh, còn hắc sắc tiểu hầu hóa thành cự viên khổng lồ để tàn sát đội hình giáp sĩ và cự ưng của Giác Xi tộc. Hai chiến thuyền bỏ mặc quân mình và đồng loạt pháo kích, nhưng Hàn Lập dùng lôi độn tránh né rồi xuất hiện ngay phía trên một chiếc. Hắn liên tục dùng Nguyên Từ Thần Sơn nện xuống, vượt qua độ bền cùng khả năng tự khôi phục của chiến thuyền và phá nó thành đống vụn. Trên chiến thuyền còn lại, bốn tu sĩ Luyện Hư xuất hiện, trong đó quái nhân mặt tái nhợt dùng quái nhận đánh lén Hàn Lập. Nhóm này dụ Giáp Thiên Mộc đổi huyết thống và quy thuận Giác Xi tộc, nhưng ông cự tuyệt, đồng thời vạch rõ âm mưu chiếm đoạt khôi lỗi thuật và thu thập tình báo về Thiên Vân mười ba tộc. Quái nhân cùng lão ẩu sau đó nhận ra Hàn Lập qua hình vẽ do Đồ sứ giả truyền tới và xem việc bắt cả hai người là cơ hội lập công lớn. Tuy cự hán tin bốn người đủ sức áp đảo Hàn Lập, tên lùn vẫn cảnh báo rằng họ chưa chắc ngăn được hắn đào thoát."},{"chuong":1573,"tieuDe":"Bằng Biến","tomTat":"Bốn tu sĩ Luyện Hư được truyền tống từ chiến thuyền tới chiến trường, còn Hàn Lập nhận ra mục tiêu của họ có liên quan đến hai ngọc hạp mình đang giữ. Hắn chủ động chia hơn mười đạo kiếm ti đánh cả bốn người, chém nát cự phủ đỏ và tiêu diệt cự hán mặc da thú cùng nguyên thần. Ba người còn lại phải liên tục phi độn né tránh cho đến khi chiến thuyền bắn hàng trăm cột sáng trắng xuống cứu viện. Từ trong bạch quang, Hàn Lập thi triển Côn Bằng Biến, hóa thành đại bàng khổng lồ phủ điện hồ và lao xuống tấn công lão ẩu. Xích Túc quái nhân cùng tên lùn phối hợp cứu viện, trong khi lão ẩu dùng tinh huyết tăng cường kim sắc pháp trận trên họa trục. Hàn Lập dùng điện hồ làm trận pháp rung chuyển rồi lấy cự trảo phá tan kim quang, đánh lão ẩu thành huyết vụ trước khi hai đồng bạn kịp tới."},{"chuong":1574,"tieuDe":"Liên Tiếp Diệt Đồng Giai","tomTat":"Hàn Lập biến thành đại bàng khổng lồ, dùng tinh quang hộ tráo hóa giải công kích rồi truy sát gã lùn và Xích Túc quái nhân trong hắc vụ. Đề Hồn thú thi triển Nhiếp Hồn thần quang hút phần lớn âm vụ, buộc hai đối thủ lộ vị trí; Hàn Lập lập tức phá pháp bảo phòng hộ và bóp nát cả thân thể lẫn nguyên thần của gã lùn. Xích Túc quái nhân dùng huyết độn chạy trốn nhưng huyết ảnh bị khôi lỗi màu lam của Giáp Thiên Mộc dùng Ích Tà thần lôi đánh tan. Hàn Lập tiếp tục xé thủng rồi phá hủy chiến thuyền Giác Xi tộc, trong khi Đề Hồn thú và Báo Lân thú tiêu diệt phần lớn giáp sĩ cùng cự ưng hai đầu. Sau trận chiến, Hàn Lập cảnh cáo Giáp Thiên Mộc vì đã kéo mình vào cuộc giao tranh, còn Giáp Thiên Mộc tiết lộ hắn phát hiện Hàn Lập nhờ Uẩn Niệm châu có khả năng tạm thời tăng thần thức và linh giác. Từ lời giải thích này, Hàn Lập nhớ tới nội đan dị thú từng lấy được tại Trụy Ma cốc và nghi ngờ mình cũng có thể luyện một viên Uẩn Niệm châu. Biết phía trước bị Giác Xi tộc phong tỏa nghiêm ngặt, Hàn Lập đồng ý hộ tống Giáp Thiên Mộc tới truyền tống trận bí mật của Thiên Vân mười ba tộc, rồi hai người cùng rời khỏi chiến trường."},{"chuong":1575,"tieuDe":"Yêu Cầu","tomTat":"Giác Xi tộc triển khai hơn trăm chiến thuyền cùng giáp sĩ, cư ưng hai đầu, vũ giao và nhiều loại khôi lỗi để bao vây Hoàng Thủy Thành. Nữ tử họ Ân nhận tin một đội truy binh bị diệt và biết người cứu Giáp Thiên Mộc cũng là đối tượng Đồ sứ giả đang truy tìm, nên chuyển nhiệm vụ truy bắt cho phía Đồ sứ giả và lệnh đại quân công thành trong ba ngày. Đại quân Giác Xi tộc phát động công kích, dùng chiến thuyền và ba loại khôi lỗi thú cỡ lớn đánh vào hoàng sắc quang tráo phòng hộ của thành. Trong khi đó, Hàn Lập cùng Giáp Thiên Mộc sử dụng truyền tống trận khẩn cấp của Vạn Cổ tộc để đến một cứ điểm bí mật gần Vân Thành. Giáp Thiên Mộc mời Hàn Lập gia nhập Vạn Cổ tộc làm khách khanh, nhưng Hàn Lập chưa đồng ý vì chưa biết sẽ ở Thiên Vân bao lâu. Sau đó, hai người rời cứ điểm, hóa thành độn quang hướng về Vân Thành."},{"chuong":1576,"tieuDe":"Vân Thành","tomTat":"Hàn Lập theo Giáp Thiên Mộc tới trước Vân Thành, một đại thành màu trắng lơ lửng giữa không trung và có quy mô che khuất hơn nửa bầu trời khi nhìn gần. Giáp Thiên Mộc giải thích những khối cầu trắng quanh thành là Vân Thành chi vệ do Vạn Cổ tộc và Thạch Kiền tộc hợp lực chế tạo, có khả năng hút rồi dùng hỏa lực thôn phệ bảo vật kim loại. Tại cửa thành, ông dùng lệnh bài xác nhận thân phận Giáp đại sư và được báo rằng các trưởng lão Vạn Cổ tộc đang chờ tại Thiên Húc các, trong khi thành có nguy cơ bị gian tế Giác Xi tộc xâm nhập. Giáp Thiên Mộc từ chối hộ tống, đứng ra bảo đảm cho Hàn Lập và yêu cầu cấp thân phận bài tự do cấp cao nhất cho hắn. Các thủ vệ dùng pháp bàn cùng thần niệm hợp lực để kiểm tra tu vi và huyết mạch của Hàn Lập, sau đó cấp ngọc bài cho phép hắn đi lại tại phần lớn khu vực trong thành. Sau khi tiến vào Vân Thành, Hàn Lập lập tức hỏi Giáp Thiên Mộc về bí thuật có thể dung hợp thần niệm của nhiều người."},{"chuong":1577,"tieuDe":"Thiên Vân Chư Tộc","tomTat":"Giáp Thiên Mộc giải thích cho Hàn Lập về Ngưng Thần Quy Nhất Thuật, một thuật do Thanh Tộc sáng chế, đòi hỏi những người cùng huyết mạch và cảnh giới tương đương phối hợp. Hàn Lập muốn tìm phương pháp tu luyện để nghiên cứu cải tiến, còn Giáp Thiên Mộc hứa tìm một bản công pháp và tặng hắn một thông linh khôi lỗi sau khi xin trưởng lão trong tộc phê chuẩn. Hai người chia tay tại cửa thành Vân Thành, nơi Giáp Thiên Mộc cảnh báo về quy củ nghiêm khắc cấm tranh đấu và vận dụng linh lực. Hàn Lập tìm hiểu tình hình Thiên Vân mười ba tộc, Giác Xi Tộc và Dạ Tộc, đồng thời nhận ra Thiên Vân mười ba tộc đang chuẩn bị phản kích Giác Xi Tộc. Với mục tiêu tìm truyền tống trận về Thiên Nguyên Đại Lục, Hàn Lập vào cửa hàng của Mặc Lục Tộc mua bản đồ chi tiết Vân Thành và hỏi tin tức. Sau đó hắn đi thú xa đến một kiến trúc khổng lồ, rồi thuê một gian phòng hẻo lánh để lưu lại vài ngày."},{"chuong":1578,"tieuDe":"Gặp Lại Người Quen","tomTat":"Hàn Lập vào một khách sạn tại Vân thành và bất ngờ nhận ra lão giả phụ trách đón khách chính là Hướng Chi Lễ, người từng bị cho là đã chết sau khi vượt qua không gian tiết điểm. Hướng Chi Lễ kể rằng Hô lão ma và Phong lão quái đã tử nạn, còn ông sống sót nhờ nhiều lần sử dụng bí thuật bảo mệnh nhưng tu vi từ Hóa thần kỳ rơi xuống Kết đan kỳ. Do bị không gian gió lốc cuốn lệch tới Thiên Vân, ông được chủ nhân khách sạn thuộc Thạch Kiền tộc cứu mạng rồi ở lại làm người giúp việc để báo ân. Hàn Lập kể về việc cùng Băng Phượng thoát khỏi không gian tiết điểm và cho biết nhân tộc tại linh giới vẫn miễn cưỡng đứng vững. Hai người trao đổi thông tin về các truyền tống trận liên đại lục do Thiên Vân mười ba tộc, Giác Đổng tộc và Dạ tộc nắm giữ, đồng thời nói về điều kiện cảnh giới và chi phí sử dụng. Hàn Lập công khai mình đã tiến giai Luyện Hư kỳ, sau đó được Hướng Chi Lễ sắp xếp một căn phòng yên tĩnh để tạm trú và hẹn buổi tối tiếp tục trò chuyện."},{"chuong":1579,"tieuDe":"Tinh Tộc","tomTat":"Hướng Chi Lễ đến gặp Hàn Lập vào ban đêm và trò chuyện về Vân Thành cùng Thiên Vân mười ba tộc. Ông nói mình không thể trở về nhân tộc, đồng thời nhờ Hàn Lập trước khi rời Vân Thành ghé qua để nhận một vật và giúp một việc chưa thể nói rõ. Sau khi tiễn ông rời đi, Hàn Lập phong tỏa căn phòng bằng cấm chế, ở lại thêm một ngày rồi đến khu cửa hàng của dị tộc vào ngày thứ ba. Trên đường, hắn nhận ra quả cầu khổng lồ trên tường thành là một trong mười ba chiến tranh khôi lỗi lớn, có uy lực được nói là sánh với Hợp Thể sơ kỳ. Tại cửa hàng điển tịch, Hàn Lập chọn hơn hai mươi quyển điển tịch, trong đó có một lam sắc ngọc điệp. Nữ tử Tinh tộc làm chủ cửa hàng đề nghị tặng số điển tịch nếu hắn xem một chiếc hộp kim loại màu đen dán hai lá phù xanh, nhưng chương kết thúc trước khi vật bên trong được tiết lộ."},{"chuong":1580,"tieuDe":"Thiên Ngoại Ma Giáp","tomTat":"Nữ tử Tinh tộc dùng pháp bàn mở ngũ sắc quang trận, đưa Hàn Lập vào một tiểu không gian kín để trao đổi về chiếc hộp. Hàn Lập tháo phù phong cấm, hấp thu toàn bộ ma khí tinh thuần bên trong rồi lấy ra một chiến giáp màu tím bị hư tổn nghiêm trọng. Nữ tử Tinh tộc xác định đó có vẻ là Thiên Ngoại Ma Giáp do thiên ngoại ma đầu tự sinh ra, dù uy lực hiện tại chỉ còn chưa tới một phần mười. Hàn Lập dùng pháp quyết kích hoạt ma giáp và khiến nó dung hợp với pháp tướng ba đầu sáu tay của Phạm Thánh Chân Ma Công. Nữ tử Tinh tộc đề nghị giao dịch và cho biết ma giáp có thể chữa trị bằng vài trăm ma hạch, tốt nhất là dùng ma hạch Thánh giai làm tài liệu chủ. Cuối cùng, nàng tiết lộ đã chuẩn bị hai tin tức liên quan đến ma hạch Thánh giai để thúc đẩy cuộc giao dịch."},{"chuong":1581,"tieuDe":"Ma Kim Sơn Mạch","tomTat":"Nữ tử Tinh tộc nói cho Hàn Lập biết Vân Thành sẽ tổ chức đấu giá một viên ma hạch của ma thú thánh giai sau ba tháng, nhưng Hàn Lập nhận thấy mình khó cạnh tranh với các thánh tộc nên không chọn cách này. Nàng tiếp tục kể về Ma Kim Sơn Mạch, dãy núi đen xuất hiện sau không gian gió lốc, nơi ma khí, khe không gian và ma thú cao giai khiến tỷ lệ tử vong của người tiến vào cực cao. Các thánh tộc từng tiến vào trung tâm sơn mạch rồi phong tỏa khu vực, chỉ để lại một lối vào với thời hạn tiến nhập cố định. Tiêm Tiêm tiết lộ một ma thú thánh giai từng trốn khỏi sơn mạch đang bị thương và ngủ say bên ngoài, đồng thời đề nghị Hàn Lập dùng ma giáp để cùng nàng săn bắt. Nàng triệu hồi Ma Yên Điểu và đưa ra hình vẽ chứng minh đã nhiều lần theo dõi mục tiêu, còn Hàn Lập nhận ra ma thú có nét tương tự Sơn Nhạc Cự Viên. Cuối chương, Hàn Lập hỏi tên nữ tử và nàng tự xưng là Tiêm Tiêm."},{"chuong":1582,"tieuDe":"Thông Linh Khôi Lỗi","tomTat":"Hàn Lập đạt thỏa thuận với Tiêm Tiêm về kế hoạch liên quan đến thánh giai ma thú và Ma Kim Sơn Mạch. Hắn đặt ra các điều kiện bảo toàn lợi ích, bao gồm quyền rút lui, việc Tiêm Tiêm cùng đi và phần chân linh huyết nếu ma thú có huyết mạch Sơn Nhạc Cự Viên. Hàn Lập dùng đan dược, tài liệu quý và cực phẩm linh thạch để hoàn tất giao dịch, đồng thời để lại vạn lý phù làm phương thức liên lạc. Sau đó hắn khảo sát Vân Thành trong mười ngày và trò chuyện với Hướng Chi Lễ. Hàn Lập tiếp tục đến Vân Hà Sơn, một trong tám linh sơn của Bát Vân Xuyên Sơn, để tìm Giáp Thiên Mộc và nhận thông linh khôi lỗi. Giáp Thiên Mộc mở cửa động phủ đón hắn rồi sai một nữ tử hoàng sam mang hộp gỗ ra, nhưng Hàn Lập lại chú ý đến nữ tử này hơn là chiếc hộp."},{"chuong":1583,"tieuDe":"Khôi Lỗi Bội Nguyệt","tomTat":"Hàn Lập nhận ra nữ tỳ bên cạnh Giáp Thiên Mộc thực chất là một thông linh khôi lỗi được luyện chế để có hình dáng và khí tức giống người thật. Giáp Thiên Mộc tiếp tục giới thiệu khôi lỗi bạch xà mới luyện chế, cho nó biến thành bạch mãng rồi nữ tử áo trắng, sau đó trao nó cho Hàn Lập; khôi lỗi này có thực lực thượng tộc thất giai nhưng tiêu hao nhiều linh thạch băng. Hàn Lập lấy nhóm linh thị thu được từ Địa Uyên ra trình diễn, khiến Giáp Thiên Mộc chú ý đến ý tưởng dung hợp linh thể với khôi lỗi. Hàn Lập dùng nhóm linh thị làm điều kiện trao đổi để hỏi về truyền tống trận đến đại lục. Giáp Thiên Mộc xác nhận trận pháp tồn tại ở Thiên Vân và cho biết Tinh Tộc, Thạch Kiến Tộc, Đa Thủ Tộc cùng Vạn Cổ Tộc phối hợp trông coi và tu sửa."},{"chuong":1584,"tieuDe":"Oa Oa","tomTat":"Hàn Lập hỏi Giáp Thiên Mộc về khả năng mượn truyền tống trận để đến một đại lục khác. Giáp Thiên Mộc cho biết ngoại tộc rất khó sử dụng trận, nhưng chiến tranh với Giác Xi Tộc có thể giúp Hàn Lập lập công cho Thiên Vân rồi thương lượng với các trưởng lão Vạn Cổ Tộc. Hai người trao đổi về khôi lỗi thuật, qua đó cùng nhận ra kiến thức của đối phương đều có điểm đáng học hỏi. Sau khi trở về nơi ở, Hàn Lập kiểm tra bạch xà thông linh khôi lỗi nhưng không thể dò ra các bộ phận then chốt. Hắn tiến hành nghi thức nhận chủ kéo dài một ngày một đêm, khiến khôi lỗi biến thành bạch y nữ tử, đặt tên là Oa Oa rồi thu nó về hình dạng bạch xà. Cuối chương, Hàn Lập gia cố nơi ở bằng nhiều tầng phòng hộ để chuẩn bị nghiên cứu ngọc hạp do Đại đầu nhân giao."},{"chuong":1585,"tieuDe":"Nghiễm Hàn Lệnh","tomTat":"Hàn Lập bố trí phòng ngự rồi dùng Hắc sắc tiểu sơn, Nguyên Từ Thần Quang và Ngũ sắc hàn diễm để tháo phù triện trên ngọc hạp. Khi ngọc hạp được mở, quang trận phong ấn bên trong phát nổ, nhưng Hàn Lập dùng Nguyên Từ Thần Quang cùng Ngân sắc hỏa điểu để khống chế và làm suy yếu vụ nổ. Bên trong hộp là Nghiễm Hàn Lệnh, một lệnh bài cổ có hai mặt kim ngân, đặc tính băng hỏa và một góc bị vỡ. Lệnh bài hút máu Hàn Lập, phát ra tiếng rồng ngâm rồi phóng cột sáng kim ngân xuyên nóc nhà lên tầng mây. Chấp pháp vệ đội Tây thành Vân thành đến điều tra, còn Hàn Lập phát hiện mình không thể di chuyển lệnh bài. Bạch trưởng lão xuất hiện, nhận ra đây là Nghiễm Hàn Lệnh và giải thích rằng nó sẽ cố định trong phạm vi trăm trượng sau khi được kích hoạt."},{"chuong":1586,"tieuDe":"Thiên Cơ Tử","tomTat":"Hàn Lập phát hiện thanh niên họ Bạch là Bạch Nga, một trưởng lão Thủy Mị Tộc có tu vi Hợp Thể kỳ, và được đối phương mời làm khách khanh vì đã kích phát Nghiễm Hàn Lệnh. Bạch Nga dùng Lưu Ly Huyễn Mục tác động tâm thần nhưng Hàn Lập khôi phục tỉnh táo nhờ Đại Diễn Quyết và Minh Thanh Linh Mục. Thương Ảnh đại diện Âm Yêu Tộc xuất hiện để tranh quyền mời Hàn Lập. Thiên Cơ Tử của Vạn Cổ Tộc xuyên qua cửa tiến vào phòng, khiến Bạch Nga và Thương Ảnh đều kiêng kỵ. Ông tiết lộ Hàn Lập từng cứu Giáp đại sư, rồi tuyên bố đưa Hàn Lập về Vạn Cổ Tộc, phong bế nơi Nghiễm Hàn Lệnh xuất hiện và bố trí pháp trận khởi động. Trước chênh lệch thân phận và thực lực, Hàn Lập cung kính nhận lời đến Vạn Cổ Tộc."},{"chuong":1587,"tieuDe":"Nghiễm Hàn Giới","tomTat":"Theo lệnh Thiên Cơ Tử, các giáp sĩ phong tỏa khu vực quanh khách sạn, trưng dụng nơi này và canh giữ Nghiễm Hàn Lệnh, còn Hàn Lập được đưa rời đi. Trên đường đến Bát Vân Sơn bằng thú xa kim sư, Hàn Lập suy đoán Vạn Cổ Tộc cần hắn phối hợp vì lệnh bài đã được tinh huyết của hắn kích hoạt, nên dự định nhân cơ hội thương lượng việc mượn truyền tống trận. Thiên Cơ Tử đưa hắn vào một thành trì bí mật có nhiều lớp phòng thủ rồi đến Thông Linh Điện, trọng địa của Vạn Cổ Tộc được hai thông linh khôi lỗi cấp thượng tộc cửu giai bảo vệ. Tại chủ điện, Thiên Cơ Tử cho biết đã mời thêm hai trưởng lão vì ba người họ cùng làm chủ công việc của Vạn Cổ Tộc tại Vân Thành và chuyện Nghiễm Hàn Lệnh có liên hệ trọng đại. Ông giải thích người muốn dùng lệnh bài tiến vào Nghiễm Hàn Giới phải có một tộc đứng phía sau ủng hộ. Nghiễm Hàn Giới được mô tả là nơi có linh khí dày đặc gấp mười lần Linh giới, chứa nhiều linh dược, linh quả, động phủ và di hài hiếm gặp, đủ khả năng ảnh hưởng đến thịnh suy của một tộc. Vạn Cổ Tộc còn có bảy tám phần nắm chắc rằng nơi này là một không gian tàn phá gần Chân Tiên giới, nhưng Thiên Cơ Tử cảnh báo các bảo vật đều nằm ở khu vực bí ẩn và người tiến vào chưa chắc đạt được thu hoạch nghịch thiên."},{"chuong":1588,"tieuDe":"Yêu Cầu","tomTat":"Mã trưởng lão của Vạn Cổ Tộc đến đại điện và nhận ra Hàn Lập là ngoại tộc nhân từng kích phát Nghiễm Hàn Lệnh. Ông dùng bí thuật quan sát, phát hiện pháp lực và thần niệm của Hàn Lập vượt xa tu sĩ cùng cấp. Mã trưởng lão cùng Thiên Cơ Tử và lão già béo giải thích linh khí, tài nguyên, nguy hiểm, quy tắc ra vào và nguồn gốc viễn cổ của Nghiễm Hàn Giới. Hàn Lập khai báo rằng mình nhận được lệnh bài từ một tộc nhân Vạn Cổ Tộc trong lúc bị Giác Xi Tộc bao vây, còn Thiên Cơ Tử suy đoán người trao vật có thể liên quan đến Lục Quang Thành. Các bên cũng bàn về việc Thiên Vân mười ba tộc chỉ còn khoảng mười bảy hoặc mười tám lệnh bài sau cuộc tấn công của Giác Xi Tộc. Cuối cùng, Mã trưởng lão yêu cầu Hàn Lập đi cùng người của Vạn Cổ Tộc tiến vào Nghiễm Hàn Giới."},{"chuong":1589,"tieuDe":"Trao Đổi Cùng Hậu Thủ","tomTat":"Hàn Lập biết mình không thể dễ dàng từ chối việc tiến vào Nghiễm Hàn Giới vì người kích phát Nghiễm Hàn Lệnh phải gánh trách nhiệm liên quan đến mười ba tộc. Hắn thương lượng với Thiên Cơ Tử và Mã trưởng lão để được sử dụng truyền tống trận rời Lôi Minh Đại Lục sau khi hoàn thành việc, đồng thời chấp nhận tự chịu chi phí cực phẩm linh thạch dù được khuyên đổi sang linh đan diệu dược. Thiên Cơ Tử cho biết Nghiễm Hàn Giới có thể mở trong vài năm hoặc kéo dài đến khoảng trăm năm, rồi đề nghị Hàn Lập đến Bát Vân Sơn tu luyện trong thời gian chờ đợi. Trưởng lão thứ ba của Vạn Cổ Tộc đến gặp Hàn Lập, nói một tiếng đánh giá rồi vội rời đi để tiếp tục luyện đan; Hàn Lập nhận Vạn Lý Phù từ Mã trưởng lão và rời Thông Linh Điện. Sau đó Thiên Cơ Tử và Mã trưởng lão xác nhận Hàn Lập không phải gian tế, quyết định không dùng sưu hồn thuật và cân nhắc giữ hắn làm khách khanh nếu có thể. Hàn Lập không đến thẳng Bát Vân Sơn mà tìm một khách sạn khác để tạm trú, bố trí pháp khí phòng hộ và dự định dùng Đằng Long Đan tu luyện đến Luyện Hư Sơ Kỳ đỉnh phong trước khi nhờ linh khí Nghiễm Hàn Giới đột phá Trung Kỳ. Cuối cùng, hắn giữ lại một khối Nghiễm Hàn Lệnh trong ngọc hạp để làm hậu thủ trao đổi."},{"chuong":1590,"tieuDe":"Tứ Tộc Đấu Giá","tomTat":"Sau khi nhận tin từ Thiên Cơ Tử qua vạn lý phù, Hàn Lập chuyển đến một động phủ mới tại Bát Vân Sơn và bố trí nhiều lớp cấm chế phòng hộ. Hắn luyện Đằng Long Đan để vừa hỗ trợ tu luyện Phạm Thánh Chân Ma Công vừa đổi lấy cực phẩm linh thạch, đồng thời giữ Kim Lôi Trúc làm phương án dự phòng. Để được sử dụng truyền tống trận tiến vào Nghiễm Hàn Giới, Hàn Lập chấp nhận yêu cầu tìm tài liệu luyện khí cho Thạch Kiến Tộc. Sau một năm tu luyện khiến pháp tướng ngày càng ngưng tụ, hắn rời động phủ và gặp Thiết Kiến, một tu sĩ Luyện Hư Kỳ đỉnh giai của Thạch Kiến Tộc. Thiết Kiến cho biết Tứ Tộc Đấu Giá Hội sắp diễn ra, có khả năng xuất hiện Vạn Diệu Đan cùng hai thông linh khôi lỗi của Vạn Cổ Tộc. Hàn Lập nhận lời cùng Thiết Kiến đến đại điện đấu giá, nơi được nhiều khôi lỗi và vệ sĩ cấp cao bảo vệ. Trước khi vào hội, Thiết Kiến mời hắn sang thiên điện xem việc bán vật phẩm lấy linh thạch."},{"chuong":1591,"tieuDe":"Gặp Nhau","tomTat":"Thiết Kiên giải thích cho Hàn Lập rằng trước mỗi kỳ tứ tộc đấu giá hội, tu sĩ được tự do mua bán, trao đổi tài liệu hoặc bán vật phẩm cho phía tổ chức. Muốn gom thêm linh thạch để mua Vạn Diệu Đan, Hàn Lập theo ông vào khu giao dịch và biết đại sảnh đấu giá vốn là một pháp bảo không gian có thể chứa tới mười vạn người. Hắn quan sát các tu sĩ dùng tiểu phiên dựng quang mạc ngăn thần niệm nhưng tìm kiếm một lúc vẫn không thu hoạch được gì. Trở lại lối vào vắng người, Hàn Lập dùng hắc sắc sa cân che giấu khí tức, thay đổi dung mạo và y phục thành một nho sinh mặc hắc bào rồi tiến vào khu vực khác của thiên điện. Tại nơi có thạch bích ghi ngân sắc văn tự và nhiều ngọc ốc được quang hà bao phủ, hắn bất ngờ nhìn thấy một lam bào nữ tử có dung mạo giống hệt người quen. Hàn Lập thất thần nhìn nàng, còn nữ tử cảm ứng được ánh mắt ấy nên quay lại, khiến hai người vừa lúc đối mắt."},{"chuong":1592,"tieuDe":"Quái Nhân","tomTat":"Hàn Lập bắt gặp một nữ tử áo lam có dung mạo giống hệt Trần Xảo Thiến, nhưng sau phút dao động đã xác định nàng chỉ là một dị tộc nhân và tiếp tục tìm kiếm vật liệu. Qua những con số trên thạch bích và mười ba ngọc ốc, hắn suy ra cách bố trí các vật phẩm trong khu giao dịch. Một cuộc tranh cãi về món đồ bị cho là giả vang lên từ lầu các đỏ, rồi Đoạn Thiên Nhận với thân thể nửa máu thịt, nửa kim loại bước ra. Các tộc nhân Thạch Kiến Tộc hành lễ, qua đó xác nhận ông là tam trưởng lão của tộc và là cường giả Hợp Thể Kỳ đỉnh phong. Khi đi ngang qua Hàn Lập, Đoạn Thiên Nhận phát hiện dấu hiệu Luyện Thể Thuật, hỏi tên cùng lai lịch rồi bất ngờ vỗ vai truyền linh khí vào cơ thể hắn. Ông tiết lộ đã lưu một ấn ký có thể theo dõi Hàn Lập trong vài canh giờ và yêu cầu hắn đến Thuần Hương Các để trao đổi tâm đắc. Không rõ mục đích thật sự của đối phương, Hàn Lập trở nên bất an và không thể bình tĩnh tiếp tục tìm kiếm."},{"chuong":1593,"tieuDe":"Cửu Hương Linh Tửu","tomTat":"Sau cuộc gặp Đoạn Thiên Nhận, Hàn Lập từ bỏ kế hoạch dịch dung bán linh dược để tránh gây chú ý. Nhớ lại ánh mắt đối phương từng kín đáo hướng về tay áo mình, hắn kiểm tra Nguyên Từ Sơn và cánh tay đang phong ấn thanh kiếm Huyền Thiên, lo rằng bí mật bảo vật đã bị cảm ứng. Biết mình không thể chống lại cường giả Hợp Thể hậu kỳ đỉnh phong hoặc dễ dàng thoát khỏi Vân thành, Hàn Lập quyết định bước vào Thuần Hương Các để xác định họa phúc. Tại căn phòng tầng ba được kim quang bảo vệ, hắn gặp Đoạn Thiên Nhận và Thái tiên tử, chủ nhân Thuần Hương Các có tu vi Hợp Thể sơ kỳ. Đoạn Thiên Nhận giao việc nghiệm chứng Hàn Lập cho Thái tiên tử và yêu cầu được chia phần lớn lợi ích nếu thành công, trong khi nàng cũng chú ý đến cánh tay hắn. Thái tiên tử dùng Cửu Hương Linh Tửu khoản đãi và tiết lộ loại rượu này mỗi trăm năm chỉ luyện được mười bình vì bí pháp chế tạo phụ thuộc vào công pháp của nàng. Sau khi kiểm tra rượu không có vấn đề, Hàn Lập nếm thử và cảm nhận linh tửu chuyển từ lạnh như băng thành dòng nước ấm thơm ngát tự trôi xuống bụng."},{"chuong":1594,"tieuDe":"Nguyên Từ Chi Thể","tomTat":"Hàn Lập được Đoạn Thiên Nhận và Thải Lưu Anh mời uống linh tửu, nhưng nhanh chóng nhận ra cuộc gặp còn có mục đích khác. Thải Lưu Anh dùng ngân châm kiểm tra bàn tay hắn, khiến dấu ấn Nguyên Từ Thần Sơn hiện ra và xác nhận hắn đã hình thành Nguyên Từ Chi Thể. Hàn Lập thi triển Nguyên Từ Thần Quang hóa giải hỏa cầu của Thải Lưu Anh, rồi thu nhận toàn bộ hôi quang do Đoạn Thiên Nhận phóng ra, cho thấy thần thông của hắn mạnh và ổn định hơn. Hai người tiết lộ đã tìm kiếm người sở hữu Nguyên Từ Thần Quang trong nhiều năm và Hàn Lập là người thứ ba phù hợp với kế hoạch. Khi biết việc trợ giúp có thể kéo dài từ vài năm đến một trăm năm, Hàn Lập nghi ngờ mục đích của họ có liên quan đến Nghiễm Hàn Giới."},{"chuong":1595,"tieuDe":"Thải Lưu Anh","tomTat":"Hàn Lập biết Đoạn Thiên Nhận và Thải Lưu Anh đang chuẩn bị tiến vào Nghiễm Hàn Giới để phá một cấm chế bí ẩn. Cấm chế được cho là phong ấn những vật có thể giúp họ ứng phó đại thiên kiếp, nhưng cần ba người có Nguyên Từ Chi Thể hợp lực mới có khả năng phá giải. Thải Lưu Anh giải thích rằng một người là tán tu làm khách khanh của Tinh Tộc, người còn lại do Đoạn Thiên Nhận bồi dưỡng, còn Nguyên Từ Chi Thạch đã cạn sau nhiều lần thử nghiệm. Hàn Lập đồng ý tham gia dù chuyến đi có nguy hiểm, với điều kiện hai người kia chịu một nửa chi phí truyền tống và để nhóm tự chọn những vật phẩm còn lại. Trước khi hắn rời đi, Thải Lưu Anh yêu cầu giữ bí mật kế hoạch rồi tiết lộ tên thật của mình và danh xưng Tiết phu nhân."},{"chuong":1596,"tieuDe":"Giám Định","tomTat":"Hàn Lập rời Thuần Hương Các và đi theo dòng người tiến vào đại điện đấu giá Vân thành. Biết khu Giám định chuyên thẩm định bảo vật quý, hắn quyết định đưa Đằng Long Đan cùng Kim Lôi Trúc ra bán để kiếm phần linh thạch còn thiếu cho việc truyền tống. Các giám định viên kiểm tra đoạn Kim Lôi Trúc bằng hắc khí và lục khí, xác nhận nó là linh trúc thật; đồng thời xác định Đằng Long Đan đã thông linh, thuộc mộc làm chủ kim làm phụ và được xếp vào nhóm nhất phẩm. Cả hai vật đều được nhận vào nhóm đấu giá ưu tiên, còn Hàn Lập nhận ngọc bài giao ước để lĩnh linh thạch sau khi đấu giá kết thúc. Sau đó hắn vào thính đường ba tầng, chọn một chỗ khuất và lẳng lặng chờ cuộc đấu giá bắt đầu."},{"chuong":1597,"tieuDe":"Lưu Ly Thiên Hỏa Dịch","tomTat":"Trong thời gian chờ đợi, đại điện đấu giá tại Vân thành nhanh chóng chật kín tu sĩ từ Nguyên Anh kỳ trở lên, riêng cường giả Hợp Thể kỳ đã có số lượng rất lớn. Đoạn Thiên Nhận và Thiên Cơ Tử cũng xuất hiện trong nhóm cường giả đỉnh giai, khiến Hàn Lập nhận ra nội tình của Vân thành vượt xa Thiên Uyên Thành. Sau khi cửa điện đóng lại, Tiêu Bố Y thông qua pháp trận xuất hiện trên đài, tự giới thiệu là tu sĩ Sa Tộc có tu vi Hợp Thể trung kỳ và tuyên bố khai mạc tứ tộc đấu giá hội. Phượng Hoàng Thạch được nữ tử Mặc Lục Tộc mua với giá hơn năm trăm vạn linh thạch, còn Kim Vương Hoa được lão giả khô gầy có sừng trắng mua với giá bảy trăm vạn. Cuối cùng, nửa bình Lưu Ly Thiên Hỏa Dịch, một trong bát đại linh dịch của Linh giới, được đưa ra với giá khởi điểm một ngàn tám trăm vạn linh thạch. Sự xuất hiện của linh dịch khiến toàn trường chấn động và làm Hàn Lập biến sắc."},{"chuong":1598,"tieuDe":"Hà Tỳ Phẩm","tomTat":"Lưu Ly Thiên Hoả Dịch xuất hiện tại đấu giá hội với giá khởi điểm thấp bất thường, khiến Hàn Lập sinh nghi vì đây vốn là tài liệu quý mà Thanh Nguyên Tử cần để luyện đan. Tiêu Bố Y công bố bình linh dịch là hà tỳ phẩm, có công hiệu kém chính phẩm, rồi dùng một thanh phi kiếm để chứng minh khả năng nung chảy kim thạch và uy lực hỏa diễm của nó vẫn còn đáng kể. Vì cho rằng linh dịch vẫn có thể hữu dụng với Thanh Nguyên Tử, Hàn Lập mở giá ba ngàn vạn linh thạch nhằm ép phần lớn đối thủ rút lui. Phù lão và một nữ tử Thánh tộc trên tầng ba lần lượt tham gia tranh giá, đẩy mức giá lên bốn ngàn bảy trăm vạn. Hàn Lập chốt giá năm ngàn vạn linh thạch, gần chạm giới hạn tài lực của mình, khiến nữ tử Thánh tộc phải bỏ cuộc. Hắn giao linh thạch cho Tiêu Bố Y, nhận nửa bình Lưu Ly Thiên Hoả Dịch rồi trở lại chỗ ngồi. Khoản chi tiêu lớn và bảo vật vừa đoạt được khiến Hàn Lập bị nhiều ánh mắt mang ác ý chú ý."},{"chuong":1599,"tieuDe":"Dị Thú","tomTat":"Hàn Lập dùng ảo thuật che giấu khuôn mặt để tránh bị những người từng gặp hắn nhận ra. Cuộc đấu giá tại Vân thành tiếp tục thuận lợi, bình Đằng Long Đan của hắn được nữ tử Thánh tộc mua với giá sáu ngàn ba trăm vạn linh thạch. Từ việc tính toán giá trị số đan dược đã dùng, Hàn Lập càng nhận thức rõ thần bí tiểu bình là nền tảng quan trọng đối với con đường tu luyện của mình. Khi phần vật phẩm áp trục bắt đầu, bốn khách khanh Hợp Thể Trung Kỳ của Vân thành xuất hiện trên đài, trong đó Lam huynh giới thiệu một dị thú màu tím mang hơn phân nửa huyết mạch Nhân Diện Giao. Sau khi vật trói vàng bạc được tháo ra, dị thú phát ra ánh tím chói mắt rồi biến mất khỏi lồng sắt. Lam huynh bình tĩnh cảnh cáo và chuẩn bị thi triển thủ đoạn chế ngự, nhưng chương kết thúc trước khi kết quả được thể hiện."},{"chuong":1600,"tieuDe":"Kinh Biến","tomTat":"Lam huynh dùng lồng sắt màu đen phóng điện để ép tử sắc tiểu thú hiện hình và bộc lộ huyết mạch Nhân Diện Giao. Tử hồ triệu ra ngân sắc cự giao ảnh hấp thu điện quang, nhưng sau đó bị kim ngân tế ti trói chặt. Tiêu Bố Y chủ trì cuộc tranh giá, cuối cùng lão giả họ Lục dùng một triệu ba ngàn vạn linh thạch mua được tử hồ và chuẩn bị mang nó đi. Hàn Lập nhận thấy ánh mắt của tử hồ gợi nhớ Ngân Nguyệt, rồi bóp nát thành ghế ngọc khi con thú phản kháng bằng tiếng kêu khiến người tu vi thấp choáng váng. Ngay sau đó, một nam tử bí ẩn đánh vỡ cấm chế cửa đại điện, công khai thách thức bốn tộc và bước vào đấu giá hội."},{"chuong":1601,"tieuDe":"Nhân Diện Giao","tomTat":"Một ngân bào nam tử cùng thanh niên họ Phỉ xuất hiện tại đại điện đấu giá Vân thành. Thái độ cung kính của các thánh tộc khiến Hàn Lập và Tiêu Bố Y suy đoán họ Phỉ là Đại Thừa kỳ, còn người đi cùng cũng có thực lực tương tự. Ngân bào nam tử nhận ra tử sắc ấu thú bị nhốt trong lồng và lập tức đánh lui lão già họ Lục, phá lồng cùng dây bạc để giải cứu nó. Sau khi nghe con gái tố cáo nhóm khách khanh, ông ra tay phá hủy viên châu màu xanh và ba tầng quang mạc của lão Ông, suýt lấy mạng bốn người. Họ Phỉ ngăn ông giết người nhưng cho phép trừng phạt nhóm khách khanh, đồng thời tiết lộ họ đã săn bắt linh thú gần động phủ của ông. Ngân bào nam tử công khai xác nhận bản thể là Nhân Diện Giao, khiến lão Ông và ba đồng bọn tái mặt, thất thần."},{"chuong":1602,"tieuDe":"Hiểu Lầm","tomTat":"Tại Vân thành, Nhân Diện Giao biến thành ngân bào nam tử để tìm lại nữ nhi là tử sắc tiểu thú và truy cứu nhóm lão Ông đã hành hạ nàng. Thanh niên họ Phỉ đứng ra hòa giải, nhưng Nhân Diện Giao vẫn chém đứt một cánh tay lão Ông, buộc bốn người bồi thường bốn triệu linh thạch và cấm họ tiến vào Tử Vi hải. Sau đó, hắn dùng thần thông giúp tử sắc tiểu thú hóa thành nữ đồng, yêu cầu nàng trở về tu luyện cho đến khi có thể tự biến thân. Nữ đồng phát hiện khí tức yếu liên quan đến bộ tộc bên mẫu thân trên người Hàn Lập nên chỉ về phía hắn. Nhân Diện Giao dùng thần niệm kiểm tra Hàn Lập, nhận ra mối liên hệ rất yếu và không tiếp tục truy cứu. Hàn Lập hành lễ trước Đại Thừa, còn Nhân Diện Giao ôm nữ đồng rời khỏi điện bằng độn quang."},{"chuong":1603,"tieuDe":"Địa Linh Tộc Cùng Địa U Chiến Xa","tomTat":"Sau khi Nhân Diện Giao rời đi, Hàn Lập vẫn nghi hoặc về mối liên hệ mà đối phương ám chỉ, đồng thời nhận thấy mình bị nhiều dị tộc và tu sĩ Hợp Thể chú ý. Thanh niên họ Phỉ cảnh cáo nhóm họ Lục tránh xa Tử Vi hải, còn Tiêu Bố Y sắp xếp cho lão giả họ Lục dưỡng thương và giữ phụ nhân cùng hai người đồng hành ở lại chủ trì đấu giá hội. Lam lão giả nhận lại linh thạch rồi rời khỏi đại điện vì không muốn tiếp tục tham gia. Phụ nhân đưa Địa U chiến xa lên đài; bộ chiến xa có nguồn gốc từ Địa Linh Tộc, sở hữu bốn khôi lỗi kỵ sĩ Luyện Hư trung kỳ và khả năng hút thần niệm dò xét. Nữ tử che mặt mua bộ chiến xa với giá hai triệu hai ngàn vạn linh thạch, khiến người dự hội kinh ngạc. Sau đó, Kim Lôi Trúc của Hàn Lập được đưa lên đấu giá, phát ra điện hồ màu vàng và khiến nhiều người nhận ra Ích Tà Thần Lôi cùng Mộc thần lôi."},{"chuong":1604,"tieuDe":"Phệ Linh Hỏa Điểu Cùng Lưu Ly Thiên Hỏa Dịch","tomTat":"Hàn Lập theo dõi cuộc tranh đoạt Kim Lôi Trúc tại đấu giá hội Vân thành và nhận ra các thánh tộc đặc biệt coi trọng linh trúc này. Nữ tử che mặt cuối cùng mua được Kim Lôi Trúc với giá ba triệu bảy trăm ngàn linh thạch, mặc cho nam tử họ Kinh lên tiếng đe dọa. Tiêu Bố Y tiếp tục đưa Vạn Diệu Đan ra làm vật phẩm áp trục, khiến Hàn Lập nảy ý định tìm đan phương để tự luyện chế nhằm chuẩn bị cho việc đột phá Hợp Thể Kỳ. Trở về động phủ tại Vân Mộng Sơn, Hàn Lập tính toán kế hoạch vào Nghiễm Hàn Giới, hỗ trợ Thạch Kiến Tộc, Thải Lưu Anh và Đoạn Thiên Nhận, sau đó trở về Phong Nguyên Đại Lục. Hắn muốn tu luyện đến đỉnh phong Luyện Hư Sơ Kỳ trước khi tiến vào Nghiễm Hàn Giới để tìm cơ hội đột phá Luyện Hư Trung Kỳ. Cuối chương, Hàn Lập mở Lưu Ly Thiên Hỏa Dịch thứ phẩm để kiểm nghiệm và khiến hỏa diễm bạc hóa thành Phệ Linh Hỏa Điểu. Hỏa điểu bị hỏa dịch thu hút, tự bay tới trước khi Hàn Lập kịp ra lệnh."},{"chuong":1605,"tieuDe":"Việt Tông","tomTat":"Hàn Lập ngăn Phệ Linh hỏa điểu nuốt Thiên Hỏa Dịch trước khi dùng pháp quyết, quang trận ngũ sắc và bí thuật thần niệm để kiểm nghiệm vật chất này. Sau khi xử lý, hắn cho hỏa điểu hấp thu một phần, còn phần còn lại được thu vào bình ngọc. Hàn Lập nhận ra hỏa dịch có những công hiệu chủ yếu của Lưu Ly Thiên Hỏa Dịch chân chính nhưng vẫn lẫn tạp chất chưa rõ. Hắn dùng Đằng Long Đan rồi bế quan tu luyện Phạm Thánh Chân Ma Pháp Tướng trong ba tháng. Khi nhận tin Nghiễm Hàn Giới mở ra, Hàn Lập rời mật thất đến cửa hàng bí mật gặp Tiêm Tiêm. Tiêm Tiêm dùng pháp bàn đưa hắn vào khe không gian riêng và giới thiệu Việt Tông, thợ săn ma thú nổi tiếng tại Ma Kim Sơn mạch, người sẽ hỗ trợ chuyến tiến vào sơn mạch."},{"chuong":1606,"tieuDe":"Kỳ Lân","tomTat":"Tiêm Tiêm mời Việt Tông, một thợ săn ma thú từng ba mươi bảy lần vào Ma Kim Sơn Mạch, làm người dẫn đường cho nàng và Hàn Lập. Việt Tông chấp thuận với điều kiện chỉ phụ trách tìm đường và xử lý ma thú trên lộ trình, đổi lại một phần Vạn Niên Thủy Chi Linh Dịch. Qua lời giải thích của hắn, Hàn Lập biết ma khí có thể khiến địa hình sơn mạch biến đổi nhanh chóng và làm những nơi từng an toàn trở thành sào huyệt ma thú. Ba người thống nhất xuất phát sau ba ngày rồi Hàn Lập dùng truyền tống trận rời đi chuẩn bị. Việt Tông sau đó tiết lộ sơn mạch đang bước vào chu kỳ năm trăm năm phun trào ma khí, khiến cả vùng ngoại vi cũng có thể xuất hiện ma thú cường đại. Tiêm Tiêm thừa nhận nàng phải tiến vào nơi này trong vòng hai năm và đã cố ý giấu Hàn Lập tình hình nguy hiểm vì muốn mượn thần thông ma đạo của hắn. Sau khi Việt Tông rời đi, nàng gọi ra một tiểu thú màu xanh có hình dáng gần giống Kỳ lân Chân linh nhưng thân thể mờ nhạt đến mức dường như có thể tan biến theo gió."},{"chuong":1607,"tieuDe":"Kỳ Ảnh","tomTat":"Tiêm Tiêm hỏi Kỳ Ảnh về thời điểm mở Chân linh chi huyệt và nguồn gốc thông tin mà hắn nắm giữ. Kỳ Ảnh kể lại việc từng muốn phụ thân vào thai nhi Tiêm Tiêm nhưng thất bại, sau đó hình thành quan hệ cộng sinh với hồn phách của nàng. Vì đang mắc tại bình cảnh, Tiêm Tiêm quyết định sớm cùng Hàn Lập và Việt Tông tiến vào Ma Kim Sơn Mạch, đồng thời lo ngại nơi đó đã bị ma thú hoặc phân thần Kỳ lân khác chiếm trước. Kỳ Ảnh đánh giá Việt Tông có thể che giấu sát chiêu, còn Hàn Lập nguy hiểm hơn nhiều, nên tạm thời ẩn mình để tránh bị phát hiện. Ba ngày sau, Hàn Lập, Việt Tông và Tiêm Tiêm tập hợp gần Vân thành rồi khởi hành. Sau một tháng phi hành, họ đến Thanh linh vân hải, cấm chế được Việt Tông xác nhận là lối vào duy nhất của Ma Kim Sơn Mạch."},{"chuong":1608,"tieuDe":"Chi Tiên","tomTat":"Hàn Lập, Việt Tông và Tiêm Tiêm theo thông đạo kim quang tiến vào vụ hải bên ngoài Ma Kim Sơn Mạch. Việt Tông dẫn hai người đến Lôi Vân Các, giải thích rằng họ cần lĩnh Ích Lôi Phiên mới có thể chính thức tiến vào sơn mạch. Tại tầng ba, hơn ba mươi tu sĩ đang tụ tập, trong đó có nhiều cường giả từ Luyện Hư sơ kỳ đến Luyện Hư đỉnh giai. Ngạn tiền bối kể về Chi Tiên hình người đã đánh trọng thương một tu luyện giả rồi trốn vào Ma Kim Sơn Mạch. Các tu sĩ cho biết Chi Tiên thông linh thổ mộc, dường như luyện thành Phù quang hóa ảnh, bị Kim nguyên cấm quang đánh trúng nhưng vẫn xuyên qua Vạn Lôi Áp Đỉnh của Lôi Vân Đại Trận."},{"chuong":1609,"tieuDe":"Châm Ngòi","tomTat":"Một thanh niên kể rằng Chi tiên đang bị Kim Nguyên Cấm Quang áp chế và có thể bị truy tung trong phạm vi trăm dặm, khiến nó trở thành mục tiêu săn bắt trong thời hạn một tháng. Cốc tiền bối thuộc Thánh tộc đưa ra thù lao lớn gồm Vạn Diệu Đan, Vạn Niên Bích Liên Hoa và linh thạch để đổi lấy Chi tiên, bất kể sống chết. Quy định vào Ma Kim Sơn Mạch được khôi phục, người muốn tiến vào phải vượt qua trắc nghiệm mới được cấp Ích Lôi Tán. Nhóm của lão già họ Ngạn mời Việt Tông truy bắt Chi tiên; ông từ chối nhưng nhận tướng mạo Chi tiên và truy tung pháp bàn. Hàn Lập chất vấn Tiêm Tiêm vì đã che giấu nguy hiểm của ma khí và ma thú, rồi cảnh cáo sẽ chấm dứt hợp tác nếu việc này tái diễn. Cuối chương, một trung niên dị tộc ép Việt Tông ngày hôm sau cùng hắn và Miêu đạo hữu vào Ma Kim Sơn Mạch, khiến lão già họ Ngạn đứng ra chất vấn."},{"chuong":1610,"tieuDe":"Ra Tay","tomTat":"Phe dị tộc dựa vào ưu thế nhân số và cường giả đỉnh giai để ép Việt Tông đi theo, nhưng lão giả họ Ngạn viện dẫn quy củ của Lôi Vân Trấn, yêu cầu giải quyết tranh chấp bằng đấu pháp giữa những người cùng cảnh giới. Khi Tiêm Tiêm truyền âm cầu viện, Hàn Lập biết Việt Tông giữ vai trò dẫn đường tới nơi ẩn thân của thánh giai ma thú nên quyết định ra tay giúp đỡ. Hàn Lập đứng ra đưa ra lựa chọn thứ ba, trực tiếp nghênh chiến dị tộc tóc xanh và dùng Nguyên Từ Thần Quang phối hợp với cự lực của Phạm Thánh Chân Ma Công hóa giải toàn bộ công kích của đối phương. Sau đó, hắn biến quang thủ thành Hắc hồ sơn, phá tan hộ thể linh quang rồi trấn áp dị tộc tóc xanh, khiến toàn bộ đại sảnh chấn động và phe họ Khuê phải thừa nhận chênh lệch thực lực. Mẫn chấp sự ngăn Khuê tiền bối tiếp tục giao chiến trong Lôi Vân Các, đồng thời công bố quy trình kiểm tra trước khi tiến vào Ma Kim Sơn Mạch. Khi đến lượt tiếp theo, Hàn Lập chủ động cùng Tiêm Tiêm lên tầng trên kiểm tra, còn nàng tiết lộ đã chuẩn bị trước cho thử thách bí mật này."},{"chuong":1611,"tieuDe":"Sơ Nhập Ma Kim Sơn Mạch","tomTat":"Hàn Lập lên tầng bốn lầu các kiểm tra và được Mẫn chấp sự miễn kiểm tra nhờ năng lực đã thể hiện trước đó. Hắn nhận chủ Ích Lôi Tán, đồng thời biết pháp khí chỉ có hiệu lực một tháng và người mắc kẹt trong Ma Kim Sơn Mạch có thể bị ma khí ma hóa thành ma vật. Tiêm Tiêm bất chấp nguy hiểm, dùng các bí thuật thanh tâm trấn thần để vượt qua huyễn cảnh kiểm tra và nhận Ích Lôi Tán. Trong lúc chờ đợi, Hàn Lập thăm dò thị trấn, phát hiện một đại trạch viện được cấm chế cao minh bảo vệ nhưng không cưỡng ép xâm nhập. Việt Tông cũng được miễn kiểm tra nhờ danh khí của mình. Sau đó Hàn Lập, Tiêm Tiêm và Việt Tông kích phát Ích Lôi Tán, xuyên qua thế giới lôi điện và chính thức tiến vào Ma Kim Sơn Mạch."},{"chuong":1612,"tieuDe":"Quạ Ma Xuất Hiện","tomTat":"Hàn Lập dùng Minh Thanh Linh Mục thăm dò vụ hải nhưng nhận ra ma khí hạn chế cả tầm nhìn lẫn thần niệm. Tiêm Tiêm giao thạch phiến ghi địa điểm cho Việt Tông, và ba người chọn tuyến đường trung gian để kịp tới nơi trong mười ngày. Sau đó, nhiều toán tu sĩ lần lượt tiến vào Ma Kim Sơn Mạch, gồm đội của đại hán mặt đen, Khuê Hoán, lão giả họ Ngạn và người của Lôi Vân Quỹ. Ba ngày sau, Việt Tông dùng viên châu màu trắng giết hơn mười ma nha xuất hiện bất thường ở ngoại vi, từ đó nghi chúng bị ma thú có linh trí điều động. Nhóm Hàn Lập quyết định tăng độn tốc để dụ kẻ theo dõi lộ diện và sẵn sàng tiêu diệt nó nếu không thể cắt đuôi. Khi ba người biến mất ở chân trời, trong vụ hải cách đó khoảng mười dặm lóe lên huyết quang cùng hơn mười con mắt đỏ."},{"chuong":1613,"tieuDe":"Đa Nhãn Ma","tomTat":"Hàn Lập, Tiêm Tiêm và Việt Tông phi hành qua Ma Kim Sơn Mạch thì bị đàn chuột bay ma thú quấy nhiễu, nhưng Tiêm Tiêm nhanh chóng dùng kim mang tiêu diệt chúng. Việt Tông phát hiện một ma thú cao giai vẫn bám theo phía sau, còn Hàn Lập dùng Minh Thanh Linh Mục xác nhận vị trí của nó. Hàn Lập từ chối phương án bố trí cạm bẫy, triển khai cánh trong suốt và chủ động nghênh chiến. Hắn nhanh chóng chém chết Đa Nhãn Ma trước khi nó kịp thi triển nhiếp hồn thuật, rồi mang phần đầu về cho Việt Tông nhận dạng. Tiêm Tiêm nhận định mắt mê hồn của ma thú là tài liệu luyện khí quý, sau đó cả ba thu hồi phần đầu và tiếp tục lên đường. Gần nửa ngày sau, lão giả trong mây đen phát hiện Đa Nhãn Ma là con mình, ra lệnh cho Cửu Dạ và Ngũ Khấp truy tìm hung thủ. Cửu Dạ gọi tàn hồn từ thi thể, còn Ngũ Khấp lần theo khí tức và xác định nhóm Hàn Lập gồm một người trực tiếp ra tay cùng hai kẻ ngoại lai đồng hành."},{"chuong":1614,"tieuDe":"Ma Ảnh Tàn Sát Bừa Bãi","tomTat":"Ngũ Khấp dùng tàn hồn còn sót lại trong thi thể thiếu chủ để tái hiện hình ảnh Hàn Lập, giúp lão giả ma tộc xác định hắn là hung thủ đã phá giải thần thông thuấn di của con mình bằng Phá Diệt Pháp Mục. Vì phân thân Thủy tổ sắp thức tỉnh và không thể chậm trễ nghênh đón, lão giả giao Cửu Dạ lần theo khí tức nhóm Hàn Lập, còn mình cùng Ngũ Khấp mang thi thể thiếu chủ rời đi. Ở một nơi khác trong Ma Kim Sơn Mạch, hai tu sĩ Linh giới đang dựa vào pháp bàn và thuật bói toán để tìm Chi tiên thì bất ngờ bị Thiết Ma cùng Cự thủ phục kích, một người bị quang nhận màu đen chém chết, người còn lại bị nuốt sống. Cự thủ dùng Hấp hồn thuật tiêu hóa nguyên thần nạn nhân, biết được mục đích của họ là tìm linh thảo thông linh có thể hóa hình người. Thiết Ma lập tức nảy sinh hứng thú với Chi tiên, đồng thời quyết định thanh trừ mọi biến số có thể ảnh hưởng đến thời khắc Thủy tổ thức tỉnh."},{"chuong":1615,"tieuDe":"Ngân Giao, Quái Trùng","tomTat":"Cự sí nam tử nhận ra những người Linh giới đang truy tìm Hóa hình Ma tiêu và bí mật sai Cự thủ triệu tập ma thú tìm Chi tiên. Cự thủ giao lại pháp bàn truy tung còn nguyên vẹn, còn Cự sí nam tử rời đi lo việc cung nghênh Thủy tổ đại nhân. Hai ngày sau, Khuê Hoán truy sát ba lam bào nhân, dùng chiến giáp bạc hóa thành Ngân giao rồi phóng huyết quang từ Huyết hồng châu để tiêu diệt cả ba. Ở một nơi khác, Hàn Lập, Tiêm Tiêm và Việt Tông gặp dải sương trắng chứa sát khí chắn ngang sơn mạch. Vì mục tiêu chuyến đi quan trọng, Hàn Lập quyết định tiến vào thay vì quay lại; Việt Tông cũng liều mạng đi theo vì từng chịu ân của hắn, còn Tiêm Tiêm dựa vào thủ đoạn bảo mệnh của mình. Khi vào sương mù, Hàn Lập thi triển Linh mục thần thông và dùng tiểu thuẫn Quái nga hộ thân, trong khi Việt Tông mở chiếc hòm chứa một quái trùng mập có các điểm bạc và khuôn mặt quỷ dị trên đầu."},{"chuong":1616,"tieuDe":"Nhân Diện Thứu","tomTat":"Tiêm Tiêm, Hàn Lập và Việt Tông tiếp tục di chuyển trong khu vực sương mù, nơi tầm nhìn bị hạn chế và có ma thú cấp cao ẩn nấp. Quái trùng của Việt Tông phát hiện năm yêu ma đang nhanh chóng tiến đến từ hướng tây nam. Hàn Lập lập tức bố trí Xuân Lệ kiếm trận, che giấu trận thế để bảo vệ hai đồng hành. Tiếng kêu của năm ma cầm làm Việt Tông mờ mịt, nhưng Tiêm Tiêm dùng phù hàn vụ giúp hắn thanh tỉnh, còn Đại Diễn Quyết giúp Hàn Lập khôi phục tâm thần. Năm ma cầm mặt nữ xuất hiện, trong đó con đầu đàn đạt Luyện Hư hậu kỳ và biết nói tiếng người. Hàn Lập dùng năm viên Bạo Lôi Châu đánh trúng đội hình, khiến cả năm ma cầm bị thương; bốn con bị thương sau đó nổi giận lao về phía hắn."},{"chuong":1617,"tieuDe":"Kim Ô Chân Hỏa","tomTat":"Hàn Lập dùng Xuân Lệ kiếm trận vây bốn ma cầm phi hành, khiến chúng mắc trong rừng cự mộc có cảnh vật hư thực đan xen. Bốn ma cầm thử dùng bạch sắc hỏa điệp phá trận nhưng không thành công, còn một con bị lực phản chấn đánh bật khi lao vào cự mộc. Ma cầm cầm đầu sau đó thi triển Kim Ô Chân Hỏa, làm kiếm trận hiện hình và khiến Tiêm Tiêm nhận ra khả năng nó mang huyết mạch Chân linh Kim Ô. Hàn Lập gọi Phệ Linh Thiên Hỏa ra giao chiến, truyền chân nguyên để ngân sắc hỏa điểu áp đảo bạch hỏa, nhưng ma cầm lập tức dùng ma hạch hóa thành vô số châm nhỏ phản công. Hàn Lập dùng Thủy tinh thuẫn làm lệch hướng công kích rồi dùng ngũ sắc quang mang thu sạch những châm còn lại. Khi Phệ Linh hỏa điểu suy yếu, Hàn Lập hóa thành ngũ sắc Thải phượng, mở khe hở hư không và xuyên qua đó để xuất hiện bên cạnh chiến trường."},{"chuong":1618,"tieuDe":"Kỳ Độc Tái Hiện","tomTat":"Hàn Lập biến ảo thành Thải phượng bằng Kinh Chập Thập Nhị Quyết rồi dùng không gian thần thông Thiên Phượng tiến vào trận chiến giữa Phệ Linh hỏa điểu và ma cầm Kim Ô biến dị. Huyết mạch Thiên Phượng khiến ma cầm sợ hãi, trong khi Linh Tuyền Tà Quang đánh bật công kích của nó, xuyên thủng ma hạch màu trắng và đâm vào đầu nó. Ma cầm phá vỡ thanh quang, ngưng tụ Kim Ô pháp tướng và chuẩn bị phản kích, nhưng độc lực của Linh Tuyền Tà Quang đột ngột phát tác khiến nó hóa thành độc thủy. Phệ Linh hỏa điểu nuốt độc thủy, Kim Ô pháp tướng và phần bạch diễm còn lại để hấp thu chiến lợi phẩm. Hàn Lập thu lấy ma hạch màu trắng, hơn trăm tế châm cùng tàn thi của bốn ma cầm Luyện Hư sơ kỳ bị Xuân Lệ kiếm trận chém giết. Khi trở về, hắn khiến Việt Tông kinh hãi trước thực lực vượt xa biểu hiện tu vi của mình."},{"chuong":1619,"tieuDe":"Giết Chóc","tomTat":"Tiêm Tiêm cảnh báo trong vụ hải có thể còn ma thú ẩn náu, khiến Hàn Lập, Tiêm Tiêm và Việt Tông nhanh chóng rời khỏi khu vực nguy hiểm rồi tiếp tục lên đường. Một nữ tử tai nhọn dùng sương bạc lần theo khí tức của nhóm và xác định hướng truy đuổi. Trong sơn cốc sâu của Ma Kim Sơn Mạch, Cự Thử tập hợp hơn một ngàn ma thú, ra lệnh săn giết người ngoại lai, đoạt pháp bàn để tìm Chi tiên và dâng linh vật cho Thiết Ma. Cuộc tập hợp bị vẹt huyết sắc bí mật theo dõi; sau khi tự bạo truyền tin, nó khiến đại hán trong thạch phòng nghi ngờ hành động của Thiết Sí và sai Huyết Anh điều tra. Ở ngoại vi sơn mạch, nhiều dị tộc và ma thú giao chiến, trong đó ma điểu độc giác cầm đầu cướp được một pháp bàn, còn lão già họ Ngạn cùng bạch diện thanh niên dùng bùa vàng thoát khỏi quái vân. Sau vài ngày, hơn phân nửa dị tộc tiến vào sơn mạch đã chết, ma thú vẫn không tìm thấy Chi tiên, trong khi nhóm Hàn Lập bình an tiếp cận mục tiêu."},{"chuong":1620,"tieuDe":"Khách Tới Ngoài Ý Muốn","tomTat":"Hàn Lập, Tiêm Tiêm và Việt Tông đến một dãy núi để tìm cửa vào khu vực bí mật, sau đó Việt Tông ở lại còn hai người theo Ma Yên Điểu tiến sâu vào sơn mạch. Linh điểu tìm ra cửa động bị vách đá cùng khói đen che giấu và xác nhận thánh giai ma thú bên trong vẫn đang ngủ. Hàn Lập dùng kim quang hộ thể một mình tiến vào động phủ để đánh phủ đầu, trong khi Tiêm Tiêm cùng hư ảnh Kỳ Lân chờ cuộc giao chiến nổ ra nhằm tranh thủ mở Chân linh chi huyệt. Ở bên ngoài, Việt Tông phát hiện dấu hiệu bất thường từ quái trùng rồi chạm trán Khuê Hoán, kẻ đang truy hỏi tung tích những người còn lại. Việt Tông thả quái trùng, dùng phù lục, pháp bảo và độn thuật để chống trả rồi bỏ chạy, nhưng Khuê Hoán phân hóa thành ba thân ảnh và lần lượt phá tan mọi thủ đoạn. Một thân ảnh hóa thành Ngân giao, đánh gãy hai bạch cốt phi kiếm rồi dùng hạt châu màu hồng biến Việt Tông thành máu huyết và thôn phệ hắn. Sau khi hợp nhất trở lại, Khuê Hoán suy đoán nhóm Hàn Lập cũng đang tìm vật bí mật trong khu vực, phát hiện một người khác ẩn nấp gần đó và phóng ngân sắc phi đao công kích."},{"chuong":1621,"tieuDe":"Các Trình Tâm Cơ","tomTat":"Khuê Hoán dùng phi đao công kích nơi Cửu Dạ ẩn thân nhưng không thành công rồi hóa thành huyết quang rời đi. Sau khi hiện thân, Cửu Dạ nhận định đối phương rất mạnh, xác định cần cầu viện và phát tín hiệu bằng những ngân mang từ nhung mao ở đuôi. Hàn Lập theo Ma Yên Điểu tiến vào hệ thống thông đạo ma khí dưới lòng núi, sau đó chế trụ nó khi tới gần một lối ra có bạch quang. Hắn bố trí ngân sắc hỏa điểu, bảy mươi hai phi kiếm, Giáp Nguyên Phù và Thái Nhất Hoá Thanh Phù để chuẩn bị đối phó ma thú thánh giai. Tiêm Tiêm cùng hư ảnh Kỳ lân quyết định hành động sớm, dùng Ma Lân Lệnh tạo hắc phong rồi dùng tiểu kiếm xanh lấy tinh huyết làm vật dẫn. Hắc phong tan biến, để lộ Mặc Kỳ lân có cơ thể dài hơn một trượng."},{"chuong":1622,"tieuDe":"Đánh Lén","tomTat":"Tiêm Tiêm dùng những ký hiệu màu đen khống chế hư ảnh Mặc kỳ lân, rồi cùng thanh sắc Kỳ lân tiến vào ma khí để tiếp tục mục tiêu bí mật. Hàn Lập ẩn thân tiến vào một đại sảnh hình tròn, phát hiện Cự viên màu đen đạt Hợp Thể trung giai đang trọng thương trên huyết sắc đại sàng và được pháp trận cùng mười hai cột đá bảo vệ. Nhờ Phệ Kim Trùng biến dị có năng lực liễm khí hóa thạch, hắn vừa duy trì trinh sát bên ngoài vừa âm thầm bố trí phù lục, viên châu và linh trùng quanh mục tiêu. Sau khi cân nhắc mục đích chưa rõ của Tinh Tộc nữ tử, Hàn Lập quyết định tạm bỏ qua chuyện đó và đánh lén Cự viên để đoạt tinh hạch. Linh Tuyền Tà Quang xuyên qua huyết sắc hộ quang nhưng bị tử sắc chiến giáp của Cự viên đánh bật. Hàn Lập lập tức triệu xuất pháp tướng kim sắc ba đầu sáu tay, hợp ba đạo kiếm quang thành tam sắc kiếm quang, đồng thời kích phát các viên châu đánh sập mười hai cột đá. Khi màn hộ quang bị điện hồ áp chế, tam sắc kiếm quang và hai Phệ Kim Trùng cùng xông vào, khiến cuộc tập kích bước sang đợt công kích toàn lực."},{"chuong":1623,"tieuDe":"Tam Nguyên Trảm Và Tàn Nhận","tomTat":"Hàn Lập thi triển Tam Nguyên Trảm bằng cách dung hợp chân nguyên của Phạm Thánh Chân Ma Công, Thanh Nguyên Kiếm Quyết và Kim Cương Quyết, nhưng một lần phát động đã tiêu hao khoảng một nửa chân nguyên. Điện hồ, kiếm quang và hai con Phệ Kim Trùng đồng loạt đánh vào Ma viên, song huyết quang từ chiếc giường màu máu đã hỗ trợ chiến giáp chống đỡ. Hàn Lập tiếp tục dùng Phệ Linh hỏa và kim sắc cự phong, khiến pháp trận tử sắc cùng đại sảnh bị phá hủy nghiêm trọng, nhưng Ma viên vẫn sống và giữ chặt hai con Phệ Kim Trùng. Trước người Ma viên xuất hiện một tàn nhận tử sắc bán trong suốt, bên trong chứa sinh vật dị hình có linh áp kinh người. Hàn Lập kích phát Cưu Cung Thiên Kiền phù để triệu hồi quang trận và hư ảnh cung điện, nhưng tàn nhận phóng tử ngân chém đôi toàn bộ thế công. Ma viên lập tức biến mất khỏi vị trí cũ, áp sát tung quyền kèm âm lãng vô hình, trong khi tử ngân và khí lãng đồng thời phủ xuống chỗ Hàn Lập."},{"chuong":1624,"tieuDe":"Huyệt Linh","tomTat":"Tiêm Tiêm và hư ảnh Kỳ lân đi tới cuối thông đạo, dùng viên châu màu xanh thăm dò thạch bích và xác định đúng vị trí Chân linh chi huyệt. Tiêm Tiêm bố trí pháp trận bằng bộ trận kỳ đặc chế, phá hủy chuông nhỏ màu xanh cùng ngọc như ý màu trắng rồi dung hợp linh huyết của Bát túc nguyên thú và Bất tử điểu làm vật dẫn. Huyệt linh hiện ra, nuốt Chân linh huyết và bị pháp trận làm ngủ say, khiến miệng nó hóa thành con đường dẫn xuống lòng đất để Tiêm Tiêm cùng Kỳ lân tiến vào. Khuê Hoán nhận được cảnh báo từ cấm chế đã bố trí trước nên lập tức dùng huyết độn bám theo, còn Cửu Dạ sau khi suy đoán nguồn ma khí cũng tiến vào thông đạo. Trong đại sảnh, Hàn Lập duy trì hình thái ba đầu sáu tay để trực tiếp đối kháng Ma viên và dùng quang mạc làm lệch khí lãng từ hai nắm tay đối phương. Hai Phệ Kim Trùng đồng thời thay nhau áp sát Huyền Thiên tàn nhận, lợi dụng khoảng dừng giữa các lần phát kích để ngăn nó thoát ra tấn công Hàn Lập."},{"chuong":1625,"tieuDe":"Hồn Thể Phân Nguyên Đại Pháp","tomTat":"Hàn Lập giằng co với Ma viên bằng Nguyên Từ Thần Quang, Ngũ sắc hàn diễm, Phệ Kim Trùng, pháp tướng và nhiều pháp bảo, nhưng vẫn bị sức mạnh thân thể cùng chiến giáp màu tím của đối phương áp chế. Hắn dùng thanh ti từ tiểu đỉnh màu xanh và lôi độn để dẫn Ma viên về phía Xuân Lệ kiếm trận. Khi đến cửa đại sảnh, Hàn Lập bị giường màu máu và huyết ảnh tập kích, cánh tay đỏ xuyên thủng thân thể hắn. Hoá Linh phù thế thân giúp hắn tránh trọng thương, nhưng lá phù cần hơn trăm năm bồi dục mới có thể dùng lại. Huyết ảnh nhập vào chiến giáp khiến Ma viên khôi phục khí thế, sau đó Ma viên xác nhận đã dùng Hỗn Thể Phân Nguyên Đại Pháp để chia lìa hồn và thể chữa thương. Hàn Lập cũng nhận ra Ma viên đã hồi phục nguyên thần bảy tám phần và biết công pháp hắn tu luyện có nguồn gốc từ Ma giới."},{"chuong":1626,"tieuDe":"Yêu Viên Linh Mục","tomTat":"Hàn Lập nhận ra nguyên thần của Ma viên chưa khôi phục như lời đối phương nói và chủ động lùi vào ma khí để dụ địch truy kích. Hắn dùng tiểu sơn màu xám làm đòn nghi binh, đồng thời ngưng tụ Ích Tà Lôi Châu khiến Ma viên lập tức tìm cách ngăn cản. Hai giáp sĩ do Giáp Nguyên Phù biến thành đã làm chậm Ma viên, giúp Hàn Lập phát động Xuân Lệ kiếm trận. Ma viên dùng đôi yêu mục có tử mang và ký hiệu ngũ sắc để nhìn thấu huyễn thuật, bắt được Thanh Trúc Phong Vân Kiếm thật. Hàn Lập khiến phi kiếm hư hóa thoát khỏi tay đối phương, nhưng sau đó phát hiện Ma viên còn có thể xuyên qua kiếm trận để khóa chính xác vị trí của hắn."},{"chuong":1627,"tieuDe":"Kiếm Trận Vây Ma","tomTat":"Ma viên phun tinh khí hắc hồng vào tử sắc cự kiếm, chém ra kiếm quang tử sắc tấn công Hàn Lập. Hàn Lập điều khiển Xuân Lê kiếm trận cùng hai khôi lỗi chống đỡ nhưng các cột sáng và đao ảnh đều bị phá, sau đó hắn dốc toàn bộ pháp lực khiến thanh liên trong kiếm trận liên tục tái sinh và chặn được kiếm quang. Hàn Lập nhận ra tu vi Ma viên đã suy yếu, nhưng tử sắc chiến giáp và tàn nhận vẫn khiến đối phương khó đối phó. Hắn dùng phù toản màu xanh, kim sắc viên châu và thái cực ký hiệu để phát động Tế lôi thuật, đồng thời biến hóa kiếm trận thành rừng rậm, giáp sĩ, mũi tên xanh và bàn tay đất nhằm đánh lạc hướng Ma viên. Khi Ma viên mất cảnh giác và định chém bàn tay đất, Ích Tà Thần Lôi từ trên không hóa thành kim sắc quang tuyền giáng xuống đỉnh đầu nó, khiến sắc mặt Ma viên đại biến."},{"chuong":1628,"tieuDe":"Sơn Nhạc Chân Linh","tomTat":"Thánh giai Ma viên dùng tử sắc cự kiếm chống đỡ Tế lôi thuật và Ích Tà Thần Lôi, đồng thời vận chuyển ma khí để duy trì thế phòng thủ. Hàn Lập lợi dụng kiếm trận che mắt, giấu Nguyên Từ Thần Sơn dưới trận rồi bất ngờ đánh văng Ma viên và phát động sát cục liên hoàn bằng lôi quang, tế ti, pháp tướng cùng khôi lỗi. Ma viên tuy bị phá hỏng chiến giáp và trọng thương thân thể nhưng nguyên thần vẫn mang tàn nhận thoát khỏi quang đoàn, chém vỡ các đợt công kích tiếp theo. Sau đó nó hiến tế thân thể đã tĩnh dưỡng hàng trăm năm, dùng tàn nhận hút hết tinh huyết và lực lượng còn lại để triệu ra tử sắc hư ảnh có hoa văn chữ Sơn trước ngực."},{"chuong":1629,"tieuDe":"Tái Hiện Huyền Thiên","tomTat":"Hàn Lập nhận ra pháp tướng Sơn Nhạc Cự Viên của Ma viên và định dùng Phệ Kim Trùng kết hợp Xuân Lệ kiếm trận để đoạt chân linh huyết. Trước khi kế hoạch được thực hiện, Ma viên dùng huyết hà thúc đẩy Huyền Thiên tàn nhận hấp thu thực ma khí trong thông đạo, khiến tàn nhận khôi phục đầy đủ và hiển lộ uy lực Huyền Thiên Chi Bảo. Sự cộng hưởng giữa tàn nhận và Huyền thiên kiếm bị phong ấn trong cánh tay khiến Hàn Lập phải dùng hơn nửa pháp lực để áp chế bảo vật. Khi pháp tướng Sơn Nhạc Cự Viên cầm tàn nhận phát hắc sắc khí lãng phá tan Xuân Lệ kiếm trận, Hàn Lập buông áp chế và giải phóng Huyền Thiên Quả Thực. Phạm Thánh pháp tướng truyền lực vào bảo vật, kích phát một đạo kiếm mang xanh biếc có thuý sắc ký hiệu để phản kích."},{"chuong":1630,"tieuDe":"Diệt Viên","tomTat":"Hàn Lập dồn pháp lực cùng sức mạnh của Phạm Thánh Chân Ma pháp tướng vào Huyền Thiên kiếm, tạo ra kiếm quang xanh biếc áp đảo hắc lãng của Ma viên và phá tan Xuân Lệ kiếm trận ở giữa. Ma kiếm cùng Sơn Nhạc Cự Viên pháp tướng lần lượt tan vỡ, còn nguyên thần Ma viên bị thiên địa chi lực cố định, đánh nát và cuốn vào hắc động. Huyền Thiên kiếm sau đó trở lại hình thái Huyền Thiên Quả Thực, tự chui vào cánh tay Hàn Lập và hóa thành một ấn ký vàng dần mờ đi. Hàn Lập triệu hồi những điểm thanh quang còn lại, giúp bảy mươi hai Thanh Trúc Phong Vân Kiếm tái ngưng tụ nhờ thần thông hóa hư. Khi chiến giáp tím của Ma viên tự phân tách bỏ chạy, hắn dùng tế ti màu đen khống chế rồi lấy Hư Thiên Đỉnh cưỡng ép thu giữ. Cuối cùng, Hàn Lập dùng phi kiếm khoét thủng đan điền thi thể Ma viên và khiến một vật chưa rõ rơi ra."},{"chuong":1631,"tieuDe":"Huyền Thiên Luyện Khí Thuật","tomTat":"Sau trận chiến, Hàn Lập thu ma hạch của thánh giai Ma viên vào hộp ngọc và dùng phù lục bạc phong bế ma khí để dành làm nguyên liệu tu bổ ma giáp. Hắn thử nghiệm Huyền Thiên tàn nhận, nhận ra vật này có thể điều động một phần pháp tắc chi lực, chống lại ngũ sắc hàn diễm nhưng lại hấp thu ma khí do Phạm Thánh Chân Ma Công tạo ra. Tàn nhận chuyển từ màu tím sang vàng ròng, để lộ linh vật bên trong và hút mất khoảng một phần ba pháp lực, buộc Hàn Lập phải dừng đồng hóa rồi dùng đan dược cùng đỉnh giai linh thạch để hồi phục. Sau đó, hắn thu thây khô của Ma viên và kiểm tra đại sảnh, nơi chỉ còn pháp trận hư tổn cùng huyết sắc ngọc sàng. Linh mục thần thông giúp hắn nhận thấy bí mật của ngọc sàng, còn những pháp quyết tiếp theo khiến cổ văn màu bạc hiện ra và hợp thành một thiên kinh văn. Hàn Lập nhận ra đó là Ngân khoa văn mang tên Huyền Thiên luyện khí thuật, một phát hiện khiến hắn vô cùng kinh ngạc."},{"chuong":1632,"tieuDe":"Sơn Băng","tomTat":"Hàn Lập giải đọc sơ bộ kinh văn bằng Ngân khoa văn và xác định đó là Huyền Thiên luyện khí thuật, nhưng những thủ đoạn như Luyện nhật và Dong hải vượt xa năng lực hiện tại của hắn. Không cam lòng bỏ cuộc, hắn kiểm tra rồi phá chiếc giường của Ma viên, phát hiện Kim khuyết ngọc thư thứ ba ẩn bên trong và cưỡng ép thu vật này khi nó tìm cách né tránh. Sau khi phong kín ngọc thư trong hộp ngọc, Hàn Lập rời đại sảnh, vừa khôi phục pháp lực vừa quyết định tìm đến chỗ Tiêm Tiêm. Một dị biến bất ngờ khiến ma khí trong thông đạo mất khống chế, tạo ra cuồng phong, phong nhận và tiếng tê minh làm pháp lực của hắn nhất thời đình trệ. Dù dùng Nguyên Từ Thần Quang và Đại Diễn Quyết để ứng phó, Hàn Lập vẫn bị cả ngọn núi sụp đổ chôn dưới vô số cự thạch. Khi ngọn núi gần như bị san bằng, Huyệt linh với thân thể dài hơn nghìn trượng bằng hắc quang và hắc sắc lôi điện hiện ra. Nam tử họ Khuê hóa giao long đỏ phá thân quái vật thoát ra, còn Kỳ lân màu xanh hóa gió né hắc sắc hồ quang rồi tái hiện với vẻ kinh sợ."},{"chuong":1633,"tieuDe":"Chân Lân Bản Nguyên","tomTat":"Tiêm Tiêm kể lại việc nàng bị Huyệt linh nuốt sau khi tiến vào Chân linh chi huyệt, nhưng nhờ bí dược đặc chế và thần thông phụ thân của Kỳ lân mà hóa thành hư ảnh Kỳ lân để tránh bị tiêu hóa. Kỳ lân và nam tử họ Khuê xác nhận cả hai đều là những phần thần niệm tách ra từ cùng một bản tôn, đồng thời trình bày hai con đường khôi phục Chân linh thể của mình. Quái vật khống chế Huyệt linh tiết lộ rằng nó đã nuốt nhiều phần thần niệm tương tự và Chân Lân bản nguyên đang nằm trong cơ thể nó. Kỳ lân cùng nam tử họ Khuê tạm thời liên thủ để diệt quái vật và chia đều bản nguyên. Quái vật phát hiện Cửu Dạ đang ẩn nấp rồi dùng hắc sắc cự kiếm diệt sát nàng trong một đòn. Hàn Lập từ dưới núi đá hiện thân, điều khiển bảy mươi hai tiểu kiếm màu xanh chống đỡ hắc sắc cự kiếm, dùng quầng sáng thủy tinh làm lệch kiếm quang và triệu hồi một đóa kim hoa."},{"chuong":1634,"tieuDe":"Linh Chủng Ma Uy","tomTat":"Phệ Kim Trùng trở về và truyền cho Hàn Lập toàn bộ tin tức thu được trong lúc truy tung, giúp hắn biết thêm về Huyệt linh và âm mưu liên quan đến Ma viên. Huyệt linh thừa nhận từng dụ Ma viên đến nơi có ma khí để dưỡng thương, còn Tiêm Tiêm thú nhận đã lợi dụng Hàn Lập nhằm tìm Chân lân bản nguyên. Tiêm Tiêm đề nghị chia một phần bản nguyên và truyền phương pháp luyện hóa nếu Hàn Lập giúp giết Huyệt linh. Huyệt linh phát động linh chủng đã gieo trong cơ thể Tiêm Tiêm và Khuê Hoán, phá hủy hai hóa thân cùng phân hồn của Khuê Hoán, đồng thời khiến Tiêm Tiêm mất khả năng cử động. Sau đó Huyệt linh dùng hắc sắc lôi kiếm kết thành điện võng tập kích Hàn Lập. Hàn Lập dùng bảy mươi hai phi kiếm tạo thành thanh sắc kiếm liên để phá lưới sét, nhưng điện võng tự tái ngưng tụ. Cuối chương, Huyệt linh hóa thành Mặc kỳ lân trấn áp Hàn Lập, song hắn hiện kim sắc lân phiến cùng đôi cánh tay vàng và đánh vỡ trói buộc."},{"chuong":1635,"tieuDe":"Huyễn Hóa Bách Thiên","tomTat":"Hàn Lập dùng cự thủ và kim sắc lôi liên ngăn cự túc cùng hắc lôi của Mặc kỳ lân. Khi đối phương thi triển Đại thôn diệt thuật, Nguyên Từ Thần Sơn bị hắc động cưỡng thu, nhưng Hàn Lập dựa vào Bách Mạch Luyện Bảo Quyết để triệu hồi pháp bảo trở lại. Ngay sau đó, hắn bị nuốt vào một không gian tối trong cơ thể Mặc kỳ lân, nơi thần niệm bị phong tỏa và Linh mục thần thông chỉ có thể quan sát trong phạm vi hạn chế. Mặc kỳ lân tạo hắc bào hóa thân để kiềm chế hắn, song Hàn Lập dùng Kinh Thần Thứ, lôi độn và Ích Tà Thần Lôi đánh tan hóa thân đầu tiên. Phần nguyên thần còn lại tiếp tục phân hóa thành hơn trăm tiểu nhân, bắn ra thủy linh lực nhưng bị Nguyên từ thần quang khắc chế. Các hóa thân tái sinh sau mỗi lần bị phá hủy, cho thấy nguyên thần Mặc kỳ lân gần như bất tử trong chính thân thể nó. Không muốn tiếp tục bị kéo vào cuộc tiêu hao, Hàn Lập lấy Huyền Thiên tàn nhận và quyết định dùng pháp tắc chi lực tung một kích kết liễu đối thủ."},{"chuong":1636,"tieuDe":"Hình Thú","tomTat":"Đề Hồn thú đột nhiên thoát khỏi tay áo Hàn Lập, hóa thành cự quỷ ba mắt và được Huyệt linh kinh hãi gọi là Hình thú. Trong trạng thái cắt đứt liên hệ với chủ nhân, nó dùng Huyết liên khóa chặt quái vật, khiến mọi lần biến hóa hay tự bạo đào thoát của đối phương đều thất bại. Đề Hồn tiếp tục biến một gai xương trên lưng thành Thiên phạt thần mâu mang Kim Triện Văn, bất chấp việc Huyệt linh tự nhận là phân hồn Thiên ngoại Ma quân và xin làm ma nô. Thần mâu xuyên thủng ma diện, còn Đề Hồn nuốt sạch hắc khí cùng các mảnh vỡ rồi trở lại hình dạng tiểu hầu và bất tỉnh vì thể lực, thần niệm khô kiệt. Khi không gian màu đen bắt đầu sụp đổ, Hàn Lập không tìm thấy Chân lân bản nguyên nên thu Đề Hồn và trở về quái điện đá trắng. Tại đó, Tiêm Tiêm và nam tử họ Khuê đã khôi phục hành động; cả hai chất vấn Hàn Lập về Huyệt linh và tung tích Chân lân bản nguyên, nhưng hắn chỉ thừa nhận mình đã tiêu diệt đối thủ."},{"chuong":1637,"tieuDe":"Đồ Lao Vô Công","tomTat":"Hàn Lập dò hỏi Tiêm Tiêm và nam tử họ Khuê về lời tự xưng của hóa thân Thiên ngoại Ma quân vừa bị tiêu diệt. Tiêm Tiêm giải thích đây là tồn tại đỉnh cấp trong Thiên ngoại ma đầu, có thể xâm nhập tâm thần và ma hóa cả Chân linh thành khôi lỗi. Nam tử họ Khuê kiểm tra bụi đen từ thi hài quái vật, xác nhận đó là ma hóa chi trần và cảnh báo bản thể Ma quân có thể quấy nhiễu Hàn Lập khi hắn độ kiếp phi thăng. Cả Tiêm Tiêm lẫn nam tử họ Khuê đều không cảm ứng được Chân lân bản nguyên trên người Hàn Lập, còn Hàn Lập cũng tìm kiếm kỹ phạm vi vài dặm mà không thu được kết quả. Ba người suy đoán bản nguyên đã tản về đại địa hoặc quay lại Chân linh chi huyệt để tái sinh sau vài trăm năm. Do lo tuổi thọ không đủ để chờ đợi, Tiêm Tiêm bác bỏ việc hợp nhất thần niệm theo điều kiện của nam tử họ Khuê, khiến hắn nổi sát ý. Nam tử họ Khuê hứa hậu tạ nếu Hàn Lập rời đi rồi trực tiếp hỏi hắn có định can thiệp vào cuộc đối đầu hay không."},{"chuong":1638,"tieuDe":"Phát Hiện","tomTat":"Tiêm Tiêm hứa sửa Thiên ngoại ma giáp và đưa Hàn Lập trở lại tìm Chân lân bản nguyên, còn Hàn Lập quyết định bảo vệ nàng trước lời lôi kéo của Khuê Hoán. Hai người phối hợp triển khai thần thông, khiến Khuê Hoán nhận thấy bất lợi và dùng phi xa màu đỏ rời đi. Sau đó Hàn Lập yêu cầu phần tài liệu từ thánh giai Ma viên, còn Tiêm Tiêm đồng ý sửa giáp và chuẩn bị lễ vật. Tại nơi từng chia tay Việt Tông, Tiêm Tiêm phát hiện ông rất có thể đã ngã xuống, nên hai người quay về theo đường cũ. Ở phía sau, Ngũ Khấp dẫn hàng trăm ma thú truy kích theo dấu Cửu Dạ để lại, dù viên châu định vị đã nứt và tắt sáng. Cuối chương, lão giả họ Ngạn cùng cung trang nữ tử tranh chấp một sơn cốc khả nghi với dị tộc nhân tóc xanh và hán tử khô gầy."},{"chuong":1639,"tieuDe":"Chặn Đường","tomTat":"Dị tộc nhân tóc xanh tạm từ bỏ ý định động thủ sau khi được hán tử khô gầy nhắc nhở, khiến các nhóm thống nhất trước tiên cùng tiến vào sơn cốc để xác minh tung tích Chi tiên. Lão giả họ Ngạn và Ny nhi phát hiện sơn cốc phủ ma khí, phía dưới sâu quá nghìn trượng vẫn không thấy đáy, trong khi một Hắc Uyên ngạc gần đạt thánh giai đang ẩn dưới bùn đáy sông. Một đoàn ma thú do Cự thử dẫn đầu cũng lần theo phản ứng của pháp bàn tới đây; dù thuộc hạ cảnh báo về Hắc Uyên ngạc, Cự thử vẫn ra lệnh tiếp tục và hứa ban thưởng cho kẻ tìm thấy Chi tiên. Phía sau đoàn ma thú còn có một đám huyết vụ mỏng che giấu bóng người thon thả âm thầm bám theo. Ở một hướng khác, Hàn Lập và Tiêm Tiêm mất năm ngày đi hơn nửa chặng đường trở về, đồng thời thận trọng xuyên qua vùng sương mù từng do Nhân diện thứu chiếm giữ. Hàn Lập đã khôi phục hơn nửa pháp lực, nhận thấy Đề Hồn thú vẫn hôn mê nhưng không nguy hiểm và phát hiện Phệ Linh Thiên Hỏa đang dung hợp Kim Ô chân hỏa trong đan điền. Vừa rời vùng sương, hai người bất ngờ gặp hàng trăm ma thú do một thủ lĩnh sừng đen dẫn đầu đang giằng co với người mặc ngân giáp đứng trên huyết sắc phi xa, buộc Hàn Lập phải dừng lại."},{"chuong":1640,"tieuDe":"Đoạt Lộ","tomTat":"Khuê Hoán vừa rời nhóm Hàn Lập đã bị một đàn ma thú trung và cao giai đông đảo chặn đường, trong đó thủ lĩnh hai sừng Ngũ Khấp có tu vi không kém hắn. Ngũ Khấp nhận ra Hàn Lập là người đã giết thiếu chủ, liền ra lệnh giết Tiêm Tiêm và Khuê Hoán nhưng phải bắt sống Hàn Lập. Hàn Lập yêu cầu cả nhóm chia nhau phá vây; Khuê Hoán kích hoạt Huyết xa bằng huyết khí, còn Tiêm Tiêm dùng tiểu kỳ trong suốt phân hóa thành hàng trăm quang cầu trắng để đánh lạc hướng truy binh. Ngũ Khấp cùng Anh Đường và Thanh phong xác định đúng hướng của Hàn Lập rồi bám sát hắn, trong khi các ma thú khác chia nhau truy đuổi Khuê Hoán và những quang cầu của Tiêm Tiêm. Do tu vi chưa khôi phục hoàn toàn và không muốn bị bao vây, Hàn Lập kích hoạt Phong Lôi Sí, liên tục thi triển Lôi độn để bỏ xa ba ma thú cao giai. Ngũ Khấp sau đó dùng gương đồng tam giác cùng ba viên châu để hợp nhất lực lượng tam ma, tạo tam sắc quang hà và tăng mạnh tốc độ truy kích. Cuộc đuổi bắt kéo dài về phía chân trời, còn đàn ma thú phía sau truy theo nhiều vạn dặm nhưng cuối cùng mất dấu cả Hàn Lập lẫn ba kẻ dẫn đầu."},{"chuong":1641,"tieuDe":"Linh Giới Bách Tộc","tomTat":"Đội ma thú đang truy đuổi Hàn Lập tranh luận về cách tiếp tục bám theo mục tiêu, cuối cùng Lưu ly tiểu thú quyết định chỉ giữ lại năm thành viên có độn tốc nhanh nhất. Hàn Lập dùng độn thuật lôi điện chạy qua Ma Kim Sơn Mạch nhưng vẫn bị Ngũ Khấp, Anh Đường và Thanh phong bám đuổi hơn nửa ngày. Lo ngại thời hạn rời sơn mạch chỉ còn mười ba ngày, Ích Tà Thần Lôi đã tiêu hao nhiều và phía trước còn có ma thú thánh giai, hắn tiến vào một vùng vụ hải màu xám. Hàn Lập dùng Thái Nhất Hoá Thanh Phù hư hoá toàn bộ thân thể để che giấu khí tức, dù trạng thái này khiến độn tốc giảm mạnh. Khi mất dấu mục tiêu, Ngũ Khấp đoán Hàn Lập đang ẩn trong vụ hải và tiết lộ thiếu chủ nhiều khả năng đã chết trong tay hắn. Ngũ Khấp biến đôi sừng thành song chuỳ, Anh Đường hoá thành hoàng bào nhân mang cốt mâu và viên thuẫn, còn Thanh phong tạo ra nhiều ma phong phân thân để mở đường lục soát vụ hải."},{"chuong":1642,"tieuDe":"Thuấn Sát","tomTat":"Thanh phong dẫn hàng trăm ma phong tiến vào vụ hải và thi triển Thiên Phong Phân Thân Thuật, phân hóa chúng thành vô số thanh hoa để tìm kiếm mục tiêu. Khi một kim sắc nhân ảnh dùng trường thương vàng giết ma phong rồi bỏ chạy, nhóm Thanh phong phối hợp truy đuổi, sử dụng cốt mâu, tế ti và cự chùy để kìm hãm rồi đánh đối phương thành tro bụi. Ngay lúc nhóm ma thú mất cảnh giác, một thanh trường kiếm xanh bất ngờ chém Thanh phong làm đôi, buộc nguyên thần hắn chạy đến cầu Anh Đường cứu viện. Hàn Lập hiện thân, dùng công kích thần thức và ngũ sắc quang diễm khống chế Anh Đường, sau đó xuyên thủng viên thuẫn và lồng ngực để lấy ma hạch. Ngân diễm của Hàn Lập thiêu diệt nguyên thần Anh Đường, khiến nguyên thần Thanh phong hoảng sợ đổi hướng bỏ chạy. Cuối cùng, Hàn Lập vận dụng Nguyên từ thân quang cuốn lấy và nghiền nát nguyên thần Thanh phong."},{"chuong":1643,"tieuDe":"Đắc Kính","tomTat":"Hàn Lập nhanh chóng tiêu diệt nguyên thần Thanh phong và đánh chết Anh Đường, khiến Ngũ Khấp nhận ra mình không thể trực tiếp đối đầu. Ngũ Khấp dùng Gương đồng tam giác độn vào hư không, nhưng Hàn Lập thi triển Phá diệt pháp mục nhìn thấu vị trí và đánh bật hắn hiện thân. Hàn Lập tiếp tục hóa thành thanh sắc đại bằng mang lôi điện, chặn thiết chùy, phá màn phòng hộ do Lam sắc phiên kỳ tạo ra rồi xuyên thủng ngực đối thủ. Lôi điện hủy diệt cả thân thể lẫn nguyên thần Ngũ Khấp, sau đó Hàn Lập thu Gương đồng tam giác và nhận ra bảo vật có thể liên kết pháp lực của nhiều người cũng như hỗ trợ độn vào hư không. Khi Hàn Lập đã tiến sâu vào Vụ hải, một nhóm năm ma thú đến chiến trường tìm kiếm ba người Ngũ Khấp. Chúng tìm thấy mảnh sừng vỡ, xác nhận cả ba đã vẫn lạc và nhận định kẻ ngoại lai mạnh hơn dự tính. Lưu ly tiểu thú quyết định từ bỏ truy đuổi, ra lệnh cả nhóm quay về dù các thành viên lo sợ chủ nhân sẽ nổi giận."},{"chuong":1644,"tieuDe":"Xảo Hoạch","tomTat":"Lưu ly tiểu thú thuyết phục mãng thú cùng những ma thú còn lại quay về hội hợp đồng loại và chuẩn bị mai phục Hàn Lập tại lối ra Ma Kim Sơn Mạch. Sau khi thoát khỏi khu vực truy đuổi, Hàn Lập đổi đường rút, đồng thời lo lắng Tiêm Tiêm chưa chắc đã thoát thân nên Thiên Ngoại Ma Giáp có thể không được tu bổ. Trên đường, hắn phát hiện một cuộc giao chiến có thanh thế vượt xa mức Luyện Hư thông thường và định tránh xa, nhưng bốn đạo độn quang bất ngờ lao ra khỏi hỏa vân. Nhận ra tử quang dẫn đầu mang theo Chi tiên bị thương và chưa hoàn thành biến hóa, Hàn Lập lập tức bắt lấy linh vật, dùng phù lục phong cấm rồi thu vào bình ngọc. Ba người truy đuổi Chi tiên nhanh chóng bao vây hắn, trong đó người toàn thân huyết quang điều khiển hai thanh huyết sắc trường kiếm phát động công kích. Hàn Lập dùng Nguyên từ thần quang cùng hư ảnh tiểu sơn áp chế hai thanh kiếm, nhưng chúng vận dụng Kiếm linh hoá hư để vỡ thành huyết quang rồi tái hiện bên chủ nhân. Sau lần giao thủ, Hàn Lập nhận ra hai người còn lại chính là lão giả họ Ngạn và dị tộc nhân tóc xanh từng gặp tại Lôi Vân Các."},{"chuong":1645,"tieuDe":"Vung Tay Đánh Lớn","tomTat":"Hàn Lập bị lão giả họ Ngạn, dị tộc nhân tóc xanh và cung trang nữ tử vây quanh vì cả ba muốn đoạt Chi tiên. Hắn xác nhận Việt Tông đã bị người khác hạ độc thủ và vẫn lạc, nhưng không biết rõ hung thủ. Cung trang nữ tử đề nghị ba người liên thủ giết Hàn Lập rồi chia đều chiến lợi phẩm trước khi những kẻ truy đuổi khác tới nơi. Không chờ đối phương ra tay, Hàn Lập dùng Nguyên Từ Thần Sơn áp chế ngân sắc đại ấn của lão giả họ Ngạn, buộc ông phải dùng lụa nhũ bạch hóa thành bạch vân để giảm lực. Dị tộc nhân tóc xanh kích hoạt cổ đỉnh triệu ra hoàng sắc phong long, còn cung trang nữ tử dùng huyết phiến phóng vô số huyết sắc hỏa cầu. Hàn Lập triển khai Hư Thiên bảo đỉnh chặn phong long và để Phệ Linh hỏa điểu đối phó huyết diễm. Phệ Linh hỏa điểu phình lớn thành hình thái giống ngân sắc phượng hoàng, dùng ngân vũ phá hủy hỏa cầu rồi hóa thành ngân sắc hỏa đoàn thôn phệ phần lớn huyết diễm, khiến cung trang nữ tử kinh sợ."},{"chuong":1646,"tieuDe":"Đánh Chết Lục Phát","tomTat":"Nữ tử cung trang dùng huyết phiến phóng huyết diễm tấn công, nhưng Phệ Linh hỏa điểu nuốt sạch ngọn lửa, khiến huyết phiến vỡ và chủ nhân chịu phản phệ. Nàng lập tức triệu huyết hồng hồ lô tạo huyết lãng âm hàn, còn Phệ Linh hỏa điểu dùng bạch hà do Kim Ô chân hỏa biến thành để duy trì thế giằng co. Hàn Lập nhận định dị tộc nhân tóc xanh là mắt xích dễ phá nhất nên dùng kiếm quang ghìm chân lão giả họ Ngạn và nữ tử, đồng thời tập trung công kích người này. Chiến giáo vàng có năng lực phá pháp diệt công không xuyên qua được ngũ sắc đại thủ, trong khi thanh ti của Hư Thiên đỉnh trói chặt dị tộc nhân bất chấp hỏa diễm xanh biếc. Hàn Lập nhiếp tiểu đỉnh về để tăng sức giam cầm rồi dùng đại thủ ép nát đầu đối phương; đoàn lục hỏa thoát khỏi thi thể cũng lập tức bị phi kiếm truy sát. Cái chết nhanh chóng của một tu sĩ Luyện Hư đỉnh giai khiến hai đối thủ còn lại kinh sợ. Khi Hàn Lập chuẩn bị tiếp tục công kích, hắc thủy và hỏa vân ở xa đồng thời tách ra rồi cuồn cuộn tiến về chiến trường."},{"chuong":1647,"tieuDe":"Đại Địch Truy Tới","tomTat":"Hàn Lập thu hồi hắc sắc tiểu sơn, ngân sắc hỏa điểu, phi kiếm màu xanh và tiểu đỉnh xanh vàng sau khi đánh chết dị tộc nhân tóc xanh, rồi dùng Phong Lôi Sí rời khỏi chiến trường. Lão giả họ Ngạn và cung trang nữ tử không dám trực tiếp truy đuổi hắn, nhưng Cự thử và Ma ngạc nhanh chóng xuất hiện từ hỏa vân và hắc thủy để tranh đoạt Chi tiên. Ma ngạc vừa tiến lên thánh giai, còn Cự thử đang bị Thiết Sí Ma phụ thể; hai bên chia nhau truy đuổi lão giả họ Ngạn và Hàn Lập. Hàn Lập cố ý dẫn Cự thử đi xa hơn mười ngàn dặm đến một ngọn núi cao, sau đó triển khai Xuân Lệ kiếm trận và thừa nhận Chi tiên đang ở trong tay mình. Khi Cự thử phun xích ảnh lưỡi dài đánh lén, Hàn Lập dùng Linh mục thần thông nhìn rõ đòn đánh và dùng Nguyên Từ Thần Sơn ngăn lại. Cự thử tiếp tục hấp thu hỏa vân vào cơ thể, khiến Hàn Lập nhận ra tình thế nguy hiểm và trở nên ngưng trọng."},{"chuong":1648,"tieuDe":"Nguyên Khí Tái Hiện","tomTat":"Hỏa vân tan đi, để lộ một cự thú đỏ sẫm bán trong suốt với nhiệt lực đủ thiêu chết tu sĩ trung giai và hủy diệt nguyên thần. Hàn Lập dùng ngân diễm bảo vệ thân thể, sau đó ngưng tụ Ích Tà Thần Lôi thành kim cầu khiến cự thú từ bỏ việc tiếp tục chuẩn bị bí thuật và chuyển sang tấn công. Hàn Lập lùi vào Xuân Lê kiếm trận, dùng trận thế và Thanh Liên hóa giải nhiều đòn đánh của cự thú, còn ngân diễm hóa thành Hỏa Điểu bạc để phá quầng sáng đỏ. Cự thú triển khai ma phong, hỏa diễm và phi kiếm thành phong hỏa kiếm quang. Trong lúc đó, Hàn Lập điều động thiên địa nguyên khí vào kiếm trận, khiến dây mây nở hoa kết quả thành hồ lô xanh và ngưng kết Nguyên khí chi kiếm. Khi cự thú hoàn tất bí thuật, Hàn Lập ra lệnh chém, để hồ lô phun ra kiếm quang dài gần một thước mang ngũ sắc linh quang."},{"chuong":1649,"tieuDe":"Tam Ma","tomTat":"Hàn Lập dùng Nguyên Khí Chi Kiếm phá phong hỏa thần thông, chém chết Cự thừ cùng nguyên thần của ký phụ hóa thân. Sau trận chiến, hắn thu được một túi màu lam và viên châu lam chưa rõ lai lịch, rồi gọi Phệ Linh hỏa điểu thôn phệ biển lửa, giải kiếm trận thành bảy mươi hai thanh tiểu kiếm và rời khỏi khu vực. Trong cung điện sâu thuộc Ma Kim Sơn Mạch, Thiết huynh, Huyết Tí và Đa Nhãn trao đổi về việc ký phụ hóa thân bị hủy, nguồn gốc Ma cốt châu và khả năng Ma viên đang tìm cách chữa trị Huyền Thiên tàn bảo để trở về Thánh giới. Thiết huynh tiết lộ Hắc Uyên ngạc đã tiến lên thánh giai, nhưng ba ma đầu không tiện trực tiếp xử lý vì nó từng là tọa kỵ của Minh La Thánh tổ. Họ quyết định chờ Thánh tổ đại nhân sắp thức tỉnh phân phó, đồng thời tranh luận về việc các bên phái thuộc hạ ra ngoài vì Chi tiên."},{"chuong":1650,"tieuDe":"Hoa Thụ Cùng Thánh Tổ","tomTat":"Ngân bào lão giả được xác nhận là Đa Nhãn ma, kẻ từng phái Cửu Dạ và Ngũ Khấp truy tìm hung thủ giết con mình nhưng cả hai thuộc hạ đều đã chết. Trong khi Lưu ly tiểu thú dẫn đám ma thú còn lại tới ngoại vi Ma Kim Sơn Mạch mai phục đoàn Hàn Lập, Đa Nhãn ma biết được cuộc tranh đoạt Chi tiên và sai Mã Công điều tra linh vật này. Hắn tiếp đó thông báo thông đạo giới diện đang xuất hiện dị biến, khiến Thiết Sí ma và Huyết Tí nghi ngờ phía Thánh giới sắp dùng Thánh tổ cùng Huyền Thiên chi bảo mở lại đường sang Linh giới. Cánh cửa đá phủ kinh văn màu phấn hồng bỗng mở ra, báo hiệu vị Thánh tổ đang ngủ say đã thức tỉnh. Ba ma thú thánh giai tiến vào một thiên địa có trời xanh, đồng cỏ và hoa thụ khổng lồ, rồi được nữ Thánh tổ dùng một đóa hoa đưa tới trước mặt. Bà tiết lộ mình chỉ còn non nửa pháp lực và phải tìm một ngoại vật đặc biệt mới có thể khôi phục thêm. Do thuộc hạ thánh giai có nguy cơ bị cường giả Linh giới nhìn thấu thân phận, bà quyết định tự mình ra ngoài tìm kiếm bất chấp sự can gián của tam ma. Nữ Thánh tổ khẳng định dù chưa chắc đánh bại được đối thủ cùng cấp, bà vẫn đủ khả năng đào thoát."},{"chuong":1651,"tieuDe":"Huyền Thiên Như Ý Nhận","tomTat":"Bạch y nữ tử quyết định rời Ma Kim Sơn Mạch để tìm cách hồi phục thương thế và đề phòng nguy cơ từ Thánh giới. Trước khi đi, nàng truyền cho Đa Nhãn ma, Thiết Sí ma và Huyết Tí phương pháp gia cố thông đạo, đồng thời xử lý việc một tàn phiến Huyền Thiên Như Ý Nhận bị Thánh giai Ma viên đoạt mất. Hai tàn phiến còn lại được giao cho Đa Nhãn ma và Huyết Tí phòng thân. Hắc Uyên ngạc tiến giai thánh giai nên được nàng chọn mang theo, còn Chi tiên được giao cho tam ma tự mình tranh đoạt. Ở lối ra Ma Kim Sơn Mạch, Hàn Lập dùng Minh Thanh Linh Mục phát hiện hàng trăm ma thú mai phục rồi kích hoạt Thái Nhất Hóa Thanh Phù để vượt qua. Một tiểu thú phát quầng sáng nhiều màu, phá hiệu lực ẩn thân của phù lục và khiến Hàn Lập bị lộ giữa vòng phục kích."},{"chuong":1652,"tieuDe":"Ly Sơn","tomTat":"Hàn Lập và Tiêm Tiêm bị hơn trăm ma thú trung, cao giai phát hiện trong thông đạo, nhưng lần lượt dùng độn pháp xuyên hư không và ngân phù để thoát khỏi đòn hợp kích. Lưu ly tiểu thú không giải tán quần thú sau thất bại mà ra lệnh tiếp tục mai phục, trong khi Cốc lão giả đến muộn vì bị Lưu phong tử giữ chân nên bỏ lỡ cơ hội chặn hai người. Hàn Lập và Tiêm Tiêm vượt qua khu vực đầy hồ quang màu xanh, rời khỏi vùng linh khí loãng rồi bay thẳng ra ngoài thay vì quay lại Tiêu Vân trấn. Sau khi tới gần Vân Thành, họ quyết định tách nhau vào thành để tránh gây chú ý. Hàn Lập giao thánh giai ma hạch cho Tiêm Tiêm để nàng luyện chế nguyên liệu tu bổ Thiên ngoại ma giáp và hẹn nửa tháng sau nhận lại. Khi Hàn Lập rời đi, Kỳ ảnh thức tỉnh trong người Tiêm Tiêm, đánh giá thần thông của hắn gần tương đương Thánh giai sơ giai và tán thành việc tiếp tục giao hảo. Kỳ ảnh cuối cùng hé lộ một thượng cổ di tích của luyện đan tông sư thời viễn cổ, nơi có thể cải thiện thể chất Tinh Tộc và giúp Tiêm Tiêm tiến vào Thánh tộc."},{"chuong":1653,"tieuDe":"Thi Thể Cùng Chân Huyết","tomTat":"Tại một đầm lầy trong Ma Kim Sơn Mạch, Hắc Uyên ngạc vừa tiến giai thánh giai đang củng cố cảnh giới thì Hoa đại nhân xuất hiện. Nàng xác nhận Tà Long chân huyết của hắn đã được khai mở, cho biết Minh La mất tích sau một cuộc đại chiến tại Thánh giới và yêu cầu hắn đi theo mình. Sau khi Hắc Uyên ngạc đồng ý, Hoa đại nhân thi triển thần thông đưa cả hai rời khỏi sơn mạch. Trong khi đó, Hàn Lập trở về động phủ tại Vân Mộng sơn thuộc Vân thành, kiểm tra cấm chế và ngủ hai ngày hai đêm để hồi phục. Hắn vào mật thất, lấy thi thể khô héo của thánh giai ma viên khỏi vòng tay trữ vật với ý định tinh luyện Sơn Nhạc cự viên chân huyết còn sót lại. Hàn Lập vận dụng bí thuật liên quan đến Kinh Chập quyết, ép thi thể từ kích thước vài trượng thu nhỏ còn khoảng bốn thước. Cuối cùng, hắn triệu xuất Nguyên anh thứ hai, để Nguyên anh bay đến cạnh thi thể và phun thanh hỏa vào đó."},{"chuong":1654,"tieuDe":"Pháp Tướng Cùng Tàn Nhận","tomTat":"Hàn Lập dùng Nguyên anh phun anh hoả nung thi thể ma viên suốt ba ngày ba đêm, tinh luyện thành công Sơn Nhạc cự viên Chân linh chi huyết — hình thái tiểu hầu hắc hồng mang khí tức man hoang, chất lượng tinh thuần, được thu vào bình ngọc phong ấn. Hắn đánh giá biến thân cự viên sau luyện hoá có thể hơn cả Thiên Bằng biến hoá. Sau khi dùng đan dược và tinh thạch khôi phục pháp lực, Hàn Lập nghiên cứu Huyền Thiên tàn nhận thu từ ma viên: thần niệm bị hất ngược, dùng Minh Thanh linh mục thấu thị chỉ thấy kim sắc hành văn nhỏ bên trong. Hắn triệu hoán Phạm Thánh Chân Ma pháp tướng ba đầu sáu tay thúc dục tàn nhận thành công — phần đầu khuyết khôi phục, bề mặt hiện ký hiệu kim sắc lưu chuyển, phát linh áp kinh người. Tuy nhiên tàn nhận liên tục rút pháp tướng căn nguyên lực nên Hàn Lập buộc phải thu hồi lực và cất đi. Hắn nhận ra ba kim triện văn trên tàn nhận giống Huyền Thiên quả thực, xác nhận đây là một kiện Huyền Thiên chi bảo khác, từ nay trở thành đòn sát thủ giản thay thế Huyền Thiên quả thực vốn đang tự phong ấn trong cánh tay không thể chủ động triệu hoán. Cuối chương Hàn Lập lấy thêm hai kiện đồ vật chiến lợi phẩm khác chuẩn bị kiểm tra."},{"chuong":1655,"tieuDe":"Ly Thủy Châu Cùng Nguyên Hợp Ngũ Cực Sơn","tomTat":"Hàn Lập giám định viên châu lam chiến lợi phẩm, dùng Thanh Trúc Phong Vân kiếm, hoả cầu và Phệ Linh hoả điểu thử phá màn nước Thiên Ly thuỷ tinh đều thất bại, xác nhận đây là Ly Thủy Châu thật. Vì công pháp không thuỷ thuộc tính nên không thể luyện thành Ly thuỷ thân, hắn suy luận băng thuộc tính biến dị từ thuỷ rồi trao Ly Thủy Châu cho Thông linh khôi lỗi Oa oa. Oa oa vừa tiếp xúc thuỷ linh khí liền có phản ứng linh tính bất thường, chủ động nuốt viên châu, sau đó được phân phó trông coi dược viên và xuyên qua cửa đá bất chấp cấm chế khiến Hàn Lập kinh ngạc. Hàn Lập mở hộp ngọc lấy Kim Khuyết ngọc thư — trang giấy ngọc từ huyết sàng ma viên, dùng thần niệm nghiên cứu hơn nửa ngày. Phần cuối Huyền Thiên luyện khí thuật ghi phương pháp luyện chế Nguyên Hợp Ngũ Cực Sơn — hậu Huyền Thiên chi bảo dung hợp năm đỉnh giai Thông thiên linh bảo. Hàn Lập nhận ra Nguyên từ thần sơn và Bắc Cực nguyên sơn nằm trong tài liệu cần thiết, rất động tâm vì công hiệu suy yếu non nửa uy lực lôi kiếp."},{"chuong":1656,"tieuDe":"Bỏ Lỡ Cơ Duyên","tomTat":"Hàn Lập suy ngẫm về giá trị bảo vật hậu Huyền Thiên Nguyên Hợp Ngũ Cực Sơn — có thể suy yếu gần nửa uy năng lôi kiếp khi độ đại thiên kiếp, nhưng ngoài Nguyên Từ Thần Sơn thì bốn tòa sơn phong còn lại hoàn toàn không có tung tích. Tu sĩ Luyện Hư kỳ cứ ba ngàn năm phải độ một lần đại thiên kiếp, không thể vượt chín lần — buộc phải tiến giai Hợp Thể kỳ. Hàn Lập kiểm tra Đề Hồn thú đang hôn mê từ sau trận chiến ở Ma Kim Sơn Mạch, kinh ngạc phát hiện pháp lực cuồng tăng hơn phân nửa và dị biến liên tục trong cơ thể, nghi đang tiến giai. Sâu trong đan điền con thú có một hạt tinh lạp bí ẩn gần trong suốt bị hào quang nhiếp hồn bao vây luyện hoá, Hàn Lập rút ra cất vào bình ngọc rồi dùng Minh Thanh Linh Nhãn quan sát. Rời động phủ đến Vân thành, Hàn Lập hao phí tinh thạch khổng lồ mua lượng lớn điển tịch suốt hơn mười ngày. Cuối cùng tìm được miếng ngọc cổ xưa ghi chép về Chân Linh Bản Nguyên, đọc xong thì thất vọng nhận ra thiên đại cơ duyên đã đi qua sát bên người mà bỏ lỡ."},{"chuong":1657,"tieuDe":"Hứa Lão Quái","tomTat":"Hàn Lập nghiên cứu điển tịch phát hiện Chân linh bản nguyên tinh thể đã bị chân nguyên người trước đồng hóa triệt để, người khác không thể hấp thu, cưỡng ép thì biến thành lực lượng thiên địa bình thường. Không cam lòng, hắn lập pháp trận kết hợp anh hỏa xanh nung tinh thể thử nghiệm. Tinh thể biến đổi qua nhiều màu sắc rồi bất ngờ vỡ tung, hóa thành sương mù vàng kim bành trướng mất kiểm soát, phá vỡ pháp trận và Nguyên Từ thần quang của Hàn Lập, xuyên thủng nóc mật thất bay lên trời gây thiên tượng Cự phong vàng kim kinh động cả linh sơn. Hứa lão quái, tu sĩ Luyện Hư hậu kỳ khiến nhiều dị tộc kiêng kỵ, biến hóa thành hỏa giao đỏ dùng hồ lô đỏ son thu hết thiên địa nguyên khí, tuyên bố dùng để luyện bảo vật, vô tình che giấu cho Hàn Lập. Hàn Lập trở về mật thất, triệu Đề Hồn thú ra nhìn hồi lâu rồi thở dài."},{"chuong":1658,"tieuDe":"Áp Chế","tomTat":"Hàn Lập xác nhận chỉ có thể để Đề Hồn thú chậm rãi hấp thu Chân lân bản nguyên rồi thu nó lại vào linh thú hoàn. Hắn bố trí trận pháp nhỏ trong mật thất, lấy Chi tiên ra từ bình ngọc phong ấn và khôi phục nguyên hình — thân cao hai trượng, mặt xanh biếc, bốn chân tím nhạt, vượt xa Cửu Khúc Linh Sâm về mức biến hóa. Hàn Lập cắt rễ Chi tiên lấy linh huyết dịch trắng sữa tinh thuần thử luyện đan nhưng thất bại, kết luận Chi tiên phải có công dụng thần kỳ khác ngoài linh huyết mới khiến tồn tại Hợp Thể kỳ coi trọng. Hắn đánh thức Chi tiên đàm phán — Chi tiên tỏ ra bình tĩnh bất ngờ, từ chối tiết lộ bí mật, không sợ sưu hồn thuật từ Phạm Thánh Chân Ma công. Hàn Lập chuyển sang uy hiếp: hoặc luyện đan hủy bản thể, hoặc bán cho tu sĩ luyện bí thuật đặc thù khiến nguyên thần Chi tiên mất công tu luyện. Hắn đề xuất binh giải cho Chi tiên tiến nhập luân hồi để đổi lấy bí mật, Chi tiên dao động nhưng chưa đồng ý."},{"chuong":1659,"tieuDe":"Thỏa Hiệp","tomTat":"Chi tiên đưa điều kiện giao dịch với Hàn Lập: dùng thiên phú bí thuật chia nguyên thần làm hai, phần ý thức tự chủ hơn nửa được thả trước vào luân hồi, phần ký ức giữ lại để tiết lộ bí mật về pháp thân. Hàn Lập nhanh chóng đồng ý, cho rằng tóm được Chi tiên đã là vui mừng ngoài ý muốn. Hàn Lập triệu Phệ Kim Trùng thành thục thể cùng chim lửa bạc bay vào miệng Chi tiên để trấn giữ, Chi tiên biết rõ sự lợi hại nhưng đành cắn răng nuốt xuống. Hàn Lập gỡ hơn phân nửa cấm chế, rút hơn mười sợi chỉ bạc đọc chú ngữ hoá bùa năm màu biến mất, cảnh cáo phần cấm chế còn lại càng thần diệu hơn. Chi tiên sau khi được giải phóng tự động khôi phục đáng kể, bốn chân xúc tu tím biến thành tay chân nhân loại, xứng danh thiên địa linh vật. Chi tiên xin vào dược viên cắm rễ mượn linh khí, cần một năm để hoàn thành bí thuật, Hàn Lập giao Oa oa (Luyện Hư sơ kỳ) giám sát. Trong dược viên, Chi tiên bất ngờ gặp nguyên thần Cửu Khúc Linh Sâm đã hoá hình thành thỏ trắng trong suốt, run rẩy vui mừng kinh hãi vì lần đầu gặp đồng loại hoá hình. Thỏ trắng trước kia nhát như chuột nay ngang ngược không thèm coi ai ra gì, Hàn Lập dở khóc dở cười."},{"chuong":1660,"tieuDe":"Phá Giới Ma Niệm","tomTat":"Chi tiên dùng mộc linh khí thu phục thỏ trắng trong vườn thuốc, nhận xét linh trí của nó sắp mở ra và đề nghị mở linh trí, truyền thần thông công pháp cho đồng loại. Hàn Lập đồng ý nhưng yêu cầu khôi lỗi Oa oa giám sát Chi tiên không rời nửa bước. Chi tiên biến trở lại hình dạng cây cắm rễ vào đất. Trước khi rời động phủ, Hàn Lập để Báo Lân thú và nguyên thần thứ hai ở lại, mở toàn bộ cấm chế bảo vệ. Hàn Lập cưỡi thú xa đến cửa hàng Tiêm Tiêm, được truyền tống vào khe không gian riêng nơi đã bố trí sẵn pháp trận tu bổ ma giáp. Tiêm Tiêm giải thích đã tinh thể hóa triệt để ma hạch Thánh giai ma viên, chọn phương án luyện hóa triệt để thay vì khảm nguyên vẹn để vá toàn bộ vết rách. Nàng kích hoạt cấm chế không gian, triệu hư ảnh Kỳ Lân xanh phun hỏa cầu vào đỉnh đồng, quá trình tu bổ Thiên ngoại ma giáp chính thức bắt đầu, dự kiến ba ngày hoàn thành."},{"chuong":1661,"tieuDe":"Phá Giới Ma Niệm","tomTat":"Tiêm Tiêm tiến hành sửa chữa thiên ngoại ma giáp cho Hàn Lập trong pháp trận với đỉnh đồng làm trung tâm, Hàn Lập được phân công rót pháp lực vào cờ ma. Nửa đầu thuận lợi, nhưng khi bước sửa chữa cuối hoàn tất, một đạo thần niệm âm lãnh của ma vật thế giới khác cưỡng chế phá vỡ bức tường không gian phủ xuống, hướng thẳng ma giáp, suýt mượn ma khí ngưng tụ thành ma thân. Hàn Lập phản ứng nhanh, phóng toàn bộ Ích Tà Thần Lôi còn lại trong cơ thể (hơn mười lượt, hàng trăm hàng ngàn đạo hồ quang điện vàng) tiêu diệt hoàn toàn thần niệm cùng ma thể đang ngưng tụ. Sau sự cố, pháp trận hỏng hơn nửa, đỉnh đồng nứt nẻ, tinh thạch vụn nát. Kỳ Lân hư ảnh nhận định ma giáp lai lịch bất phàm, tu vi chủ nhân thần niệm không kém chân linh, nghi thuộc thập đại ma đầu. Tiêm Tiêm thừa nhận từng tính giữ ma giáp nhưng cảm nhận thần thông Hàn Lập không kém Thánh tộc sơ giai, bảo mệnh bảo vật đã tiêu hao bảy tám phần ở Ma Kim sơn mạch, quyết định để Hàn Lập thu về. Kỳ Lân hỏi về tiến độ tìm vật cần thiết để vào thượng cổ di chỉ, Tiêm Tiêm nói chưa tìm được, dự định tìm mua hoặc mượn từ con cháu lão quái Thánh giai. Hàn Lập rời đi trên thú xa, bề ngoài bình tĩnh nhưng trong lòng hiếu kỳ về lai lịch ma giáp, hảo cảm với Tiêm Tiêm tăng thêm vài phần."},{"chuong":1662,"tieuDe":"Vân Tộc","tomTat":"Hàn Lập trở về động phủ trên Linh sơn, liên hệ nguyên thần thứ hai xác nhận ba ngày qua không có sự cố. Trước cửa động phủ có Hứa lão quái (trường bào đỏ, bên hông mang hồ lô) cùng hậu bối thiếu niên Hứa Luân Tường đang đợi. Hứa lão quái hỏi về quan hệ giữa Hàn Lập và Thiên Cơ Tử trưởng lão Vạn Cổ Tộc, Hàn Lập phủ nhận quan hệ trực tiếp. Hứa lão quái đi vào mục đích chính: hỏi thiên tượng kinh người mấy ngày trước có phải Hàn Lập gây ra không, Hàn Lập xác nhận. Hứa lão quái tự tiết lộ mình thuộc Vân tộc — một trong Thiên Vân thập tam tộc, nhân số thưa thớt nhưng thực lực luôn xếp trước ba, am hiểu thuật ẩn nấp biến hóa và sở hữu thiên phú cốt lõi bản mạng Vân thú (có thể hợp nhất với chủ thành Vân thú cự linh tăng tu vi). Hứa lão quái hỏi Hàn Lập liệu có thể tái tụ thiên địa nguyên khí, rồi chỉ vào Hứa Luân Tường cho biết mục đích thực sự liên quan bản mạng Vân thú của thiếu niên này."},{"chuong":1663,"tieuDe":"Đổi Lấy","tomTat":"Hứa lão quái giới thiệu cháu trai duy nhất Hứa Tường với Hàn Lập — thiếu niên tư chất kinh người nhưng bản mạng vân thú trước sau không thể ngưng tụ ở bước cuối cùng. Lão tiết lộ mục đích thực sự: thiên địa nguyên khí từ thiên tượng Hàn Lập tạo ra trước đó có thể trợ giúp Hứa Tường cô đọng bản mạng vân thú, trong khi nguyên khí bình thường hoàn toàn vô dụng. Nguyên khí thu được lần trước đã bị lão vô tình dùng mất hơn nửa nên lão muốn Hàn Lập tái tạo thiên tượng. Hàn Lập hiểu rõ thiên tượng thực chất do tinh thể chân lân căn nguyên tán loạn tạo thành — vốn là linh đan quý tăng tiến tu vi cho Đề Hồn thú, thiếu đi sẽ ảnh hưởng tiến giai của con khỉ, nên từ chối khéo. Hứa lão quái không chịu buông, bày ra bảy tám hộp ngọc trân phẩm bao gồm trứng Man hoang viêm điệp, pháp bảo, đan dược luyện hư kỳ để đổi. Hàn Lập lần lượt xem nhưng không vừa mắt kiện nào, vì hắn sở hữu nhiều trọng bảo kể cả hai món huyền thiên bảo vật. Chương kết thúc bỏ lửng khi Hàn Lập chưa dứt khoát cự tuyệt."},{"chuong":1664,"tieuDe":"Viêm Kim Chi Tinh","tomTat":"Hàn Lập tiếp tục đàm phán với Hứa lão quái, chần chừ vì cần thêm tài liệu quý cho Thanh Nguyên Tử nhưng sợ đòi quá mức. Hứa lão quái cắn răng lấy ra Viêm kim chi tinh — đỉnh giai tài liệu hỏa thuộc tính, vốn định dâng trưởng lão trong tộc — đổi lấy chân lân bản nguyên vì tiền đồ đứa cháu. Hàn Lập thử bằng đoản kiếm thấy kiếm tan thành khói, nhận ra giá trị, chủ động bù thêm 500 vạn linh thạch. Hắn xác nhận đã đủ ba chủ tài liệu cô đọng Phạm Thánh Chân Ma pháp tướng (kim tủy tinh trùng, huyết hạnh, Viêm kim chi tinh). Sau đó gọi Đề Hồn lấy chân lân bản nguyên luyện hóa gây thiên tượng lần hai cho Hứa lão quái dùng hồ lô đỏ thẫm thu thiên địa nguyên khí. Hàn Lập ra Vân Thành mua hơn ba mươi loại tài liệu phụ trợ rồi bế quan. Nửa tháng sau, Vân Thành siết chặt an ninh vì truy tìm kẻ Giác Xi tộc xâm nhập cung phụng đường. Hơn mười đại nhân vật thánh tộc họp bí mật, thanh niên Đại Thừa kỳ họ Phí chủ trì chất vấn Bạch đạo hữu Thủy Mị bộ lạc, người đã phái tinh nhuệ dùng mê hồn thuật kiểm tra nửa năm nhưng không tìm được tung tích Giác Xi tộc."},{"chuong":1665,"tieuDe":"Sa Lão Phu Nhân","tomTat":"Các thánh tộc họp bàn trong Vân thành để truy bắt gián điệp Giác Xi Tộc đã trộm đồ giải cấm chế đại trận mới bố trí xong. Bạch đạo hữu tự xưng tộc mình đứng nhất về Mê Hồn Thuật, Thương Ảnh (Âm Yêu Tộc) tranh luận rồi nhượng bộ. Thải Lưu Anh hiến kế ngoài chậm trong nhanh — một tháng đại tra toàn lực rồi giả vờ thả lỏng, tổ chức ba đội tinh nhuệ dẫn dụ gián điệp tự lộ, phần kế sách bí mật truyền âm riêng cho họ Phí khiến Phí kinh ngạc rồi vui mừng. Sa lão phu nhân — vị Đại Thừa kỳ bí ẩn nhất, sống lâu nhất, không ai biết thuộc tộc nào — xuất hiện tuyên bố chỉ xuống núi giúp đỡ khi có cường địch và giúp đứa nhỏ kia rồi rời đi, ngay cả họ Phí cũng phải xưng vãn bối. Họ Phí giao toàn quyền truy bắt cho Thải Lưu Anh và Bạch đạo hữu rồi chuyển sang bàn Nghiễm Hàn Giới. Thiên Cơ Tử báo cáo Nghiễm Hàn nghi trong Thông Linh đại điện đã có phản ứng hai ngày trước, dự đoán Nghiễm Hàn Giới sẽ mở lại trong vài tháng đến ba bốn năm. Thải Lưu Anh và Đoạn Thiên Nhận nghe tin liếc nhau rồi trở lại bình thường."},{"chuong":1666,"tieuDe":"Lai Khách","tomTat":"Tại đại sảnh Vân thành, thanh niên họ Ông chủ trì hội nghị thánh giai bàn việc Nghiễm Hàn Giới sắp mở do Nghiễm Hàn Nghi xuất hiện dự triệu sớm hơn dự kiến. Đại hán đen thui xác nhận Vân thành chỉ có hai khối Nghiễm Hàn Lệnh, cần chuẩn bị hai pháp trận do Vạn Cổ Tộc phụ trách. Thiên Cơ Tử kể chuyện Hàn Lập cho thanh niên họ Ông, tiết lộ Hàn Lập không phải người Thiên Vân và không phải người đại lục, nhưng khẳng định không có vấn đề. Thanh niên họ Ông đồng ý cho Hàn Lập tham gia nhưng dặn âm thầm giám thị. Thánh tộc da xanh bẩm báo Giác Xi Tộc có thêm viện binh thánh giai tăng năm sáu người, đã công phá 3 tòa thành, thanh niên họ Ông lập tức điều năm thánh giai và hơn ngàn cao giai ra tiền tuyến. Hàn Lập bế quan trong động phủ ba năm, mật thất có ba nhân ảnh: bản thể kim sắc lân giáp, nguyên anh thứ hai da xanh biếc phát tử quang, và quái vật kim sắc cự tượng ba đầu sáu tay. Cảm ứng có khách, Hàn Lập tiếp Thải Lưu Anh mang theo đệ tử mới là nữ tử đội nón trắng che mặt bằng tinh quang thân phận bí ẩn, đãi linh trà ngàn năm và tặng bà một hộp trà."},{"chuong":1667,"tieuDe":"Hợp Kích Bí Thuật","tomTat":"Thải Lưu Anh đến gặp Hàn Lập, giới thiệu nữ đồ đệ đội nón trắng che mặt — chính là người sở hữu Nguyên Từ Chi Thể trước đây từng được nhắc, vốn là khách khanh Tinh tộc nay đã bái sư. Nữ tử khẳng định tự nguyện bái sư không bị ép buộc. Thải Lưu Anh thông báo Nghiễm Hàn Giới sẽ mở sau một tháng, Hàn Lập tiếc nuối vì hiện chỉ là thượng tộc thất giai, không đủ thời gian đột phá bình cảnh. Thải Lưu Anh chia sẻ kinh nghiệm từng vào Nghiễm Hàn Giới: cảnh báo tránh khu cực nóng cực lạnh và phải chạy trốn ngay khi nhìn thấy đám mây đỏ. Trước khi rời đi, nàng trao bạch sắc ngọc phiến ghi Hợp kích bí thuật — bí thuật liên thủ vừa bài trừ cấm chế vừa là thần thông đối địch lợi hại, cần dùng Nguyên Từ Thần Quang ngưng luyện, dặn phải vào Nghiễm Hàn Giới mới được luyện. Hàn Lập trở về mật thất, thu hồi kim sắc quái vật ba đầu sáu tay — quái vật vỡ ra thành kim sắc phù văn nhập vào người và hắc khí ngưng tụ thành Ma Anh (Nguyên Anh thứ hai) cao một tấc, đen như mực, trên người mang thiên ngoại ma giáp."},{"chuong":1668,"tieuDe":"Ma Anh Và Linh Khu","tomTat":"Hàn Lập thu ma anh trở lại, xác nhận tu vi nguyên anh thứ hai đã đạt Nguyên Anh Trung Kỳ đỉnh phong, dự định vào Nghiễm Hàn Giới mới cho đột phá Hậu Kỳ. Hắn phát hiện thân thể chi tiên sau khi binh giải luân hồi là vật tuyệt hảo để luyện thế thân — chi tiên hấp thu linh dịch bình nhỏ chuyển hóa thành linh lực tinh thuần, pháp lực đã tăng đến Luyện Hư Trung Kỳ không gặp bình cảnh. Hàn Lập dự tính dùng nguyên anh phụ nhập vào linh khu đối địch, kết hợp thần thông và pháp lực để không sợ Hợp Thể Kỳ, nhưng cảm thấy linh khu khó đạt mức nghịch thiên dựa trên tiền lệ kim lôi trúc. Cửu Khúc Linh Tham đã mở linh trí, nguyên thần biến từ thỏ trắng thành nữ đồng sáu bảy tuổi, được Hàn Lập đặt tên Khúc Nhi. Khúc Nhi có thể tiến vào thân thể chi tiên điều động pháp lực luyện hóa, bản thân cũng được lợi ích. Hàn Lập thu nhỏ linh khu thành một tấc cất vào tay áo, dặn Khúc Nhi đi cùng vào Nghiễm Hàn Giới. Trong một tháng chuẩn bị, hắn sưu tầm tài liệu pháp khí ở Vân thành, Đoạn Thiên Nhận và Thiên Cơ Tử lần lượt đến gặp. Cuối cùng Hàn Lập nhận truyền tin xác nhận Nghiễm Hàn Giới mở, đứng dậy ra khỏi động phủ."},{"chuong":1669,"tieuDe":"Thiên Cương Ấn","tomTat":"Đội hộ vệ gồm bốn Luyện Hư Kỳ hoàng bào do Thiết thống lĩnh dẫn đầu cùng giáp sĩ phụng mệnh Thiên Cơ Tử đến đón Hàn Lập bằng linh xa, hộ tống hắn đến khu vực pháp trận bảo vệ Nghiễm Hàn Giới. Vân thành lúc này được bảo vệ nghiêm ngặt, ít người qua lại, giáp sĩ tuần tra khắp nơi. Khu vực pháp trận phương viên mười dặm bị ngũ sắc quang mạc bao phủ, canh giữ bởi hơn tám trăm khôi lỗi và hàng ngàn giáp sĩ, Hoa huynh mặc giáp xanh cưỡi cự lang dùng lệnh bài mở thông đạo cho đoàn vào. Bên trong có hai pháp trận truyền tống khảm tinh thạch và một điện phủ nơi thanh niên họ Ông ngồi ghế chính, xung quanh là Thiên Cơ Tử, Đoạn Thiên Nhận, Thải Lưu Anh cùng bảy tám Hợp Thể Kỳ khác. Hàn Lập nhận ra thanh niên họ Ông từ tứ tộc đấu giá hội. Thanh niên họ Ông nhận xét pháp lực và thần thức Hàn Lập vượt xa đồng bối cùng cảnh giới, chủ động tặng hắn dị bảo Thiên Cương Ấn — ngân sắc tiểu ấn cổ xưa, hao phí thần niệm nhưng hữu dụng với thánh giai. Hàn Lập nhận ấn, nhận ra ba chữ thượng cổ văn tự trên mặt dưới. Thiên Cơ Tử cho biết vài canh giờ nữa Nghiễm Hàn Giới sẽ mở và sẽ giới thiệu đồng bạn cùng truyền tống."},{"chuong":1670,"tieuDe":"Nghiễm Hàn Nghi","tomTat":"Hàn Lập thu nhận dị bảo mà Đại Thừa Kỳ thanh niên họ Ông ban cho, trong lòng phân tích nguyên nhân. Thiên Cơ Tử giới thiệu các thành viên đoàn vào Nghiễm Hàn Giới: Nguyệt tiên tử (người kích hoạt Nghiễm Hàn Lệnh thứ hai, dẫn đội thứ hai), Thạch Côn (Thạch Kiến Tộc, đồ đệ Đoạn Thiên Nhận), Phong Khiếu (Thanh Tộc), huynh đệ song sinh Vân Đằng Tộc — toàn Luyện Hư Kỳ đỉnh giai, phần lớn coi thường Hàn Lập vì hắn chỉ là thất giai dị tộc. Ba mươi người chia hai đội mỗi đội mười lăm, Liễu Thủy Nhi và Thạch Côn được xếp vào đội Hàn Lập khiến hắn ngầm nghi Thải Lưu Anh và Đoạn Thiên Nhận mua chuộc Thiên Cơ Tử. Thiên Cơ Tử phát hơn năm sáu mươi bảo vật từ bí khố, Hàn Lập chọn bích ngọc phiến tử thuộc tính băng hàn. Mọi người ra ngoài điện chuẩn bị, Hàn Lập phát hiện Nghiễm Hàn Lệnh bị cấm chế trong ngũ sắc quang cầu trên không. Thiên Cơ Tử ra lệnh mang Nghiễm Hàn Nghi — đại chung thanh sắc cao hơn mười trượng khắc tượng rồng — ra sân rồi phóng pháp quyết kích hoạt, phù văn hiện lên và tượng rồng nhúc nhích như sống. Thanh niên họ Ông vẫn chưa ra khỏi điện phủ."},{"chuong":1671,"tieuDe":"Nhập Giới","tomTat":"Các tu sĩ dị tộc tập trung trước Nghiễm Hàn Giới chờ pháp trận kích hoạt. Thanh niên họ Ông từ đại điện ra lệnh phát động trận pháp, mười mấy con long tượng mở mắt, ngũ sắc quang mạc tỏa ra, hắc sắc tuyền qua hình thành giữa không trung. Thiên Cơ Tử chỉ định Hàn Lập và Nguyệt tiên tử dẫn đầu vào trận thúc dục Nghiễm Hàn Lệnh. Hàn Lập bắt quyết kích hoạt lệnh bài, lệnh bài phát kim ngân phù văn rồi phóng ngân sắc quang trụ xuyên tuyền qua, xé mở khe không gian bạc sắc rộng bảy tám trượng. Thần niệm Hàn Lập hao tổn điên cuồng, các dị tộc nhân ném pháp khí tạo ngũ sắc quang hà bao phủ đám người bay vào khe, Nguyệt tiên tử dẫn đội khác vào khe bên kia, nhập giới hoàn tất. Thanh niên họ Ông lệnh canh giữ pháp trận nghiêm ngặt suốt một năm, ai trái lệnh giết không tha. Tại Nghiễm Hàn Giới, hôi phát lão giả đơn thương bay đi bế quan mong đột phá thánh giai, Kim đạo hữu đề nghị liên thủ bị đại hán cự tuyệt và mỉa mai trở mặt như thay áo. Hàn Lập rủ Thạch Côn và Liễu Thuý Nhi đồng hành, ba người bay hơn ngàn dặm, Liễu Thuý Nhi đề xuất theo ý Thiên Cơ Tử ẩn ở nơi bí mật thao luyện hợp kích Nguyên Từ Thần quang để phòng nguy hiểm."},{"chuong":1672,"tieuDe":"Tiểu Đảo Hải Thú","tomTat":"Ba người Hàn Lập, Thạch Côn, Liễu Thuỷ Nhi bất đồng ý kiến về kế hoạch tiếp theo trong Nghiễm Hàn Giới. Liễu Thuỷ Nhi muốn luyện thuật hợp kích Nguyên từ thần quang do sư phụ nàng sáng tạo, Thạch Côn muốn nhanh chóng tìm cấm chế chi địa để đột phá bình cảnh. Hàn Lập đề nghị phương án dung hoà: bỏ nửa tháng luyện hợp kích rồi lập tức đi tìm cấm chế chi địa, cả hai đồng ý. Ba người phi hành suốt một đêm vượt trăm vạn dặm mới tìm được một hòn đảo nhỏ duy nhất, cho thấy tiểu đảo cực hiếm trong hải vực này. Hàn Lập dùng mắt thần (giấu là bí thuật đặc thù) phát hiện đảo có một con hải thú tu vi ngang bọn họ, quyết định liên thủ diệt hải thú chiếm đảo. Hàn Lập bố trí pháp trận bằng trận kỳ, Liễu Thuỷ Nhi bổ sung cấm chế bằng hoàng sắc viên bàn. Thạch Côn khoác chiến giáp lao xuống đảo, một quyền san bằng toàn bộ núi đá cây cối, thể hiện sức mạnh khủng khiếp của Thạch Kiến Tộc. Ngay sau đó bảy tám xúc tu khổng lồ màu đen từ dưới nước bắn lên, hải thú lộ diện."},{"chuong":1673,"tieuDe":"Các Hiện Thần Thông","tomTat":"Thạch Côn xông lên giao chiến trực tiếp với xúc tu hải thú bạch tuộc đen trên tiểu đảo, dùng hoàng sắc quang nhận và cự quyền phù văn đánh nát liên tục nhưng hải thú có thần thông Bất diệt thể nên xúc tu tái sinh không ngừng. Hàn Lập phân tích cần diệt bản thể dưới biển, Liễu Thuý Nhi tự tiến cử vì công pháp thuỷ thuộc tính rồi hóa lam sắc kinh hồng lao xuống. Hải thú phản kích bằng cự lãng hơn trăm trượng từ bốn phía, Hàn Lập tung ngũ sắc hàn diễm biến quang mạc thành ngũ sắc, nước biển va vào liền đóng băng thành tường băng bảo vệ đảo. Liễu Thuý Nhi trong thời gian ngắn giết chết bản thể hải thú — con bạch tuộc đen to như ngọn núi, đầu mơ hồ có bộ dáng nam tử hung ác, hai tay cầm trường thương. Sau trận, Hàn Lập phun ngân sắc hoả diễm hóa hoả điểu phá tan toàn bộ tường băng. Liễu Thuý Nhi kinh ngạc nhận xét Hàn Lập sở hữu cả hai loại thần thông băng hoả hiếm thấy, quang mang trong mắt chớp động."},{"chuong":1674,"tieuDe":"Luận Bàn","tomTat":"Ba người Hàn Lập, Liễu Thuý Nhi và Thạch Côn hạ xuống tiểu đảo nơi Thạch Côn chờ sẵn để chuẩn bị thao luyện thuật hợp kích Nguyên từ thần quang. Liễu Thuý Nhi đề xuất tỉ thí để xác định ai mạnh nhất về Nguyên từ thần quang làm chủ đạo. Hàn Lập tự rút khỏi cuộc tỉ thí, nói mình chỉ dựa vào ngoại vật nên kém cỏi, thực tế giấu bảo vật Nguyên từ thần sơn. Thạch Côn thi đấu với Liễu Thuý Nhi: vòng đầu bất phân thắng bại, vòng hai Thạch Côn dốc toàn lực phóng hàng trăm quang cầu nhưng bị phù văn khổng lồ của Liễu Thuý Nhi nuốt trọn không sót. Thạch Côn sảng khoái nhận thua, đánh giá nàng mới dùng sáu bảy thành lực. Kết quả xác định Liễu Thuý Nhi làm chủ, Hàn Lập và Thạch Côn làm phụ. Ba người bố trí ảo trận che tiểu đảo, tu luyện thuật hợp kích hơn mười ngày hoàn thành thuận lợi, sau đó rời đảo hướng lên lục địa tìm cấm chế chi địa."},{"chuong":1675,"tieuDe":"Trấn Hải Viên","tomTat":"Ba người Hàn Lập, Liễu Thuý Nhi, Thạch Côn phi hành trên biển Nghiễm Hàn Giới suốt năm ngày, dọc đường gặp nhiều tiểu đảo bị hải thú cường đại chiếm cứ không dám dừng chân. Khi sắp lên bờ lục địa, Trấn Hải Viên — thượng cổ mãnh thú hình cự viên đầu mọc sừng — trồi lên từ biển thi triển Thiên Hống thần thông, tiếng rống chấn động trăm dặm giết vô số hải ngư, khống chế nhục thân và pháp lực cả ba tu sĩ không thể nhúc nhích. Hàn Lập thi triển thần thông bí thuật từng tu luyện trước đây, phát tiếng hừ lạnh kèm kim quang phá tan khống chế, giải cứu cả ba người phi độn thoát nạn. Liễu Thuý Nhi nhận định cự thú là Trấn Hải Viên trong truyền thuyết, có khả năng xé giao long nuốt tồn tại thánh giai, ba người sống sót chủ yếu vì cự thú không chủ ý tấn công. Hai người cảm tạ Hàn Lập cứu mạng và hứa hồi báo. Cuối chương, một con tử sắc đại điểu thể tích ngang Trấn Hải Viên bay tới từ bờ đối diện, miễn nhiễm Thiên Hống, lao thẳng tới giao chiến."},{"chuong":1676,"tieuDe":"Ám Thú Rừng Rậm","tomTat":"Liễu Thuý Nhi nhận định cự điểu đang giao chiến có uy thế không kém Trấn Hải Viên, nên ba người Hàn Lập lập tức hóa độn quang rời khỏi vùng biển. Ngay sau đó, chiến trường bùng nổ dữ dội, sóng lớn ngàn trượng nuốt trọn nơi họ vừa đứng, khiến cả nhóm càng chắc chắn phải tránh xa. Khi đặt chân lên đại lục, Thạch Côn cảm thán Nghiễm Hàn Giới quả nhiên đầy những thượng cổ mãnh thú đã tuyệt tích ở Linh giới. Liễu Thuý Nhi nhờ Hàn Lập hộ pháp rồi cùng Thạch Côn dùng Nghiễm Hàn Đồ xác định phương vị, biết mình đang ở rìa Vạn Cầm Lĩnh và hải vực vừa vượt qua là Bát Hung Hải. Từ bản đồ, họ cân nhắc ba tuyến đường gồm Vạn Cầm Lĩnh, Lam Dương sa mạc và Ám Thú sâm lâm, nhưng hai nơi đầu quá hung hiểm hoặc tốn thời gian. Liễu Thuý Nhi nhấn mạnh cấm chế chi địa còn rất xa, nhóm còn cần thời gian đột phá bình cảnh, nên không thể đi vòng quá lâu. Sau khi Hàn Lập tỏ ý tùy theo quyết định chung và Liễu Thuý Nhi nhắc đến áp lực từ Đoạn tiền bối, Thạch Côn đồng ý xuyên qua Ám Thú sâm lâm."},{"chuong":1677,"tieuDe":"Chư Tộc Trong Tộc","tomTat":"Liễu Thuý Nhi, Hàn Lập và Thạch Côn thống nhất liên thủ xuyên qua Ám Thú sâm lâm rồi bay dọc bờ biển rời đi. Hai dị tộc nhân mập lùn và cao gầy xuất hiện ngoài khơi, vừa thoát khỏi trận đấu của hai thượng cổ mãnh thú phải tự bạo bảo vật; dùng định vị bàn do Tinh Tộc luyện chế nhưng thất bại vì nguyên khí rối loạn, rồi rời đi và không ai gặp lại. Tác giả phác họa nhiều cảnh: ba dị tộc Thiên Vân chạy trốn quái thú sư tử, quái nhân trắng phi hành trong tuyết, hai gã lục bào dùng hồng sắc phiên kỳ thiêu quỷ thụ thu tinh thể xanh biếc. Tại sa mạc, kim giác thanh niên — đặc sứ Giác Xi Tộc — tiết lộ sứ mệnh bí mật: trưởng lão trong tộc dùng Huyền Thiên chi bảo luyện năm kiện nghịch thiên bảo vật để ẩn trong Thiên Vân tránh cao tầng mười ba tộc, mười mấy đội xâm nhập nhưng chỉ năm đội có bảo vật. Trên hồ nước, nữ tử dị tộc nửa người nửa cá dùng thanh âm đồng loại thuần phục quái kình sáu mắt rồi cưỡi bay đi, nam tử cùng tộc bay sát theo."},{"chuong":1678,"tieuDe":"Ám Thú Sơ Hiện","tomTat":"Hàn Lập, Liễu Thuý Nhi và Thạch Côn sau hơn nửa tháng di chuyển đã đến Ám Thú sâm lâm — khu rừng trong Nghiễm Hàn Giới nơi hai phần ba thời gian là ban đêm, ám thú hàng ngàn đầu sinh sống. Ba người ẩn trong huyệt động bên trong thân cây lớn, dùng gương pháp bảo quan sát từ xa hơn mười dặm trận chiến giữa một ám thú mới trưởng thành và một Thanh Dạ mãng. Thanh Dạ mãng bị kích thích cuồng hoá biến thân — thân to gấp đôi, lân phiến đổi trắng bạc, mọc sừng xoắn ốc — nhưng sau gần nửa canh giờ giao chiến, ám thú hoá hàng trăm hư ảnh cắn chết đối thủ và nuốt nội đan. Liễu Thuý Nhi thở dài tắt gương, hỏi Hàn Lập và Thạch Côn cảm nghĩ sau khi tận mắt thấy sức mạnh ám thú."},{"chuong":1679,"tieuDe":"Thiên Biến Huyễn Diện","tomTat":"Thạch Côn tự đánh giá thực lực trước ám thú, nhận định đơn đả thắng một con nhưng từ năm con trở lên sẽ bại. Liễu Thuý Nhi giới thiệu chi tiết ba loại ám thú trong Ám Thú sâm lâm: phổ thông, Tam nhãn ám thú có mắt thứ ba phóng tia huỷ diệt, và Ám thú vương da vàng chỉ huy hàng trăm con. Cả ba phân tích lợi hại ngày-đêm rồi thống nhất hành quân ban đêm vì ám thú phòng bị buông lỏng dù thực lực mạnh hơn. Liễu Thuý Nhi lấy ra ba tấm Thiên Biến Huyễn Diện do gia sư Thải Lưu Anh cho mượn, bảo vật biến ảo hình dáng tùy ý, khó bị thần niệm thông thường dò xét. Hàn Lập quan sát phù văn trên bảo vật, kinh ngạc phát hiện đó chính là Ngân khoa văn trên Kim khuyết ngọc thư, suy đoán Thải Lưu Anh cũng sở hữu Kim khuyết ngọc thư nhưng cố tình che giấu phát hiện này. Thạch Côn dùng thổ độn thuật đi giết con ám thú bị thương lấy da nguyên vẹn mang về, rồi là người đầu tiên thử nghiệm Thiên Biến Huyễn Diện, bảo vật hoá ngân quang nhập vào da ám thú phủ xuống người hắn."},{"chuong":1680,"tieuDe":"Săn Thú","tomTat":"Thạch Côn thử nghiệm Thiên Biến Huyễn Diện, bọc da thú lên cây gậy đá biến hình ám thú hoàn hảo không sai biệt. Ba người lên đường tiến sâu vào Ám thú sâm lâm, mỗi người thi triển cách ẩn thân khác nhau: Thạch Côn hóa ám thú phun hoàng vân, Liễu Thuý Nhi cưỡi ngọc thử trắng trong suốt, Hàn Lập dùng Thanh Trúc Phong Vân Kiếm mộc thuộc tính phi độn. Liễu Thuý Nhi phục kích hạ sát ám thú giống cái bằng thần thông thủy thuộc tính, con thú chết mà da lông không vết thương. Hàn Lập từng buông tha một ám thú bị thương bên cạnh có ấu thú, Thạch Côn nghi là lòng từ bi nhưng Hàn Lập giải thích da không dùng được. Hàn Lập thi triển Xuân Lệ kiếm trận gồm mấy chục khẩu phi kiếm tạo thanh sắc quang mạc dày đặc, ngăn cách thần niệm và cách âm hoàn toàn, vây giết ám thú khổng lồ — Liễu Thuý Nhi và Thạch Côn kinh sợ, đánh giá dưới thánh cáp ít có địch thủ. Ba người đủ da thú, chuẩn bị tiến sâu hơn vào rừng."},{"chuong":1681,"tieuDe":"Ám Thú Chi Vương","tomTat":"Hàn Lập, Thạch Côn và Liễu Thuý Nhi bàn chiến thuật trước khi tiến sâu Ám Thú sâm lâm: không thả thần niệm, nhắc đến thuật hợp kích Nguyên Từ Thần Quang nhưng Hàn Lập cảnh giác không nên dùng trừ phi bất đắc dĩ. Ba người biến ảo thành ám thú, tách nhau di chuyển bằng bảo vật che dấu. Suốt hơn mười ngày xuyên trung tâm rừng, hành trình thuận lợi bất thường, không gặp một đầu Tam nhãn ám thú nào. Hàn Lập dùng Minh Thanh Linh Mục thay thần niệm dò xét, ấn tượng trước khả năng tránh ám thú của Liễu Thuý Nhi và Thạch Côn. Đột nhiên Ám Thú Vương — ám thú toàn thân kim quang, thần thông ngoài thánh giai — từ bóng tối bắn ra tấn công Thạch Côn, đánh bắn gãy đại thụ khiến Thạch Côn thống khổ không đứng dậy nổi. Hàn Lập cân nhắc giữa cứu và bỏ: Thạch Côn chết thì cấm chế chi địa không thể mở, nhưng hắn vẫn quyết ưu tiên mạng sống mình. Trong khi đó Liễu Thuý Nhi sẵn sàng động thủ không do dự, khiến Hàn Lập kinh ngạc. Đúng lúc tình thế nguy cấp, Ám Thú Vương đột nhiên thần sắc biến đổi cực kỳ kinh sợ, gầm lên hoá kim ảnh bỏ chạy biến mất, ba người thoát nạn bất ngờ."},{"chuong":1682,"tieuDe":"Hai Con","tomTat":"Sau khi Ám thú vương vừa lướt qua, Hàn Lập và Liễu Thuý Nhi kinh ngạc, còn Thạch Côn truyền âm cho biết mình chỉ bị thân thể tê dại. Ngay sau đó, hàng vạn ám thú hống vang như sấm và từ rừng cây tuôn ra, khiến ba người phải lập tức phân tán ẩn nấp. Hàn Lập dùng hắc sa phối hợp Hoá Thanh phù ẩn thân tại chỗ, trong khi Liễu Thuý Nhi và Thạch Côn vừa ẩn nặc vừa chạy xa. Một con Ám thú vương thứ hai kim sắc xuất hiện cùng bảy tám ngân mục ám thú, phát thần niệm cường đại quét ngang và phát hiện Liễu Thuý Nhi cùng Thạch Côn, nhưng Hàn Lập thoát được nhờ hư hoá chi thân. Khi hai người lộ diện bỏ chạy, Ám thú vương thứ hai nghe tiếng hú đáp trả của Ám thú vương thứ nhất nên sai ngân mục ám thú truy sát họ, còn bản thân đích thân đuổi theo đối thủ. Hàn Lập chờ an toàn rồi giải trừ ẩn nặc, biến thành ám thú và dùng phi kiếm đuổi theo hơn nửa ngày nhưng chưa bắt kịp. Nhờ bảo vật định vị đã luyện chế trước, hắn không mất dấu hai đồng bạn và cuối cùng quyết định hiện nguyên hình, thu da thú, triển khai Lôi Độn để tăng tốc."},{"chuong":1683,"tieuDe":"Tân Nguyên Từ Sơn","tomTat":"Hàn Lập triển khai Phong Lôi Sí truy đuổi với tốc độ ngang thánh tộc, sau hơn một canh giờ đuổi kịp Liễu Thuý Nhi và Thạch Côn đang giao chiến với bảy ngân mục ám thú. Thạch Côn lộ thần thông thực sự là hỏa thuộc tính, dùng đôi chùy đỏ sẫm và bình ngọc sắc hồng giằng co với ba con. Liễu Thuý Nhi tế bộ ngân toa kết hợp pháp tướng ngân giáp nữ tử phóng kiếm khí bao phủ trăm trượng, tạm chiếm thượng phong trước bốn con. Hàn Lập nhận ra cả hai đều giấu thực lực từ đầu. Hắn vận Phạm Thánh Chân Ma Công tới cực hạn, ẩn hình bằng lụa đen, triệu hoán bạch sắc cự mãng đánh lén rồi đè Tân Nguyên Từ Sơn trăm trượng khắc ấn Ngân Khoa Văn xuống đầu ám thú. Con ám thú phân thân thành trăm hắc sắc hồ điệp cố thoát, bị hừ lạnh thần thông tinh thần làm loạng choạng, Ngân Khoa Văn phóng hôi ti xuyên thủng toàn bộ. Thạch Côn phóng đôi chùy huyễn hóa cùng lực vô hình kiềm giữ hai ám thú còn lại."},{"chuong":1684,"tieuDe":"Sơ Hiện Thần Thông","tomTat":"Nguyên từ thần sơn thu hết hắc sắc quang điểm của ám thú vừa bị đánh tan, khiến hai ám thú còn lại giận dữ biến thân và tăng mạnh khí tức. Thạch Côn dùng Song hoả chuỳ cùng quyền ảnh đối đầu nhị thú, còn Oa oa hiện thành nữ tử và dùng Lam sắc ngọc phiến phối hợp công kích. Hai ám thú dung hợp thành song thủ cự thú, dùng ngân quang yêu mục phong tỏa cả cự lãng lẫn Nguyên từ thần sơn. Hàn Lập xuất hiện, dùng Thiên Cương Ấn đỡ cự trảo và Thuỷ tinh thuẫn bài hóa giải ngân quang, đồng thời hài lòng với lần thử bảo vật mới. Hắn kích hoạt Nguyên từ thần sơn, dịch chuyển ngọn núi cùng cự thú xuống mặt đất rồi đè đối phương bất động trong hố lớn. Hai phi kiếm tiếp đó hóa thành cự kiếm chém rơi hai đầu cự thú, trước khi thần sơn nghiền nát thân thể và thu toàn bộ quang điểm. Sau khi thu Oa oa, Hàn Lập bay sang chiến trường còn lại, nơi Liễu Thuý Nhi đang bị một cự thú bốn đầu có khí tức cỡ thánh giai dồn vào tình thế nguy cấp."},{"chuong":1685,"tieuDe":"Hợp Kích Bí Thuật","tomTat":"Liễu Thuý Nhi một mình chống đỡ ngân tuyến của cự thú bốn đầu bằng Ngân toa, Kim sắc tiểu cổ và hàng trăm đoá băng liên, nhưng việc duy trì thế phòng thủ khiến nàng tiêu hao nghiêm trọng. Khi Hàn Lập và Thạch Côn tới, ba người cùng thi triển hợp kích bí thuật, hợp lực tạo một ngân quang cầu khổng lồ chứa đầy phù văn rồi trút mưa phù văn xuống đối thủ. Liễu Thuý Nhi còn xé rách hư không để hút quang trụ hợp nhất của cự thú và phóng ngược trở lại, buộc nó phải dùng chính quang trụ của mình đối kháng. Trước sức ép của ba người, cự thú tiếp tục biến hoá, mọc thêm sừng, nanh, mắt, xúc tu và dựng hắc sắc quang mạc bảo vệ thân thể, khiến va chạm nguyên khí tạo thành cơn lốc dữ dội. Hàn Lập xuyên qua lớp quang mạc bằng lôi dực, áp sát cự thú rồi hiện hư ảnh ba đầu sáu tay để chém kim sắc tàn nhận vào lớp phòng ngự. Ở nơi cách chiến trường nhiều vạn dặm, một kim sắc thú ảnh đang dẫn theo nhóm tam mục ám thú bất ngờ dừng lại và ngoái nhìn về phía sau với vẻ kinh nghi."},{"chuong":1686,"tieuDe":"Truy Sát","tomTat":"Ám thú vương cảm ứng được những ngân mục ám thú đã bị giết nhưng chỉ phái một Tam mục ám thú quay lại xử lý kẻ xâm nhập, còn bản thân tiếp tục truy đuổi mục tiêu quan trọng hơn. Hàn Lập điều động pháp tướng sử dụng Huyền Thiên tàn nhận chém chết cự thú có thực lực không dưới thánh tộc sơ giai, đồng thời phát hiện lượng pháp lực tiêu hao đã giảm xuống chưa tới một phần ba so với trước. Hắn thu chiến lợi phẩm và cho Tiểu thú nuốt tổng cộng bảy viên nội đan ngân mục ám thú rồi thu nó vào linh thú hoàn chờ tiêu hóa. Liễu Thuý Nhi và Thạch Côn cảm tạ Hàn Lập, kinh ngạc trước thần thông của hắn và cùng quyết định nhanh chóng rời khỏi khu rừng. Trong mười lăm ngày tiếp theo, đoàn người liên tục bị các đàn ám thú phục kích nhưng đều tiêu diệt được chúng, dù hành trình vì thế chậm lại. Khi đến rìa Ám Thú sâm lâm, họ phát hiện hơn ba mươi ám thú chắn đường, trong đó Tam mục ám thú chiếm hơn phân nửa."},{"chuong":1687,"tieuDe":"Không Hẹn Mà Gặp","tomTat":"Hơn mười ám thú có thần thông ngang Luyện Hư Kỳ bao vây Hàn Lập, Liễu Thuý Nhi và Thạch Côn, buộc ba người phải chia nhau phá vòng vây theo đề nghị của Liễu Thuý Nhi. Hàn Lập dùng Lôi Độn, Liễu Thuý Nhi phối hợp lam sắc tinh cầu với ngọc bội, còn Thạch Côn dựa vào chiến giáp và độn thổ để thoát thân. Hàn Lập nhanh chóng bỏ xa truy binh, dùng Thanh Trúc Phong Vân Kiếm diệt những ám thú chặn đường rồi rời khỏi Ám Thú sâm lâm. Trên thảo nguyên, hắn dùng hồng sắc pháp bàn và nhận ra hai đồng bạn đã tới gần điểm hẹn nhưng chưa xuất hiện, vì vậy lập tức bay tới kiểm tra. Hàn Lập phát hiện Liễu Thuý Nhi và Thạch Côn đang đối mặt một nam một nữ thuộc Hải Vương Tộc, thế lực nằm trong tam đại thuỷ tộc và liên minh với Giác Xi Tộc. Cuộc đối thoại nhanh chóng trở nên căng thẳng khi nam tử Hải Vương Tộc châm chọc đối phương, khiến Thạch Côn bước lên công khai đòi lãnh giáo thần thông của hắn."},{"chuong":1688,"tieuDe":"Huyền Thiên Thánh Khí","tomTat":"Nam tử Hải Vương Tộc rút tam xoa kích định tấn công Thạch Côn, nhưng nữ tử đi cùng và Liễu Thuý Nhi đồng thời ngăn cuộc giao chiến. Sau khi cân nhắc tổn thất pháp lực và thực lực đôi bên, Liễu Thuý Nhi đề nghị hai nhóm xem như chưa từng gặp, được nữ tử Hải Vương Tộc chấp thuận. Rời khỏi nhóm Hàn Lập, nữ tử tiết lộ Huyền Thiên Thánh Khí do các trưởng lão ban cho đã phản ứng kịch liệt khi đến gần hắn, khiến hai người suy đoán hắn mang Huyền Thiên chi bảo hoặc một kiện thánh khí cực mạnh. Thực tế, kiện thánh khí chỉ cảm ứng được Huyền Thiên tàn nhận, còn Huyền Thiên quả thực phong ấn trong cánh tay Hàn Lập vẫn không bị phát hiện. Đôi nam nữ Hải Vương Tộc mừng vì đã tránh được giao chiến rồi tiếp tục nhiệm vụ bí mật, đồng thời lưu ý hướng đi của nhóm Hàn Lập trùng với hướng yêu vân Nhân Nguyên Tiên bỏ chạy. Về phía Hàn Lập, hắn cảm thấy nữ tử kia mang theo một mối uy hiếp khác thường và đề nghị cả nhóm nghỉ ngơi để khôi phục pháp lực. Liễu Thuý Nhi chần chừ vì lo việc nghỉ lại sẽ làm chậm hành trình tới cấm chế chi địa."},{"chuong":1689,"tieuDe":"Hung Hiểm","tomTat":"Sau khi rời xa hai người Hải Vương Tộc, Hàn Lập, Liễu Thuý Nhi và Thạch Côn chiếm một động quật trong núi xanh để điều tức, khôi phục pháp lực. Trên đường tìm cấm chế chi địa, họ lần lượt tiêu diệt một đàn quái điểu phun phong nhận và dùng thuật ẩn nặc vượt qua hồ nước có những cự thú phun cột nước. Một tháng sau, ba người giao chiến với bốn Dạ Tộc Nhân trên hoang nguyên, rồi phối hợp thi triển Nguyên từ thần quang tiêu diệt toàn bộ đối phương trước khi trời tối. Ba tháng sau, họ bị ngân triều hung trùng có sức phá hoại không kém Phệ Kim Trùng truy đuổi suốt ba ngày ba đêm, khiến pháp lực tiêu hao gần một nửa. Hàn Lập đề nghị dẫn đàn hung trùng tới khu vực có thượng cổ mãnh thú, nhưng nơi đó vẫn còn cách khoảng một ngày đường. Khi cả nhóm chưa thoát khỏi ngân triều, một đàn lục sắc quái điệp dữ tợn lại xuất hiện phía trước, đẩy họ vào tình thế bị uy hiếp từ hai phía."},{"chuong":1690,"tieuDe":"Hung Trùng Chi Chiến","tomTat":"Hàn Lập, Liễu Thuý Nhi và Thạch Côn nhận ra đàn lục điệp là Hoá Huyết Điệp, thiên địch của ngân sắc phi trùng, rồi quyết định chia ba hướng thoát thân và hẹn hội hợp sau hai tháng tại cấm chế chia địa. Hai đàn hung trùng chia lực lượng vừa giao chiến vừa truy đuổi, trong đó Hoá Huyết Điệp dùng độc phong hạ sát và nuốt ngân trùng, còn ngân trùng dựa vào số lượng cùng khả năng kháng độc để giằng co. Hơn trăm dị thú bị cuốn vào trận chiến và chết không còn hài cốt. Hàn Lập dùng Phong Lôi sí bỏ xa đàn thú, nhưng một nhóm hơn ngàn ngân trùng vẫn truy tìm được hắn bất chấp Hắc sa ẩn nặc. Đàn trùng hợp thể thành một cự trùng có khả năng thuấn di, buộc Hàn Lập phải phóng hàng trăm Phệ Kim Trùng thành thục ra nghênh chiến. Ngân sắc cự trùng lập tức hoảng sợ tháo chạy, nhưng Hàn Lập dùng Lôi Độn chặn đầu rồi tung Nguyên Từ Thần Sơn, tạo quang mạc bằng Nguyên từ thần quang để vây khốn toàn bộ đàn trùng trong lúc Phệ Kim Trùng áp sát."},{"chuong":1691,"tieuDe":"Lôi Bằng Khôi Lỗi","tomTat":"Hàn Lập thả Phệ Kim Trùng áp đảo hơn ngàn ngân sắc phi trùng, sau đó dùng Ngũ sắc hàn diễm bắt và cắt nát ngân ảnh nhân diện trùng đang tìm cách trốn thoát. Nhận thấy nguyên thần vừa bị diệt có lai lịch bất thường, hắn thu hồi linh trùng cùng Hắc sắc tiểu sơn, liên tục đổi hướng và dùng Thái Nhất Hoá Thanh Phù che giấu hành tung trước khi tiếp tục lên đường. Ở nơi cách đó hơn mười vạn dặm, một Nhân diện cự trùng cảm ứng được biến cố, triệu tập ngân trùng phụ cận thành một cự thể rồi bay đi. Hai tháng sau, tại một sa mạc bão cát trong Nghiễm Hàn Giới, sáu dị tộc nhân đi trên ba chiến xa dùng Thanh đồng cổ kính phát hiện phế tích đền đài rộng lớn. Khi họ chuẩn bị hạ xuống, một Lôi bằng khôi lỗi đầy thương tích bất ngờ lao tới tấn công. Sáu dị tộc nhân hợp nhất Ngân sắc pháp luân và điều khiển quái thú phun thanh sắc hoả diễm để chống trả, khiến hai bên giao chiến dữ dội mà chưa phân thắng bại."},{"chuong":1692,"tieuDe":"Ảnh Tinh","tomTat":"Lôi bằng khôi lỗi giao chiến dữ dội với sáu gã Hắc Nho Tộc, phá thế hợp kích của sáu pháp luân nhưng cuối cùng vẫn bị đánh đến thân thể tàn liệt và rơi xuống phế tích. Nhóm Hắc Nho Tộc giành chiến thắng sau khoảng một canh giờ song bảo vật, chiến giáp và khôi lỗi đều chịu tổn thất nặng. Ngay khi họ chuẩn bị thu chiến lợi phẩm, hơn mười người Giác Xi Tộc do một thanh niên ba sừng vàng chỉ huy bất ngờ xuất hiện và tuyên bố sẽ diệt khẩu. Ba chiến xa của Hắc Nho Tộc vừa bỏ chạy đã bị thuật thuấn di chặn đầu, buộc sáu người phải liều mạng chống trả trong tình thế tuyệt vọng. Cách chiến trường mấy trăm dặm, Hàn Lập và Liễu Thuý Nhi ẩn trong một lầu các đổ nát, dùng Ảnh Tinh theo dõi toàn bộ diễn biến. Liễu Thuý Nhi lo Giác Xi Tộc cũng nhắm tới cấm chế chi địa, còn Hàn Lập cho rằng khả năng hai bên trùng mục tiêu không cao nhưng vẫn đồng ý đổi nơi ẩn thân. Hai người quyết định tiếp tục dùng Ảnh Tinh xác định ý đồ của đối phương rồi chờ Thạch Côn đến hội hợp, đồng thời lưu ý rằng bảo vật sẽ vô dụng nếu mục tiêu dùng cấm chế che giấu hành động."},{"chuong":1693,"tieuDe":"Thái Ất Thanh Quang","tomTat":"Một thanh niên Giác Xi Tộc kích phát hắc viên bát, thả hắc khí che kín bầu trời rồi cùng đồng bọn dùng huyễn thuật cắt đứt sự quan sát qua ảnh tinh. Không muốn làm lộ hành tung, Hàn Lập quyết định tránh đối đầu, dự kiến bố trí nhiều tầng pháp trận che giấu quá trình phá cấm và phái Oa oa mang hắc sa cùng Thái Nhất Hoá Thanh Phù đi giám thị. Liễu Thuý Nhi cũng thả một tiểu thú có cánh, phát ngũ sắc quang mang và sở hữu độn tốc cực nhanh để phối hợp theo dõi Giác Xi Tộc. Hai người tiếp tục vượt qua di chỉ thượng cổ rồi tìm thấy bạch sắc quang hà nuốt bão cát, xung quanh chất đầy xương thú. Liễu Thuý Nhi dùng pháp trận bàn xác nhận đây là cấm chế chi địa do sư phụ nàng cùng Đoạn tiền bối chỉ dẫn. Nàng tiết lộ cấm chế hình thành từ Thái Ất thanh quang, một loại thiên địa kỳ quang cực hiếm và sắc bén, chỉ có thể bị khắc chế bằng Nguyên từ thần quang của ba người có Nguyên từ thần thể. Từ đặc tính không thể hậu thiên tu luyện của kỳ quang, Hàn Lập suy đoán phía dưới cấm chế có một bảo vật có thể sử dụng hoặc ẩn chứa Thái Ất thanh quang."},{"chuong":1694,"tieuDe":"Tuyết Hống Tộc","tomTat":"Liễu Thuý Nhi dùng một thanh phi xoa đỏ thử bạch sắc quang hà, còn Hàn Lập vận dụng Minh Thanh linh mục để nhận ra những hư ảnh trong suốt cấu thành Thái Ất thanh quang. Hàn Lập tiếp tục đưa một thanh Thanh Trúc Phong Vân Kiếm vào cấm chế; phi kiếm bị chém vỡ nhưng được hắn thu hồi và tái ngưng tụ nguyên vẹn. Từ việc nguồn thanh quang vẫn được duy trì qua thời gian dài, hắn suy đoán Thái Ất thanh sơn có thể nằm tại đây và hy vọng dùng nó luyện đệ nhị cực sơn. Hai người tạm lui tới một điện phủ đổ nát giữa bão cát để chờ Thạch Côn, người tới sau nửa tháng trong tình trạng nguyên khí tổn thương vì bị Tuyết Hống Tộc truy sát. Sau khi nghe kể về chủng tộc chuyên tu thần thông băng này, cả nhóm chờ Thạch Côn hồi phục và tiếp tục giám sát nhóm Giác Xi Tộc ở xa. Ba người sau đó trở lại bạch sắc quang hà, lập thế tam giác và chuẩn bị dùng sức liên thủ cùng Nguyên từ thần sơn để phá liên tục mười một tầng cấm chế. Trước khi bắt đầu, Hàn Lập xác nhận lại giao ước phân chia bảo vật với Liễu Thuý Nhi và Thạch Côn rồi hài lòng chấp nhận cam kết của họ."},{"chuong":1695,"tieuDe":"Phá Cấm","tomTat":"Liễu Thuý Nhi dùng Tị không tán phong bế phạm vi mười dặm rồi bố trí Kim Đô Cấm Linh trận để che giấu linh áp và phòng bị ngoại địch. Thạch Côn đặt mười ba viên Âm phách tử mẫu hoàn quanh khu vực, còn Hàn Lập vì cảm thấy bất an nên thúc giục mọi người lập tức phá cấm. Ba người lần lượt vận dụng tiểu phiên màu đen, Nguyên Quang lệnh bài và Nguyên cực từ sơn, hợp nhất ba luồng Nguyên từ chi lực thành một phù văn khổng lồ. Phù văn này khắc chế Thái Ất thanh quang và liên tiếp phá tan chín tầng cấm chế trước khi gần cạn uy năng. Liễu Thuý Nhi kịp bổ sung Nguyên từ thần quang, sau đó cả ba đồng thời công kích tầng cấm chế thứ mười và đánh tan đợt phản kích của Thái Ất thanh quang. Tầng cuối hóa thành màn cát vàng sẫm, khiến từng hạt cát phình lớn rồi dồn ép Nguyên Quang lệnh bài cùng Nguyên cực từ sơn. Hai dị bảo vẫn chống đỡ được, đồng thời cổ văn và ngân sắc phù văn trên chúng bắt đầu phát sáng, báo hiệu uy năng thực sự sắp được triển khai."},{"chuong":1696,"tieuDe":"Thu Sơn","tomTat":"Hàn Lập dùng Nguyên Từ Cực Sơn hút phần lớn biển cát vàng, rồi phối hợp lệnh bài lam chuôi hóa thành cự kiếm màu xám để phá đệ thập trọng cấm chế. Trọng cấm chế thứ mười một hiện ra dưới dạng một bức họa thanh sơn chứa đàn linh cầm và Thái Ất Thanh Sơn, với bích võng Thái Ất thanh quang khắc chế Nguyên Từ chi lực. Hàn Lập nhận ra ngọn núi mình tìm kiếm và cùng Thạch Côn giao chiến với cấm chế, sau đó Liễu Thuý Nhi dùng phiên kỳ trợ chiến. Ba người hợp lực đánh tan bích võng, phá hủy bức họa và mở ra một cửa vào tỏa ánh sáng trắng ngà. Nhân lúc hai đồng hành chú ý tới cửa động, Hàn Lập nhanh chóng dùng Nguyên Từ Cực Sơn trấn áp và thu lấy Thái Ất Thanh Sơn đang suy yếu. Liễu Thuý Nhi cùng Thạch Côn tuy nhận ra giá trị của bảo vật nhưng cuối cùng đều chấp nhận việc Hàn Lập đã giành được trước, rồi hướng sự chú ý về những trọng bảo có thể nằm phía trong."},{"chuong":1697,"tieuDe":"Sơn Phong, Cung Điện, Thạch Giai","tomTat":"Liễu Thuý Nhi và Thạch Côn lần lượt tiến vào lỗ thủng cấm chế, còn Hàn Lập kiểm tra xung quanh rồi mới theo sau và được ngũ sắc quang trận truyền tống tới một không gian riêng. Tại đây, cả nhóm nhìn thấy đài đá, kỳ hoa dị thảo cùng một ngọn núi có cung điện màu tím phát ngân quang trên đỉnh. Hàn Lập và Thạch Côn thử phi hành nhưng bị cấm chế ép xuống, đồng thời phát hiện sức cấm không tăng gấp đôi sau mỗi thước độ cao. Lo ngại Giác Xi Tộc đang ở gần, ba người quyết định không trì hoãn và lập tức tiến về cung điện. Thạch Côn thả cự lang khôi lỗi bằng sắt để hỗ trợ trong hoàn cảnh pháp khí và bảo vật bị hạn chế. Khi bước lên sơn đạo gồm hàng vạn bậc đá trắng, họ phát hiện hấp lực tăng dần theo từng bậc; Hàn Lập và Thạch Côn vẫn tiếp tục tiến lên nhờ thân thể mạnh mẽ, còn Liễu Thuý Nhi dừng ngay tại bậc đầu tiên."},{"chuong":1698,"tieuDe":"Lên Núi Khó Khăn","tomTat":"Hàn Lập, Thạch Côn và Liễu Thuý Nhi cùng tranh nhau vượt sơn đạo để tới tử sắc cung điện trước và giành lợi thế đoạt bảo. Liễu Thuý Nhi dùng ba tấm phù vàng, bạc và đỏ gia trì thân thể nhưng vẫn nhanh chóng kiệt sức, phải dừng lại dùng đan dược khôi phục. Hàn Lập dựa vào thể chất mạnh mẽ để vượt qua Thạch Côn, khiến đối phương phải nuốt huyết sắc đan hoàn và vận dụng bí thuật biến thành cự nhân đuổi theo. Trước sự truy đuổi ấy, Hàn Lập triệu kim sắc pháp tướng ba đầu sáu tay, dung hợp thành quang giáp rồi bỏ xa Thạch Côn hàng trăm bậc. Tuy nhiên, hấp lực của cấm chế càng gần đỉnh càng tăng dữ dội, lần lượt ép Liễu Thuý Nhi và Thạch Côn dừng chân. Hàn Lập tiến được tới hơn mười bậc cuối nhưng kim giáp đã có nguy cơ tan rã, buộc hắn phải dừng lại khi tử sắc cung điện chỉ còn trong gang tấc."},{"chuong":1699,"tieuDe":"Tân Thần Thông","tomTat":"Hàn Lập vượt qua những bậc đá cuối cùng và lên đỉnh núi trước Thạch Côn cùng Liễu Thuý Nhi, nhờ đó giành thời gian thăm dò tử điện. Những khối linh thạch dị thường trên cửa và Ngân khoa văn trên tường khiến hắn nhận định đây là nơi ở của tiên nhân Tiên giới, nhưng tử quang cùng lực lượng vô hình đều ngăn cản các phép thăm dò trực tiếp. Hắn dùng cự viên khôi lỗi mở cửa và tiến vào một quảng trường xanh có chủ điện màu tím cùng ba điện nhỏ ở phía trước. Sau khi đi một thời gian mà vẫn quanh quẩn gần góc quảng trường, Hàn Lập xác định mình đã mắc vào một ảo trận mà linh mục thông thường không thể nhìn thấu. Hắn lần đầu đưa thần thông dung hợp giữa Phá Diệt pháp mục và Minh Thanh linh mục vào thực chiến, tạo ra quang cầu đen xanh rồi phóng ti võng phủ khắp không gian. Sức mạnh này làm các lớp hào quang nổ tung, khiến hư không vặn vẹo và ép một quang môn lớn hiện ra tại trung tâm quảng trường."},{"chuong":1700,"tieuDe":"Tử Điện","tomTat":"Hàn Lập cùng cự viên khôi lỗi vượt qua quang môn tiến vào khu vực Tử kim đại điện, sau đó quang môn biến mất và quảng trường bên ngoài trở lại trạng thái ban đầu. Trong khi Thạch Côn và Liễu Thuý Nhi tiếp tục tiến gần đỉnh núi, Hàn Lập nhận ra cổ văn trên bảng hiệu có khả năng là Kim Triện Văn nhưng không thể đọc. Hắn điều khiển khôi lỗi thử mở cửa chủ điện, khiến cấm chế tử sắc lôi điện phát động, hủy khôi lỗi rồi truy kích chính hắn. Thủy tinh tiểu thuẫn bị hòa tan hoàn toàn và lôi y cũng bị thôn phệ, nhưng Thiên ngoại ma giáp phóng hắc sắc phù văn triệt tiêu đợt công kích cuối cùng. Nhận thấy phá cấm chế chủ điện sẽ mất quá nhiều thời gian và có thể tạo cơ hội cho hai người phía sau, Hàn Lập quyết định chuyển sang một tòa thiên điện. Sau khi dùng khôi lỗi khác thăm dò và chuẩn bị nhiều lớp phòng hộ, hắn xác nhận cửa thiên điện không có cấm chế rồi tiến vào. Bên trong là không gian thờ phụng có bàn thờ bạch ngọc, thần tượng màu tím, hàng trăm bồ đoàn vàng, bốn lư hương xanh và hương đàn thơm ngát."},{"chuong":1701,"tieuDe":"Bồ Đoàn, Đàn Hương, Thần Tượng","tomTat":"Hàn Lập khám xét đại sảnh có bố trí giống chùa miếu và thu hơn mười bảo vật bán thành phẩm cao giai đặt trên hai giá Tuyết mộc. Hắn dùng Thanh Trúc Phong Vân Kiếm thử độ bền của một chiếc bồ đoàn, từ đó nhận ra hơn trăm bồ đoàn trong điện đều được bện bằng Giáp Y thảo có khả năng chống trảm kích và tự phục hồi. Tiếp đó, hắn phát hiện ba phần tàn hương trong các lư đồng là Hắc u băng hương, thánh vật giúp trừ tâm ma khi đột phá Hợp Thể cảnh, rồi cẩn thận cất chúng vào ngọc hạp. Khi vận dụng Minh Thanh linh mục nhìn xuyên lục hà che mặt thần tượng, Hàn Lập bị phạm âm thiên nhạc chấn động thần thức hải và suýt ngã. Lo ngại pho tượng có liên hệ với một đại thần thông giả tại Chân tiên giới, hắn kiềm chế lòng tham và quyết định không mang nó đi. Sau đó, Hàn Lập cùng cự viên khôi lỗi rời đại sảnh, mở cửa hơn mười gian sương phòng và bước vào căn phòng đầu tiên để tiếp tục khám xét."},{"chuong":1702,"tieuDe":"Kim Kiếm Đồ","tomTat":"Hàn Lập tìm kiếm khu phòng ở trong thiên điện nhưng không thấy bảo vật đáng giá, chỉ thu vài ngọc giản ghi bằng loại cổ văn chưa biết để sau này nghiên cứu về Chân tiên giới. Qua một cửa hông khác, hắn phát hiện dãy mật thất tu luyện được bảo vệ bằng cấm chế Ngân Khoa văn. Sau khi xác nhận cấm chế không phản kích, hắn dùng hắc sắc tiểu sơn phá lớp ngân quang rồi lấy Thanh Trúc Phong Vân Kiếm chém mở từng cửa đá. Trong mật thất thứ bảy, Hàn Lập tìm thấy Kim Kiếm Đồ chứa vô số hình phi kiếm và bị thần niệm chi lực từ bức tranh đánh lui như trúng kiếm kích. Hắn dùng hơn mười phù lục phong ấn kim quang cùng khí tức của bức tranh rồi thu lấy để nghiên cứu bản chất và pháp môn có thể ẩn chứa bên trong. Ba hộp ngọc gần đó chứa các phù lục Ngân Triện văn đã mất linh khí, còn hai bình nhỏ chỉ lưu lại mùi linh dịch, nhưng hắn vẫn giữ các phù lục vì giá trị nghiên cứu và phục chế. Sau khi kiểm tra những mật thất còn lại, Hàn Lập rời thiên điện và suy đoán Thạch Côn cùng Liễu Thuý Nhi đã lên tới đỉnh núi."},{"chuong":1703,"tieuDe":"Dược Viên","tomTat":"Hàn Lập nhận định hai người đang vượt ảo trận ngoài quảng trường chưa thể nhanh chóng tiến vào nên tranh thủ tìm kiếm bảo vật trong khu di tích. Sau khi cân nhắc hai thiên điện, hắn lần theo mộc linh khí và dược hương tới khu lầu các phía sau chủ điện, nơi có một dược viên tiên nhân được bảo vệ nghiêm ngặt. Hắn dùng Phệ Linh Thiên Hỏa bào mòn ngũ sắc quang tráo, nhưng các tử kim quang trụ liên tục bổ sung linh lực khiến màn sáng tự khôi phục. Khi hỏa điểu được thúc lớn và phá vỡ từng mảng quang tráo, cấm chế chuyển sang phóng tử sắc hồ quang hợp thành lôi cầu phản kích. Hàn Lập triển khai Thiên Ngoại ma giáp, phù lục phòng hộ và Nguyên Từ Cực Sơn; dù Nguyên Từ Thần Quang không khắc chế được loại lôi điện này, hắc sắc quang võng vẫn làm lôi cầu suy yếu trước khi va vào ngọn núi. Hai luồng tử điện vòng qua pháp bảo tạo thành cơn lốc điện, nhưng hắn dùng pháp tướng ba đầu sáu tay phối hợp với quang trụ từ ma giáp để đánh tan. Ngay lúc Hàn Lập lao về phía dược viên, ngũ sắc quang tráo đột ngột tái lập khiến hắn không kịp dừng, chui vào màn sáng và tiếp tục đối mặt với những tử sắc điện xà mới hình thành."},{"chuong":1704,"tieuDe":"Trịch Sơn","tomTat":"Bị ngũ sắc quang hà giam cứng giữa lúc năm đạo tử điện đánh tới, Hàn Lập gọi pháp tướng kim thân ba đầu sáu tay vừa luyện thành để chống đỡ và bóp tan điện hồ. Trước khi các tử kim quang trụ tiếp tục phát động, hắn vận chuyển huyền công, hóa thành Sơn Nhạc cự viên cao hơn mười trượng và dùng thần lực xé vỡ quang tráo đang trói buộc mình. Hàn Lập tiếp tục dùng ngân sắc hỏa điểu đẩy lui ngũ sắc quang hà, sau đó trực tiếp cầm Nguyên Từ Cực Sơn ném về phía các quang trụ. Những cú ném liên tiếp đánh hỏng quá nửa cả năm cây cột, khiến ngũ sắc quang tráo mất nguồn hỗ trợ và bị ngân sắc hỏa điểu cắn nuốt hoàn toàn. Sau khi giải trừ Kinh Trập quyết và trở lại hình người, Hàn Lập nhận ra Sơn Nhạc cự viên biến đặc biệt phù hợp với thể chất của mình vì có thể tăng mạnh sức mạnh thân thể."},{"chuong":1705,"tieuDe":"Hồng La Tiên Tửu, Thực Độc Thảo","tomTat":"Sau khi ngũ sắc quang tráo tan đi, Hàn Lập tiến vào dược viên và kiểm tra những mảnh linh dược còn sót lại từ thời thượng cổ. Hắn nhận ra hơn trăm cây Hồng La Quả, nguyên liệu chính để ủ Hồng La tiên tửu, đồng thời nhớ lại loại rượu này có hương vị đặc biệt, giúp cải thiện thể chất và thậm chí có thể làm tiên nhân say bất tỉnh. Tuổi đời nhiều vạn năm của số linh quả khiến hắn tin rằng chúng có giá trị rất lớn và có thể tạo ra linh tửu mang công hiệu khác thường. Ở một mảnh dược điền khác, Hàn Lập phát hiện khoảng bảy tám mươi gốc Thực Tâm thảo, loài độc thảo đã tuyệt diệt tại Linh giới nhưng lại là nguyên liệu của nhiều loại đỉnh giai đan dược. Hắn lấy một ngọc hạp lớn ra, gọi Khúc nhi và giao nàng thu hái toàn bộ linh dược trong ba mảnh ruộng. Khúc nhi dùng bích ti nhổ nguyên vẹn từng nhóm cây khỏi đất, nhanh chóng thu gom hơn trăm gốc linh dược vào ngọc hạp."},{"chuong":1706,"tieuDe":"Thúc Thủ Vô Sách","tomTat":"Khúc nhi thu hoạch trọn ba loại linh dược và xếp chúng vào ngọc hạp, còn Hàn Lập gom những dược thảo quý hiếm trong các dược điền thông thường. Khi khảo sát hơn mười khu trồng riêng cùng một đại linh tuyền, hắn gặp nhiều linh thụ, linh hoa và đài sen bạc không được ghi chép tại Nhân giới hay Linh giới nên phỏng đoán chúng có thể bắt nguồn từ Tiên giới. Hàn Lập dùng Nguyên Từ Thần Quang đối phó lớp kim linh khí dưới đất, rồi phải mượn sức Nguyên Từ Cực Sơn mới phá được lớp phòng hộ. Tuy nhiên, năm linh dược hắn thử đào liên tiếp tự hủy bằng những phương thức khác nhau ngay khi rời đất. Thần niệm và Minh Thanh linh mục đều không tìm ra dấu vết cấm chế, khiến hắn suy đoán cơ chế tự hủy nằm ở bộ rễ. Không thể di dời nguyên cây, Hàn Lập đổi sang thu hoạch hoa quả và hạt giống, dùng kiếm ti cắt một đóa kỳ hoa rồi lập tức lấy Ngũ sắc quang diễm đóng băng nó vào hộp ngọc."},{"chuong":1707,"tieuDe":"Ngân Sắc Đài Sen","tomTat":"Hàn Lập dùng kiếm quang cắt tám gốc linh dược, đóng băng và phong cấm chúng để ngăn cấm chế tiềm ẩn kích phát khiến linh dược tự diệt. Khi thử thu ngân sắc đài sen, hắn phát hiện cuống sen không những đẩy bật kiếm ti mà còn phản chấn phá vỡ đòn hợp nhất từ mười đạo kiếm ti. Nhờ pháp mục, Hàn Lập nhận ra bộ rễ chỉ cuộn nổi dưới đáy linh tuyền nên bố trí pháp trận, dùng bình ngọc màu xanh hút trọn nước suối, đài sen và bộ rễ. Hắn tiếp tục vét sạch những linh dược còn lại, gọi Khúc nhi trở vào tay áo rồi rời dược viên để tới chủ điện. Tại đó, Thạch Côn và Liễu Thuý Nhi đã phá được ảo thuật ngoài quảng trường nhưng cấm chế tử điện ở cửa điện đánh tan đôi cự chùy của Thạch Côn và phá hủy gương bạc của Liễu Thuý Nhi. Nhận thấy cấm chế rất mạnh, Hàn Lập đề nghị ba người liên thủ phá giải. Thạch Côn tỏ vẻ ghen tị với thu hoạch riêng của Hàn Lập, còn Liễu Thuý Nhi bình tĩnh cho rằng việc giành được bảo vật phụ thuộc vào cơ duyên và bản sự."},{"chuong":1708,"tieuDe":"Cân Bằng Cùng Phá Cửa","tomTat":"Liễu Thuý Nhi và Thạch Côn đề nghị Hàn Lập gánh thêm sức trong việc phá cấm chủ điện vì hai người đã tiêu hao hơn nửa pháp lực và mất các bảo vật thuận tay. Dù kiêng kỵ lẫn nhau, ba người vẫn duy trì hợp tác do Hàn Lập bị ràng buộc bởi lời hứa và đạo tâm, còn hai người kia không chắc có thể thắng hắn ngay cả khi liên thủ. Hàn Lập yêu cầu đồng bạn sử dụng toàn bộ thủ đoạn chuyên phá cấm rồi chủ động dùng Nguyên từ thần sơn công kích cửa điện, đồng thời triệu hồi Thiên ngoại ma giáp và Phạm Thánh kim thân chống tử sắc lôi điện phản kích. Liễu Thuý Nhi dùng ba cây giáo ngắn hấp thu phần lớn uy năng điện võng, còn Thạch Côn kích nổ bạch liên do phù phá cấm tạo thành để quét sạch tử sắc hồ quang. Khi cấm chế suy yếu, Hàn Lập thúc Nguyên từ thần sơn đánh vỡ hoàn toàn cửa chủ điện. Liễu Thuý Nhi và Thạch Côn lập tức tranh tới trước cửa rồi cùng dừng lại đề phòng nhau, sau đó Liễu Thuý Nhi tuyên bố Hư Linh đan nhất định phải thuộc về phía sư phụ nàng."},{"chuong":1709,"tieuDe":"Bình Phong, Kim Đỉnh","tomTat":"Thạch Côn và Liễu Thuý Nhi đều phụng lệnh sư phụ giành Hư Linh đan nên không ai chịu nhường, dù Liễu Thuý Nhi đề nghị đổi bằng một lọ Tinh Nguyệt Dịch. Khi hai bên sắp trở mặt, Hàn Lập nhắc rằng họ còn chưa xác nhận bảo vật có thật sự ở trong điện, khiến cả ba tạm gác tranh chấp và cùng tiến vào. Chủ điện rộng lớn chứa nhiều cột tím vàng, binh khí cổ và giáp trụ, nhưng đáng chú ý nhất là bình phong phủ thanh quang cùng kim sắc cổ đỉnh ở phía trước. Hàn Lập dùng linh mục nhìn xuyên bình phong và thấy một quái môn phủ Ngân khoa văn cùng Kim triện văn, song luồng thần niệm dò xét lập tức bị kéo vào rồi cắt đứt. Kim sắc cổ đỉnh cũng ngăn thần niệm, có hoa văn xoắn ốc và hai vết lõm dùng để đặt hai vật tương ứng. Liễu Thuý Nhi tiết lộ nàng và Thạch Côn mỗi người đều mang một vật cần thiết để lấy bảo vật trong đỉnh, còn Thạch Côn lấy ra vật phát kim quang đầu tiên ngay trước khi chương kết thúc."},{"chuong":1710,"tieuDe":"Đỉnh Trung Thủ Bảo","tomTat":"Liễu Thuý Nhi và Thạch Côn lần lượt đưa ra Phượng Linh Lung Thược và Long Linh Lung Thược, xác nhận phải dùng đủ cả hai mới có thể mở kim đỉnh được cho là đang cất Hư Linh đan. Để tránh nghi kỵ và tranh chấp, họ giao cặp chìa khóa cho Hàn Lập thực hiện việc mở đỉnh. Sau khi được rót pháp lực, hai chìa khóa hóa thành giao long và phượng hoàng, kích hoạt kim đỉnh cùng vòng xoáy kim quang có khả năng tác động đến tâm thần. Hàn Lập vận chuyển Đại Diễn Quyết và dùng linh mục để hóa giải ảnh hưởng, rồi đánh pháp quyết khiến nhiều kim sắc quang đoàn bay khỏi đỉnh. Nguyên Từ Thần Quang không thể giữ những quang đoàn này, nên hắn triệu Hư Thiên Bảo Đỉnh, kết thanh ti thành lưới và thu toàn bộ chúng vào trong. Thạch Côn nhận ra bảo đỉnh tương tự một vật từng thấy trên bản sao Hỗn Độn Vạn Linh Bảng và giải thích rằng bảng này ghi chép, thường xuyên cập nhật các thiên địa linh vật cùng chí bảo tại Linh giới."},{"chuong":1711,"tieuDe":"Kim Hồ Cùng Hóa Hình Linh Dược","tomTat":"Trước khi kiểm tra những thứ lấy được từ Hư Thiên Đỉnh, Hàn Lập dựng một cấm chế pháp trận bao quanh khu vực để đề phòng bất trắc. Vật đầu tiên được lấy ra là Hồ Trung Kiếm, một hồ lô vàng chứa nhiều phi kiếm, nhưng Liễu Thuý Nhi và Thạch Côn xác nhận đây không phải mục tiêu do sư trưởng giao phó nên để Hàn Lập tạm giữ. Tiếp đó, hai cây Ngưng Thuỷ Thảo đã hóa thành tiểu mã xanh biếc được chia cho Liễu Thuý Nhi và Thạch Côn, khiến sự nghi ngờ của họ đối với Hàn Lập tiêu tan. Hàn Lập tiếp tục tạm thu pháp bàn lục giác và kim sắc bảo tháp, còn loại tài liệu quý hiếm do Thải Lưu Anh cùng Đoạn Thiên Nhận chỉ định được chia đều cho hai người đồng hành. Khi Hư Linh Đan vẫn chưa xuất hiện, Liễu Thuý Nhi và Thạch Côn bắt đầu bất an. Cuối cùng, Hàn Lập mở một tử kim tiểu bình vừa được lấy khỏi đỉnh, khiến kim sắc linh diễm phun ra rồi hóa thành một con hỏa điểu vàng óng."},{"chuong":1712,"tieuDe":"Bình Trung Động Thiên","tomTat":"Hàn Lập dùng năm đạo hàn diễm ép hai viên đan dược hóa thành kim sắc hỏa điểu trở lại nguyên hình, rồi chia Hư Linh Đan cho Liễu Thuý Nhi và Thạch Côn. Thạch Côn kiểm tra tử kim tiểu bình vì nghi còn viên thứ ba nhưng chỉ thấy bên trong trống rỗng. Hai tài liệu quý hiếm cuối cùng trong Hư Thiên Bảo Đỉnh cũng được Liễu Thuý Nhi và Thạch Côn chia nhau nhận lấy. Ba dị bảo sau đó lần lượt có chủ: Hàn Lập giữ kim sắc hồ lô, Liễu Thuý Nhi lấy kim sắc bảo tháp, còn Thạch Côn nhận lục giác pháp bàn. Thạch Côn tiếp tục nhanh tay thu lấy kim sắc cổ đỉnh vì cho rằng nó còn công dụng khác. Khi Hàn Lập dùng pháp mục dò xét tấm bình phong, thất sắc quang hà bất ngờ phun ra cuốn hắn biến mất. Liễu Thuý Nhi và Thạch Côn chạy tới, phát hiện mặt sau bình phong đã hiện bốn cổ văn mang nghĩa Bình trung động thiên."},{"chuong":1713,"tieuDe":"Đắc Đan","tomTat":"Hàn Lập tiến vào không gian bí mật trong bình phong rồi dùng trận bàn tạo sương mù, che khuất bản thân cùng cánh cửa khổng lồ khỏi tầm quan sát bên ngoài. Hắn gọi Khúc nhi ra khỏi Hư Thiên Đỉnh và nhận viên Hư Linh Đan nàng đã bí mật lấy được theo kế hoạch, sau đó kiểm tra rồi phong kín linh đan trong tử kim tiểu bình. Hàn Lập giải thích rằng chỉ lấy một trong ba viên mới đủ an toàn để không khiến Thải Lưu Anh và Đoạn Thiên Nhận phát hiện bất thường. Hắn cho Khúc nhi giữ hắc sa cùng Thái Nhất Hóa Thanh Phù, đồng thời thưởng nàng bộ ba trăm sáu mươi phi đao luyện từ cánh quái nga và lệnh nàng trở về bản thể luyện hóa. Ở bên ngoài, Thạch Côn và Liễu Thuý Nhi không thể phá cấm chế bình phong; Liễu Thuý Nhi còn suy đoán Hàn Lập sở hữu Phá Diệt Pháp Mục. Lo việc phá cửa sẽ cắt đường lui và chọc giận Hàn Lập, hai người quyết định chuyển sang các thiên điện khác, còn Thạch Côn thu gom binh khí cùng khôi giáp trong chủ điện trước khi rời đi."},{"chuong":1714,"tieuDe":"Giáp Sĩ","tomTat":"Liễu Thuý Nhi dùng viên hoàn màu xanh biếc thu hết binh khí và khôi giáp còn lại trong chủ điện, sau đó cùng Thạch Côn chuyển sang một thiên điện khác tìm bảo vật. Trong Tu di động thiên, Hàn Lập lần lượt dùng Ngũ sắc hàn diễm, Nguyên từ thần quang và Ích Tà Thần Lôi nhưng không phá được cấm chế trên đại môn. Phệ linh thiên hoả hoá thành ngân sắc hoả điểu, làm quang hà cùng phù văn kim ngân nhanh chóng suy yếu. Hàn Lập tiếp tục hoá thành cự viên ném Nguyên từ thần sơn khiến cửa lõm sâu, song đại môn vẫn tự khôi phục. Hắn bèn triệu kim thân pháp tướng ba đầu sáu tay, vận dụng Huyền Thiên tàn nhận hấp thu thiên địa nguyên khí và chém đôi cánh cửa. Sau đại môn, Hàn Lập phát hiện một sân rộng khép kín với đài cao vẽ nhật nguyệt tinh không, ghế bành xanh biếc và chín khôi lỗi giáp bạc cầm ngân thương trong tư thế kỳ dị."},{"chuong":1715,"tieuDe":"Tinh Không Đồ Cùng Pháp Quyết","tomTat":"Hàn Lập phát hiện một quang đoàn vàng bí ẩn trên bầu trời Tu di động thiên và xác định chín ngân giáp giáp sĩ bên dưới là khôi lỗi tự hành có khả năng phản kích. Khi chăm chú quan sát tinh không đồ trên sân đá, hắn bị kéo vào huyễn cảnh nhật nguyệt và quần tinh vận chuyển, cảm nhận hàng vạn năm trôi qua chỉ trong vài nhịp thở. Đại Diễn Quyết tự hành vận chuyển, cưỡng ép kéo thần niệm hắn trở lại trước khi hắn vĩnh viễn mắc kẹt, rồi được tiếp tục vận hành để hóa giải xung đột giữa ký ức huyễn cảnh và thời gian thực. Sau đó, hơn một trăm chữ Ngân khoa văn hiện trên ghế xanh; Hàn Lập ghi nhớ toàn bộ trước khi chúng tan thành linh quang nhập lại vào ghế. Nhận ra đây là một đoạn pháp quyết kích phát không rõ đối tượng, hắn không dùng chân thân mà triệu xuất kim thân pháp tướng rồi cho đệ nhị Nguyên Anh phụ thân. Đệ nhị Nguyên Anh tụng pháp quyết ba lần, nhưng cả quang đoàn vàng lẫn chín khôi lỗi đều không xuất hiện biến hóa."},{"chuong":1716,"tieuDe":"Quang Trụ","tomTat":"Hàn Lập cân nhắc giữa nguy hiểm và cơ duyên rồi quyết định để đệ nhị Nguyên Anh điều khiển Phạm Thánh Kim Thân ngồi lên chiếc ghế giữa đài cao. Phù văn trên ghế cùng ba loại văn tự kỳ dị hợp thành quang trận, khiến chín ngân giáp khôi lỗi vận chuyển cấm chế và tạo ra một cơn lốc vàng có linh áp đủ sức liên tiếp đánh bật Hàn Lập. Khi các khôi lỗi phóng quang trụ vào cơn lốc, Tinh Không Đồ tái hiện không gian tinh tú kỳ dị; Hàn Lập thử dùng phi kiếm chém các tinh tú nhưng chúng lập tức phục hồi. Một nhũ bạch quang trụ mang linh lực tinh thuần và khí tức tinh thần mênh mông giáng xuống, khóa chặt kim thân và cưỡng ép truyền lực lượng vào bên trong. Đệ nhị Nguyên Anh nhờ đó liên tiếp vượt qua Nguyên Anh hậu kỳ và đại bình cảnh, tiến vào Hóa Thần sơ kỳ trong chưa đầy mười nhịp thở. Ngay sau đó, Phạm Thánh Kim Thân tan thành hơn nghìn giọt dịch vàng và bị ngũ sắc phù văn liên tục gột rửa. Biến cố cuối cùng khiến Hàn Lập cùng đệ nhị Nguyên Anh đồng thời đau đớn từ sâu trong hồn phách, còn đệ nhị Nguyên Anh mất ổn định rồi rơi khỏi không trung."},{"chuong":1717,"tieuDe":"Tiến Giai","tomTat":"Hàn Lập và đệ nhị Nguyên Anh cùng chịu đau đớn dữ dội trong nhũ bạch quang trụ, nhưng Hàn Lập phát hiện năng lượng thần bí đang thúc đẩy Phạm Thánh Chân Ma Công và trực tiếp gia tăng tu vi. Bản thể lần lượt phá bình cảnh Luyện Hư trung kỳ rồi hậu kỳ, trong khi đệ nhị Nguyên Anh hấp thu năng lượng nhanh hơn và liên tục vượt qua nhiều cảnh giới. Kim sắc dịch tích nhiều lần hội tụ thành kim thân ba đầu sáu tay có phù văn tử kim, linh áp cùng khả năng hấp thu mạnh hơn, rồi lại bị quang trụ phân rã để tiếp tục gột rửa. Chín ngân giáp khôi lỗi đồng loạt dùng ngân thương tăng cường quang trụ, khiến quá trình luyện hóa và cường hóa càng dữ dội. Hàn Lập nhờ nguyên thần và thân thể được Đại Diễn Quyết cùng Phạm Thánh Chân Ma Công rèn luyện nên vượt qua nguy cơ thân tử đạo tiêu và tiến vào Luyện Hư hậu kỳ. Tuy nhiên, pháp lực của hắn vẫn tăng ngoài kiểm soát, làm nguy cơ bạo thể chưa được giải trừ. Cuối chương, đệ nhị Nguyên Anh đạt Luyện Hư hậu kỳ đỉnh phong, vượt trước bản thể và bắt đầu công kích đại bình cảnh Hợp Thể kỳ."},{"chuong":1718,"tieuDe":"Bạo Thể Và Hoàng Kim Bàn","tomTat":"Năng lượng thần bí giúp đệ nhị Nguyên Anh liên tục trùng kích bình cảnh Hợp Thể, nhưng sau bảy tám lượt khiến kim thân vỡ rồi tái tạo, bình cảnh vẫn chỉ hơi rung động. Bản thể Hàn Lập cũng bị linh lực và năng lượng dồn tới sát bờ bạo thể, trong khi hồn phách đau đớn khiến hắn không thể thi pháp hay vận dụng bảo vật. Phạm Thánh Chân Ma Công vì thế tự thúc sinh một phần Phạm Thánh giáp y vốn chỉ xuất hiện ở cấp độ Hợp Thể. Không còn đường thoát, Hàn Lập chuẩn bị tự bạo pháp thể để chủ Nguyên Anh đào mạng rồi phụ thể vào Chi tiên linh khu. Đúng lúc ấy, Huyền Thiên quả thực trên cánh tay tự giải phong và hút phần lớn nguồn năng lượng đang đẩy hắn vào tử cục. Bảo vật sau đó hóa thành Huyền Thiên chi kiếm, dẫn động thiên địa nguyên khí và dùng pháp tắc chi lực chém đứt quang trụ. Lốc xoáy màu vàng bị ép lộ nguyên hình thành Hoàng kim bàn đến từ Chân tiên giới, còn thanh sắc kiếm quang phá sạch phòng ngự rồi chém thẳng lên bản thể dị bảo."},{"chuong":1719,"tieuDe":"Thu Hoạch","tomTat":"Một trảm của Huyền Thiên chi kiếm phá hủy kim sắc viên bàn, đồng thời khiến ngân sắc viên bàn của một bộ xương khô trong mật thất dưới đáy biển sâu ở Linh giới nứt vỡ và tan biến. Bộ xương khô nổi giận phá vách mật thất nhưng kiềm chế lại sau khi nhìn những ngọn lục diễm trên các Thanh đồng đăng. Tại Nghiễm Hàn Giới, Huyền Thiên chi kiếm trở về hình thái mộc côn và tự phong ấn trong cánh tay Hàn Lập, còn hắn xác nhận mình đã đạt Luyện Hư hậu kỳ đỉnh phong dù pháp lực tạm thời cạn sạch. Đệ nhị Nguyên Anh vẫn bình an nhưng phải tĩnh tu lâu dài để củng cố cảnh giới và tránh tâm ma. Hàn Lập cũng phát hiện Phạm Thánh kim thân đã xuất hiện tử kim sắc phù văn, có khí tức mạnh hơn trước nhiều lần. Sau hơn nửa ngày dùng đan dược và tinh thạch đỉnh giai, hắn hồi phục đủ pháp lực để tự bảo vệ. Cuối cùng, Hàn Lập thu chiếc ghế xanh cùng đám giáp sĩ khôi lỗi có linh áp gần Hợp Thể kỳ, dù nguồn năng lượng trong chúng chỉ còn đủ cho khoảng một hai kích toàn lực."},{"chuong":1720,"tieuDe":"Sụp Đổ","tomTat":"Khi Hàn Lập định thu lấy một khôi lỗi trên đài cao, chín ngân giáp khôi lỗi đồng loạt dùng ngân thương chém đôi những cá thể gần nhất rồi tự hủy. Hắn thu sạch các mảnh vỡ làm từ tài liệu lạ, sau đó dùng họa quyển và bí pháp sao chép tinh không đồ để nghiên cứu về sau. Không tìm thấy thêm vật có giá trị và cũng không thể thu lấy Tu di không gian bảo vật đã bị người khác luyện hóa, Hàn Lập xuyên qua bình phong trở về đại điện. Ngay sau đó, toàn bộ không gian cung điện rung chuyển, thiên địa nguyên khí hỗn loạn và hàng loạt cấm chế bắt đầu mất kiểm soát. Liễu Thuý Nhi cùng Thạch Côn buộc phải bỏ dở việc tìm kiếm bảo vật, thoáng nghi ngờ Hàn Lập có liên quan đến dị biến nhưng quyết định ưu tiên thoát thân. Cả ba dùng truyền tống trận rời khỏi cung điện rồi tiếp tục bay xa hơn mấy nghìn dặm. Khi họ đã rời khỏi khu vực nguy hiểm, một tiếng nổ kinh thiên động địa truyền đến từ phía sau."},{"chuong":1721,"tieuDe":"Đuổi Kịp","tomTat":"Vụ nổ trong không gian bí mật tạo ra phong trụ cùng linh áp dữ dội, phá hủy nhiều tầng cấm chế tại lối vào và buộc Hàn Lập, Liễu Thuý Nhi cùng Thạch Côn lập tức chia đường đào thoát. Liễu Thuý Nhi thu hồi tiểu điểu ngũ sắc rồi cưỡi ngân sắc phi chu rời đi, Thạch Côn hóa thành hoàng quang theo hướng khác, còn Hàn Lập dùng đôi cánh trong suốt và thu hồi tiểu bạch xà khi tăng tốc. Thục Thử dẫn lực lượng Giác Xi Tộc tới hiện trường, sai Lãnh Hàn và Bạch Quả chia quân truy sát hai người còn lại, trong khi hắn dùng quái trùng hình ốc sên xác định hướng chạy của Hàn Lập. Không thể loại bỏ dấu vết khóa chặt dù đã dùng linh mục thần thông, Hàn Lập xác định chỉ có một truy binh cùng giai phía sau nên chủ động dừng lại tại nơi cách xa viện binh. Hắn giấu vài chục phi kiếm màu xanh quanh chiến trường rồi chờ Thục Thử cưỡi quái thú sáu chân bốn cánh đuổi tới. Khi quái thú ẩn thân tập kích, Hàn Lập dùng kim sắc quyền ảnh ép nó hiện hình, còn Thục Thử nhân lúc đối phương phân tâm âm thầm khiến ô mâu biến mất để chuẩn bị đòn đánh tiếp theo."},{"chuong":1722,"tieuDe":"Ngân Thước Và Kim Thân","tomTat":"Kim giác thanh niên bất ngờ dùng Âm linh mâu xuyên qua Ích Tà Thần Lôi và đánh trúng Hàn Lập, nhưng Thiên ngoại ma giáp tự động hộ chủ nên hắn không bị thương. Nhận ra chiến giáp bất phàm, thanh niên tuyên bố muốn chiếm lấy nó rồi lấy ngân sắc đoản thước ra giao chiến. Hàn Lập kích phát Xuân Lê kiếm trận vây đối thủ, đồng thời thả Oa Oa hóa thành ngân sắc cự mãng để kiềm chế quái thú Luyện Hư trung giai. Ngân thước lần lượt phá ảo cảnh thảo nguyên và rừng rậm của kiếm trận, sau đó dùng thước ảnh che mắt để chân thân xuyên không đánh lén Hàn Lập. Nhờ mở linh mục thần thông từ trước, Hàn Lập nhìn thấu thủ đoạn và dùng cánh tay tử kim chặn bảo vật. Tân kim thân pháp tướng ba đầu sáu tay tiếp tục phá lớp ngân quang hộ thể, làm linh quang của ngân thước ảm đạm rồi nuốt bảo vật vào bụng. Kim giác thanh niên mất liên hệ với ngân thước, nhất thời vừa kinh sợ vừa tức giận."},{"chuong":1723,"tieuDe":"Điên Đảo Càn Khôn","tomTat":"Hàn Lập phát hiện kim thân mới có khả năng cướp bảo vật không phải bản mạng pháp bảo của đối thủ, rồi tiếp tục vận dụng Xuân Lê kiếm trận và Phệ Linh hỏa điểu vây công. Kim giác thanh niên triệu ra lam sắc pháp tướng, dùng quái chùy ba đầu thú cùng tấm chắn tam giác xích diễm chống lại tầng tầng kiếm quang. Khi bị kim thân và hỏa điểu giáp công, hắn gọi ra một tiểu chung trắng như tuyết, dùng tiếng chuông đảo ngược nhận thức và phương hướng trong kiếm trận, khiến các đòn công kích chệch mục tiêu và làm trận pháp tan vỡ. Kim giác thanh niên sau đó ẩn vào hư không, nhưng Hàn Lập mở Phá Diệt Pháp Mục và phóng ô quang ép hắn hiện thân. Hàn Lập điều khiển bảy mươi hai thanh Thanh Trúc Phong Vân Kiếm thuấn di tập kích, song đối thủ tiếp tục gõ tiểu chung tạo ra bạch sắc khí lãng từ vô số vết nứt không gian. Không gian chi lực cuốn qua và phá tan toàn bộ đợt phi kiếm công kích, khiến Hàn Lập nhận ra bản chất đáng sợ của dị bảo hình chuông."},{"chuong":1724,"tieuDe":"Cự Viên Hung Uy","tomTat":"Kim giác thanh niên dốc toàn lực thúc giục tiểu chung, pháp tướng và nhiều loại thần thông nhằm kết liễu Hàn Lập trong một đòn. Hàn Lập điều khiển kim thân triệu ra Huyền Thiên tàn nhận, khiến bảo vật hấp thu thiên địa nguyên khí của Nghiễm Hàn Giới, huyễn hóa lưỡi đao rồi phá tan hỏa vân, hắc khí và tam sắc hỏa lãng. Kim giác thanh niên liên tục đánh chuông, dùng không gian chi lực phá quái phong, làm suy yếu Thiên ngoại ma giáp, tạo hắc động và cưỡng ép phá độn thuật của Phong Lôi Sí. Khi không gian pháp tắc bao phủ và kéo xé thân thể, Hàn Lập biến thành kim mao cự viên, dựa vào sức mạnh thể phách phá tan sự trói buộc. Cự viên nhanh chóng áp sát, chống chịu vô số lam sắc đoản nhận mà không bị thương rồi phá hủy pháp tướng cùng hắc khí của đối thủ. Cuối cùng, Hàn Lập xuyên thủng hộ thể linh quang và bóp nổ đầu kim giác thanh niên bằng một trảo."},{"chuong":1725,"tieuDe":"Giác Xi Mưu Đồ","tomTat":"Nguyên Anh của kim giác thanh niên định mượn tiểu chung chạy trốn nhưng bị tiếng rống từ hình thái cự viên của Hàn Lập tiêu diệt, khiến tiểu chung cũng bạo liệt thành bạch quang. Hàn Lập tiếp tục đánh chết quái thú Luyện Hư trung kỳ, lấy yêu đan, còn bạch sắc cự mãng nuốt tinh hồn của nó. Tại một lầu các bí mật ở Linh giới, ba người Giác Xi Tộc nhận ra một Huyền Thiên thánh khí đã bị hủy và xác định đội ngũ của kim giác thanh niên không thể hoàn thành phần nhiệm vụ được giao. Họ tiết lộ mục tiêu bí mật gồm năm phần, nhiều đội đã được phái vào Nghiễm Hàn Giới cùng các thánh khí phỏng chế chuyên dùng để đối phó phong ấn. Dù nhiệm vụ này xuất hiện tổn thất, kế hoạch nguyên bản của Giác Xi Tộc vẫn được đánh giá có khả năng thành công cao, và mỹ phụ trung niên thanh giác đề xuất tiến hành trận chiến cuối cùng với Thiên Vân mười ba tộc. Không biết mình đã phá hỏng một phần đại kế ấy, Hàn Lập nhận ra biến thân cự viên ở Luyện Hư hậu kỳ đủ sức giao chiến với tu sĩ Hợp Thể kỳ rồi quyết định tiếp tục thu thập tài liệu cho Thạch Kiến Tộc. Sau khi tìm nơi hồi phục pháp lực, hắn thả Báo Lân Thú vừa tỉnh lại và phát hiện linh thú đã có thêm hoa văn đen cùng khí tức nguy hiểm sau khi luyện hóa yêu đan."},{"chuong":1726,"tieuDe":"Phi Hồng Ngư","tomTat":"Hàn Lập nhận thấy Báo Lân Thú tỏa ra khí tức nguy hiểm bất thường, nhưng tạm hoãn nghiên cứu cho tới khi rời Nghiễm Hàn Giới. Sau bảy ngày đả tọa, hắn khôi phục chín thành pháp lực rồi phát hiện Ám thú vương bị một quái thú đầu trư thân lam mạnh hơn truy đuổi, song quyết định che giấu khí tức và không can dự. Hàn Lập rời huyệt động, vừa phi hành vừa bổ sung pháp lực, sau khoảng một tháng thì tới một hồ nước rộng lớn gần như không có cao giai ma thú. Dù nhận ra khu vực có dấu hiệu nguy hiểm, hắn vẫn tiếp tục tìm kiếm vì nhiệm vụ thu thập khoáng thạch cho Thạch Kiến Tộc và lời bảo đảm về truyền tống trận của Đoạn Thiên Nhận. Hắn tìm thấy hải đảo trùng khớp với địa đồ, nơi có hai ngọn núi và khoáng thạch mục tiêu nằm trên ngọn núi cao. Khi một quái ngư từ dưới hồ tập kích, Hàn Lập dùng phi kiếm chém chết nó, khiến vô số quái ngư đủ màu trong phạm vi vài dặm đồng loạt xuất hiện. Hắn nhận ra chúng là Phi Hồng Ngư đã tuyệt diệt tại Linh giới, có kịch độc, thường tụ tập thành đàn lớn và sở hữu nội đan dùng làm chủ tài liệu luyện Thất Thải đan."},{"chuong":1727,"tieuDe":"Linh Hỏa Khắc Địch","tomTat":"Hàn Lập xem đàn Phi hồng ngư là cơ hội thu thập nội đan để luyện Thất thải đan, nhưng trước tiên dựng nhiều tầng phòng ngự nhằm kiểm chứng độc tính của chúng. Thanh Trúc Phong Vân Kiếm giết gần nghìn quái ngư trong đợt đầu, song độc dịch màu lục nhanh chóng ăn mòn kiếm mạc và tiếp tục tiêu hao Ngũ sắc hàn diễm. Hàn Lập chuyển sang Phệ linh thiên hỏa, dùng ngân sắc hỏa điểu cùng Kim ô chân hỏa phá độc mãng rồi hóa vô số hỏa ti ngăn chặn màn dịch độc. Nhờ linh hỏa khắc chế độc dịch, hàng trăm kiếm quang diệt sạch khoảng bốn đến năm vạn Phi hồng ngư trong thời gian uống một chén trà. Phần độc dịch rơi xuống hồ còn giết hàng loạt loài cá khác, khiến Hàn Lập xác nhận mức độ nguy hiểm của loài quái ngư này. Sau trận chiến, hắn triệu Khúc nhi ra thu toàn bộ nội đan rồi bay tới hòn đảo phía trước. Trên ngọn núi xám, Hàn Lập kích hoạt kim bàn do Thạch Kiến Tộc giao, khiến pháp khí hiện ngân sắc phù văn và tự bay về phía ngọn núi."},{"chuong":1728,"tieuDe":"Hỗn Nguyên Xích","tomTat":"Hàn Lập dùng kim bàn dò xét sơn phong trên đảo, phát hiện một khoáng mạch trong lòng núi rồi giao Đệ nhị Nguyên Anh điều khiển khôi lỗi khai thác. Khúc nhi mang về mấy vạn nội đan Phi hồng ngư, sau đó được phép tự đi tìm linh dược nhờ khả năng cảm ứng của thiên địa linh vật. Hàn Lập bố trí cấm chế che giấu sơn phong, lấy ngân xích từ Phạm thánh kim thân ra và xác định đó là Hỗn Nguyên Xích cấp Thông thiên linh bảo. Hắn chỉ mất ba ngày để tham ngộ hoàn chỉnh Thông bảo quyết và đạt khả năng tùy ý khu sử bảo vật. Trong lúc tìm linh dược quanh đáy hồ, Khúc nhi gặp Nguyệt tiên tử và Tư lão đang bị một nam tử giọng khàn điều khiển chiến xa truy sát vì Cửu diễm thảo. Nguyệt tiên tử thà hủy linh dược chứ không giao, còn Tư lão dựa vào pháp khí cảm ứng người Thiên Vân tộc để dẫn cả nhóm chạy về phía đảo. Cảm ứng dấu thần niệm trên Khúc nhi gặp biến cố, Hàn Lập nổi giận lao khỏi cấm chế để nghênh chiến."},{"chuong":1729,"tieuDe":"Nhung Tộc","tomTat":"Bốn chiến xa của Nhung Tộc hợp thành một chiến xa hình thoi khổng lồ có khả năng xuyên qua không gian, nhanh chóng đuổi kịp nhóm Nguyệt tiên tử, lão giả đồng hành và Khúc nhi. Khúc nhi không tiếc tổn hao chân nguyên để tăng độn tốc rồi phóng hàng trăm phi nhận chống cự trảo từ chiến xa, nhưng vẫn rơi vào nguy hiểm. Hàn Lập kịp thời dùng Phong lôi sí tới cứu nàng, lấy ngân sắc đại ấn phá tan cự trảo và dùng Hỗn nguyên xích bảo vệ Khúc nhi. Sau khi nhận ra Nguyệt tiên tử, hắn ở lại đối đầu bốn người Nhung Tộc và dùng ngân xích mang lôi quang áp chế hắc phiên cùng lục kính. Hàn Lập tiếp tục dùng hắc sắc tiểu sơn đánh vỡ hồng châu của một đối thủ, đồng thời lấy hôi quang giữ lại hơn mười phi đao đỏ đậm. Khi phía Nhung Tộc dựng hắc võng, lục sắc quang trụ và hôi sắc kiếm quang để phòng thủ, các đòn đánh ấy chỉ chạm vào hư ảnh của cự xích. Cự xích thật bất ngờ xuất hiện trên đầu người sử dụng hắc phiên và giáng xuống, nhưng kết quả của đòn đánh chưa được hé lộ."},{"chuong":1730,"tieuDe":"Động Tuyền Kim Quang","tomTat":"Hàn Lập điều khiển ngân xích đánh nổ đầu tên Nhung Tộc cầm hắc phiên rồi diệt luôn Nguyên Anh đang chạy trốn, sau đó dùng bản thể ngân xích và lôi quang thiêu chết tên cầm lục kính. Hai người còn lại mất chiến ý, thúc giục chiến xa hình thoi tháo chạy nhưng bị Hàn Lập dùng Nguyên Từ Thần Sơn vượt hư không chặn đường và phá hủy chiến xa. Hàn Lập vận dụng Phong Lôi Sí đuổi theo một người, dùng Thanh Trúc Phong Vân Kiếm phá các tầng phòng ngự rồi hóa kiếm ti chém nát cả thân thể, Nguyên Anh và bảo vật hộ thân của đối phương. Cùng lúc đó, đệ nhị Nguyên Anh điều khiển Phạm Thánh Kim Thân truy sát người cuối cùng. Kim thân ba đầu sáu tay hóa giải trường nhận và cự trảo, sau đó thi triển Động Tuyền Kim Quang khiến không gian quanh mục tiêu ngưng trọng. Kim sắc tuyền qua hút tên Nhung Tộc vào trong rồi thu nhỏ và biến mất, hoàn tất việc tiêu diệt cả bốn truy binh."},{"chuong":1731,"tieuDe":"Cửu Diễm Thảo","tomTat":"Sau khi tiêu diệt bốn người Nhung Tộc, Hàn Lập thu hồi kim thân và đệ nhị Nguyên Anh, còn Khúc nhi trở vào tay áo hắn. Tư lão và Nguyệt tiên tử tiến đến cảm tạ, đồng thời giải thích rằng họ đã tổn hao nghiêm trọng pháp lực và nguyên khí vì trúng quỷ kế rồi phải dùng bí thuật đào mạng. Nguyệt tiên tử trao Cửu Diễm Thảo cho Hàn Lập để báo đáp ơn cứu mạng và cho biết linh dược đã tuyệt tích ở Linh giới này chính là nguyên nhân khiến Nhung Tộc truy sát họ. Khi linh thảo định bay khỏi ngọc hạp, Hàn Lập dùng lực vô hình chế trụ nó rồi thu giữ. Không muốn chiếm tiện nghi của hai người, hắn trao lại cho mỗi người một bình đan dược có thể tăng tiến tu vi và hỗ trợ xung kích bình cảnh. Sau khi biết Hàn Lập đã phân tán với hai bạn đồng hành, Nguyệt tiên tử tiết lộ một địa phương đang bị Nhung Tộc chiếm giữ và đề nghị hắn trợ giúp đoạt lại nơi có bản công pháp Kim triện văn."},{"chuong":1732,"tieuDe":"Luyện Thần Thuật","tomTat":"Tư lão và Nguyệt tiên tử kể cho Hàn Lập về mật động chứa một thiên công pháp Kim triện văn mà nhóm họ từng phát hiện, đồng thời thuật lại việc Nhung Tộc giả vờ hợp tác rồi bất ngờ bao vây khiến các đạo hữu khác tử trận. Nguyệt tiên tử xác nhận công pháp mang tên Luyện thần thuật, có khả năng gia tăng thần niệm lên nhiều lần, hỗ trợ đột phá Hợp Thể Kỳ và vượt những bình cảnh về sau. Do Hàn Lập chưa hiểu Kim triện văn, hai người hứa truyền toàn bộ kiến thức của họ về loại linh văn này nếu hắn đoạt được công pháp. Hàn Lập chấp thuận, nhận ngọc giản ghi vị trí và đường đi trong mật động rồi một mình lên đường. Sau khi hắn rời đi, Tư lão đánh giá thực lực của hắn không dưới Thánh tộc sơ giai và ước tính cơ hội thành công vào khoảng năm phần, nhưng cũng cảnh báo trong nhóm Nhung Tộc có một tu sĩ đặc biệt lợi hại. Trên đường, Hàn Lập nhận định Luyện thần thuật còn có thể giúp hắn điều khiển thêm Phệ kim trùng, hỗ trợ luyện đan và trận pháp nên quyết không bỏ qua cơ duyên này. Lo Nhung Tộc phá hết cấm chế trước khi mình đến, hắn vận dụng Phong Lôi sí và toàn lực phi độn, rút hành trình từ khoảng một ngày xuống còn nửa ngày."},{"chuong":1733,"tieuDe":"Mật Động Nhung Tộc","tomTat":"Hai lính cảnh giới Nhung Tộc bàn về những người Thiên Vân Tộc đang bị truy sát và việc chưa thể lấy trọn công pháp Kim triện văn trong mật động. Qua cuộc trò chuyện, họ xác định phần khẩu quyết cuối là phần trọng yếu, trong khi hai khối Nghiễm Hàn Lệnh hiện có chưa chắc đủ hóa giải toàn bộ cấm chế. Hàn Lập dùng Thái Nhất Hoá Thanh Phù hư hóa thân thể, bí mật nghe lén rồi quyết định không giết lính gác để tránh làm kinh động những người bên trong. Nhờ linh mục thần thông, hắn nhận ra Bắc đẩu tinh đồ ẩn trong các vết nứt trên vách đá và xuyên vào thông đạo tinh thạch. Trước đại môn màu xanh, hắn mạo hiểm lướt qua hai lính Nhung Tộc cùng giai, sẵn sàng cưỡng ép xông vào nếu bị phát hiện. Hắc mao Nhung Tộc cảm thấy khác thường, dùng thần niệm dò xét rồi bất ngờ phóng ngân ti phủ kín thông đạo. Ngân ti xuyên qua thân thể đã hư hóa của Hàn Lập mà không làm hắn hiện hình, nhưng hai lính gác vẫn chăm chú quan sát khoảng không."},{"chuong":1734,"tieuDe":"Thạch Bích Linh Văn","tomTat":"Hàn Lập duy trì trạng thái hư hóa, lặng lẽ vượt qua hai thủ vệ Nhung Tộc rồi tiến vào đại môn màu xanh. Nhờ địa đồ do Tư lão cung cấp, hắn đi xuyên qua hệ thống thông đạo phức tạp và tìm thấy động quật có thạch bích hiện kim sắc phù văn. Hàn Lập bất ngờ dùng kim thân ba đầu sáu tay cùng Nguyên từ thần sơn áp chế, bắt sống người Nhung Tộc đang nghiên cứu tại đó và phong bế cả Nguyên Anh của đối phương. Vì trữ vật trạc không thể thu nguyên thạch bích, hắn chuyển sang dùng ngọc giản sao chép toàn bộ linh văn. Sau đó Hàn Lập tìm thêm ba nơi lưu giữ linh văn, bắt sống một người canh giữ khác và thu thập gần đủ các phần của bộ công pháp. Biết lực lượng Nhung Tộc còn lại có thể đang tập trung tại động quật cuối, hắn bố trí hơn trăm trận kỳ cùng Cửu Cung Thiên Kiền phù tại ngã tư để chặn viện binh. Hoàn tất chuẩn bị, Hàn Lập phái kim thân, ngân điểu và hai ngân ảnh lẻn đi trước nhằm thăm dò mục tiêu cuối cùng."},{"chuong":1735,"tieuDe":"Kịch Chiến","tomTat":"Hàn Lập bố trí Oa Oa cùng hai đạo Giáp Nguyên Phù làm hậu chước, sau đó dùng Thái Nhất Hoá Thanh Phù che giấu thân hình để tiến vào một động quật rộng như quảng trường. Tại đây, bốn tu sĩ Nhung Tộc trấn giữ ngân sắc quang tráo bao phủ thạch bích linh văn, trong đó Hàn Lập xác định đại hán mang cự nhận là đối thủ nguy hiểm nhất. Cự nhận tự động cảnh báo khiến cuộc đánh lén thất bại, buộc Hàn Lập hiện thân và dùng Ngân sắc đoản xích nghênh chiến. Hắn tiếp tục triệu Nguyên Từ Thần Sơn, ép đại hán phải dùng huyết sắc đại thủ và năm đóa huyết liên chống đỡ. Phá Hư Linh Xà của đại hán phá được độn thuật của Hàn Lập nhưng bị hắn bắt, đóng băng bằng Ngũ sắc hàn diễm rồi dùng kim sắc hồ quang tiêu diệt. Viên bát huyết nhận cũng không xuyên qua được Hắc sắc chiến giáp, trong khi Oa Oa và hai hóa thân ngân ảnh cầm chân ba tu sĩ Nhung Tộc còn lại. Cuối chương, Hàn Lập nghiền vỡ huyết sắc đại thủ, làm Nguyên Từ Thần Sơn né khỏi Ngân sắc cự phủ rồi cùng thần sơn tái hiện ngay trên đầu đại hán để tiếp tục đập xuống."},{"chuong":1736,"tieuDe":"Quần Tảo Chúng Địch","tomTat":"Hàn Lập dùng Nguyên Từ Thần Sơn phá nhiều tầng huyết quang hộ thân của Đại hán Nhung Tộc, phối hợp Phệ Linh Thiên Hỏa kiềm chế cự phủ rồi triệu Phạm Thánh Kim Thân tiêu diệt đối thủ. Hắc sắc cự nhận mất chủ hóa thành giao long bỏ chạy nhưng bị thanh ti của Tiểu đỉnh màu xanh trói, hoàn nguyên và thu lấy. Ba người Nhung Tộc còn lại chạy về động khẩu tìm viện binh song đều bị Hàn Lập, Oa Oa và các khôi lỗi truy sát. Hàn Lập tiếp tục quét sạch những kẻ bị pháp trận cùng Cửu Cung Thiên Kiền Phù vây khốn; chỉ Hắc mao Nhung Tộc thoát được bằng cách tự bạo thân thể và hóa thành nhiều đạo huyết quang. Trở lại quảng trường, hắn thử kiếm quang, Phệ Linh Thiên Hỏa, Ngân xích cùng nhiều bảo vật nhưng không thể phá ngân sắc quang tráo. Huyền Thiên tàn nhận chém được một khe nhỏ, song cấm chế lập tức tự khép và khiến pháp lực của hắn phản phệ. Sau một ngày một đêm nghiên cứu trận pháp và liên hệ thông tin về Nghiễm Hàn Lệnh, Hàn Lập tìm thấy manh mối rồi lấy lệnh bài cổ xưa tỏa kim ngân quang ra."},{"chuong":1737,"tieuDe":"Đoạt Linh Văn","tomTat":"Hàn Lập bố trí quang trận bằng mười mấy cây trận kỳ, lần lượt đưa ba tấm Nghiễm Hàn Lệnh vào để tăng mạnh kim ngân quang trụ và phá tan ngân sắc quang tráo. Hắn sao chép toàn bộ Luyện thần thuật trên vách đá, sau đó dùng Nguyên từ thần sơn đánh sập hạp cốc nhằm xóa dấu vết. Trở lại hồ nước, Hàn Lập gặp Tư lão và Nguyệt tiên tử rồi giao trước một ngọc giản chứa nửa đầu công pháp để kiểm chứng. Nguyệt tiên tử xác nhận đây là Tiên giới bí thuật chân chính viết bằng Kim triện văn, nhưng có điều kiện tu luyện cực kỳ hà khắc đối với tu sĩ Linh giới. Tư lão và Nguyệt tiên tử luân phiên truyền thụ kiến thức Kim triện văn, giúp Hàn Lập nắm giữ toàn bộ hiểu biết của họ sau nửa tháng, đổi lại hắn giao nốt phần Luyện thần thuật còn lại. Năm ngày sau, một nhân diện lão giả dẫn hơn mười người Nhung Tộc tới hạp cốc đã bị phá hủy. Hàn Lập, Tư lão và Nguyệt tiên tử chia tay, mỗi người bắt đầu tìm nơi bí ẩn để tiềm tu trùng kích bình cảnh trước khi Nghiễm Hàn Giới đóng cửa."},{"chuong":1738,"tieuDe":"Tái Ngộ Ám Thú Vương","tomTat":"Hàn Lập dành hơn nửa tháng giải đọc Luyện thần thuật và biết bí pháp Tiên giới này gồm ba tầng, có thể tăng thần niệm lần lượt lên gấp hai, bốn và tám lần nhưng cũng gây phản phệ chí mạng nếu thần thức hoặc pháp thể không đủ mạnh. Nhờ Đại diễn quyết, Phạm Thánh Chân Ma Công và nền tảng pháp thể song tu, hắn nhận định mình có thể tu luyện tầng thứ nhất, trong khi tầng thứ hai vẫn cần tiếp tục cường hóa thân thể. Hắn còn phát hiện hai đan phương Di cương đan và Ngưng hồn hoàn dùng để hỗ trợ thần niệm cùng thân thể, nhưng các nguyên liệu đều xa lạ và khó tìm tại Linh giới. Sau đó, ba khối Nghiễm Hàn Lệnh đột nhiên biến mất, thiên địa nguyên khí hỗn loạn và toàn giới rung chuyển, báo hiệu Nghiễm Hàn Giới chỉ còn nhiều nhất nửa ngày trước khi đóng lại. Hàn Lập phát hiện Ám Thú Vương trọng thương đang bị một quái thú sáu cánh kiên quyết truy sát, trong khi cả hai đều đã hao tổn nhiều nguyên khí. Tiếng gầm cấp bách của Báo Lân Thú khiến hắn liên tưởng tới dị biến do yêu đan Ngân sắc tam nhãn ám thú gây ra và quyết định nhắm vào Ám Thú Vương. Hắn dùng độn thuật áp sát, triệu pháp tướng ba đầu sáu tay phóng sáu đạo kim sắc quang trụ, rồi tiếp tục ép xuống bằng hắc sắc cự sơn và ngân sắc cự xích, nhưng kết quả trận phục kích vẫn chưa được xác định."},{"chuong":1739,"tieuDe":"Phản Hồi Vân Thành","tomTat":"Hàn Lập dùng quang trận ngân sắc cùng nhiều pháp bảo áp chế Ám thú vương, phá hủy thân thể và chặn cả hai lần thi triển bí thuật thoát thân của nó. Ngân sắc hỏa điểu thôn phệ hình thái cuối cùng của Ám thú vương, giúp Hàn Lập thu được kim sắc yêu đan rồi giao cho Báo lân thú nuốt. Quái thú sáu cánh dù thèm muốn yêu đan vẫn phải rút lui khi nhận ra không thể thắng Hàn Lập. Sau nhiều canh giờ, pháp tắc giới diện cưỡng ép truyền Hàn Lập trở lại Vân Thành, nơi Giác Xi Tộc và Thiên Vân mười ba tộc đang giao chiến dữ dội. Một giáp sĩ Giác Xi Tộc lập tức tập kích hắn nhưng bị Thiên Ngoại Ma Giáp chặn đòn, sau đó bị thanh sắc tiểu kiếm chém đầu và diệt cả Nguyên Anh. Liễu Thuý Nhi, Thạch Côn và hai thành viên khác trong nhóm lần lượt trở về; trung niên nam tử đã tiến lên Hợp Thể sơ kỳ, còn Liễu Thuý Nhi và Thạch Côn không vượt qua bình cảnh. Nguyệt tiên tử cũng trở về với tu vi Hợp Thể sơ kỳ, trong khi Tư lão không xuất hiện và chưa rõ tung tích."},{"chuong":1740,"tieuDe":"Vân Thành Chi Loạn","tomTat":"Hàn Lập nhận ra mình bị truyền tống khỏi Nghiễm Hàn Giới trước mọi người vì Huyền Thiên quả phong ấn trong cánh tay đã bài xích pháp tắc nơi đó để hộ chủ, trong khi Nguyệt tiên tử và trung niên họ Ngưng đều tiến giai Hợp Thể thành công. Những người vừa trở về phát hiện đại quân Giác Xi Tộc đã đánh sâu vào Vân thành, khiến chiến chu, chiến thú và giáp sĩ giao tranh khắp không trung. Ngu đạo hữu mang lệnh bài của trưởng lão hội tới truyền lệnh, yêu cầu họ lập tức đến thông linh chiến bảo thay vì dừng lại tham chiến. Đoàn người do hai tu sĩ Hợp Thể dẫn đầu xuyên qua chiến trường, tiêu diệt những kẻ cản đường và phá hủy hơn trăm chiến chu trước khi tới Bát Vân sơn. Trên đường, Hàn Lập nhìn thấy một Vân thành chi vệ khôi lỗi có chiến lực tương đương Hợp Thể sơ kỳ đã bị đánh tan nát, từ đó nhận ra tình thế của Vân thành vô cùng nguy cấp. Bát Vân sơn vẫn được phòng thủ nghiêm mật, còn tổng bộ Vạn Cổ Tộc cùng thông linh chiến bảo đã trở thành trung tâm chỉ huy toàn thành dưới sự trấn thủ của thanh niên họ Ông. Tại Thông linh điện, thanh niên họ Ông vui mừng trước việc hai người tiến giai thành công nhưng đặc biệt dừng mắt trên Hàn Lập, khiến hắn nhớ tới Thiên cương ấn và cảm thấy bất an."},{"chuong":1741,"tieuDe":"Hư Linh Bảo Đỉnh","tomTat":"Thanh niên họ Ông thông báo Vân Thành không thể giữ được vì lực lượng chủ lực đã mắc kế Giác Xi tộc, bản đồ cấm chế toàn thành bị đánh cắp và đại quân đối phương đang áp sát sau khi phá mười ba thành. Ông giải thích mình cùng hai thái thượng trưởng lão Đại Thừa của Giác Xi tộc tạm thời kiềm chế lẫn nhau, còn trạng thái các thánh giai chưa trực tiếp tham chiến cũng khó kéo dài, nên ra lệnh rút đến Phục Giao Thành. Sau khi giữ Hàn Lập lại, ông nhìn thấu xuất thân Nhân tộc của hắn và kiểm tra Hư Thiên Đỉnh, xác định bảo vật này có thể là vật luyện thử trước khi Hư Linh Đỉnh được hoàn thành. Ông giao cho Hàn Lập một hộp ngọc cùng một ngọc giản lam sắc bị phong ấn, yêu cầu chuyển chúng cho Băng Phách Tiên Tử hoặc hậu nhân cùng huyết thống. Hàn Lập dùng tâm ma lập lời thề nhận nhiệm vụ, đồng thời nhận ba hộp tài liệu quý và quyền sử dụng siêu cấp Truyền Tống Trận tại Phục Giao Thành một lần. Sau đó hắn hội hợp với Nguyệt tiên tử, Liễu Thuý Nhi và những người khác trên phi xa bạc do sáu quái thú Đường Lang kéo, rồi cả đoàn bay khỏi Thông Linh Điện."},{"chuong":1742,"tieuDe":"Ngẫu Ngộ","tomTat":"Sau nửa tháng trở về hậu phương, đoàn Hàn Lập tới Phục Giao thành, nơi đang giới nghiêm vì đại quân Giác Xi Tộc đã áp sát. Bính tiền bối đưa mọi người qua cửa thành rồi quay lại Vân thành, còn Hàn Lập cùng những người đồng hành đi Tinh Vân các để lĩnh mệnh. Trên đường, Hàn Lập bất ngờ gặp Hướng Chi Lễ đang bị một tu sĩ mặt tím thúc ép trả nợ và lập tức thanh toán toàn bộ tinh thạch thay ông. Hàn Lập dùng Nguyên từ thần quang ngăn nghe lén, cho biết mình sắp sử dụng siêu cấp truyền tống trận để trở về Phong Nguyên đại lục. Hướng Chi Lễ nói có một vật cần giao nhưng không mang theo, vì vậy hẹn hắn tới Thanh Kỳ phong sau ba ngày. Sau khi Hàn Lập rời đi, Hướng Chi Lễ lộ biểu hiện giống một nụ cười gian xảo, khiến cuộc hẹn trở nên đáng ngờ. Hàn Lập sau đó tới Tinh Vân các và được Thiên Cơ Tử đứng chờ trước cửa nghênh đón."},{"chuong":1743,"tieuDe":"Linh Dược Cùng Trao Đổi","tomTat":"Hàn Lập tới gặp Thiên Cơ Tử và lập tức bị đối phương nhìn ra tu vi thượng tộc cửu giai, dù hắn đã dùng bí thuật che giấu. Thiên Cơ Tử dẫn hắn qua một tiểu truyền tống trận vào đại sảnh, nơi Đoạn Thiên Nhận, Thải Lưu Anh cùng Thạch Côn và Liễu Thuý Nhi đang chờ. Ba vị thánh giai đánh giá chiến lực Hàn Lập đã có thể sánh với thánh tộc sơ giai, rồi đề nghị dùng đan dược hỗ trợ phá bình cảnh cùng các bảo vật khác để đổi Tiên giới linh dược của hắn. Sau khi cân nhắc, Hàn Lập lấy hơn trăm ngọc hạp linh dược ra để ba người kiểm định và định giá. Nhờ lịch duyệt lâu năm, họ nhận diện được nhiều linh dược quý hiếm, trong đó Đoạn Thiên Nhận đặc biệt kinh ngạc khi phát hiện Viêm hô thảo. Sau khi xem gần hết số ngọc hạp, Thiên Cơ Tử cho rằng Hàn Lập vẫn chưa lấy toàn bộ thu hoạch ra và trực tiếp yêu cầu hắn đưa phần linh dược còn lại."},{"chuong":1744,"tieuDe":"Sắp Xếp Ổn Thỏa","tomTat":"Hàn Lập thừa nhận vẫn còn linh dược nhưng buộc ba vị Hợp Thể phải trưng hàng trước, khiến Thải Lưu Anh, Đoạn Thiên Nhận và Thiên Cơ Tử lần lượt đưa ra đan dược cùng linh dịch quý hiếm. Sau khi kiểm tra, hắn lấy thêm hơn trăm gốc linh dược từ Quảng Hàn Giới và yêu cầu vật liệu quý, Cửu Văn Tinh Nguyệt Dịch, đan phương Vạn Diệu Đan cùng phương pháp luyện chế Thông Linh khôi lỗi. Hai bí truyền bị từ chối vì không truyền cho người ngoại tộc, nhưng Thải Lưu Anh đồng ý trao một lọ linh dịch, còn Hàn Lập đổi các điều kiện còn lại thành số Cực Phẩm Linh Thạch cần cho Truyền Tống Trận. Ba vị Hợp Thể nhanh chóng cung cấp sáu bảy phần danh sách vật liệu, trong đó có nhiều thứ Thanh Nguyên Tử từng yêu cầu Hàn Lập thu thập. Đoạn Thiên Nhận cam kết sẽ sai người giao những vật liệu còn tìm được trong vòng mười ngày. Hàn Lập kiểm tra kỹ linh thạch và linh dịch, thu toàn bộ chiến lợi phẩm rồi lập tức dùng Truyền Tống Trận rời đi. Khi Liễu Thủy Nhi và Thạch Côn được lệnh trở lại đại sảnh, hắn đã biến mất không rõ hướng."},{"chuong":1745,"tieuDe":"Cự Linh Phù Cùng Huyết Ảnh","tomTat":"Đoạn Thiên Nhận, Thải Lưu Anh và Thiên Cơ Tử mặc cả rồi hoàn tất việc phân chia số linh dược tiên giới, trong đó Thải Lưu Anh được bù thêm năm cây. Thiên Cơ Tử nảy lòng tham, đề nghị liên thủ lấy thêm linh dược từ Hàn Lập nhưng phải từ bỏ khi hai người còn lại e ngại Ông tiền bối và đánh giá Hàn Lập không dễ đối phó. Trên đường xuống núi, Hàn Lập xác định mình vẫn chiếm lợi vì đã giữ lại giống của phần lớn linh dược có thể thúc dục bằng tiểu bình thần bí, đồng thời không giao ra những linh vật độc nhất và Ngân sắc đài sen. Sau ba ngày thu mua tài liệu tại Phục Giao Thành, hắn đến Thanh Giao Phong gặp Hướng Chi Lễ và nhận một hộp ngọc chứa Cự Linh phù. Hàn Lập cảnh giác chém vỡ hộp rồi dùng thần niệm tinh hóa dò xét phù lục, khiến nó chuyển sang màu đen và phóng quang ti xám trắng xuyên qua kim quang hộ thể. Khi Hàn Lập bị tê liệt toàn thân, thân thể Hướng Chi Lễ nứt tung và một huyết ảnh đỏ như máu xuất hiện, lao thẳng tới hắn."},{"chuong":1746,"tieuDe":"Ly Khai Lôi Minh","tomTat":"Thiên Ma chiến giáp ngăn huyết ảnh xâm nhập và buộc tà vật hiện nguyên hình với nhiều khuôn mặt, trong đó có Hướng Chi Lễ và Hô lão ma. Huyết ảnh dùng huyết sắc điện quang xuyên thủng chiến giáp rồi phun huyết diễm đánh lén, nhưng bị Phạm Thánh Kim Thân bắt giữ, Phá Diệt Pháp Mục hóa giải đòn phản kích và Phệ Linh chân hỏa luyện hóa. Hàn Lập ép quang cầu trắng xám ra khỏi cơ thể rồi thiêu hủy, đồng thời xác nhận hài cốt thuộc về Hướng Chi Lễ và suy đoán nguyên thần Hướng Chi Lễ cùng Hô lão ma đã bị tà vật thôn phệ. Hắn thiêu hủy thi thể, thu hồi các trận kỳ che giấu và rời khỏi ngọn núi trước khi đội giáp sĩ tuần tra tới kiểm tra. Sau khi trở lại Phục Giao Thành, Hàn Lập nhận đủ số tài liệu do phía Thiên Cơ Tử chuyển tới trong vòng mười ngày. Một tháng sau, hắn tiến vào ngọn núi cao nhất trong thành, nơi một cột sáng từ lòng núi phóng lên trời. Cùng lúc đó, tại một đại lục xa xôi cũng xuất hiện cột sáng tương ứng và một nhân ảnh hiện ra giữa pháp trận lớn."}];
